import Foundation
import HelixBytecode
import HelixCore
import HelixInterface

extension CanonicalSIL {
public struct Lowerer: Sendable {
    private let typeEnvironment: CanonicalSIL.TypeEnvironment

    /// Swift emits these Foundation bridges around imported Objective-C APIs.
    /// HLBC calls a generated, Swift-typed NativeImport instead, so lowering
    /// preserves the Swift value while validating the exact compiler bridge.
    private enum ObjectiveCBridgeIntrinsic: Equatable {
        case stringToObjectiveC
        case stringFromObjectiveC
        case arrayToObjectiveC
        case arrayFromObjectiveC
        case nativeValueToObjectiveC

        init?(mangledName: String, loweredType: String) {
            switch mangledName {
            case "$sSS10FoundationE19_bridgeToObjectiveCSo8NSStringCyF":
                self = .stringToObjectiveC
            case "$sSS10FoundationE36_unconditionallyBridgeFromObjectiveCySSSo8NSStringCSgFZ":
                self = .stringFromObjectiveC
            case "$sSa10FoundationE19_bridgeToObjectiveCSo7NSArrayCyF":
                self = .arrayToObjectiveC
            case "$sSa10FoundationE36_unconditionallyBridgeFromObjectiveCySayxGSo7NSArrayCSgFZ":
                self = .arrayFromObjectiveC
            default:
                guard mangledName.hasPrefix("$s10Foundation"),
                      mangledName.contains("19_bridgeToObjectiveC")
                else { return nil }
                self = .nativeValueToObjectiveC
            }
            guard accepts(loweredType: loweredType) else { return nil }
        }

        func accepts(loweredType: String) -> Bool {
            let normalized = loweredType
                .replacingOccurrences(of: "Swift.", with: "")
                .filter { !$0.isWhitespace }
            return switch self {
            case .stringToObjectiveC:
                normalized
                    == "@convention(method)(@guaranteedString)->@ownedNSString"
            case .stringFromObjectiveC:
                normalized
                    == "@convention(method)(@guaranteedOptional<NSString>,@thinString.Type)->@ownedString"
            case .arrayToObjectiveC:
                normalized.hasPrefix("@convention(method)<τ_0_0>")
                    && normalized.hasSuffix("(@guaranteedArray<τ_0_0>)->@ownedNSArray")
            case .arrayFromObjectiveC:
                normalized.hasPrefix("@convention(method)<τ_0_0>")
                    && normalized.hasSuffix(
                        "(@guaranteedOptional<NSArray>,@thinArray<τ_0_0>.Type)->@ownedArray<τ_0_0>"
                    )
            case .nativeValueToObjectiveC:
                Self.acceptsNativeValueToObjectiveC(normalized)
            }
        }

        private static func acceptsNativeValueToObjectiveC(
            _ normalized: String
        ) -> Bool {
            guard normalized.utf8.count <= 8_192 else { return false }
            let convention = "@convention(method)"
            let ownershipPrefixes = [
                "(@in_guaranteed", "(@guaranteed",
            ]
            guard let ownership = ownershipPrefixes.compactMap({ prefix in
                normalized.range(of: prefix).map { (prefix, $0) }
            }).min(by: { $0.1.lowerBound < $1.1.lowerBound })
            else { return false }
            let functionPrefix = normalized[..<ownership.1.lowerBound]
            guard functionPrefix == convention
                    || functionPrefix.hasPrefix(convention + "<")
                        && functionPrefix.hasSuffix(">")
                        && hasBalancedAngles(
                            functionPrefix.dropFirst(convention.count)
                        )
            else { return false }
            let separator = ")->@owned"
            guard let separatorRange = normalized.range(
                of: separator,
                options: .backwards
            ),
                  separatorRange.upperBound < normalized.endIndex
            else { return false }
            let sourceStart = ownership.1.upperBound
            let source = normalized[sourceStart..<separatorRange.lowerBound]
            let target = normalized[separatorRange.upperBound...]
            return isNominalTypeSpelling(source)
                && isNominalTypeSpelling(target)
        }

        private static func isNominalTypeSpelling(
            _ value: Substring
        ) -> Bool {
            !value.isEmpty
                && hasBalancedAngles(value)
                && value.allSatisfy {
                    $0 == "_" || $0 == "." || $0 == "," || $0 == ":"
                        || $0 == "&" || $0 == "?" || $0 == "<" || $0 == ">"
                        || $0.isLetter || $0.isNumber
                }
        }

        private static func hasBalancedAngles(
            _ value: Substring
        ) -> Bool {
            var depth = 0
            for character in value {
                if character == "<" {
                    depth += 1
                } else if character == ">" {
                    depth -= 1
                    if depth < 0 { return false }
                }
            }
            return depth == 0
        }
    }

    private struct PendingArrayLiteral {
        var elementType: Bytecode.ValueType
        var count: Int
        var elements: [Int: Bytecode.Register]
        var elementComponents: [Int: [Int: Bytecode.Register]]

        init(elementType: Bytecode.ValueType, count: Int) {
            self.elementType = elementType
            self.count = count
            elements = [:]
            elementComponents = [:]
        }
    }

    private struct ArrayLiteralAddress {
        var allocation: String
        var index: Int
    }

    private struct ArrayIteratorState {
        var elementType: Bytecode.ValueType
        var array: Bytecode.Register
        var indexSlot: Bytecode.StackSlot
    }

    /// A `_modify` coroutine lends one element address while retaining the
    /// value-semantic collection snapshot needed for writeback. The yielded
    /// element lives in a VM stack slot so arbitrary nested inout calls,
    /// including throwing calls, use the ordinary address and exclusivity
    /// machinery rather than an API-specific store pattern.
    private struct CollectionElementMutation {
        enum Source {
            case array(array: Bytecode.Register, index: Bytecode.Register)
            case dictionaryDefault(
                dictionary: Bytecode.Register,
                key: Bytecode.Register,
                keyType: Bytecode.ValueType,
                valueType: Bytecode.ValueType
            )
        }

        var collectionAddress: String
        var source: Source
        var elementType: Bytecode.ValueType
    }

    private struct DictionaryIteratorState {
        var keyType: Bytecode.ValueType
        var valueType: Bytecode.ValueType
        var dictionary: Bytecode.Register
        var indexSlot: Bytecode.StackSlot
    }

    private struct SetIteratorState {
        var elementType: Bytecode.ValueType
        var set: Bytecode.Register
        var indexSlot: Bytecode.StackSlot
    }

    private struct ArrayLiteralComponentAddress {
        var allocation: String
        var index: Int
        var component: Int
    }

    private struct TupleComponentAddress {
        var base: String
        var index: Int
    }

    /// Field identity is independent of how compiler-only aggregate values are
    /// cached. Both tuples and patch-local structs use declaration-order paths.
    private struct AggregateComponentAddress {
        var base: String
        var index: Int
    }

    private struct CompilerStorageIdentity: Hashable {
        var root: String
        var path: [Int]

        func overlaps(_ other: Self) -> Bool {
            root == other.root
                && (path.starts(with: other.path)
                    || other.path.starts(with: path))
        }
    }

    private struct NativePropertyAddress {
        var receiver: Bytecode.Register
        var valueType: Bytecode.ValueType
        var getter: CanonicalSIL.DirectCallBinding?
        var setter: CanonicalSIL.DirectCallBinding?
        var unavailableGetter: CanonicalSIL.UnavailableDirectCall?
        var unavailableSetter: CanonicalSIL.UnavailableDirectCall?
    }

    private struct NativeReferenceConversion {
        var argument: Bytecode.Register
        var tracksCompilerTemporary: Bool
        var forwardsExplicitOwner: Bool
    }

    enum MetatypeIdentity: Equatable, Sendable {
        case native(Core.TypeID)
        case local(Bytecode.LocalTypeKey)
        case swift(String)
    }

    struct ErasedMetatype: Equatable, Sendable {
        var physicalIndex: Int
        var identity: MetatypeIdentity
    }

    /// Keeps the physical SIL ABI separate from the frozen device target.
    /// Static metatypes and indirect results never cross the VM boundary.
    private struct ResolvedFunctionReference {
        var binding: CanonicalSIL.DirectCallBinding
        var physicalParameterConventions: [Bytecode.ParameterConvention]
        var physicalValueParameterSpellings: [String]
        var hasIndirectResult: Bool
        var thrownType: Bytecode.ValueType?
        var indirectErrorType: Bytecode.ValueType?
        var erasedMetatypes: [ErasedMetatype]
        var usesObjectiveCBridge: Bool
    }

    /// One physical Swift function reference can name several frozen source
    /// call variants when different default arguments were omitted. The
    /// concrete NativeImport is selected only at `apply`, where SSA default
    /// provenance is available.
    private struct ResolvedFunctionReferenceSet {
        var variants: [ResolvedFunctionReference]

        var sole: ResolvedFunctionReference? {
            variants.count == 1 ? variants[0] : nil
        }
    }

    private struct DeferredGenericFunctionReference {
        var symbol: String
        var loweredType: String
        var bindings: [CanonicalSIL.DirectCallBinding]
    }

    /// A Swift SDK default-expression helper is compiler implementation, not
    /// application code. Its value may be erased only when the frozen
    /// NativeImport projection proves that the corresponding source argument
    /// was omitted and the generated Swift invoker will supply the default.
    private struct ExternalDefaultArgumentGenerator: Equatable {
        var symbol: String
        var ownerSymbols: Set<String>
        var loweredType: String
    }

    private struct ExternalDefaultArgumentValue: Equatable {
        var ownerSymbols: Set<String>
        var generatorSymbol: String
        var valueType: Bytecode.ValueType
        var isProjected = false
    }

    private struct ExternalDefaultArgumentAddress: Equatable {
        var ownerSymbols: Set<String>
        var generatorSymbol: String
        var valueType: Bytecode.ValueType
        var isConsumed = false
        var isDestroyed = false
    }

    private struct HostedSuperReference {
        var context: CanonicalSIL.TypeEnvironment.HostedMethodContext
        var objectToken: String
    }

    private struct ExistentialProjection {
        var destination: String
        var dynamicType: Bytecode.DynamicType
        var components: [Int: Bytecode.Register]
        var componentStoreMode: Bytecode.StackStoreMode?

        var storageType: Bytecode.ValueType {
            dynamicType.storageType
        }

        init(destination: String, dynamicType: Bytecode.DynamicType) {
            self.destination = destination
            self.dynamicType = dynamicType
            components = [:]
            componentStoreMode = nil
        }
    }

    private struct ExistentialComponentAddress {
        var projection: String
        var index: Int
    }

    private enum StrongReferenceOperation: Equatable {
        case retain
        case release
    }

    /// Swift may publish an existential box into strong storage before its
    /// projected payload is initialized. HLBC represents the completed Error
    /// value rather than that physical box, so these ownership-only uses are
    /// replayed once the semantic value exists.
    private enum DeferredErrorExistentialOperation {
        case strong(
            StrongReferenceOperation,
            block: Bytecode.BlockID
        )
        case store(
            destination: String,
            mode: Bytecode.StackStoreMode,
            sourceLine: Int,
            block: Bytecode.BlockID
        )

        var block: Bytecode.BlockID {
            switch self {
            case let .strong(_, block): block
            case let .store(_, _, _, block): block
            }
        }
    }

    private struct OptionalAddressInitialization {
        var wrappedType: Bytecode.ValueType
        var payload: Bytecode.Register?
    }

    /// A standard-library enum that remains compiler-only while its semantic
    /// payload is lowered to typed HLBC operations.
    private struct CompilerEnumCase: Equatable {
        var typeName: String
        var caseName: String
    }

    /// Lowering represents a destructive enum-payload projection as a value
    /// take followed by writeback. The first reconstructed enum must therefore
    /// initialize the VM storage even when the original SIL expresses an
    /// in-place payload mutation.
    private struct TakenOptionalPayload {
        var address: String
        var requiresInitialization = true
    }

    /// Canonical SIL may spell the unmentioned Optional case as `default`.
    /// Keep the semantic case mapping independent of clause order and retain
    /// whether `.some` is explicit, because only an explicit case forwards the
    /// wrapped payload to its successor block.
    private struct OptionalSwitchPlan {
        var operand: String
        var someTarget: Bytecode.BlockID
        var noneTarget: Bytecode.BlockID
        var someCaseIsExplicit: Bool
    }

    private enum SequenceBuilderOutput {
        case representedCollection
        case stringCharacters
    }

    private struct CollectionQueryPlan {
        var source: CanonicalSIL.SequenceSpecialization
        /// The Collection getter is exact. Zip2Sequence instead invokes each
        /// source through its Sequence witness, for which some represented
        /// adapters intentionally report zero.
        var underestimatedCountIsExact: Bool
    }

    private struct SequenceHigherOrderPlan {
        var operation: CanonicalSIL.HigherOrderIntrinsic
        var sourceToken: String
        var source: CanonicalSIL.SequenceSpecialization
        var closureToken: String
        var initialToken: String?
        var resultDestination: String?
        var errorDestination: String?
        var inputType: Bytecode.ValueType
        var closureResultType: Bytecode.ValueType
        var callResultType: Bytecode.ValueType
        var callbackShape: SequenceCallbackShape = .element
        var consumesSource = false
        var builderOutput: SequenceBuilderOutput = .representedCollection
        /// Present only when a result exposes the source Collection's
        /// represented integer-index identity.
        var sourceIndexModel: CanonicalSIL.CollectionIndex.Model? = nil
        var preservesSubsequenceIndexBase = false
    }

    private enum SequenceCursor {
        case managedCollection(
            collection: Bytecode.Register,
            indexSlot: Bytecode.StackSlot
        )
        case progression(
            end: Bytecode.Register,
            stride: Bytecode.Register,
            cursorSlot: Bytecode.StackSlot,
            boundary: Bytecode.ProgressionBoundary
        )

        var slot: Bytecode.StackSlot {
            switch self {
            case let .managedCollection(_, indexSlot): indexSlot
            case let .progression(_, _, cursorSlot, _): cursorSlot
            }
        }
    }

    private struct PreparedSequenceTraversal {
        var cursor: SequenceCursor
        var cleanup: [IntermediateRepresentation.Instruction]
    }

    private enum SequenceCallbackShape: Equatable {
        /// The closure receives the collection's represented `Element`.
        case element
        /// `Dictionary.mapValues` callbacks receive only the value field.
        case dictionaryValue
        /// `Dictionary.filter` has a two-argument key/value callback ABI even
        /// though the represented sequence element is one tuple.
        case dictionaryKeyValue
    }

    private struct SequenceOrderingPlan {
        var operation: CanonicalSIL.OrderingIntrinsic
        var sourceToken: String
        var source: CanonicalSIL.SequenceSpecialization
        var closureToken: String
        var elementType: Bytecode.ValueType
        var mutationIndexModel: CanonicalSIL.CollectionIndex.Model? = nil
    }

    private struct RangeReplaceableDestinationPlan {
        var representation: CanonicalSIL
            .RangeReplaceableCollectionRepresentation
        /// Canonical frontend identity retained independently from the erased
        /// HLBC storage type for operator-metatype validation.
        var logicalTypeIdentity: String
        /// Source-level Element identity retained independently from its
        /// potentially erased HLBC ValueType.
        var logicalElementTypeIdentity: String
        var indexModel: CanonicalSIL.CollectionIndex.Model
    }

    private struct RangeReplaceableAppendPlan {
        enum Input {
            case element(token: String)
            case sequence(
                token: String,
                specialization: CanonicalSIL.SequenceSpecialization
