        func appendInstruction(_ instruction: IntermediateRepresentation.Instruction) {
            guard var block = current else {
                preconditionFailure("HLBC instruction emitted outside a basic block")
            }
            let offset = UInt32(exactly: block.instructions.count)
            block.instructions.append(instruction)
            current = block
            if let offset, let currentSourceLocation {
                sourceMap.append(
                    .init(
                        blockID: block.id,
                        instructionOffset: offset,
                        location: currentSourceLocation
                    )
                )
            }
            if instruction.isTerminator {
                retainFlow.recordExit(instruction, from: block.id)
            }
        }

        func allocate(type: Bytecode.ValueType) throws -> Bytecode.Register {
            guard let raw = UInt32(exactly: registerTypes.count) else {
                throw CanonicalSIL.LoweringError.malformedSIL("register table exceeds UInt32")
            }
            registerTypes.append(type)
            return .init(rawValue: raw)
        }

        func allocateStackSlot(type: Bytecode.ValueType) throws -> Bytecode.StackSlot {
            guard let raw = UInt32(exactly: stackSlotTypes.count) else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "stack-slot table exceeds UInt32"
                )
            }
            stackSlotTypes.append(type)
            return .init(rawValue: raw)
        }

        func allocateSyntheticBlockID() throws -> Bytecode.BlockID {
            guard let raw = nextSyntheticBlock else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "synthetic block table exceeds UInt32"
                )
            }
            let advanced = raw.addingReportingOverflow(1)
            nextSyntheticBlock = advanced.overflow ? nil : advanced.partialValue
            return .init(rawValue: raw)
        }

        func copyOwnedValue(
            _ source: Bytecode.Register
        ) throws -> Bytecode.Register {
            let type = registerTypes[Int(source.rawValue)]
            guard !type.isTrivial else { return source }
            let copy = try allocate(type: type)
            appendInstruction(.copyValue(result: copy, source: source))
            return copy
        }

        func requiresManagedOwnership(_ type: Bytecode.ValueType) -> Bool {
            type.requiresLinearOwnership
                || typeEnvironment.containsOwningReference(type)
        }

        func retainedValueAliasRoot(for token: String) -> String {
            var current = token
            var visited = Set<String>()
            while let next = retainedValueAliasRoots[current],
                  visited.insert(current).inserted {
                current = next
            }
            return current
        }

        func aliasRetainedValue(
            _ resultToken: String,
            to sourceToken: String
        ) {
            let sourceRoot = retainedValueAliasRoot(for: sourceToken)
            let resultRoot = retainedValueAliasRoot(for: resultToken)
            guard resultRoot != sourceRoot else { return }
            if let pending = retainFlow.current.removeValue(
                forKey: resultRoot
            ) {
                retainFlow.current[sourceRoot, default: []]
                    .append(contentsOf: pending)
            }
            retainedValueAliasRoots[resultRoot] = sourceRoot
            retainedValueAliasRoots[resultToken] = sourceRoot
        }

        func recordPendingRetainedValue(
            _ value: Bytecode.Register,
            for token: String
        ) {
            let root = retainedValueAliasRoot(for: token)
            retainFlow.current[root, default: []].append(value)
        }

        func takePendingRetainedValue(
            for token: String
        ) -> Bytecode.Register? {
            let root = retainedValueAliasRoot(for: token)
            guard var pending = retainFlow.current[root],
                  let retained = pending.popLast()
            else { return nil }
            if pending.isEmpty {
                retainFlow.current.removeValue(forKey: root)
            } else {
                retainFlow.current[root] = pending
            }
            return retained
        }

        func compilerTemporaryAliasRoot(for token: String) -> String {
            var current = token
            var visited = Set<String>()
            while let next = compilerTemporaryAliasRoots[current],
                  visited.insert(current).inserted {
                current = next
            }
            return current
        }

        func aliasCompilerTemporary(
            _ resultToken: String,
            to sourceToken: String
        ) {
            let sourceRoot = compilerTemporaryAliasRoot(for: sourceToken)
            let resultRoot = compilerTemporaryAliasRoot(for: resultToken)
            guard resultRoot != sourceRoot else { return }
            compilerTemporaryAliasRoots[resultRoot] = sourceRoot
            compilerTemporaryAliasRoots[resultToken] = sourceRoot
        }

        func borrowedTemporaryValue(for token: String) -> Bytecode.Register? {
            borrowedTemporaryValues[compilerTemporaryAliasRoot(for: token)]
        }

        func compilerOwnedTemporaryValue(
            for token: String
        ) -> Bytecode.Register? {
            compilerOwnedTemporaryValues[
                compilerTemporaryAliasRoot(for: token)
            ]
        }

        func compilerTemporaryAliasTokens(for token: String) -> Set<String> {
            let root = compilerTemporaryAliasRoot(for: token)
            var aliases: Set<String> = [root, token]
            for candidate in compilerTemporaryAliasRoots.keys
            where compilerTemporaryAliasRoot(for: candidate) == root {
                aliases.insert(candidate)
            }
            return aliases
        }

        func clearBorrowedTemporaryClassification(for token: String) {
            for alias in compilerTemporaryAliasTokens(for: token) {
                borrowedValueTokens.remove(alias)
                borrowedLoadTokens.remove(alias)
            }
        }

        func recordBorrowedTemporaryValue(
            _ value: Bytecode.Register,
            for token: String
        ) throws {
            let root = compilerTemporaryAliasRoot(for: token)
            guard borrowedTemporaryValues[root] == nil,
                  compilerOwnedTemporaryValues[root] == nil
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "borrowed temporary token already owns a VM value"
                )
            }
            borrowedTemporaryValues[root] = value
        }

        @discardableResult
        func removeBorrowedTemporaryValue(
            for token: String
        ) -> Bytecode.Register? {
            borrowedTemporaryValues.removeValue(
                forKey: compilerTemporaryAliasRoot(for: token)
            )
        }

        func recordCompilerOwnedTemporaryValue(
            _ value: Bytecode.Register,
            for token: String
        ) throws {
            let root = compilerTemporaryAliasRoot(for: token)
            guard borrowedTemporaryValues[root] == nil,
                  compilerOwnedTemporaryValues[root] == nil
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "compiler-owned temporary token already owns a VM value"
                )
            }
            compilerOwnedTemporaryValues[root] = value
        }

        @discardableResult
        func removeCompilerOwnedTemporaryValue(
            for token: String
        ) -> Bytecode.Register? {
            compilerOwnedTemporaryValues.removeValue(
                forKey: compilerTemporaryAliasRoot(for: token)
            )
        }

        func prepareOwnedValue(
            _ token: String,
            expectedType: Bytecode.ValueType? = nil,
            line: Int
        ) throws -> Bytecode.Register {
            let value = try resolveStorableValue(
                token,
                expectedType: expectedType,
                line: line
            )
            let type = registerTypes[Int(value.rawValue)]
            if let retained = takePendingRetainedValue(for: token) {
                guard registerTypes[Int(retained.rawValue)] == type else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "retained owned value has the wrong type"
                    )
                }
                return retained
            }
            guard requiresManagedOwnership(type) else { return value }
            if let temporary = borrowedTemporaryValue(for: token) {
                guard temporary == value else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "borrowed temporary ownership does not match its SIL value"
                    )
                }
                let owned = try copyOwnedValue(value)
                if !hasFutureSemanticUse(
                    ofCompilerTemporaryAliasedTo: token,
                    after: currentSILLineIndex
                ) {
                    removeBorrowedTemporaryValue(for: token)
                    clearBorrowedTemporaryClassification(for: token)
                    appendInstruction(.destroyValue(temporary))
                }
                return owned
            }
            let hasFutureUse = compilerOwnedTemporaryValue(for: token) != nil
                ? hasFutureSemanticUse(
                    ofCompilerTemporaryAliasedTo: token,
                    after: currentSILLineIndex
                )
                : hasFutureSemanticUse(
                    of: token,
                    after: currentSILLineIndex
                )
            let preservesSource = isBorrowedValue(token: token, register: value)
                || hasFutureUse
            guard preservesSource else {
                if let temporary = removeCompilerOwnedTemporaryValue(
                    for: token
                ), temporary != value {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "compiler-owned temporary does not match its SIL value"
                    )
                }
                return value
            }
            // Every HLBC aggregate/call/return ownership edge is explicit.
            // Canonical SIL may express that edge as ARC traffic around a
            // borrowed or subsequently reused SSA value, so materialize a VM
            // owner when no explicit retained owner is available.
            return try copyOwnedValue(value)
        }

        func prepareReturnValue(
            _ token: String,
            line: Int
        ) throws -> Bytecode.Register {
            try prepareOwnedValue(token, line: line)
        }

        func prepareStoredValue(
            _ token: String,
            expectedType: Bytecode.ValueType,
            line: Int
        ) throws -> Bytecode.Register {
            try prepareOwnedValue(
                token,
                expectedType: expectedType,
                line: line
            )
        }

        func materializeRetain(
            of token: String,
            value: Bytecode.Register
        ) throws {
            let type = registerTypes[Int(value.rawValue)]
            guard requiresManagedOwnership(type) else { return }
            let retained = try copyOwnedValue(value)
            if let temporary = borrowedTemporaryValue(for: token) {
                guard temporary == value else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "borrowed temporary retain does not match its SIL value"
                    )
                }
                removeBorrowedTemporaryValue(for: token)
                for alias in compilerTemporaryAliasTokens(for: token)
                where values[alias] == temporary {
                    values[alias] = retained
                }
                clearBorrowedTemporaryClassification(for: token)
                appendInstruction(.destroyValue(temporary))
                return
            }
            recordPendingRetainedValue(retained, for: token)
        }

        func releaseClosureValueIfFinal(
            token: String,
            value: Bytecode.Register
        ) throws {
            guard case .closure = registerTypes[Int(value.rawValue)] else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "closure release references a non-closure value"
                )
            }
            // Canonical non-OSSA SIL may keep using the same closure reference
            // after a strong_release while an aggregate or another explicit
            // owner keeps its context alive. A VM register is itself one
            // strong root, so end that root only at the token's final semantic
            // release; owned aggregate/copy edges already have distinct roots.
            guard borrowedTemporaryValue(for: token) != nil
                    || (!isBorrowedValue(token: token, register: value)
                        && !hasFutureSemanticUse(
                            of: token,
                            after: currentSILLineIndex
                        ))
            else { return }
            try closeBorrowedTemporaryLifetime(for: token, resolved: value)
            appendInstruction(.destroyValue(value))
        }

        func isBorrowedParameter(_ register: Bytecode.Register) -> Bool {
            zip(parameterRegisters, signature.parameterConventions).contains {
                $0.0 == register && $0.1 == .borrowed
            }
        }

        func isBorrowedValue(
            token: String,
            register: Bytecode.Register
        ) -> Bool {
            borrowedValueTokens.contains(token)
                || borrowedLoadTokens.contains(token)
                || isBorrowedParameter(register)
        }

        func lineContainsSILValue(_ token: String, line: String) -> Bool {
            line.range(
                of: "(?<![0-9])" + NSRegularExpression.escapedPattern(for: token)
                    + "(?![0-9])",
                options: .regularExpression
            ) != nil
        }

        func hasFutureSemanticUse(of token: String, after lineIndex: Int) -> Bool {
            guard lineIndex + 1 < rawLines.count else { return false }
            return rawLines[(lineIndex + 1)...].contains { rawLine in
                let instruction = CanonicalSIL.DebugMetadata.strippingComment(
                    from: rawLine
                ).trimmingCharacters(in: .whitespaces)
                guard !instruction.isEmpty,
                      !instruction.hasPrefix("debug_value"),
                      !instruction.hasPrefix("debug_step"),
                      !instruction.hasPrefix("end_borrow"),
                      !instruction.hasPrefix("fix_lifetime")
                else { return false }
                return lineContainsSILValue(token, line: instruction)
            }
        }

        func hasFutureSemanticUse(
            ofCompilerTemporaryAliasedTo token: String,
            after lineIndex: Int
        ) -> Bool {
            compilerTemporaryAliasTokens(for: token).contains {
                hasFutureSemanticUse(of: $0, after: lineIndex)
            }
        }

        func removeAccessMetadata(_ token: String) {
            passthroughRuntimeAccesses.remove(token)
            initializingRuntimeAccesses.remove(token)
            scopedRuntimeAddresses.remove(token)
            runtimeAddressValues.removeValue(forKey: token)
            runtimeAddressPointees.removeValue(forKey: token)
            mutableCaptureState.addresses.removeValue(forKey: token)
            values.removeValue(forKey: token)
            addressAliases.removeValue(forKey: token)
        }

        func prepareNativeReferenceConversion(
            sourceToken: String,
            source: Bytecode.Register,
            lineIndex: Int
        ) throws -> NativeReferenceConversion {
            if let retained = takePendingRetainedValue(for: sourceToken) {
                guard registerTypes[Int(retained.rawValue)]
                        == registerTypes[Int(source.rawValue)]
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "retained native conversion owner has the wrong type"
                    )
                }
                return .init(
                    argument: retained,
                    tracksCompilerTemporary: false,
                    forwardsExplicitOwner: true
                )
            }
            // Native bridge calls consume their argument. Preserve a borrowed
            // or subsequently reused SIL source and own the conversion result
            // as a compiler-generated temporary until its final semantic use.
            let sourceIsBorrowed = isBorrowedValue(
                token: sourceToken,
                register: source
            )
            let preservesSource = sourceIsBorrowed
                || hasFutureSemanticUse(of: sourceToken, after: lineIndex)
            return .init(
                argument: preservesSource
                    ? try copyOwnedValue(source)
                    : source,
                tracksCompilerTemporary: preservesSource,
                forwardsExplicitOwner: false
            )
        }

        func releaseCompilerTemporariesAfterLastUse(
            _ tokens: some Sequence<String>,
            after lineIndex: Int
        ) {
            for token in Set(tokens) where !hasFutureSemanticUse(
                ofCompilerTemporaryAliasedTo: token,
                after: lineIndex
            ) {
                if let value = removeBorrowedTemporaryValue(for: token) {
                    clearBorrowedTemporaryClassification(for: token)
                    appendInstruction(.destroyValue(value))
                } else if let value = removeCompilerOwnedTemporaryValue(
                    for: token
                ) {
                    appendInstruction(.destroyValue(value))
                }
            }
        }

        /// Track a VM owner introduced for a physical SIL value that has no
        /// corresponding SIL cleanup. The compiler must end this synthetic
        /// lifetime after the value's last semantic use.
        func trackCompilerTemporaryOwner(
            token: String,
            value: Bytecode.Register,
            after lineIndex: Int
        ) throws {
            guard requiresManagedOwnership(
                registerTypes[Int(value.rawValue)]
            ) else { return }
            if let tracked = compilerOwnedTemporaryValue(for: token) {
                guard tracked == value else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "compiler-owned temporary does not match its SIL value"
                    )
                }
            } else if borrowedTemporaryValue(for: token) == nil {
                try recordCompilerOwnedTemporaryValue(value, for: token)
            }
            releaseCompilerTemporariesAfterLastUse(
                [token],
                after: lineIndex
            )
        }

        /// Clang-imported value types have no ARC cleanup in physical SIL,
        /// while their frozen Native representation owns a VM handle.
        func trackNonreferenceNativeTemporary(
            token: String,
            value: Bytecode.Register,
            after lineIndex: Int
        ) throws {
            guard typeEnvironment.isNonreferenceNativeValue(
                registerTypes[Int(value.rawValue)]
            ) else { return }
            if let tracked = borrowedTemporaryValue(for: token) {
                guard tracked == value else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "borrowed temporary ownership does not match its SIL value"
                    )
                }
            } else if compilerOwnedTemporaryValue(for: token) == nil {
                try recordBorrowedTemporaryValue(value, for: token)
            }
            releaseCompilerTemporariesAfterLastUse(
                [token],
                after: lineIndex
            )
        }

        func closeBorrowedTemporaryLifetime(
            for token: String,
            resolved value: Bytecode.Register
        ) throws {
            guard let tracked = removeBorrowedTemporaryValue(for: token)
            else { return }
            guard tracked == value else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "borrowed temporary ownership does not match its SIL value"
                )
            }
            clearBorrowedTemporaryClassification(for: token)
        }

        func closeCompilerOwnedTemporaryLifetime(
            for token: String,
            resolved value: Bytecode.Register
        ) throws {
            guard let tracked = removeCompilerOwnedTemporaryValue(for: token)
            else { return }
            guard tracked == value else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "compiler-owned temporary does not match its SIL value"
                )
            }
        }

        func transferBorrowedTemporaryLifetime(
            from sourceToken: String,
            resolved source: Bytecode.Register,
            to resultToken: String,
            result: Bytecode.Register
        ) throws {
            guard let tracked = removeBorrowedTemporaryValue(for: sourceToken)
            else { return }
            guard tracked == source else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "borrowed temporary cannot transfer into a different owner"
                )
            }
            clearBorrowedTemporaryClassification(for: sourceToken)
            try recordBorrowedTemporaryValue(result, for: resultToken)
        }

        func transferCompilerOwnedTemporaryLifetime(
            from sourceToken: String,
            resolved source: Bytecode.Register,
            to resultToken: String,
            result: Bytecode.Register
        ) throws {
            guard let tracked = removeCompilerOwnedTemporaryValue(
                for: sourceToken
            ) else { return }
            guard tracked == source else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "compiler-owned temporary cannot transfer into a different owner"
                )
            }
            try recordCompilerOwnedTemporaryValue(result, for: resultToken)
        }

        func transferCompilerTemporaryOwnersIntoControlFlow(
            tokens: [String],
            arguments: [Bytecode.Register]
        ) throws {
            guard tokens.count == arguments.count else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "branch owner transfer has inconsistent arity"
                )
            }
            for (token, argument) in zip(tokens, arguments) {
                if let tracked = borrowedTemporaryValue(for: token) {
                    guard tracked == argument else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "branch owner transfer does not match its SIL value"
                        )
                    }
                    removeBorrowedTemporaryValue(for: token)
                    clearBorrowedTemporaryClassification(for: token)
                } else if let tracked = compilerOwnedTemporaryValue(
                    for: token
                ) {
                    guard tracked == argument else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "branch owner transfer does not match its SIL value"
                        )
                    }
                    removeCompilerOwnedTemporaryValue(for: token)
                }
            }
        }

        func addressBase(_ token: String) -> String {
            var current = token
            var visited = Set<String>()
            while let next = addressAliases[current], visited.insert(current).inserted {
                current = next
            }
            return current
        }

        func mutableCell(at token: String) -> Bytecode.Register? {
            (mutableCaptureState.addresses[token]
                ?? mutableCaptureState.addresses[addressBase(token)])?.register
        }

        func mutableCellPointee(at token: String) -> Bytecode.ValueType? {
            (mutableCaptureState.addresses[token]
                ?? mutableCaptureState.addresses[addressBase(token)])?.pointee
        }

        func nonOwningReference(
            at token: String
        ) -> Bytecode.Register? {
            for candidate in [token, addressBase(token)] {
                guard let register = values[candidate],
                      case .nonOwningReference = registerTypes[
                        Int(register.rawValue)
                      ]
                else { continue }
                return register
            }
            return nil
        }

        func isKnownSomeOptionalAddress(
            _ token: String,
            in blockID: Bytecode.BlockID?
        ) -> Bool {
            guard let blockID else { return false }
            return knownSomeOptionalAddresses[blockID]?
                .contains(compilerStorageIdentity(for: token)) == true
        }

        func setKnownSomeOptionalAddress(
            _ token: String,
            in blockID: Bytecode.BlockID,
            isKnownSome: Bool
        ) {
            let key = compilerStorageIdentity(for: token)
            if isKnownSome {
                knownSomeOptionalAddresses[blockID, default: []].insert(key)
            } else {
                knownSomeOptionalAddresses[blockID]?.remove(key)
            }
        }

        func isKnownSomeOptionalValue(
            _ token: String,
            in blockID: Bytecode.BlockID?
        ) -> Bool {
            knownOptionalSomePayloads[token] != nil
                || blockID.map {
                    knownSomeOptionalValues[$0]?.contains(token) == true
                } == true
        }

        func setKnownSomeOptionalValue(
            _ token: String,
            in blockID: Bytecode.BlockID,
            isKnownSome: Bool
        ) {
            if isKnownSome {
                knownSomeOptionalValues[blockID, default: []].insert(token)
            } else {
                knownSomeOptionalValues[blockID]?.remove(token)
            }
        }

        func stackType(at token: String) -> Bytecode.ValueType? {
            mutableCellPointee(at: token)
                ?? runtimeAddressPointees[token]
                ?? nativePropertyAddresses[addressBase(token)]?.valueType
                ?? stackAddressTypes[addressBase(token)]
        }

        func runtimeAddress(at token: String) -> Bytecode.Register? {
            runtimeAddressValues[token] ?? runtimeAddressValues[addressBase(token)]
        }

        func isScopedRuntimeAddress(_ token: String) -> Bool {
            scopedRuntimeAddresses.contains(token)
                || scopedRuntimeAddresses.contains(addressBase(token))
        }

        func stackValue(at token: String) -> Bytecode.Register? {
            guard runtimeAddress(at: token) == nil,
                  mutableCell(at: token) == nil
            else { return nil }
            if let key = aggregateComponentStorageIdentity(for: token),
               let component = aggregateComponentValues[key] {
                return component
            }
            return stackAddressValues[addressBase(token)]
        }

        func loadNativePropertyValue(
            _ property: NativePropertyAddress,
            line: Int
        ) throws -> Bytecode.Register {
            guard let binding = property.getter else {
                if let unavailable = property.unavailableGetter {
                    throw CanonicalSIL.LoweringError.unavailableNativeImport(
                        line: line,
                        mangledName: unavailable.mangledName,
                        canonicalCallee: unavailable.canonicalCallee,
                        reason: unavailable.reason
                    )
                }
                throw CanonicalSIL.LoweringError.unsupportedInstruction(
                    line: line,
                    text: "stored property getter is absent from the frozen Shell"
                )
            }
            guard case let .nativeImport(requirement) = binding.target else {
                throw CanonicalSIL.LoweringError.invalidCallTable(
                    "stored property getter is not a NativeImport"
                )
            }
            let result = try allocate(type: property.valueType)
            let receiver = try copyOwnedValue(property.receiver)
            appendInstruction(
                .nativeApply(
                    result: result,
                    importID: requirement.id,
                    arguments: [receiver]
                )
            )
            return result
        }

        func recordCompilerAddressValue(_ value: Bytecode.Register, at token: String) {
            if let key = aggregateComponentStorageIdentity(for: token) {
                // A projected write invalidates any cached aggregate snapshot
                // containing that field, as well as nested snapshots replaced
                // by the write. Storage itself is keyed by semantic field path
                // so distinct SIL projections alias one value.
                stackAddressValues.removeValue(forKey: key.root)
                stackAddressValues.removeValue(forKey: addressBase(token))
                aggregateComponentValues = aggregateComponentValues.filter {
                    candidate,
                    _ in
                    !candidate.overlaps(key)
                }
                aggregateComponentValues[key] = value
                return
            }
            let root = addressBase(token)
            stackAddressValues[root] = value
            aggregateComponentValues = aggregateComponentValues.filter {
                $0.key.root != root
            }
        }

        @discardableResult
        func removeCompilerAddressValue(at token: String) -> Bytecode.Register? {
            if let key = aggregateComponentStorageIdentity(for: token) {
                let removed = aggregateComponentValues[key]
                    ?? stackAddressValues[addressBase(token)]
                stackAddressValues.removeValue(forKey: key.root)
                stackAddressValues.removeValue(forKey: addressBase(token))
                aggregateComponentValues = aggregateComponentValues.filter {
                    candidate,
                    _ in
                    !candidate.overlaps(key)
                }
                return removed
            }
            return stackAddressValues.removeValue(forKey: addressBase(token))
        }

        func aggregateComponentStorageIdentity(
            for token: String
        ) -> CompilerStorageIdentity? {
            let identity = compilerStorageIdentity(for: token)
            return identity.path.isEmpty ? nil : identity
        }

        func unpackTupleValue(
            _ tuple: Bytecode.Register,
            retainedOwnerFor token: String? = nil
        ) throws -> [Bytecode.Register] {
            guard case let .tuple(types) = registerTypes[Int(tuple.rawValue)]
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "tuple storage does not contain a tuple VM value"
                )
            }
            if let existing = unpackedTuples[tuple] {
                return existing
            }
            let owner = token.flatMap(takePendingRetainedValue) ?? tuple
            guard registerTypes[Int(owner.rawValue)] == .tuple(types) else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "retained tuple projection owner has the wrong type"
                )
            }
            let elements = try types.map { try allocate(type: $0) }
            unpackedTuples[tuple] = elements
            unpackedTuples[owner] = elements
            // Canonical SIL commonly retains an aggregate before projecting
            // fields whose ownership is then released or transferred
            // independently. Destructure that explicit owner so the borrowed
            // aggregate itself remains untouched and ownership is distributed
            // to the projected VM values.
            appendInstruction(.unpackTuple(results: elements, tuple: owner))
            return elements
        }

        func compilerAggregateFieldTypes(
            _ type: Bytecode.ValueType
        ) throws -> [Bytecode.ValueType]? {
            switch type {
            case let .tuple(types):
                return types
            case let .local(key):
                guard case let .structure(fields) = try typeEnvironment
                    .definition(for: key).kind
                else { return nil }
                return fields.map(\.type)
            default:
                return nil
            }
        }

        /// Compiler-only tuple and local-struct storage may alternate between
        /// one aggregate register and independently initialized fields. Rebuild
        /// only after every leaf exists so nested ownership remains explicit.
        func rebuildAggregateStorageValue(
            root: String,
            type: Bytecode.ValueType,
            path: [Int] = []
        ) throws -> Bytecode.Register? {
            if path.isEmpty, let aggregate = stackAddressValues[root] {
                return aggregate
            }
            if !path.isEmpty,
               let aggregate = aggregateComponentValues[
                .init(root: root, path: path)
               ] {
                return aggregate
            }
            guard let types = try compilerAggregateFieldTypes(type) else {
                return nil
            }

            var elements: [Bytecode.Register] = []
            elements.reserveCapacity(types.count)
            for (index, elementType) in types.enumerated() {
                let childPath = path + [index]
                let childKey = CompilerStorageIdentity(
                    root: root,
                    path: childPath
                )
                let child: Bytecode.Register? = if let value =
                    aggregateComponentValues[childKey] {
                    value
                } else if try compilerAggregateFieldTypes(elementType) != nil {
                    try rebuildAggregateStorageValue(
                        root: root,
                        type: elementType,
                        path: childPath
                    )
                } else {
                    nil
                }
                guard let child,
                      registerTypes[Int(child.rawValue)] == elementType
                else { return nil }
                elements.append(child)
            }

            let result = try allocate(type: type)
            switch type {
            case .tuple:
                appendInstruction(.makeTuple(result: result, elements: elements))
            case .local:
                appendInstruction(.makeStruct(result: result, fields: elements))
            default:
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "compiler aggregate reconstruction lost its aggregate type"
                )
            }
            aggregateComponentValues = aggregateComponentValues.filter {
                candidate,
                _ in
                guard candidate.root == root else { return true }
                return !candidate.path.starts(with: path)
                    || candidate.path.count <= path.count
            }
            if path.isEmpty {
                stackAddressValues[root] = result
            } else {
                aggregateComponentValues[
                    .init(root: root, path: path)
                ] = result
            }
            return result
        }

        /// Materializes every declared descendant projection from an aggregate
        /// regardless of whether the projection address was formed before or
        /// after the aggregate became initialized.
        func materializeTupleComponents(
            at base: String,
            tuple: Bytecode.Register
        ) throws {
            guard case .tuple = registerTypes[Int(tuple.rawValue)] else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "tuple address does not contain a tuple VM value"
                )
            }
            let baseKey = aggregateComponentStorageIdentity(for: base)
            let root = baseKey?.root ?? addressBase(base)
            let basePath = baseKey?.path ?? []
            let targets = Set(tupleComponentAddresses.keys.compactMap {
                aggregateComponentStorageIdentity(for: $0)
            }.filter {
                $0.root == root
                    && $0.path.count > basePath.count
                    && $0.path.starts(with: basePath)
            }).sorted { lhs, rhs in
                if lhs.path.count != rhs.path.count {
                    return lhs.path.count < rhs.path.count
                }
                for (left, right) in zip(lhs.path, rhs.path)
                where left != right {
                    return left < right
                }
                return false
            }
            guard !targets.isEmpty else { return }

            for target in targets {
                var current = tuple
                var currentPath = basePath
                for index in target.path.dropFirst(basePath.count) {
                    let childPath = currentPath + [index]
                    let childKey = CompilerStorageIdentity(
                        root: root,
                        path: childPath
                    )
                    if let cached = aggregateComponentValues[childKey] {
                        current = cached
                    } else {
                        let elements = try unpackTupleValue(current)
                        if currentPath.isEmpty {
                            stackAddressValues.removeValue(forKey: root)
                        } else {
                            aggregateComponentValues.removeValue(
                                forKey: .init(
                                    root: root,
                                    path: currentPath
                                )
                            )
                        }
                        guard elements.indices.contains(index) else {
                            throw CanonicalSIL.LoweringError.malformedSIL(
                                "tuple component address is out of bounds"
                            )
                        }
                        for (childIndex, element) in elements.enumerated() {
                            aggregateComponentValues[
                                .init(
                                    root: root,
                                    path: currentPath + [childIndex]
                                )
                            ] = element
                        }
                        current = elements[index]
                    }
                    currentPath = childPath
                }
            }
            if let baseKey {
                aggregateComponentValues.removeValue(forKey: baseKey)
            } else {
                stackAddressValues.removeValue(forKey: root)
            }
        }

        func compilerStorageIdentity(
            for token: String
        ) -> CompilerStorageIdentity {
            var current = token
            var reversedPath: [Int] = []
            var visited = Set<String>()
            while visited.insert(current).inserted {
                if let component = aggregateComponentAddresses[current] {
                    reversedPath.append(component.index)
                    current = component.base
                    continue
                }
                let canonical = addressBase(current)
                guard canonical != current else { break }
                current = canonical
            }
            return .init(
                root: addressBase(current),
                path: Array(reversedPath.reversed())
            )
        }

        func optionalValueSource(at token: String) -> String? {
            guard let blockID = current?.id else { return nil }
            return optionalValueSourcesByBlock[blockID]?[
                compilerStorageIdentity(for: token)
            ]
        }

        func recordOptionalValueSource(
            _ source: String?,
            at token: String
        ) {
            guard let blockID = current?.id else { return }
            let key = compilerStorageIdentity(for: token)
            if let source {
                optionalValueSourcesByBlock[blockID, default: [:]][key] = source
            } else {
                optionalValueSourcesByBlock[blockID]?.removeValue(forKey: key)
            }
        }

        func invalidateOptionalStorageFacts(at token: String) {
            guard let blockID = current?.id else { return }
            let changed = compilerStorageIdentity(for: token)
            if let known = knownSomeOptionalAddresses[blockID] {
                knownSomeOptionalAddresses[blockID] = Set(
                    known.filter { !changed.overlaps($0) }
                )
            }
            if let sources = optionalValueSourcesByBlock[blockID] {
                optionalValueSourcesByBlock[blockID] = sources.filter {
                    !changed.overlaps($0.key)
                }
            }
        }

        func inheritKnownOptionalValueCase(
            from source: String,
            to result: String
        ) {
            guard let blockID = current?.id,
                  isKnownSomeOptionalValue(source, in: blockID)
            else { return }
            setKnownSomeOptionalValue(result, in: blockID, isKnownSome: true)
        }

        func recordOptionalLoadCase(
            from address: String,
            to result: String,
            type: Bytecode.ValueType
        ) {
            guard case .optional = type,
                  let blockID = current?.id,
                  isKnownSomeOptionalAddress(address, in: blockID)
            else { return }
            setKnownSomeOptionalValue(result, in: blockID, isKnownSome: true)
        }

        @discardableResult
        func removeAggregateComponentValues(
            rootedAt root: String
        ) -> [Bytecode.Register] {
            let canonicalRoot = addressBase(root)
            let matching = aggregateComponentValues.filter {
                $0.key.root == canonicalRoot
            }
            for key in matching.keys {
                aggregateComponentValues.removeValue(forKey: key)
            }
            return Array(matching.values)
        }

        func reconstructedOptionalNone(
            for token: String,
            line: Int
        ) throws -> Bytecode.Register? {
            guard let blockID = current?.id,
                  let source = optionalSourceByNoneBlock[blockID],
                  addressBase(source) == addressBase(token)
            else { return nil }
            let root = addressBase(source)
            if let replacement = reconstructedNoneValues[blockID]?[root] {
                return replacement
            }
            guard runtimeAddress(at: source) == nil else { return nil }
            guard let original = stackAddressValues[root] ?? values[source] else {
                throw CanonicalSIL.LoweringError.undefinedValue(
                    line: line,
                    value: token
                )
            }
            let type = registerTypes[Int(original.rawValue)]
            guard case .optional = type else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "switch_enum none edge does not reference an Optional"
                )
            }
            let replacement = try allocate(type: type)
            appendInstruction(.makeOptionalNone(result: replacement))
            reconstructedNoneValues[blockID, default: [:]][root] = replacement
            if stackAddressTypes[root] != nil {
                stackAddressValues[root] = replacement
                values[root] = replacement
                values[source] = replacement
            }
            return replacement
        }

        func resolvedStackValue(
            at token: String,
            line: Int
        ) throws -> Bytecode.Register? {
            if let replacement = try reconstructedOptionalNone(
                for: token,
                line: line
            ) {
                return replacement
            }
            if let value = stackValue(at: token) {
                return value
            }
            if let reference = nonOwningReference(at: token) {
                return reference
            }
            guard runtimeAddress(at: token) == nil,
                  mutableCell(at: token) == nil
            else { return nil }
            if let key = aggregateComponentStorageIdentity(for: token) {
                if let rootAggregate = stackAddressValues[key.root] {
                    if case .tuple = registerTypes[Int(rootAggregate.rawValue)] {
                        try materializeTupleComponents(
                            at: key.root,
                            tuple: rootAggregate
                        )
                        return aggregateComponentValues[key]
                    }
                    return nil
                }
                guard let componentType = stackType(at: token) else {
                    return nil
                }
                return try rebuildAggregateStorageValue(
                    root: key.root,
                    type: componentType,
                    path: key.path
                )
            }
            let root = addressBase(token)
            guard let rootType = stackAddressTypes[root] else { return nil }
            return try rebuildAggregateStorageValue(root: root, type: rootType)
        }

        func copyStoredValue(
            at token: String,
            line: Int
        ) throws -> Bytecode.Register? {
            guard let type = stackType(at: token) else { return nil }
            if storageInitializationPlan.consumesApplicationArgument(
                token,
                at: currentSILLineIndex
            ) {
                guard let taken = try takeStoredValue(at: token, line: line) else {
                    throw CanonicalSIL.LoweringError.unsupportedInstruction(
                        line: line,
                        text: "consuming @in argument cannot transfer its storage"
                    )
                }
                return taken
            }
            if let cell = mutableCell(at: token) {
                let result = try allocate(type: type)
                appendInstruction(
                    .loadMutableCell(result: result, cell: cell)
                )
                return result
            }
            if let address = runtimeAddress(at: token) {
                let result = try allocate(type: type)
                if isScopedRuntimeAddress(token) {
                    appendInstruction(
                        .loadAddress(result: result, address: address, mode: .copy)
                    )
                } else {
                    let access = try allocate(type: .address(type))
                    appendInstruction(
                        .beginAccess(result: access, address: address, kind: .read)
                    )
                    appendInstruction(
                        .loadAddress(result: result, address: access, mode: .copy)
                    )
                    appendInstruction(.endAccess(access))
                }
                return result
            }
            guard let stored = try resolvedStackValue(at: token, line: line),
                  registerTypes[Int(stored.rawValue)] == type
            else { return nil }
            guard !type.isTrivial else { return stored }
            let result = try allocate(type: type)
            appendInstruction(.copyValue(result: result, source: stored))
            return result
        }

        func borrowStoredValue(
            at token: String,
            line: Int
        ) throws -> BorrowedStoredValue? {
            guard let type = stackType(at: token) else { return nil }
            if let property = nativePropertyAddresses[addressBase(token)] {
                let snapshot: Bytecode.Register
                if let stored = stackValue(at: token) {
                    snapshot = stored
                } else {
                    snapshot = try loadNativePropertyValue(property, line: line)
                    recordCompilerAddressValue(snapshot, at: token)
                }
                guard registerTypes[Int(snapshot.rawValue)] == type else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "native property snapshot has the wrong VM type"
                    )
                }
                // Enum-address inspection and payload projection must observe
                // one getter snapshot. The corresponding end_access releases
                // the snapshot on paths that do not consume its payload.
                return .init(register: snapshot, temporaryOwner: nil)
            }
            if runtimeAddress(at: token) != nil || mutableCell(at: token) != nil {
                guard let copy = try copyStoredValue(at: token, line: line) else {
                    return nil
                }
                return .init(
                    register: copy,
                    temporaryOwner: requiresManagedOwnership(type) ? copy : nil
                )
            }
            guard let stored = try resolvedStackValue(at: token, line: line),
                  registerTypes[Int(stored.rawValue)] == type
            else { return nil }
            return .init(register: stored, temporaryOwner: nil)
        }

        /// Produces a value that a consuming operation may transfer. Storage
        /// retains its own lifetime; direct linear values are copied for the
        /// same reason, while non-linear direct values may be reused.
        func materializeOwnedValue(
            at token: String,
            line: Int
        ) throws -> Bytecode.Register {
            if stackType(at: token) != nil {
                guard let copy = try copyStoredValue(at: token, line: line) else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "address-backed value is uninitialized"
                    )
                }
                return copy
            }
            return try prepareOwnedValue(token, line: line)
        }

        func takeStoredValue(
            at token: String,
            line: Int
        ) throws -> Bytecode.Register? {
            guard let type = stackType(at: token),
                  mutableCell(at: token) == nil
            else { return nil }
            let root = addressBase(token)
            if let address = runtimeAddress(at: token) {
                guard let slot = runtimeStackSlots[root] else {
                    throw CanonicalSIL.LoweringError.unsupportedInstruction(
                        line: line,
                        text: "taking caller-owned address storage requires writeback"
                    )
                }
                let result = try allocate(type: type)
                if token == root, !isScopedRuntimeAddress(token) {
                    appendInstruction(
                        .loadStack(result: result, slot: slot, mode: .take)
                    )
                } else if isScopedRuntimeAddress(token) {
                    appendInstruction(
                        .loadAddress(
                            result: result,
                            address: address,
                            mode: .take
                        )
                    )
                } else {
                    let access = try allocate(type: .address(type))
                    appendInstruction(
                        .beginAccess(
                            result: access,
                            address: address,
                            kind: .modify
                        )
                    )
                    appendInstruction(
                        .loadAddress(
                            result: result,
                            address: access,
                            mode: .take
                        )
                    )
                    appendInstruction(.endAccess(access))
                }
                stackAddressValues.removeValue(forKey: root)
                invalidateOptionalStorageFacts(at: token)
                return result
            }
            guard let stored = try resolvedStackValue(at: token, line: line),
                  !requiresManagedOwnership(type)
                    || !isBorrowedValue(token: token, register: stored)
            else { return nil }
            removeCompilerAddressValue(at: token)
            invalidateOptionalStorageFacts(at: token)
            return stored
        }

        func transferAddressCastSource(
            mode: String,
            at token: String,
            line: Int
        ) throws -> Bytecode.Register? {
            switch mode {
            case "take_always":
                return try takeStoredValue(at: token, line: line)
            case "copy_on_success":
                return try copyStoredValue(at: token, line: line)
            default:
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "checked address cast has unknown ownership mode \(mode)"
                )
            }
        }

        func destroyRuntimeStoredValue(
            at token: String,
            line: Int,
            ifInitialized: Bool
        ) throws -> Bool {
            guard let type = stackType(at: token),
                  mutableCell(at: token) == nil,
                  let address = runtimeAddress(at: token)
            else { return false }
            let root = addressBase(token)
            guard runtimeStackSlots[root] != nil else {
                throw CanonicalSIL.LoweringError.unsupportedInstruction(
                    line: line,
                    text: "destroying caller-owned or object address storage requires writeback"
                )
            }
            let destroy: Bytecode.Instruction = if ifInitialized {
                .destroyAddressIfInitialized(address)
            } else {
                .destroyAddress(address)
            }
            if isScopedRuntimeAddress(token) {
                appendInstruction(destroy)
            } else {
                let access = try allocate(type: .address(type))
                appendInstruction(
                    .beginAccess(
                        result: access,
                        address: address,
                        kind: .modify
                    )
                )
                let scopedDestroy: Bytecode.Instruction = if ifInitialized {
                    .destroyAddressIfInitialized(access)
                } else {
                    .destroyAddress(access)
                }
                appendInstruction(scopedDestroy)
                appendInstruction(.endAccess(access))
            }
            removeCompilerAddressValue(at: token)
            invalidateOptionalStorageFacts(at: token)
            return true
        }

        /// Records a value written through the raw storage returned by
        /// `_allocateUninitializedArray`. Calls whose result convention is
        /// indirect can target these addresses directly, including one field
        /// of a tuple element, so every constructed-value path must share the
        /// same pending-literal sink as an ordinary SIL `store`.
        func storePendingArrayLiteralValue(
            _ value: Bytecode.Register,
            at token: String
        ) throws -> Bool {
            let valueType = registerTypes[Int(value.rawValue)]
            if let address = arrayLiteralComponentAddresses[token] {
                guard var pending = pendingArrayLiterals[address.allocation],
                      case let .tuple(types) = pending.elementType,
                      address.index >= 0,
                      address.index < pending.count,
                      types.indices.contains(address.component),
                      types[address.component] == valueType,
                      pending.elements[address.index] == nil,
                      pending.elementComponents[address.index]?[address.component]
                        == nil
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Array tuple component store is invalid, duplicated, or has the wrong type"
                    )
                }
                pending.elementComponents[address.index, default: [:]][
                    address.component
                ] = value
                pendingArrayLiterals[address.allocation] = pending
                return true
            }
            if let address = arrayLiteralAddresses[token] {
                guard var pending = pendingArrayLiterals[address.allocation],
                      address.index >= 0,
                      address.index < pending.count,
                      pending.elementType == valueType,
                      pending.elements[address.index] == nil,
                      pending.elementComponents[address.index] == nil
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Array literal store is invalid, duplicated, or has the wrong type"
                    )
                }
                pending.elements[address.index] = value
                pendingArrayLiterals[address.allocation] = pending
                return true
            }
            return false
        }

        // Hidden block parameters make alternate element initializers one SSA
        // value; commit it only in the block that finalizes this allocation.
        func applyMergedArrayLiteralWrites(
            to allocation: String
        ) throws {
            guard let blockID = current?.id,
                  let writes = compilerAddressWrites[blockID]
            else { return }
            let matching = writes.keys.filter { token in
                arrayLiteralAddresses[token]?.allocation == allocation
                    || arrayLiteralComponentAddresses[token]?.allocation
                        == allocation
            }.sorted()
            for token in matching {
                guard let value = writes[token],
                      try storePendingArrayLiteralValue(value, at: token)
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "merged Array literal write lost its element address"
                    )
                }
                compilerAddressWrites[blockID]?.removeValue(forKey: token)
            }
        }

        // Materialized values must cross this single sink so compiler-only
        // storage, runtime stack slots, scoped accesses, and projected
        // addresses preserve the same SIL initialization semantics.
        func storeVMValue(
            _ value: Bytecode.Register,
            at token: String,
            requestedMode: Bytecode.StackStoreMode? = nil
        ) throws {
            let valueType = registerTypes[Int(value.rawValue)]
            guard compilerAddressType(token) == valueType
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "store value does not match its stack address"
                )
            }
            invalidateOptionalStorageFacts(at: token)
            if try storePendingArrayLiteralValue(value, at: token) {
                return
            }
            guard let addressType = stackType(at: token) else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "store value does not reference represented storage"
                )
            }
            if let addressRegister = runtimeAddress(at: token) {
                let root = addressBase(token)
                let inferredMode = storageInitializationPlan.storeMode(
                    at: currentSILLineIndex,
                    address: token
                )
                let effectiveMode = requestedMode
                    ?? (initializingRuntimeAccesses.contains(token)
                        ? .initialize : inferredMode)
                if isScopedRuntimeAddress(token) {
                    appendInstruction(
                        .storeAddress(
                            address: addressRegister,
                            source: value,
                            mode: effectiveMode
                        )
                    )
                } else if let slot = runtimeStackSlots[root], token == root {
                    appendInstruction(
                        .storeStack(
                            slot: slot,
                            source: value,
                            mode: effectiveMode
                        )
                    )
                } else {
                    let access = try allocate(type: .address(addressType))
                    appendInstruction(
                        .beginAccess(
                            result: access,
                            address: addressRegister,
                            kind: .modify
                        )
                    )
                    appendInstruction(
                        .storeAddress(
                            address: access,
                            source: value,
                            mode: effectiveMode
                        )
                    )
                    appendInstruction(.endAccess(access))
                }
                // Runtime storage owns the consumed source. Never retain that
                // register as a compiler-address value: doing so would let a
                // later read bypass load/copy semantics after ownership moved.
                stackAddressValues.removeValue(forKey: root)
                initializingRuntimeAccesses.remove(token)
                return
            }
            let mode = requestedMode ?? storageInitializationPlan.storeMode(
                at: currentSILLineIndex,
                address: token
            )
            if mode != .initialize,
               let previous = try resolvedStackValue(
                at: token,
                line: currentSILLineIndex + 1
               ),
               previous != value,
               requiresManagedOwnership(
                   registerTypes[Int(previous.rawValue)]
               ),
               !values.contains(where: { candidate, registered in
                   registered == previous
                       && addressBase(candidate) != addressBase(token)
                       && hasFutureSemanticUse(
                           of: candidate,
                           after: currentSILLineIndex
                       )
               }) {
                // Compiler-only addresses elide VM storage instructions, but
                // assignment still ends the previous stored ownership unless
                // SIL first moved it into an SSA value whose later release is
                // the ownership endpoint.
                appendInstruction(.destroyValue(previous))
            }
            recordCompilerAddressValue(value, at: token)
            values[token] = value
            values[addressBase(token)] = value
        }

        func resolve(_ token: String, line: Int) throws -> Bytecode.Register {
            if let replacement = try reconstructedOptionalNone(
                for: token,
                line: line
            ) {
                return replacement
            }
            guard let register = values[token] else {
                throw CanonicalSIL.LoweringError.undefinedValue(line: line, value: token)
            }
            return register
        }

        func materializeUnitValue() throws -> Bytecode.Register {
            try materializeZeroSizedValue(type: ValueRepresentation.unit)
        }

        func materializeZeroSizedValue(
            type: Bytecode.ValueType
        ) throws -> Bytecode.Register {
            guard let aggregate = try typeEnvironment.zeroSizedAggregate(
                for: type
            ) else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "value type is not statically zero-sized"
                )
            }
            switch aggregate {
            case let .tuple(elementTypes):
                let elements = try elementTypes.map {
                    try materializeZeroSizedValue(type: $0)
                }
                let result = try allocate(type: type)
                appendInstruction(.makeTuple(result: result, elements: elements))
                return result
            case let .structure(key, fields):
                let values = try fields.map {
                    try materializeZeroSizedValue(type: $0.type)
                }
                let result = try allocate(type: .local(key))
                appendInstruction(.makeStruct(result: result, fields: values))
                return result
            }
        }

        func materializeStructFactoryValue(
            plan: CanonicalSIL.TypeEnvironment.StructFieldPlan,
            physicalValues: [Bytecode.Register]
        ) throws -> Bytecode.Register {
            switch plan {
            case let .parameter(index, type):
                guard physicalValues.indices.contains(index),
                      registerTypes[Int(physicalValues[index].rawValue)] == type
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "local struct initializer physical parameter does not match its plan"
                    )
                }
                return physicalValues[index]
            case let .tuple(type, elementPlans):
                guard case let .tuple(elementTypes) = type,
                      elementTypes.count == elementPlans.count
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "local struct initializer has an invalid tuple reconstruction plan"
                    )
                }
                let elements = try elementPlans.map {
                    try materializeStructFactoryValue(
                        plan: $0,
                        physicalValues: physicalValues
                    )
                }
                guard zip(elements, elementTypes).allSatisfy({ value, expected in
                    registerTypes[Int(value.rawValue)] == expected
                }) else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "local struct initializer tuple elements do not match their plan"
                    )
                }
                let result = try allocate(type: type)
                appendInstruction(.makeTuple(result: result, elements: elements))
                return result
            }
        }

        func resolveStorableValue(
            _ token: String,
            expectedType: Bytecode.ValueType? = nil,
            line: Int
        ) throws -> Bytecode.Register {
            if voidValues.contains(token) {
                let materializedType = expectedType ?? ValueRepresentation.unit
                guard materializedType == ValueRepresentation.unit else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Void value does not match its materialized storage type"
                    )
                }
                return try materializeUnitValue()
            }
            let value = try resolve(token, line: line)
            if let expectedType {
                let registerIndex = Int(value.rawValue)
                let actualType = registerTypes[registerIndex]
                if actualType != expectedType,
                   inlineOptionalNoneValues.contains(token),
                   case .optional(.never) = actualType,
                   case let .optional(expectedWrapped) = expectedType,
                   let physicalBlock = deferredNativeBlockNoneTypes[token],
                   isSupportedBlockBridgeSpelling(
                       physicalBlock,
                       to: expectedWrapped
                   ) {
                    // A deferred Clang block has no standalone VM type, while
                    // Optional.none has no payload. Rebind only that explicit
                    // placeholder; a concrete Optional<T>.none must still
                    // agree with the callee's frozen type.
                    registerTypes[registerIndex] = expectedType
                    return value
                }
                guard actualType == expectedType else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "stored value \(token) in \(displayName) at SIL line \(line) has type "
                            + "\(actualType), expected "
                            + "\(expectedType)"
                    )
                }
            }
            return value
        }

        func nativeCallbackParameterIndices(
            for binding: CanonicalSIL.DirectCallBinding
        ) -> Set<Int> {
            guard case let .nativeImport(requirement) = binding.target else {
                return []
            }
            return Set(requirement.contract.callbacks.map {
                Int($0.parameterIndex)
            })
        }

        func nativeCallbackParameterConventions(
            for binding: CanonicalSIL.DirectCallBinding
        ) -> [Int: Bytecode.ParameterConvention] {
            let indices = nativeCallbackParameterIndices(for: binding)
            return Dictionary(uniqueKeysWithValues: indices.map { index in
                (index, binding.parameterConventions[index])
            })
        }

        func preservesPhysicalClosureOwnership(
            for binding: CanonicalSIL.DirectCallBinding
        ) -> Bool {
            if case .nativeImport = binding.target { return true }
            return false
        }

        func physicalActorIsolationIsCompatible(
            _ physical: Core.Effects,
            authoritative: Core.Effects
        ) -> Bool {
            // Compiler thunks may erase a rooted MainActor annotation from
            // their printed function type. The inverse would silently grant
            // a nonisolated callable permission to execute actor-bound SIL.
            !physical.requiresMainActor
                || authoritative.requiresMainActor
        }

        func directCallArgumentsMatch(
            _ arguments: [Bytecode.Register],
            binding: CanonicalSIL.DirectCallBinding
        ) -> Bool {
            guard arguments.count == binding.parameterTypes.count else {
                return false
            }
            return zip(arguments, binding.parameterTypes).allSatisfy {
                argument, expected in
                registerTypes[Int(argument.rawValue)] == expected
            }
        }

        func prepareDirectCallArguments(
            _ tokens: [String],
            physicalConventions: [Bytecode.ParameterConvention],
            logicalTypes: [Bytecode.ValueType],
            nativeCallbackConventions: [Int: Bytecode.ParameterConvention] = [:],
            line: Int,
            allowsCompilerInoutWriteback: Bool
        ) throws -> PreparedDirectCallArguments {
            guard tokens.count == physicalConventions.count,
                  tokens.count == logicalTypes.count
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "direct call physical and logical argument counts disagree"
                )
            }
            let inoutIdentities = zip(tokens, physicalConventions)
                .compactMap { token, convention in
                    convention == .inout
                        ? compilerStorageIdentity(for: token) : nil
                }
            for index in inoutIdentities.indices {
                for other in inoutIdentities.indices where other > index {
                    let lhs = inoutIdentities[index]
                    let rhs = inoutIdentities[other]
                    guard lhs.root == rhs.root,
                          lhs.path.starts(with: rhs.path)
                            || rhs.path.starts(with: lhs.path)
                    else { continue }
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "direct call contains overlapping inout arguments"
                    )
                }
            }
            var arguments: [Bytecode.Register] = []
            var accesses: [Bytecode.Register] = []
            var temporaryOwners: [Bytecode.Register] = []
            var compilerInoutWritebacks: [
                PreparedDirectCallArguments.CompilerInoutWriteback
            ] = []
            arguments.reserveCapacity(tokens.count)
            for (index, pair) in zip(
                zip(tokens, physicalConventions),
                logicalTypes
            ).enumerated() {
                let ((token, convention), logicalType) = pair
                let value: Bytecode.Register
                if let boundaryConvention = nativeCallbackConventions[index] {
                    guard convention != .inout else {
                        throw CanonicalSIL.LoweringError.invalidCallTable(
                            "NativeImport callback parameters cannot use inout"
                        )
                    }
                    value = boundaryConvention == .owned
                        ? try prepareOwnedValue(
                            token,
                            expectedType: logicalType,
                            line: line
                        )
                        : try resolveStorableValue(
                            token,
                            expectedType: logicalType,
                            line: line
                        )
                    let actual = registerTypes[Int(value.rawValue)]
                    guard actual == logicalType else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "NativeImport callback argument does not match its callable ABI"
                        )
                    }
                    arguments.append(value)
                    continue
                }
                if case let .mutableCell(pointee) = logicalType {
                    guard let existing = mutableCell(at: token),
                          mutableCellPointee(at: token) == pointee
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "managed mutable argument is not backed by a matching cell"
                        )
                    }
                    value = existing
                    arguments.append(value)
                    continue
                }
                if convention == .inout,
                   runtimeAddress(at: token) == nil,
                   case let .address(pointee) = logicalType,
                   stackType(at: token) == pointee {
                    guard allowsCompilerInoutWriteback else {
                        throw CanonicalSIL.LoweringError
                            .unsupportedInstruction(
                                line: line,
                                text: "compiler-only inout writeback across try_apply"
                            )
                    }
                    let preservesAggregate = takenOptionalPayloadProjection(
                        at: token
                    )?.path.isEmpty == false
                    let initial = if preservesAggregate {
                        try copyStoredValue(at: token, line: line)
                    } else {
                        try takeStoredValue(at: token, line: line)
                    }
                    guard let initial,
                          registerTypes[Int(initial.rawValue)] == pointee
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "compiler-only inout argument is uninitialized"
                        )
                    }
                    let slot = try allocateStackSlot(type: pointee)
                    appendInstruction(
                        .storeStack(
                            slot: slot,
                            source: initial,
                            mode: .initialize
                        )
                    )
                    let address = try allocate(type: .address(pointee))
                    appendInstruction(.stackAddress(result: address, slot: slot))
                    let access = try allocate(type: .address(pointee))
                    appendInstruction(
                        .beginAccess(
                            result: access,
                            address: address,
                            kind: .modify
                        )
                    )
                    arguments.append(access)
                    accesses.append(access)
                    compilerInoutWritebacks.append(
                        .init(token: token, slot: slot, pointee: pointee)
                    )
                    continue
                }
                if convention == .inout {
                    value = try resolve(token, line: line)
                } else if stackType(at: token) == logicalType {
                    // The storage plan reflects physical SIL's `@in`
                    // spelling. Imported trivial values use that spelling
                    // without transferring a VM-native handle, so the
                    // normalized physical convention remains authoritative.
                    // Taking borrowed storage here would strand its original
                    // owner after the NativeImport boundary consumes a copy.
                    let consumes = convention == .owned
                        && storageInitializationPlan
                            .consumesApplicationArgument(
                                token,
                                at: currentSILLineIndex
                            )
                    let stored: Bytecode.Register?
                    if consumes {
                        stored = try takeStoredValue(at: token, line: line)
                    } else if convention == .borrowed,
                              requiresManagedOwnership(logicalType),
                              runtimeAddress(at: token) == nil {
                        stored = try resolvedStackValue(at: token, line: line)
                    } else {
                        stored = try copyStoredValue(at: token, line: line)
                        if convention == .borrowed,
                           requiresManagedOwnership(logicalType),
                           let stored {
                            temporaryOwners.append(stored)
                        }
                    }
                    guard let stored else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "address-backed call argument is uninitialized"
                        )
                    }
                    value = stored
                } else {
                    value = convention == .owned
                        ? try prepareOwnedValue(
                            token,
                            expectedType: logicalType,
                            line: line
                        )
                        : try resolveStorableValue(
                            token,
                            expectedType: logicalType,
                            line: line
                        )
                }
                guard convention == .inout else {
                    arguments.append(value)
                    continue
                }
                guard case let .address(pointee) = registerTypes[Int(value.rawValue)] else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "inout call argument is not an address"
                    )
                }
                if isScopedRuntimeAddress(token) {
                    arguments.append(value)
                    continue
                }
                let access = try allocate(type: .address(pointee))
                appendInstruction(
                    .beginAccess(result: access, address: value, kind: .modify)
                )
                arguments.append(access)
                accesses.append(access)
            }
            return .init(
                arguments: arguments,
                accesses: accesses,
                temporaryOwners: temporaryOwners,
                compilerInoutWritebacks: compilerInoutWritebacks
            )
        }

        func appendPreparedOwnerCleanups(
            _ prepared: PreparedDirectCallArguments
        ) {
            for owner in prepared.temporaryOwners {
                appendInstruction(.destroyValue(owner))
            }
        }

        func finishPreparedAccessesAndWritebacks(
            _ prepared: PreparedDirectCallArguments
        ) throws {
            for access in prepared.accesses.reversed() {
                appendInstruction(.endAccess(access))
            }
            for writeback in prepared.compilerInoutWritebacks {
                let value = try allocate(type: writeback.pointee)
                appendInstruction(
                    .loadStack(
                        result: value,
                        slot: writeback.slot,
                        mode: .take
                    )
                )
                try storeConstructedValue(value, at: writeback.token)
            }
        }

        func schedulePreparedContinuationCleanups(
            _ prepared: PreparedDirectCallArguments,
            in targets: [Bytecode.BlockID]
        ) throws {
            guard prepared.compilerInoutWritebacks.isEmpty else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "compiler-only inout writeback cannot cross call continuations"
                )
            }
            for target in targets {
                if !prepared.accesses.isEmpty {
                    guard implicitAccessCleanups[target] == nil else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "one continuation closes multiple synthetic access sets"
                        )
                    }
                    implicitAccessCleanups[target] = Array(
                        prepared.accesses.reversed()
                    )
                }
                for owner in prepared.temporaryOwners {
                    guard !implicitOwnerCleanups[target, default: []]
                        .contains(owner)
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "one borrowed call owner is cleaned twice on a successor"
                        )
                    }
                    implicitOwnerCleanups[target, default: []].append(owner)
                }
            }
        }

        func acceptsPhysicalConventions(
            _ physical: [Bytecode.ParameterConvention],
            for binding: CanonicalSIL.DirectCallBinding
        ) -> Bool {
            guard physical.count == binding.parameterConventions.count else {
                return false
            }
            switch binding.abiAdapter {
            case .direct:
                switch binding.target {
                case .function:
                    return zip(
                        zip(physical, binding.parameterConventions),
                        binding.parameterTypes
                    ).allSatisfy { pair, type in
                        if case .mutableCell = type {
                            return pair.1 == .owned
                                && [.owned, .borrowed, .inout].contains(pair.0)
                        }
                        return pair.0 == pair.1
                    }
                case .entry:
                    // Device boundaries own values. A guaranteed physical
                    // parameter is adapted with an explicit VM copy.
                    return !physical.contains(.inout)
                        && binding.parameterConventions.allSatisfy { $0 == .owned }
                case .nativeImport:
                    return zip(physical, binding.parameterConventions)
                        .allSatisfy { pair in
                        let (physical, logical) = pair
                        guard physical != .inout, logical != .inout else {
                            return false
                        }
                        // Nonescaping callback authority is borrowed all the
                        // way through the NativeImport, so a physical +1
                        // callback cannot be silently weakened. Escaping
                        // callbacks and ordinary logical parameters own their
                        // boundary value and may adapt a physical +0 argument
                        // with an explicit copy.
                        return logical == .owned || physical == .borrowed
                    }
                }
            case .mutatingValueReceiver:
                guard case .nativeImport = binding.target,
                      physical.last == .inout,
                      !physical.dropLast().contains(.inout)
                else { return false }
                return binding.parameterConventions.allSatisfy { $0 == .owned }
            case .staticKeyPathProjection:
                guard case .function = binding.target else { return false }
                return physical == binding.parameterConventions
            }
        }

        func resolveFunctionReferenceSet(
            bindings: [CanonicalSIL.DirectCallBinding],
            loweredType: String,
            bridgesPhysicalTypes: Bool,
            usesObjectiveCBridge: Bool,
            symbol: String,
            line: Int
        ) throws -> ResolvedFunctionReferenceSet {
            guard !bindings.isEmpty else {
                throw CanonicalSIL.LoweringError.unboundCallee(
                    line: line,
                    mangledName: symbol
                )
            }
            let physicalSpellings = try physicalValueParameterSpellings(
                in: loweredType
            )
            let variants: [ResolvedFunctionReference] = try bindings.map { binding in
                let bridge: (
                    parameters: [Bytecode.ValueType],
                    result: Bytecode.ValueType
                )? = bridgesPhysicalTypes
                    ? (binding.parameterTypes, binding.resultType) : nil
                let callee = try parseFunctionType(
                    loweredType,
                    bridgingTo: bridge,
                    parameterProjection: binding.parameterProjection,
                    abiAdapter: binding.abiAdapter,
                    preservingClosureOwnership:
                        preservesPhysicalClosureOwnership(for: binding),
                    allowingForeignABIRepresentation: usesObjectiveCBridge
                )
                guard callee.parameters == binding.parameterTypes,
                      acceptsPhysicalConventions(
                          callee.parameterConventions,
                          for: binding
                      ),
                      callee.result == binding.resultType,
                      callee.effects.mayThrow == binding.effects.mayThrow,
                      callee.effects.isAsync == binding.effects.isAsync,
                      physicalActorIsolationIsCompatible(
                          callee.effects,
                          authoritative: binding.effects
                      )
                else {
                    throw CanonicalSIL.LoweringError.callSignatureMismatch(
                        line: line,
                        mangledName: symbol,
                        detail: "actual \(callee.parameters) "
                            + "\(callee.parameterConventions) -> \(callee.result) "
                            + "\(callee.effects); expected \(binding.parameterTypes) "
                            + "\(binding.parameterConventions) -> "
                            + "\(binding.resultType) \(binding.effects)"
                    )
                }
                return ResolvedFunctionReference(
                    binding: binding,
                    physicalParameterConventions: callee.parameterConventions,
                    physicalValueParameterSpellings: physicalSpellings,
                    hasIndirectResult: callee.hasIndirectResult,
                    thrownType: callee.thrownType,
                    indirectErrorType: callee.indirectErrorType,
                    erasedMetatypes: callee.erasedMetatypes,
                    usesObjectiveCBridge: usesObjectiveCBridge
                )
            }
            return .init(variants: variants)
        }

        func resolveDeferredForeignReference(
            _ deferred: (reference: String, loweredType: String),
            genericArguments rawArguments: String,
            line: Int
        ) throws -> ResolvedFunctionReferenceSet {
            let genericArguments = splitTopLevel(rawArguments).filter { !$0.isEmpty }
            guard !genericArguments.isEmpty else {
                throw CanonicalSIL.LoweringError.unsupportedInstruction(
                    line: line,
                    text: "pseudogeneric Objective-C call has no concrete specialization"
                )
            }
            let symbol = CanonicalSIL.NativeBridgeSymbols.foreignCall(
                reference: deferred.reference,
                loweredType: deferred.loweredType,
                genericArguments: genericArguments
            )
            let bindings = directCalls.bindings(for: symbol)
            guard !bindings.isEmpty else {
                if let unavailable = directCalls.unavailableCall(for: symbol) {
                    throw CanonicalSIL.LoweringError.unavailableNativeImport(
                        line: line,
                        mangledName: symbol,
                        canonicalCallee: unavailable.canonicalCallee,
                        reason: unavailable.reason
                    )
                }
                throw CanonicalSIL.LoweringError.unboundCallee(
                    line: line,
                    mangledName: symbol
                )
            }
            return try resolveFunctionReferenceSet(
                bindings: bindings,
                loweredType: deferred.loweredType,
                bridgesPhysicalTypes: true,
                usesObjectiveCBridge: true,
                symbol: symbol,
                line: line
            )
        }

        func resolveDeferredGenericFunctionReference(
            _ deferred: DeferredGenericFunctionReference,
            genericArguments rawArguments: String,
            appliedLoweredType: String,
            line: Int
        ) throws -> (
            references: ResolvedFunctionReferenceSet,
            concreteLoweredType: String
        ) {
            guard CanonicalSIL.GenericFunction.validatesCallType(
                appliedLoweredType,
                against: deferred.loweredType
            ) else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: deferred.symbol,
                    detail: "generic apply changes its referenced SIL function type"
                )
            }
            let arguments: [String]
            do {
                arguments = try CanonicalSIL.GenericFunction.arguments(
                    in: rawArguments
                )
            } catch let error as CanonicalSIL.GenericFunction.SpecializationError {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: deferred.symbol,
                    detail: error.description
                )
            }
            let matching = deferred.bindings.filter {
                $0.genericSpecialization?.arguments == arguments
            }
            guard matching.count == 1,
                  let binding = matching.first,
                  let specialization = binding.genericSpecialization
            else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: deferred.symbol,
                    detail: "no unique image-local specialization matches <"
                        + arguments.joined(separator: ", ") + ">"
                )
            }
            let references = try resolveFunctionReferenceSet(
                bindings: [binding],
                loweredType: specialization.concreteLoweredType,
                bridgesPhysicalTypes: true,
                usesObjectiveCBridge: false,
                symbol: deferred.symbol,
                line: line
            )
            return (references, specialization.concreteLoweredType)
        }

        func eraseMetatypeArguments(
            _ tokens: [String],
            for reference: ResolvedFunctionReference,
            line: Int
        ) throws -> [String] {
            let physicalValueCount = Int(
                reference.binding.parameterProjection.physicalParameterCount
            )
            let totalPhysicalCount = physicalValueCount
                + reference.erasedMetatypes.count
            return try eraseMetatypeValues(
                tokens,
                physicalRange: 0..<totalPhysicalCount,
                for: reference,
                line: line,
                context: "direct call"
            )
        }

        func eraseMetatypeCaptures(
            _ tokens: [String],
            for reference: ResolvedFunctionReference,
            line: Int
        ) throws -> [String] {
            let totalPhysicalCount = Int(
                reference.binding.parameterProjection.physicalParameterCount
            ) + reference.erasedMetatypes.count
            guard tokens.count <= totalPhysicalCount else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "partial_apply captures more physical values than its callee accepts"
                )
            }
            let firstCapturedIndex = totalPhysicalCount - tokens.count
            return try eraseMetatypeValues(
                tokens,
                physicalRange: firstCapturedIndex..<totalPhysicalCount,
                for: reference,
                line: line,
                context: "partial_apply"
            )
        }

        func eraseMetatypeValues(
            _ tokens: [String],
            physicalRange: Range<Int>,
            for reference: ResolvedFunctionReference,
            line: Int,
            context: String
        ) throws -> [String] {
            let erasedByIndex = Dictionary(
                uniqueKeysWithValues: reference.erasedMetatypes.map {
                    ($0.physicalIndex, $0.identity)
                }
            )
            guard physicalRange.lowerBound >= 0,
                  physicalRange.count == tokens.count
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "\(context) physical argument count does not match its frozen ABI"
                )
            }
            var physicalValues: [String] = []
            physicalValues.reserveCapacity(tokens.count)
            for (offset, token) in tokens.enumerated() {
                let physicalIndex = physicalRange.lowerBound + offset
                if let identity = erasedByIndex[physicalIndex] {
                    guard staticMetatypeIdentities[token] == identity else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "\(context) metatype argument does not match its concrete type"
                        )
                    }
                } else {
                    physicalValues.append(token)
                }
            }
            return physicalValues
        }

        /// Metatypes erased from HLBC remain compiler facts when canonical SIL
        /// introduces ownership-neutral SSA aliases around a captured value.
        @discardableResult
        func aliasStaticMetatype(
            _ destination: String,
            from source: String,
            consuming: Bool = false
        ) -> Bool {
            guard let identity = staticMetatypeIdentities[source] else {
                return false
            }

            func transferMapping<Value>(_ values: inout [String: Value]) {
                guard let value = values[source] else { return }
                values[destination] = value
                if consuming { values.removeValue(forKey: source) }
            }

            func transferMembership(_ values: inout Set<String>) {
                guard values.contains(source) else { return }
                values.insert(destination)
                if consuming { values.remove(source) }
            }

            staticMetatypeIdentities[destination] = identity
            if consuming {
                staticMetatypeIdentities.removeValue(forKey: source)
            }
            transferMapping(&representedCollectionMetatypeIdentities)
            transferMapping(&scalarMetatypeValues)
            transferMembership(&compilerEnumMetatypeValues)
            transferMembership(&metatypeValues)
            transferMapping(&arrayMetatypeValues)
            transferMapping(&nativeMetatypeValues)
            transferMapping(&hostedMetatypeValues)
            transferMembership(&characterMetatypeValues)
            transferMapping(&localMetatypeValues)
            transferMapping(&progressionMetatypeValues)
            transferMapping(&partialRangeMetatypeValues)
            transferMapping(&dictionaryMetatypeValues)
            transferMapping(&setMetatypeValues)
            transferMembership(&stringInterpolationMetatypes)
            return true
        }

        func projectNativeImportArguments(
            _ physicalTokens: [String],
            for reference: ResolvedFunctionReference,
            line: Int
        ) throws -> [String] {
            let binding = reference.binding
            let projection = binding.parameterProjection
            guard physicalTokens.count == Int(projection.physicalParameterCount)
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "NativeImport physical argument count does not match its frozen projection"
                )
            }
            guard case .nativeImport = binding.target else {
                guard projection.omittedPhysicalParameterIndices.isEmpty else {
                    throw CanonicalSIL.LoweringError.invalidCallTable(
                        "only a NativeImport may omit physical call arguments"
                    )
                }
                return physicalTokens
            }
            let selected = Set(projection.logicalParameterIndices.map(Int.init))
            for index in selected {
                let token = physicalTokens[index]
                let address = addressBase(token)
                guard externalDefaultArgumentAddresses[address] == nil,
                      externalDefaultArgumentValues[token] == nil
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "NativeImport selected a compiler default argument as an explicit value"
                    )
                }
            }
            let defaults = Dictionary(
                uniqueKeysWithValues: projection.defaultArguments.map {
                    (Int($0.physicalParameterIndex), $0)
                }
            )
            for (index, token) in physicalTokens.enumerated()
            where !selected.contains(index) {
                guard reference.physicalValueParameterSpellings.indices
                    .contains(index),
                      let defaultArgument = defaults[index]
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "NativeImport projection has no physical default descriptor"
                    )
                }
                let expectedDefaultType = try parseStoredType(
                    reference.physicalValueParameterSpellings[index]
                )
                let address = addressBase(token)
                switch defaultArgument.origin {
                case .externalGenerator:
                    guard let generatorSymbol = defaultArgument.generatorSymbol else {
                        throw CanonicalSIL.LoweringError.invalidCallTable(
                            "NativeImport external default has no generator symbol"
                        )
                    }
                    if var value = externalDefaultArgumentAddresses[address] {
                        guard value.ownerSymbols.contains(binding.mangledName),
                              value.generatorSymbol == generatorSymbol,
                              !value.isConsumed,
                              value.valueType == expectedDefaultType
                        else {
                            throw CanonicalSIL.LoweringError.malformedSIL(
                                "NativeImport default argument address has the wrong owner, generator, type, or lifetime"
                            )
                        }
                        value.isConsumed = true
                        externalDefaultArgumentAddresses[address] = value
                        continue
                    }
                    if var value = externalDefaultArgumentValues[token] {
                        guard value.ownerSymbols.contains(binding.mangledName),
                              value.generatorSymbol == generatorSymbol,
                              !value.isProjected,
                              value.valueType == expectedDefaultType
                        else {
                            throw CanonicalSIL.LoweringError.malformedSIL(
                                "NativeImport default argument value has the wrong owner, generator, or type"
                            )
                        }
                        let physicalSpelling = reference
                            .physicalValueParameterSpellings[index]
                        if hasExplicitBorrowedValueConvention(
                            physicalSpelling
                        ),
                           !expectedDefaultType.isTrivial {
                            // The physical +0 call leaves the generator's +1
                            // nontrivial result alive for its following Swift
                            // ownership cleanup. Retain only compiler
                            // provenance; no VM value exists.
                            value.isProjected = true
                            externalDefaultArgumentValues[token] = value
                        } else {
                            externalDefaultArgumentValues.removeValue(
                                forKey: token
                            )
                        }
                        continue
                    }
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "NativeImport omitted physical parameter is not the frozen default generator"
                    )
                case .optionalNone:
                    guard inlineOptionalNoneValues.remove(token) != nil else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "NativeImport omitted physical parameter is not Optional.none"
                        )
                    }
                    deferredNativeBlockNoneTypes.removeValue(forKey: token)
                    // Clang-imported Optional defaults such as `group: nil`
                    // are emitted directly rather than through an fA helper.
                    // Preserve the physical apply's ownership edge even
                    // though the default-only parameter is projected away.
                    let value = try resolve(token, line: line)
                    guard case .optional = registerTypes[Int(value.rawValue)],
                          registerTypes[Int(value.rawValue)]
                            == expectedDefaultType
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "NativeImport inline default argument is not the expected Optional.none"
                        )
                    }
                    if requiresManagedOwnership(
                        registerTypes[Int(value.rawValue)]
                    ) {
                        // Projection removes the value from the physical call,
                        // so retire its VM owner independently of whether SIL
                        // passed that owner +0 or +1. Any later destroy/release
                        // is compiler ownership plumbing for this same erased
                        // SSA value and must not release it twice.
                        try closeBorrowedTemporaryLifetime(
                            for: token,
                            resolved: value
                        )
                        try closeCompilerOwnedTemporaryLifetime(
                            for: token,
                            resolved: value
                        )
                        appendInstruction(.destroyValue(value))
                        projectedInlineOptionalNoneOwners.insert(value)
                    }
                }
            }
            return projection.logicalParameterIndices.map {
                physicalTokens[Int($0)]
            }
        }

        func nativeImportProjectionMatches(
            _ physicalTokens: [String],
            reference: ResolvedFunctionReference
        ) throws -> Bool {
            let binding = reference.binding
            let projection = binding.parameterProjection
            guard case .nativeImport = binding.target,
                  physicalTokens.count == Int(projection.physicalParameterCount)
            else { return false }
            let selected = Set(projection.logicalParameterIndices.map(Int.init))
            let defaults = Dictionary(
                uniqueKeysWithValues: projection.defaultArguments.map {
                    (Int($0.physicalParameterIndex), $0)
                }
            )
            for (index, token) in physicalTokens.enumerated() {
                let address = addressBase(token)
                if selected.contains(index) {
                    if externalDefaultArgumentAddresses[address] != nil
                        || externalDefaultArgumentValues[token] != nil {
                        return false
                    }
                    continue
                }
                guard let descriptor = defaults[index],
                      reference.physicalValueParameterSpellings.indices
                        .contains(index)
                else { return false }
                let expected = try parseStoredType(
                    reference.physicalValueParameterSpellings[index]
                )
                switch descriptor.origin {
                case .externalGenerator:
                    guard let generator = descriptor.generatorSymbol else {
                        return false
                    }
                    if let value = externalDefaultArgumentAddresses[address] {
                        guard value.ownerSymbols.contains(binding.mangledName),
                              value.generatorSymbol == generator,
                              !value.isConsumed,
                              value.valueType == expected
                        else { return false }
                    } else if let value = externalDefaultArgumentValues[token] {
                        guard value.ownerSymbols.contains(binding.mangledName),
                              value.generatorSymbol == generator,
                              value.valueType == expected
                        else { return false }
                    } else {
                        return false
                    }
                case .optionalNone:
                    guard inlineOptionalNoneValues.contains(token),
                          let value = values[token],
                          registerTypes[Int(value.rawValue)] == expected,
                          case .optional = expected
                    else { return false }
                }
            }
            return true
        }

        func selectFunctionReference(
            _ references: ResolvedFunctionReferenceSet,
            physicalTokens: [String],
            line: Int
        ) throws -> ResolvedFunctionReference {
            guard references.variants.count > 1 else {
                guard let reference = references.sole else {
                    throw CanonicalSIL.LoweringError.invalidCallTable(
                        "function reference has no frozen call variant"
                    )
                }
                return reference
            }
            let matching = try references.variants.filter {
                try nativeImportProjectionMatches(
                    physicalTokens,
                    reference: $0
                )
            }
            guard let minimumCount = matching.map({
                $0.binding.parameterTypes.count
            }).min() else {
                let evidence = physicalTokens.enumerated().map { index, token in
                    let address = addressBase(token)
                    if let value = externalDefaultArgumentAddresses[address] {
                        return "\(index)=generator@\(value.generatorSymbol)"
                    }
                    if let value = externalDefaultArgumentValues[token] {
                        return "\(index)=generator@\(value.generatorSymbol)"
                    }
                    if inlineOptionalNoneValues.contains(token) {
                        return "\(index)=Optional.none"
                    }
                    return "\(index)=explicit"
                }.joined(separator: ",")
                let variants = references.variants.map { reference in
                    let projection = reference.binding.parameterProjection
                    let defaults = projection.defaultArguments.map { argument in
                        switch argument.origin {
                        case .externalGenerator:
                            "\(argument.physicalParameterIndex)=generator@"
                                + (argument.generatorSymbol ?? "<missing>")
                        case .optionalNone:
                            "\(argument.physicalParameterIndex)=Optional.none"
                        }
                    }.joined(separator: ",")
                    return "[\(projection.logicalParameterIndices)]{\(defaults)}"
                }.joined(separator: ";")
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: references.variants[0].binding.mangledName,
                    detail: "no frozen source-call variant matches the physical default arguments; "
                        + "evidence \(evidence); variants \(variants)"
                )
            }
            // Canonicalize every value whose provenance exactly matches a
            // frozen default. Swift can emit the same physical Optional.none
            // for an omitted argument and for an explicit `nil`; both have
            // identical semantics, while retaining the larger projection
            // would manufacture an unnecessary linear Optional owner.
            let mostCanonical = matching.filter {
                $0.binding.parameterTypes.count == minimumCount
            }
            guard mostCanonical.count == 1, let selected = mostCanonical.first else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: references.variants[0].binding.mangledName,
                    detail: "physical default arguments match multiple equally canonical frozen source-call variants"
                )
            }
            return selected
        }

        func lowerExternalDefaultArgumentGenerator(
            _ generator: ExternalDefaultArgumentGenerator,
            resultToken: String,
            genericArguments: String,
            argumentText: String,
            appliedLoweredType: String,
            line: Int
        ) throws {
            guard genericArguments.isEmpty else {
                throw CanonicalSIL.LoweringError.unsupportedInstruction(
                    line: line,
                    text: "generic external default argument"
                )
            }
            let referenceType = try parseFunctionType(generator.loweredType)
            let appliedType = try parseFunctionType(appliedLoweredType)
            guard referenceType.parameters.isEmpty,
                  referenceType.parameterConventions.isEmpty,
                  referenceType.erasedMetatypes.isEmpty,
                  referenceType.result != .void,
                  referenceType.effects == .init(),
                  appliedType.parameters == referenceType.parameters,
                  appliedType.parameterConventions
                    == referenceType.parameterConventions,
                  appliedType.result == referenceType.result,
                  appliedType.hasIndirectResult
                    == referenceType.hasIndirectResult,
                  appliedType.indirectErrorType == nil,
                  appliedType.effects == referenceType.effects
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "external default-argument helper changes its physical ABI"
                )
            }
            var arguments = try parseApplyValueTokens(
                argumentText,
                line: line
            )
            let destinations = try consumeIndirectCallDestinations(
                from: &arguments,
                resultType: referenceType.result,
                hasIndirectResult: referenceType.hasIndirectResult,
                indirectErrorType: nil,
                physicalArgumentCount: 0
            )
            guard arguments.isEmpty, destinations.error == nil else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "external default-argument helper has runtime inputs"
                )
            }
            if let destination = destinations.result {
                let root = addressBase(destination)
                guard !resultToken.isEmpty,
                      stackType(at: destination) == referenceType.result,
                      stackAddressValues[root] == nil,
                      externalDefaultArgumentAddresses[root] == nil
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "external default argument has invalid indirect storage"
                    )
                }
                externalDefaultArgumentAddresses[root] = .init(
                    ownerSymbols: generator.ownerSymbols,
                    generatorSymbol: generator.symbol,
                    valueType: referenceType.result
                )
                voidValues.insert(resultToken)
            } else {
                guard !resultToken.isEmpty,
                      externalDefaultArgumentValues.updateValue(
                        .init(
                            ownerSymbols: generator.ownerSymbols,
                            generatorSymbol: generator.symbol,
                            valueType: referenceType.result
                        ),
                        forKey: resultToken
                      ) == nil
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "external default argument has no unique direct result"
                    )
                }
            }
        }

        func adaptBoundaryArguments(
            _ arguments: [Bytecode.Register],
            physicalConventions: [Bytecode.ParameterConvention],
            binding: CanonicalSIL.DirectCallBinding
        ) throws -> [Bytecode.Register] {
            switch binding.target {
            case .function:
                return arguments
            case .entry:
                return try zip(arguments, physicalConventions).map {
                    argument, physical in
                    physical == .borrowed
                        ? try copyOwnedValue(argument)
                        : argument
                }
            case .nativeImport:
                return try zip(
                    zip(arguments, physicalConventions),
                    binding.parameterConventions
                ).map { pair, logical in
                    let (argument, physical) = pair
                    return physical == .borrowed && logical == .owned
                        ? try copyOwnedValue(argument)
                        : argument
                }
            }
        }

        func transferOwnedCompilerAddressArguments(
            tokens: [String],
            resolvedArguments: [Bytecode.Register],
            conventions: [Bytecode.ParameterConvention],
            forceOwnedTokens: Set<String> = []
        ) throws {
            guard tokens.count == resolvedArguments.count,
                  tokens.count == conventions.count
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "owned call argument transfer has inconsistent arity"
                )
            }
            for ((token, argument), convention) in zip(
                zip(tokens, resolvedArguments),
                conventions
            ) where convention == .owned {
                let root = addressBase(token)
                guard runtimeAddress(at: token) == nil,
                      mutableCell(at: token) == nil
                else { continue }
                let consumes = storageInitializationPlan
                    .consumesApplicationArgument(
                        token,
                        at: currentSILLineIndex
                    ) || forceOwnedTokens.contains(token)
                guard consumes else { continue }
                guard let stored = stackValue(at: token) else { continue }
                guard stored == argument else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "owned call argument does not match its compiler address storage"
                    )
                }

                // An `@in` SIL argument transfers the value stored at its
                // compiler-only address into the callee. HLBC passes that same
                // value directly, so the later dealloc_stack must not release
                // it a second time.
                removeCompilerAddressValue(at: token)
                for key in [root, token] where values[key] == argument {
                    values.removeValue(forKey: key)
                }
            }
        }

        func appendCompilerAddressMergeArguments(
            target: Bytecode.BlockID,
            arguments: inout [Bytecode.Register]
        ) throws {
            guard let sourceBlock = current?.id,
                  let writes = compilerAddressWrites[sourceBlock]
            else { return }
            for (address, value) in writes.sorted(by: { $0.key < $1.key }) {
                let type = registerTypes[Int(value.rawValue)]
                let merge: Bytecode.Register
                if let existing = compilerAddressMergeRegisters[target]?[address] {
                    guard registerTypes[Int(existing.rawValue)] == type else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "compiler address merge has inconsistent value types"
                        )
                    }
                    merge = existing
                } else {
                    merge = try allocate(type: type)
                    compilerAddressMergeRegisters[target, default: [:]][address] = merge
                    implicitStackValues[target, default: []].append(
                        .init(address, merge)
                    )
                }
                arguments.append(value)
            }
        }

        func inheritCompilerAddressValue(
            _ value: Bytecode.Register,
            at address: String,
            into targets: [Bytecode.BlockID]
        ) throws {
            let root = addressBase(address)
            guard stackType(at: root) == registerTypes[Int(value.rawValue)] else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "inherited compiler address value has the wrong VM type"
                )
            }
            for target in targets {
                if let existing = inheritedCompilerAddressValues[target]?[root],
                   existing != value {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "compiler address reaches one block with multiple unmerged values"
                    )
                }
                inheritedCompilerAddressValues[target, default: [:]][root] = value
            }
        }

        func materializeIntegerOperand(
            _ token: String,
            expected: Bytecode.ValueType,
            line: Int
        ) throws -> Bytecode.Register {
            let original = try resolve(token, line: line)
            let originalType = registerTypes[Int(original.rawValue)]
            if originalType == expected { return original }
            if let cached = retypedIntegerOperands[token]?[expected] { return cached }
            if case let .integer(expectedWidth, _) = expected,
               case let .integer(actualWidth, _) = originalType,
               actualWidth == expectedWidth {
                // Swift's raw overflow builtins encode signedness at the use
                // site. Phi values therefore cannot rely on the declaration's
                // default literal signedness; preserving their bits is the
                // only representation-correct conversion.
                let result = try allocate(type: expected)
                appendInstruction(
                    .integerConvert(
                        result: result,
                        operation: .reinterpret,
                        value: original
                    )
                )
                retypedIntegerOperands[token, default: [:]][expected] = result
                return result
            }
            guard case let .integer(bitWidth, _) = expected,
                  let literal = integerLiterals[token],
                  literal.bitWidth == bitWidth
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "integer literal does not match its builtin signedness"
                )
            }
            let result = try allocate(type: expected)
            appendInstruction(
                .constantInteger(result: result, bitPattern: literal.bitPattern)
            )
            retypedIntegerOperands[token, default: [:]][expected] = result
            return result
        }

        func integerOperandType(
            bitWidth: UInt16,
            signedness: Bool?,
            lhsToken: String,
            lhs: Bytecode.Register,
            rhsToken: String,
            rhs: Bytecode.Register
        ) -> Bytecode.ValueType? {
            if bitWidth == 1 { return .bool }
            if let signedness {
                return .integer(bitWidth: bitWidth, signed: signedness)
            }
            let candidates = [(lhsToken, lhs), (rhsToken, rhs)]
            for (token, register) in candidates where integerLiterals[token] == nil {
                if case let .integer(width, signed) = registerTypes[Int(register.rawValue)],
                   width == bitWidth {
                    return .integer(bitWidth: width, signed: signed)
                }
            }
            for (_, register) in candidates {
                if case let .integer(width, signed) = registerTypes[Int(register.rawValue)],
                   width == bitWidth {
                    return .integer(bitWidth: width, signed: signed)
                }
            }
            return nil
        }

        func finishCurrent() {
            if let current { blocks.append(current) }
            current = nil
        }

        func normalizeBuiltinIntegerBranchArguments(
            _ arguments: inout [Bytecode.Register],
            target: Bytecode.BlockID
        ) throws {
            let expectedTypes: [Bytecode.ValueType]
            if let targetBlock = if current?.id == target {
                current
            } else {
                blocks.last(where: { $0.id == target })
            } {
                expectedTypes = targetBlock.parameters.map {
                    registerTypes[Int($0.rawValue)]
                }
            } else {
                expectedTypes = (declaredBlockParameterTypes[target] ?? [])
                    + (implicitStackValues[target] ?? []).map {
                        registerTypes[Int($0.register.rawValue)]
                    }
            }
            guard expectedTypes.count == arguments.count else { return }

            for index in arguments.indices {
                let source = arguments[index]
                let sourceType = registerTypes[Int(source.rawValue)]
                let destinationType = expectedTypes[index]
                guard sourceType != destinationType,
                      case let .integer(sourceWidth, _) = sourceType,
                      case let .integer(destinationWidth, _) = destinationType,
                      sourceWidth == destinationWidth
                else { continue }

                // SIL's Builtin.IntN spelling carries no signedness. HLBC
                // does, so phi edges preserve the raw bits while adopting the
                // target block's representation instead of rejecting a legal
                // signed/unsigned use-site interpretation.
                let normalized = try allocate(type: destinationType)
                appendInstruction(
                    .integerConvert(
                        result: normalized,
                        operation: .reinterpret,
                        value: source
                    )
                )
                arguments[index] = normalized
            }
        }

        func appendSyntheticBlock(
            id: Bytecode.BlockID,
            parameters: [Bytecode.Register] = [],
            instructions: [IntermediateRepresentation.Instruction]
        ) {
            retainFlow.recordSyntheticBlock(
                id: id,
                instructions: instructions
            )
            blocks.append(
                .init(
                    id: id,
                    parameters: parameters,
                    instructions: instructions
                )
            )
            if let currentSourceLocation {
                for offset in instructions.indices {
                    guard let instructionOffset = UInt32(exactly: offset) else {
                        break
                    }
                    sourceMap.append(
                        .init(
                            blockID: id,
                            instructionOffset: instructionOffset,
                            location: currentSourceLocation
                        )
                    )
                }
            }
        }

        func appendConditionalTrap(
            condition: Bytecode.Register,
            reason: Bytecode.TrapReason
        ) throws {
            guard registerTypes[Int(condition.rawValue)] == .bool else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "conditional trap requires a Bool condition"
                )
            }
            let trapID = try allocateSyntheticBlockID()
            let continuationID = try allocateSyntheticBlockID()
            appendInstruction(
                .conditionalBranch(
                    condition: condition,
                    trueTarget: trapID,
                    trueArguments: [],
                    falseTarget: continuationID,
                    falseArguments: []
                )
            )
            finishCurrent()
            appendSyntheticBlock(id: trapID, instructions: [.trap(reason)])
            retainFlow.activate(continuationID)
            current = IntermediateRepresentation.Block(
                id: continuationID,
                parameters: [],
                instructions: []
            )
        }

        /// A compiler-only enum case is statically known, but canonical SIL
        /// still contains every switch successor. Preserve those CFG edges so
        /// verifier reachability and phi validation continue to describe the
        /// complete source function while execution takes only the selected
        /// case.
        func appendStaticBranch(
            selected: Bytecode.BlockID,
            preserving targets: [Bytecode.BlockID]
        ) throws {
            var seen = Set<Bytecode.BlockID>()
            let alternatives = targets.filter {
                $0 != selected && seen.insert($0).inserted
            }
            guard !alternatives.isEmpty else {
                appendInstruction(.branch(target: selected, arguments: []))
                return
            }

            let syntheticBlocks = try alternatives.map { _ in
                try allocateSyntheticBlockID()
            }
            let selectKnownCase = try allocate(type: .bool)
            appendInstruction(
                .constantBool(result: selectKnownCase, value: true)
            )
            appendInstruction(
                .conditionalBranch(
                    condition: selectKnownCase,
                    trueTarget: selected,
                    trueArguments: [],
                    falseTarget: syntheticBlocks[0],
                    falseArguments: []
                )
            )
            finishCurrent()

            for index in alternatives.indices {
                let exposeAlternative = try allocate(type: .bool)
                let next = syntheticBlocks.indices.contains(index + 1)
                    ? syntheticBlocks[index + 1]
                    : selected
                appendSyntheticBlock(
                    id: syntheticBlocks[index],
                    instructions: [
                        .constantBool(
                            result: exposeAlternative,
                            value: false
                        ),
                        .conditionalBranch(
                            condition: exposeAlternative,
                            trueTarget: alternatives[index],
                            trueArguments: [],
                            falseTarget: next,
                            falseArguments: []
                        ),
                    ]
                )
            }
        }

        func materializeArrayLiteralElements(
            _ pending: PendingArrayLiteral
        ) throws -> [Bytecode.Register] {
            var result: [Bytecode.Register] = []
            result.reserveCapacity(pending.count)
            for index in 0..<pending.count {
                if let element = pending.elements[index] {
                    guard pending.elementComponents[index] == nil else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Array literal element mixes whole-value and component stores"
                        )
                    }
                    result.append(element)
                    continue
                }
                if try typeEnvironment.isStaticallyZeroSized(
                    pending.elementType
                ) {
                    guard pending.elementComponents[index] == nil else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "zero-sized Array literal element has component stores"
                        )
                    }
                    result.append(
                        try materializeZeroSizedValue(type: pending.elementType)
                    )
                    continue
                }
                guard case let .tuple(types) = pending.elementType
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Array literal element is incomplete"
                    )
                }
                let components = pending.elementComponents[index] ?? [:]
                var registers: [Bytecode.Register] = []
                registers.reserveCapacity(types.count)
                for index in types.indices {
                    if let component = components[index] {
                        registers.append(component)
                        continue
                    }
                    guard try typeEnvironment.isStaticallyZeroSized(
                        types[index]
                    ) else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Array literal tuple component is missing"
                        )
                    }
                    registers.append(
                        try materializeZeroSizedValue(type: types[index])
                    )
                }
                let tuple = try allocate(type: pending.elementType)
                appendInstruction(.makeTuple(result: tuple, elements: registers))
                result.append(tuple)
            }
            return result
        }

        func compilerAddressType(_ token: String) -> Bytecode.ValueType? {
            if token == indirectResultAddress { return signature.result }
            if token == indirectErrorAddress {
                return signature.indirectErrorType
            }
            if let component = tupleComponentAddresses[token],
               case let .tuple(types) = compilerAddressType(component.base),
               types.indices.contains(component.index) {
                return types[component.index]
            }
            if let root = optionalPayloadAddressRoots[token],
               let initialization = optionalAddressInitializations[root] {
                return initialization.wrappedType
            }
            if let projection = existentialProjections[token] {
                return projection.storageType
            }
            if let component = existentialComponentAddresses[token],
               let projection = existentialProjections[component.projection],
               case let .tuple(types) = projection.storageType,
               types.indices.contains(component.index) {
                return types[component.index]
            }
            if let address = arrayLiteralAddresses[token],
               let pending = pendingArrayLiterals[address.allocation] {
                return pending.elementType
            }
            if let address = arrayLiteralComponentAddresses[token],
               let pending = pendingArrayLiterals[address.allocation],
               case let .tuple(types) = pending.elementType,
               types.indices.contains(address.component) {
                return types[address.component]
            }
            return stackType(at: token)
        }

        func consumeIndirectCallDestinations(
            from argumentTokens: inout [String],
            resultType: Bytecode.ValueType,
            hasIndirectResult: Bool,
            indirectErrorType: Bytecode.ValueType?,
            physicalArgumentCount: Int
        ) throws -> IndirectCallDestinations {
            let hiddenCount = (hasIndirectResult ? 1 : 0)
                + (indirectErrorType == nil ? 0 : 1)
            let expectedCount = physicalArgumentCount.addingReportingOverflow(
                hiddenCount
            )
            guard !expectedCount.overflow,
                  argumentTokens.count == expectedCount.partialValue
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "call argument count does not match its physical result ABI"
                )
            }

            var resultDestination: String?
            if hasIndirectResult {
                guard resultType == .void || supportsIndirectResult(resultType) else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "indirect call result \(resultType)"
                    )
                }
                let destination = argumentTokens.removeFirst()
                let destinationType = compilerAddressType(destination)
                guard destinationType == resultType
                        || destinationType
                            == ValueRepresentation.storable(resultType)
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "indirect call result address does not match its result type"
                    )
                }
                resultDestination = destination
            }

            var errorDestination: String?
            if let indirectErrorType {
                let destination = argumentTokens.removeFirst()
                guard compilerAddressType(destination) == indirectErrorType else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "indirect call Error address does not match its error type"
                    )
                }
                errorDestination = destination
            }
            return .init(result: resultDestination, error: errorDestination)
        }

        func bindIndirectTryCallDestinations(
            _ destinations: IndirectCallDestinations,
            resultType: Bytecode.ValueType,
            indirectErrorType: Bytecode.ValueType?,
            normalTarget: Bytecode.BlockID,
            errorTarget: Bytecode.BlockID
        ) throws {
            if destinations.result != nil
                || resultType == .void
                || resultType == .never {
                let suppressedType: Bytecode.ValueType = resultType == .never
                    ? .never : .void
                guard implicitStackValues[normalTarget] == nil,
                      suppressedTryNormalParameterTypes.updateValue(
                        suppressedType,
                        forKey: normalTarget
                      ) == nil
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "uninhabited or indirect call normal continuation is shared"
                    )
                }
                if let destination = destinations.result,
                   resultType != .void {
                    let result = try allocate(type: resultType)
                    implicitStackValues[normalTarget] = [.init(destination, result)]
                }
            }

            if let destination = destinations.error {
                guard let runtimeErrorType = indirectErrorType,
                      runtimeErrorType != .never,
                      implicitStackValues[errorTarget] == nil
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "indirect call Error continuation does not match its image"
                    )
                }
                let error = try allocate(type: runtimeErrorType)
                implicitStackValues[errorTarget] = [.init(destination, error)]
            }
        }

        func materializeMutableCapture(
            at token: String,
            pointee: Bytecode.ValueType,
            line: Int,
            permitsBorrowedInout: Bool
        ) throws -> Bytecode.Register {
            if let existing = mutableCell(at: token) {
                guard mutableCellPointee(at: token) == pointee else {
                    throw CanonicalSIL.LoweringError.callSignatureMismatch(
                        line: line,
                        mangledName: "mutable closure capture"
                    )
                }
                return existing
            }
            let root = addressBase(token)
            if inoutParameterAddressBases.contains(root) {
                guard permitsBorrowedInout,
                      let address = runtimeAddress(at: token),
                      stackType(at: token) == pointee,
                      isScopedRuntimeAddress(token)
                else {
                    throw CanonicalSIL.LoweringError.unsupportedInstruction(
                        line: line,
                        text: "an escaping closure cannot capture caller-owned inout storage"
                    )
                }
                let cell = try allocate(type: .mutableCell(pointee))
                appendInstruction(
                    .borrowMutableCell(result: cell, address: address)
                )
                return cell
            }
            guard token == root,
                  stackAddressTypes[root] == pointee
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "mutable closure capture must reference matching local storage"
                )
            }

            let initialValue: Bytecode.Register
            if let slot = runtimeStackSlots[root] {
                initialValue = try allocate(type: pointee)
                appendInstruction(
                    .loadStack(result: initialValue, slot: slot, mode: .take)
                )
            } else {
                guard runtimeAddress(at: root) == nil else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "mutable closure capture references unsupported storage"
                    )
                }
                guard let value = try resolvedStackValue(
                    at: root,
                    line: line
                ) else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "mutable closure capture references unsupported storage"
                    )
                }
                guard registerTypes[Int(value.rawValue)] == pointee else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "mutable closure capture storage has the wrong type"
                    )
                }
                initialValue = value
            }
            stackAddressValues.removeValue(forKey: root)
            removeAggregateComponentValues(rootedAt: root)

            let cell = try allocate(type: .mutableCell(pointee))
            appendInstruction(
                .makeMutableCell(result: cell, initialValue: initialValue)
            )
            mutableCaptureState.addresses[root] = .init(
                register: cell,
                pointee: pointee
            )
            values[root] = cell
            return cell
        }

        func takenOptionalPayloadProjection(
            at token: String
        ) -> (root: String, path: [Int], state: TakenOptionalPayload)? {
            var current = token
            var reversedPath: [Int] = []
            var visited = Set<String>()
            while visited.insert(current).inserted {
                if let state = takenOptionalPayloads[current] {
                    return (
                        root: current,
                        path: Array(reversedPath.reversed()),
                        state: state
                    )
                }
                if let component = aggregateComponentAddresses[current] {
                    reversedPath.append(component.index)
                    current = component.base
                    continue
                }
                let canonical = addressBase(current)
                guard canonical != current else { return nil }
                current = canonical
            }
            return nil
        }

        /// Rebuilds only the aggregate spine containing a projected write.
        /// Sibling values are carried forward in declaration order, so this
        /// supports nested tuples and patch-local structs without a nominal- or
        /// API-specific setter table.
        func replacingAggregateProjection(
            in currentValue: Bytecode.Register,
            type: Bytecode.ValueType,
            path: ArraySlice<Int>,
            prefix: [Int] = [],
            with replacement: Bytecode.Register,
            preservingCurrentValue: Bool = false,
            updatedValues: inout [[Int]: Bytecode.Register]
        ) throws -> Bytecode.Register {
            guard registerTypes[Int(currentValue.rawValue)] == type else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "projected aggregate writeback has a mismatched value"
                )
            }
            guard let fieldIndex = path.first else {
                guard registerTypes[Int(replacement.rawValue)] == type else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "projected aggregate writeback has a mismatched replacement"
                    )
                }
                if currentValue != replacement,
                   !preservingCurrentValue,
                   !type.isTrivial {
                    appendInstruction(.destroyValue(currentValue))
                }
                updatedValues[prefix] = replacement
                return replacement
            }

            let childTypes: [Bytecode.ValueType]
            let children: [Bytecode.Register]
            let rebuild: ([Bytecode.Register]) throws -> Bytecode.Register
            switch type {
            case let .tuple(types):
                guard types.indices.contains(fieldIndex) else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "projected Optional tuple writeback is out of bounds"
                    )
                }
                let projectionSource = preservingCurrentValue
                    && requiresManagedOwnership(type)
                    ? try copyOwnedValue(currentValue)
                    : currentValue
                childTypes = types
                children = try types.map { try allocate(type: $0) }
                appendInstruction(
                    .unpackTuple(results: children, tuple: projectionSource)
                )
                rebuild = { fields in
                    let result = try allocate(type: type)
                    appendInstruction(
                        .makeTuple(result: result, elements: fields)
                    )
                    return result
                }
            case let .local(key):
                let fields = try typeEnvironment.structFields(for: key)
                guard fields.indices.contains(fieldIndex) else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "projected Optional struct writeback is out of bounds"
                    )
                }
                childTypes = fields.map(\.type)
                children = try fields.indices.map { index in
                    guard let rawIndex = UInt32(exactly: index) else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "projected Optional struct field exceeds UInt32"
                        )
                    }
                    let child = try allocate(type: fields[index].type)
                    appendInstruction(
                        .structExtract(
                            result: child,
                            structure: currentValue,
                            fieldIndex: rawIndex
                        )
                    )
                    return child
                }
                rebuild = { fields in
                    let result = try allocate(type: type)
                    appendInstruction(
                        .makeStruct(result: result, fields: fields)
                    )
                    return result
                }
                if !preservingCurrentValue {
                    // `struct_extract` copies each field. The compiler-storage
                    // owner being replaced must end after those copies are
                    // materialized; otherwise an obsolete aggregate can keep
                    // a class referent alive past a weak/unowned observation.
                    appendInstruction(.destroyValue(currentValue))
                }
            default:
                throw CanonicalSIL.LoweringError.unsupportedType(
                    "projected writeback requires a represented aggregate"
                )
            }

            var rebuiltChildren = children
            rebuiltChildren[fieldIndex] = try replacingAggregateProjection(
                in: children[fieldIndex],
                type: childTypes[fieldIndex],
                path: path.dropFirst(),
                prefix: prefix + [fieldIndex],
                with: replacement,
                updatedValues: &updatedValues
            )
            for index in rebuiltChildren.indices {
                updatedValues[prefix + [index]] = rebuiltChildren[index]
            }
            let rebuilt = try rebuild(rebuiltChildren)
            updatedValues[prefix] = rebuilt
            return rebuilt
        }

        /// Applies a field write to compiler-elided aggregate storage. Runtime
        /// addresses perform this reconstruction in `MemoryCell`; compiler-only
        /// storage must publish the rebuilt root and every already-formed field
        /// projection explicitly so no projection can retain a stale owner.
        func storeCompilerAggregateProjection(
            _ value: Bytecode.Register,
            at token: String
        ) throws -> Bool {
            guard runtimeAddress(at: token) == nil,
                  mutableCell(at: token) == nil
            else { return false }
            let identity = compilerStorageIdentity(for: token)
            guard !identity.path.isEmpty,
                  let rootType = compilerAddressType(identity.root),
                  let currentValue = stackValue(at: identity.root),
                  registerTypes[Int(currentValue.rawValue)] == rootType
            else { return false }

            let preservesRoot = values.contains { candidate, registered in
                registered == currentValue
                    && compilerStorageIdentity(for: candidate).root
                        != identity.root
                    && hasFutureSemanticUse(
                        of: candidate,
                        after: currentSILLineIndex
                    )
            }
            var updatedValues: [[Int]: Bytecode.Register] = [:]
            let rebuilt = try replacingAggregateProjection(
                in: currentValue,
                type: rootType,
                path: identity.path[...],
                with: value,
                preservingCurrentValue: preservesRoot,
                updatedValues: &updatedValues
            )
            recordCompilerAddressValue(rebuilt, at: identity.root)
            values[identity.root] = rebuilt

            for candidate in aggregateComponentAddresses.keys {
                let candidateIdentity = compilerStorageIdentity(for: candidate)
                guard candidateIdentity.root == identity.root,
                      let updated = updatedValues[candidateIdentity.path]
                else { continue }
                if stackAddressValues[addressBase(candidate)] != nil {
                    if let key = aggregateComponentStorageIdentity(
                        for: candidate
                    ) {
                        aggregateComponentValues.removeValue(forKey: key)
                    }
                    stackAddressValues[addressBase(candidate)] = updated
                } else if let key = aggregateComponentStorageIdentity(
                    for: candidate
                ) {
                    aggregateComponentValues[key] = updated
                }
            }
            return true
        }

        func storeConstructedValue(
            _ value: Bytecode.Register,
            at token: String,
            mode: Bytecode.StackStoreMode? = nil
        ) throws {
            let type = registerTypes[Int(value.rawValue)]
            guard compilerAddressType(token) == type else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "constructed value does not match its SIL address"
                )
            }
            if try storeExistentialPayload(
                value,
                at: token,
                mode: mode
            ) {
                return
            }
            if let cell = mutableCell(at: token) {
                let storeMode = mode
                    ?? storageInitializationPlan.storeMode(
                        at: currentSILLineIndex,
                        address: token
                    )
                appendInstruction(
                    .storeMutableCell(
                        cell: cell,
                        source: value,
                        mode: storeMode
                    )
                )
                return
            }
            if token == indirectResultAddress {
                guard let slot = indirectResultSlot else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "indirect result has no VM result slot"
                    )
                }
                appendInstruction(
                    .storeStack(slot: slot, source: value, mode: .initialize)
                )
                return
            }
            if var projection = takenOptionalPayloadProjection(at: token) {
                guard case let .optional(wrapped) = compilerAddressType(
                    projection.state.address
                ),
                      compilerAddressType(projection.root) == wrapped
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "taken Optional payload no longer matches its source storage"
                    )
                }
                var updatedValues: [[Int]: Bytecode.Register] = [:]
                let payload: Bytecode.Register
                if projection.path.isEmpty {
                    if let currentValue = stackValue(at: projection.root) {
                        payload = try replacingAggregateProjection(
                            in: currentValue,
                            type: wrapped,
                            path: projection.path[...],
                            with: value,
                            updatedValues: &updatedValues
                        )
                    } else {
                        payload = value
                        updatedValues[[]] = value
                    }
                } else {
                    guard let currentValue = stackValue(at: projection.root) else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "projected Optional writeback lost its payload value"
                        )
                    }
                    payload = try replacingAggregateProjection(
                        in: currentValue,
                        type: wrapped,
                        path: projection.path[...],
                        with: value,
                        updatedValues: &updatedValues
                    )
                }
                recordCompilerAddressValue(payload, at: projection.root)
                for candidate in aggregateComponentAddresses.keys {
                    guard let candidateProjection = takenOptionalPayloadProjection(
                        at: candidate
                    ), candidateProjection.root == projection.root,
                       let updated = updatedValues[candidateProjection.path]
                    else { continue }
                    if stackAddressValues[addressBase(candidate)] != nil {
                        if let key = aggregateComponentStorageIdentity(
                            for: candidate
                        ) {
                            aggregateComponentValues.removeValue(forKey: key)
                        }
                        stackAddressValues[addressBase(candidate)] = updated
                    } else if let key = aggregateComponentStorageIdentity(
                        for: candidate
                    ) {
                        aggregateComponentValues[key] = updated
                    }
                }
                let optional = try allocate(type: .optional(wrapped))
                appendInstruction(.makeOptionalSome(result: optional, value: payload))
                try storeVMValue(
                    optional,
                    at: projection.state.address,
                    requestedMode: projection.state.requiresInitialization
                        ? .initialize : mode
                )
                if let blockID = current?.id {
                    setKnownSomeOptionalAddress(
                        projection.state.address,
                        in: blockID,
                        isKnownSome: true
                    )
                }
                projection.state.requiresInitialization = false
                takenOptionalPayloads[projection.root] = projection.state
                return
            }
            if let root = optionalPayloadAddressRoots[token],
               var initialization = optionalAddressInitializations[root] {
                guard initialization.wrappedType == type,
                      initialization.payload == nil
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Optional payload address is invalid or initialized twice"
                    )
                }
                initialization.payload = value
                optionalAddressInitializations[root] = initialization
                return
            }
            if try storeCompilerAggregateProjection(value, at: token) {
                return
            }
            try storeVMValue(value, at: token, requestedMode: mode)
        }

        func isRepresentedErrorType(
            _ type: Bytecode.ValueType
        ) throws -> Bool {
            switch type {
            case .string, .error:
                true
            case let .local(key):
                try typeEnvironment.definition(for: key).conformsToError
            default:
                false
            }
        }

        func materializeErrorValue(
            from token: String,
            expectedType: Bytecode.ValueType? = nil
        ) throws -> Bytecode.Register? {
            if let value = values[token] {
                let type = registerTypes[Int(value.rawValue)]
                if try isRepresentedErrorType(type),
                   expectedType == nil || type == expectedType {
                    return value
                }
            }
            guard expectedType == nil || expectedType == .string,
                  let message = errorMessageByBox[token]
            else { return nil }
            let value = try allocate(type: .string)
            appendInstruction(
                .constantString(result: value, value: message)
            )
            values[token] = value
            return value
        }

        func closureThrownType(
            _ signature: Bytecode.ClosureSignature,
            context: String
        ) throws -> Bytecode.ValueType? {
            guard signature.hasCanonicalThrownType else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "\(context) has an inconsistent throwing ABI"
                )
            }
            guard let thrownType = signature.thrownType else { return nil }
            guard try isRepresentedErrorType(thrownType) else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "\(context) has a non-Error thrown type"
                )
            }
            return thrownType
        }

        func closureThrownType(
            _ signature: Bytecode.ClosureSignature,
            matching physicalErrorType: Bytecode.ValueType,
            context: String
        ) throws -> Bytecode.ValueType? {
            let thrownType = try closureThrownType(
                signature,
                context: context
            )
            let normalizedPhysicalType: Bytecode.ValueType? =
                physicalErrorType == .never ? nil : physicalErrorType
            guard thrownType == normalizedPhysicalType else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "\(context) changes its concrete error-result type"
                )
            }
            return thrownType
        }

        func applyStrongReferenceOperation(
            _ operation: StrongReferenceOperation,
            to token: String,
            value: Bytecode.Register
        ) throws {
            if operation == .release,
               let retained = takePendingRetainedValue(for: token) {
                appendInstruction(.destroyValue(retained))
                releaseCompilerTemporariesAfterLastUse(
                    [token],
                    after: currentSILLineIndex
                )
                return
            }
            let type = registerTypes[Int(value.rawValue)]
            if case .closure = type {
                if operation == .release {
                    try releaseClosureValueIfFinal(token: token, value: value)
                }
                return
            }
            if case .mutableCell = type { return }
            if case .nonOwningReference = type { return }
            guard type == .string || type == .error
                    || requiresManagedOwnership(type)
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "strong ownership operation references an unmanaged value"
                )
            }
            if operation == .retain {
                try materializeRetain(of: token, value: value)
            } else if borrowedTemporaryValue(for: token) != nil
                || compilerOwnedTemporaryValue(for: token) != nil
                || !isBorrowedValue(token: token, register: value) {
                try closeBorrowedTemporaryLifetime(
                    for: token,
                    resolved: value
                )
                try closeCompilerOwnedTemporaryLifetime(
                    for: token,
                    resolved: value
                )
                appendInstruction(.destroyValue(value))
            }
        }

        func storeErrorExistential(
            _ box: String,
            at destination: String,
            mode: Bytecode.StackStoreMode,
            sourceLine: Int
        ) throws {
            guard let destinationType = compilerAddressType(destination),
                  [.string, .error].contains(destinationType),
                  let materialized = try materializeErrorValue(
                    from: box,
                    expectedType: destinationType
                  ),
                  registerTypes[Int(materialized.rawValue)] == destinationType
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "Error existential box does not match its destination"
                )
            }
            let value = try prepareStoredValue(
                box,
                expectedType: destinationType,
                line: sourceLine
            )
            try storeConstructedValue(value, at: destination, mode: mode)
        }

        func finishErrorExistentialInitialization(
            _ box: String
        ) throws {
            guard values[box] != nil,
                  let block = current?.id
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "Error existential payload did not materialize its box"
                )
            }
            let deferred = deferredErrorExistentialOperations
                .removeValue(forKey: box) ?? []
            guard deferred.allSatisfy({ $0.block == block }) else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "Error existential initialization crosses a basic block"
                )
            }
            for operation in deferred {
                switch operation {
                case let .strong(ownership, _):
                    guard let value = values[box] else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Error existential ownership lost its materialized value"
                        )
                    }
                    try applyStrongReferenceOperation(
                        ownership,
                        to: box,
                        value: value
                    )
                case let .store(destination, mode, sourceLine, _):
                    try storeErrorExistential(
                        box,
                        at: destination,
                        mode: mode,
                        sourceLine: sourceLine
                    )
                }
            }
        }

        func lowerMutatingValueReceiverApply(
            resultToken: String,
            argumentTokens: [String],
            reference: ResolvedFunctionReference,
            line: Int
        ) throws {
            let binding = reference.binding
            guard binding.abiAdapter == .mutatingValueReceiver,
                  case let .nativeImport(requirement) = binding.target,
                  !binding.effects.mayThrow,
                  !binding.effects.isAsync,
                  !resultToken.isEmpty,
                  argumentTokens.count == binding.parameterTypes.count,
                  let receiverType = binding.parameterTypes.last,
                  binding.resultType == receiverType,
                  reference.physicalParameterConventions.last == .inout
            else {
                throw CanonicalSIL.LoweringError.invalidCallTable(
                    "mutating value-receiver call has an invalid frozen ABI"
                )
            }
            let receiverToken = argumentTokens[argumentTokens.count - 1]
            guard compilerAddressType(receiverToken) == receiverType else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "mutating value receiver is not stored at its expected SIL address"
                )
            }
            let valueTokens = Array(argumentTokens.dropLast())
            let valueConventions = Array(
                reference.physicalParameterConventions.dropLast()
            )
            let prepared = try prepareDirectCallArguments(
                valueTokens,
                physicalConventions: valueConventions,
                logicalTypes: Array(binding.parameterTypes.dropLast()),
                nativeCallbackConventions: nativeCallbackParameterConventions(
                    for: binding
                ),
                line: line,
                allowsCompilerInoutWriteback: true
            )
            var arguments = try zip(prepared.arguments, valueConventions).map {
                argument, convention in
                convention == .borrowed
                    ? try copyOwnedValue(argument)
                    : argument
            }
            let receiver: Bytecode.Register
            let transfersCompilerStorage: Bool
            let detachedProjection = takenOptionalPayloadProjection(
                at: receiverToken
            )
            if runtimeAddress(at: receiverToken) != nil
                || mutableCell(at: receiverToken) != nil
                || detachedProjection?.path.isEmpty == false {
                guard let copied = try copyStoredValue(
                    at: receiverToken,
                    line: line
                ) else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "mutating value receiver references uninitialized storage"
                    )
                }
                receiver = copied
                transfersCompilerStorage = false
            } else if let taken = try takeStoredValue(
                at: receiverToken,
                line: line
            ) {
                receiver = taken
                transfersCompilerStorage = true
            } else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "mutating value receiver references uninitialized storage"
                )
            }
            guard registerTypes[Int(receiver.rawValue)] == receiverType else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "mutating value receiver storage has the wrong VM type"
                )
            }
            // The adapter consumes a value snapshot and returns its mutated
            // replacement. A direct compiler-only value can transfer its
            // owner. Runtime storage and a detached aggregate projection keep
            // the enclosing value until the replacement is assigned or its
            // aggregate spine is rebuilt.
            arguments.append(receiver)
            guard directCallArgumentsMatch(arguments, binding: binding)
            else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: binding.mangledName
                )
            }
            let mutated = try allocate(type: receiverType)
            appendInstruction(
                .nativeApply(
                    result: mutated,
                    importID: requirement.id,
                    arguments: arguments
                )
            )
            try transferOwnedCompilerAddressArguments(
                tokens: valueTokens,
                resolvedArguments: prepared.arguments,
                conventions: valueConventions
            )
            if transfersCompilerStorage {
                try transferOwnedCompilerAddressArguments(
                    tokens: [receiverToken],
                    resolvedArguments: [receiver],
                    conventions: [.owned],
                    forceOwnedTokens: [receiverToken]
                )
            }
            appendPreparedOwnerCleanups(prepared)
            try storeConstructedValue(mutated, at: receiverToken)
            try finishPreparedAccessesAndWritebacks(prepared)
            voidValues.insert(resultToken)
        }

        func storeExistential(
            _ value: Bytecode.Register,
            at token: String,
            mode: Bytecode.StackStoreMode? = nil
        ) throws {
            guard registerTypes[Int(value.rawValue)] == .any else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "existential projection did not produce Any"
                )
            }
            if try storePendingArrayLiteralValue(value, at: token) {
                return
            }
            try storeConstructedValue(value, at: token, mode: mode)
        }

        func storeExistentialPayload(
            _ payload: Bytecode.Register,
            at token: String,
            mode: Bytecode.StackStoreMode? = nil
        ) throws -> Bool {
            if var projection = existentialProjections[token] {
                guard projection.components.isEmpty else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Any payload mixes direct and component writes"
                    )
                }
                if projection.componentStoreMode == nil {
                    projection.componentStoreMode = mode
                    existentialProjections[token] = projection
                }
                try finishExistentialProjection(token, payload: payload)
                return true
            }
            guard let component = existentialComponentAddresses[token]
            else { return false }
            guard var projection = existentialProjections[
                    component.projection
                  ],
                  case let .tuple(types) = projection.storageType,
                  types.indices.contains(component.index),
                  registerTypes[Int(payload.rawValue)]
                    == types[component.index],
                  projection.components.updateValue(
                    payload,
                    forKey: component.index
                  ) == nil
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "Any tuple payload component is invalid or duplicated"
                )
            }
            if projection.componentStoreMode == nil {
                projection.componentStoreMode = mode
                    ?? storageInitializationPlan.storeMode(
                        at: currentSILLineIndex,
                        address: token
                    )
            }
            existentialProjections[component.projection] = projection
            if projection.components.count == types.count {
                let elements = try types.indices.map { index in
                    guard let element = projection.components[index] else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Any tuple payload is incomplete"
                        )
                    }
                    return element
                }
                let tuple = try allocate(type: projection.storageType)
                appendInstruction(.makeTuple(result: tuple, elements: elements))
                try finishExistentialProjection(
                    component.projection,
                    payload: tuple
                )
            }
            return true
        }

        func finishExistentialProjection(
            _ token: String,
            payload: Bytecode.Register
        ) throws {
            guard let projection = existentialProjections[token],
                  registerTypes[Int(payload.rawValue)] == projection.storageType
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "Any payload does not match its concrete SIL type"
                )
            }
            let hasFutureWrite = existentialInitializationPlan.hasWrite(
                to: token,
                after: currentSILLineIndex
            )
            let requiresMerge = hasFutureWrite
                || branchMergedExistentialProjections.contains(token)
            if hasFutureWrite {
                var reset = projection
                reset.components.removeAll(keepingCapacity: true)
                reset.componentStoreMode = nil
                existentialProjections[token] = reset
                branchMergedExistentialProjections.insert(token)
            } else {
                existentialProjections.removeValue(forKey: token)
                existentialComponentAddresses = existentialComponentAddresses.filter {
                    $0.value.projection != token
                }
                branchMergedExistentialProjections.remove(token)
            }
            let erased = try allocate(type: .any)
            appendInstruction(
                .eraseToAny(
                    result: erased,
                    value: payload,
                    dynamicType: projection.dynamicType
                )
            )
            if requiresMerge {
                guard let blockID = current?.id,
                      compilerAddressWrites[blockID, default: [:]].updateValue(
                        erased,
                        forKey: projection.destination
                      ) == nil
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Any projection has multiple writes on one control-flow path"
                    )
                }
                return
            }
            try storeExistential(
                erased,
                at: projection.destination,
                mode: projection.componentStoreMode
            )
        }

        func materializeManagedCollectionElements(
            _ source: Bytecode.Register,
            sourceType: Bytecode.ValueType,
            context: String
        ) throws -> (array: Bytecode.Register, cleanupOwner: Bytecode.Register?) {
            guard registerTypes[Int(source.rawValue)] == sourceType,
                  let element = sourceType.managedCollectionElement
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "\(context) source does not match a represented managed Collection"
                )
            }
            let arrayType = Bytecode.ValueType.array(element)
            if sourceType == arrayType {
                return (source, nil)
            }
            let result = try allocate(type: arrayType)
            appendInstruction(
                .collectionMaterialize(result: result, collection: source)
            )
            return (
                result,
                requiresManagedOwnership(arrayType) ? result : nil
            )
        }

        func lowerNaturalSequenceOrdering(
            _ operation: CanonicalSIL.OrderingIntrinsic,
            resultToken: String,
            genericArguments: String,
            arguments: [String],
            line: Int
        ) throws {
            guard !operation.usesClosure,
                  arguments.count == 1
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "natural Sequence ordering has unsupported arguments"
                )
            }
            let genericSpellings = splitTopLevel(genericArguments)
                .filter { !$0.isEmpty }
            guard genericSpellings.count == 1 else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "natural ordering has an incomplete Sequence specialization"
                )
            }
            let source = try parseSequenceSpecialization(
                genericSpellings[0],
                context: "natural ordering"
            )
            let element = source.element
            guard element.isVMComparable else {
                throw CanonicalSIL.LoweringError.unsupportedType(
                    "natural ordering requires VM-defined Comparable semantics for \(element)"
                )
            }
            let arrayType = Bytecode.ValueType.array(element)
            let mutationIndexModel: CanonicalSIL.CollectionIndex.Model?
            if operation.mutatesSource {
                guard source.managedCollectionType == arrayType,
                      compilerAddressType(arguments[0]) == arrayType
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "MutableCollection.sort() requires represented Array inout storage"
                    )
                }
                let model = typeEnvironment.collectionIndexModel(
                    for: genericSpellings[0]
                )
                guard model != .opaque else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "mutating natural ordering requires represented integer indices"
                    )
                }
                mutationIndexModel = model
            } else {
                mutationIndexModel = nil
            }

            let materialized = try materializeSequenceOperand(
                source,
                token: arguments[0],
                context: "natural ordering",
                line: line
            )
            let mutationIndexBase: Bytecode.Register?
            if mutationIndexModel == .preservedBaseInteger {
                let base = try allocate(type: .int64)
                appendInstruction(
                    .arrayIndexBase(result: base, array: materialized.array)
                )
                mutationIndexBase = base
            } else {
                mutationIndexBase = nil
            }
            let sorted = try allocate(type: arrayType)
            appendInstruction(
                .arraySorted(result: sorted, array: materialized.array)
            )
            for instruction in materialized.cleanup {
                appendInstruction(instruction)
            }

            switch operation {
            case .sorted:
                values[resultToken] = sorted
            case .sort:
                let result: Bytecode.Register
                if let mutationIndexBase {
                    result = try allocate(type: arrayType)
                    appendInstruction(
                        .arrayRebase(
                            result: result,
                            array: sorted,
                            indexBase: mutationIndexBase
                        )
                    )
                } else {
                    result = sorted
                }
                try storeConstructedValue(
                    result,
                    at: arguments[0],
                    mode: .assign
                )
                voidValues.insert(resultToken)
            case .sortedBy, .sortBy:
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "closure ordering reached natural ordering lowering"
                )
            }
        }

        func lowerSeparatorArraySplit(
            resultToken: String,
            genericArguments: String,
            argumentText: String,
            line: Int
        ) throws {
            let plan = try parseArraySplitPlan(
                operation: .separator,
                genericArguments: genericArguments,
                argumentText: argumentText,
                line: line
            )
            guard plan.elementType.isVMEquatable else {
                throw CanonicalSIL.LoweringError.unsupportedType(
                    "split(separator:) requires VM-defined Equatable semantics"
                )
            }
            let arrayType = Bytecode.ValueType.array(plan.elementType)
            let materialized = try materializeSequenceOperand(
                plan.source,
                token: plan.sourceToken,
                context: "split(separator:) source",
                line: line
            )
            let borrowedSeparator = try borrowStoredValue(
                at: plan.decisionToken,
                line: line
            )
            let separator = try borrowedSeparator?.register
                ?? resolve(plan.decisionToken, line: line)
            let maximumSplits = try resolve(
                plan.maximumSplitsToken,
                line: line
            )
            let omittingEmptySubsequences = try resolve(
                plan.omittingEmptySubsequencesToken,
                line: line
            )
            guard registerTypes[Int(materialized.array.rawValue)] == arrayType,
                  registerTypes[Int(separator.rawValue)] == plan.elementType,
                  registerTypes[Int(maximumSplits.rawValue)] == .int64,
                  registerTypes[Int(omittingEmptySubsequences.rawValue)] == .bool
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "split(separator:) arguments do not match its specialization"
                )
            }
            let result = try allocate(type: .array(arrayType))
            appendInstruction(
                .arraySplitSeparator(
                    result: result,
                    array: materialized.array,
                    separator: separator,
                    maxSplits: maximumSplits,
                    omittingEmptySubsequences: omittingEmptySubsequences
                )
            )
            for instruction in materialized.cleanup {
                appendInstruction(instruction)
            }
            if let owner = borrowedSeparator?.temporaryOwner {
                appendInstruction(.destroyValue(owner))
            }
            values[resultToken] = result
        }

        func resolveSequenceOrderingClosure(
            for plan: SequenceOrderingPlan,
            line: Int
        ) throws -> (Bytecode.Register, Bytecode.ClosureSignature) {
            let closure = try resolve(plan.closureToken, line: line)
            let expectedParameters = Array(repeating: plan.elementType, count: 2)
            guard case let .closure(signature) = registerTypes[
                Int(closure.rawValue)
            ], signature.parameters == expectedParameters,
               signature.parameterConventions.count == expectedParameters.count,
               !signature.parameterConventions.contains(.inout),
               signature.result == .bool,
               signature.effects.mayThrow,
               !signature.effects.isAsync
            else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: "<Sequence ordering closure>"
                )
            }
            return (closure, signature)
        }

        func prepareSequenceOrderingContinuations(
            plan: SequenceOrderingPlan,
            normalTarget: Bytecode.BlockID
        ) throws {
            switch plan.operation {
            case .sortedBy:
                break
            case .sortBy:
                let arrayType = Bytecode.ValueType.array(plan.elementType)
                guard plan.source.managedCollectionType == arrayType,
                      compilerAddressType(plan.sourceToken) == arrayType,
                      implicitStackValues[normalTarget] == nil,
                      suppressedTryNormalParameterTypes.updateValue(
                        .void,
                        forKey: normalTarget
                      ) == nil
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "sort(by:) requires one mutable Array continuation"
                    )
                }
                let propagatedArray = try allocate(type: arrayType)
                implicitStackValues[normalTarget] = [
                    .init(
                        plan.sourceToken,
                        propagatedArray,
                        storeMode: .assign
                    ),
                ]
            case .sorted, .sort:
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "natural ordering reached try_apply continuation setup"
                )
            }
        }

        /// Comparator evaluation remains ordinary closure control flow while
        /// the VM owns a bounded stable merge-sort state machine. This keeps
        /// captures, throwing callbacks, call depth, and linear values on the
        /// same paths as every other higher-order operation.
        func lowerSequenceComparatorSortTryApply(
            plan: SequenceOrderingPlan,
            normalTarget: Bytecode.BlockID,
            errorTarget: Bytecode.BlockID,
            line: Int
        ) throws {
            guard plan.operation == .sortedBy || plan.operation == .sortBy
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "comparator sort received a different ordering operation"
                )
            }
            let arrayType = Bytecode.ValueType.array(plan.elementType)
            let materialized = try materializeSequenceOperand(
                plan.source,
                token: plan.sourceToken,
                context: "comparator ordering",
                line: line
            )
            let mutationIndexBase: Bytecode.Register?
            if plan.mutationIndexModel == .preservedBaseInteger {
                let base = try allocate(type: .int64)
                appendInstruction(
                    .arrayIndexBase(result: base, array: materialized.array)
                )
                mutationIndexBase = base
            } else {
                mutationIndexBase = nil
            }
            let (closure, closureSignature) = try resolveSequenceOrderingClosure(
                for: plan,
                line: line
            )
            try prepareSequenceOrderingContinuations(
                plan: plan,
                normalTarget: normalTarget
            )

            guard let errorType = try closureThrownType(
                closureSignature,
                context: "Sequence ordering closure"
            ) else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: "<Sequence ordering closure>"
                )
            }
            let errorParameter = try allocate(type: errorType)
            let stateType = Bytecode.ValueType.arrayState(
                kind: .stableSort,
                element: plan.elementType
            )
            let state = try allocate(type: stateType)
            let comparisonType = Bytecode.ValueType.tuple([
                plan.elementType,
                plan.elementType,
            ])
            let nextType = Bytecode.ValueType.optional(comparisonType)
            let next = try allocate(type: nextType)
            let comparison = try allocate(type: comparisonType)
            let right = try allocate(type: plan.elementType)
            let left = try allocate(type: plan.elementType)
            let predicate = try allocate(type: .bool)
            let sorted = try allocate(type: arrayType)
            let completed = try mutationIndexBase.map { _ in
                try allocate(type: arrayType)
            }
            let loop = try allocateSyntheticBlockID()
            let compare = try allocateSyntheticBlockID()
            let accepted = try allocateSyntheticBlockID()
            let complete = try allocateSyntheticBlockID()
            let failed = try allocateSyntheticBlockID()

            appendInstruction(
                .makeArraySortState(result: state, array: materialized.array)
            )
            for instruction in materialized.cleanup {
                appendInstruction(instruction)
            }
            appendInstruction(.branch(target: loop, arguments: []))
            finishCurrent()

            appendSyntheticBlock(
                id: loop,
                instructions: [
                    .arraySortNextComparison(result: next, state: state),
                    .switchOptional(
                        optional: next,
                        someTarget: compare,
                        noneTarget: complete
                    ),
                ]
            )
            appendSyntheticBlock(
                id: compare,
                parameters: [comparison],
                instructions: [
                    .unpackTuple(
                        results: [right, left],
                        tuple: comparison
                    ),
                    .closureTryApply(
                        closure: closure,
                        arguments: [right, left],
                        normalTarget: accepted,
                        errorTarget: failed
                    ),
                ]
            )

            let borrowedComparisonCleanup = zip(
                [right, left],
                closureSignature.parameterConventions
            ).compactMap { register, convention in
                requiresManagedOwnership(plan.elementType)
                    && convention == .borrowed
                    ? IntermediateRepresentation.Instruction
                        .destroyValue(register)
                    : nil
            }
            appendSyntheticBlock(
                id: accepted,
                parameters: [predicate],
                instructions: borrowedComparisonCleanup + [
                    .arraySortAcceptComparison(
                        state: state,
                        rightPrecedesLeft: predicate
                    ),
                    .branch(target: loop, arguments: []),
                ]
            )

            var completionInstructions: [
                IntermediateRepresentation.Instruction
            ] = [.finishArraySort(result: sorted, state: state)]
            if let mutationIndexBase, let completed {
                completionInstructions += [
                    .arrayRebase(
                        result: completed,
                        array: sorted,
                        indexBase: mutationIndexBase
                    ),
                    .branch(
                        target: normalTarget,
                        arguments: [completed]
                    ),
                ]
            } else {
                completionInstructions.append(
                    .branch(
                        target: normalTarget,
                        arguments: [sorted]
                    )
                )
            }
            appendSyntheticBlock(
                id: complete,
                instructions: completionInstructions
            )
            appendSyntheticBlock(
                id: failed,
                parameters: [errorParameter],
                instructions: borrowedComparisonCleanup + [
                    .destroyValue(state),
                    .branch(
                        target: errorTarget,
                        arguments: [errorParameter]
                    ),
                ]
            )
        }

        func prepareArrayPredicateMutation(
            plan: ArrayPredicateMutationPlan,
            normalTarget: Bytecode.BlockID,
            errorTarget: Bytecode.BlockID,
            line: Int
        ) throws -> ArrayPredicateMutationContext {
            let arrayType = Bytecode.ValueType.array(plan.elementType)
            guard compilerAddressType(plan.sourceToken) == arrayType,
                  let source = try takeStoredValue(
                    at: plan.sourceToken,
                    line: line
                  ),
                  registerTypes[Int(source.rawValue)] == arrayType,
                  implicitStackValues[normalTarget] == nil,
                  implicitStackValues[errorTarget] == nil,
                  suppressedTryNormalParameterTypes.updateValue(
                    .void,
                    forKey: normalTarget
                  ) == nil
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "predicate mutation requires one mutable Array continuation"
                )
            }

            let closure = try resolve(plan.closureToken, line: line)
            guard case let .closure(signature) = registerTypes[
                Int(closure.rawValue)
            ], signature.parameters == [plan.elementType],
               signature.parameterConventions.count == 1,
               signature.parameterConventions[0] != .inout,
               signature.result == .bool,
               signature.effects.mayThrow,
               !signature.effects.isAsync
            else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: "<Array predicate mutation closure>"
                )
            }

            let normalArray = try allocate(type: arrayType)
            switch plan.operation {
            case .partition:
                guard let destination = plan.resultDestination,
                      compilerAddressType(destination) == .int64
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "partition(by:) requires an out Index"
                    )
                }
                let normalBoundary = try allocate(type: .int64)
                implicitStackValues[normalTarget] = [
                    .init(destination, normalBoundary),
                    .init(
                        plan.sourceToken,
                        normalArray,
                        storeMode: .initialize
                    ),
                ]
            case .removeAllWhere:
                guard plan.resultDestination == nil else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "removeAll(where:) unexpectedly has a result destination"
                    )
                }
                implicitStackValues[normalTarget] = [
                    .init(
                        plan.sourceToken,
                        normalArray,
                        storeMode: .initialize
                    ),
                ]
            }
            let errorArray = try allocate(type: arrayType)
            implicitStackValues[errorTarget] = [
                .init(
                    plan.sourceToken,
                    errorArray,
                    storeMode: .initialize
                ),
            ]

            let count = try allocate(type: .int64)
            appendInstruction(.arrayCount(result: count, array: source))
            let indexBase = try allocate(type: .int64)
            appendInstruction(
                .arrayIndexBase(result: indexBase, array: source)
            )
            let state = try allocate(
                type: .arrayState(kind: .mutation, element: plan.elementType)
            )
            appendInstruction(
                .makeArrayMutationState(result: state, array: source)
            )
            let traversalSource: Bytecode.Register?
            if plan.operation == .removeAllWhere {
                traversalSource = source
            } else {
                appendInstruction(.destroyValue(source))
                traversalSource = nil
            }
            guard let errorType = try closureThrownType(
                signature,
                context: "Array predicate mutation closure"
            ) else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: "<Array predicate mutation closure>"
                )
            }
            return .init(
                arrayType: arrayType,
                closure: closure,
                closureSignature: signature,
                state: state,
                count: count,
                errorType: errorType,
                traversalSource: traversalSource,
                indexBase: indexBase
            )
        }

        /// Array selects the bidirectional MutableCollection overload. Mirror
        /// its low/high predicate order and write back completed swaps on both
        /// continuations so a thrown predicate exposes the same partial value.
        func lowerArrayBidirectionalPartitionTryApply(
            plan: ArrayPredicateMutationPlan,
            normalTarget: Bytecode.BlockID,
            errorTarget: Bytecode.BlockID,
            line: Int
        ) throws {
            guard plan.operation == .partition else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "bidirectional partition received a different operation"
                )
            }
            let context = try prepareArrayPredicateMutation(
                plan: plan,
                normalTarget: normalTarget,
                errorTarget: errorTarget,
                line: line
            )
            let elementNeedsCleanup = requiresManagedOwnership(plan.elementType)
                && context.closureSignature.parameterConventions[0] != .owned

            let lowSlot = try allocateStackSlot(type: .int64)
            let highSlot = try allocateStackSlot(type: .int64)
            let zero = try allocate(type: .int64)
            appendInstruction(.constantInteger(result: zero, bitPattern: 0))
            appendInstruction(
                .storeStack(slot: lowSlot, source: zero, mode: .initialize)
            )
            appendInstruction(
                .storeStack(
                    slot: highSlot,
                    source: context.count,
                    mode: .initialize
                )
            )

            let scanLow = try allocateSyntheticBlockID()
            let readLow = try allocateSyntheticBlockID()
            let lowDecision = try allocateSyntheticBlockID()
            let advanceLow = try allocateSyntheticBlockID()
            let storeAdvancedLow = try allocateSyntheticBlockID()
            let decrementHigh = try allocateSyntheticBlockID()
            let storeDecrementedHigh = try allocateSyntheticBlockID()
            let readHigh = try allocateSyntheticBlockID()
            let highDecision = try allocateSyntheticBlockID()
            let swap = try allocateSyntheticBlockID()
            let complete = try allocateSyntheticBlockID()
            let completeWriteback = try allocateSyntheticBlockID()
            let lowFailed = try allocateSyntheticBlockID()
            let highFailed = try allocateSyntheticBlockID()
            let overflowTrap = try allocateSyntheticBlockID()

            let lowIndex = try allocate(type: .int64)
            let highIndex = try allocate(type: .int64)
            let hasLow = try allocate(type: .bool)
            let lowElement = try allocate(type: plan.elementType)
            let lowPredicate = try allocate(type: .bool)
            let lowToAdvance = try allocate(type: .int64)
            let oneLow = try allocate(type: .int64)
            let advancedLow = try allocate(type: .int64)
            let lowOverflow = try allocate(type: .bool)
            let currentHigh = try allocate(type: .int64)
            let oneHigh = try allocate(type: .int64)
            let decrementedHigh = try allocate(type: .int64)
            let highOverflow = try allocate(type: .bool)
            let currentLow = try allocate(type: .int64)
            let hasHigh = try allocate(type: .bool)
            let highElement = try allocate(type: plan.elementType)
            let highPredicate = try allocate(type: .bool)
            let physicalBoundary = try allocate(type: .int64)
            let boundary = try allocate(type: .int64)
            let boundaryOverflow = try allocate(type: .bool)
            let completedArray = try allocate(type: context.arrayType)
            let lowError = try allocate(type: context.errorType)
            let highError = try allocate(type: context.errorType)
            let lowErrorArray = try allocate(type: context.arrayType)
            let highErrorArray = try allocate(type: context.arrayType)

            appendInstruction(.branch(target: scanLow, arguments: []))
            finishCurrent()
            appendSyntheticBlock(
                id: scanLow,
                instructions: [
                    .loadStack(result: lowIndex, slot: lowSlot, mode: .copy),
                    .loadStack(result: highIndex, slot: highSlot, mode: .copy),
                    .compare(
                        result: hasLow,
                        predicate: .lessThan,
                        lhs: lowIndex,
                        rhs: highIndex
                    ),
                    .conditionalBranch(
                        condition: hasLow,
                        trueTarget: readLow,
                        trueArguments: [],
                        falseTarget: complete,
                        falseArguments: []
                    ),
                ]
            )
            appendSyntheticBlock(
                id: readLow,
                instructions: [
                    .arrayMutationGet(
                        result: lowElement,
                        state: context.state,
                        index: lowIndex
                    ),
                    .closureTryApply(
                        closure: context.closure,
                        arguments: [lowElement],
                        normalTarget: lowDecision,
                        errorTarget: lowFailed
                    ),
                ]
            )
            appendSyntheticBlock(
                id: lowDecision,
                parameters: [lowPredicate],
                instructions: (elementNeedsCleanup
                    ? [.destroyValue(lowElement)] : []) + [
                    .conditionalBranch(
                        condition: lowPredicate,
                        trueTarget: decrementHigh,
                        trueArguments: [],
                        falseTarget: advanceLow,
                        falseArguments: []
                    ),
                ]
            )
            appendSyntheticBlock(
                id: advanceLow,
                instructions: [
                    .loadStack(
                        result: lowToAdvance,
                        slot: lowSlot,
                        mode: .copy
                    ),
                    .constantInteger(result: oneLow, bitPattern: 1),
                    .checkedBinary(
                        result: advancedLow,
                        overflow: lowOverflow,
                        operation: .add,
                        lhs: lowToAdvance,
                        rhs: oneLow
                    ),
                    .conditionalBranch(
                        condition: lowOverflow,
                        trueTarget: overflowTrap,
                        trueArguments: [],
                        falseTarget: storeAdvancedLow,
                        falseArguments: []
                    ),
                ]
            )
            appendSyntheticBlock(
                id: storeAdvancedLow,
                instructions: [
                    .storeStack(
                        slot: lowSlot,
                        source: advancedLow,
                        mode: .assign
                    ),
                    .branch(target: scanLow, arguments: []),
                ]
            )
            appendSyntheticBlock(
                id: decrementHigh,
                instructions: [
                    .loadStack(
                        result: currentHigh,
                        slot: highSlot,
                        mode: .copy
                    ),
                    .constantInteger(result: oneHigh, bitPattern: 1),
                    .checkedBinary(
                        result: decrementedHigh,
                        overflow: highOverflow,
                        operation: .subtract,
                        lhs: currentHigh,
                        rhs: oneHigh
                    ),
                    .conditionalBranch(
                        condition: highOverflow,
                        trueTarget: overflowTrap,
                        trueArguments: [],
                        falseTarget: storeDecrementedHigh,
                        falseArguments: []
                    ),
                ]
            )
            appendSyntheticBlock(
                id: storeDecrementedHigh,
                instructions: [
                    .storeStack(
                        slot: highSlot,
                        source: decrementedHigh,
                        mode: .assign
                    ),
                    .loadStack(
                        result: currentLow,
                        slot: lowSlot,
                        mode: .copy
                    ),
                    .compare(
                        result: hasHigh,
                        predicate: .lessThan,
                        lhs: currentLow,
                        rhs: decrementedHigh
                    ),
                    .conditionalBranch(
                        condition: hasHigh,
                        trueTarget: readHigh,
                        trueArguments: [],
                        falseTarget: complete,
                        falseArguments: []
                    ),
                ]
            )
            appendSyntheticBlock(
                id: readHigh,
                instructions: [
                    .arrayMutationGet(
                        result: highElement,
                        state: context.state,
                        index: decrementedHigh
                    ),
                    .closureTryApply(
                        closure: context.closure,
                        arguments: [highElement],
                        normalTarget: highDecision,
                        errorTarget: highFailed
                    ),
                ]
            )
            appendSyntheticBlock(
                id: highDecision,
                parameters: [highPredicate],
                instructions: (elementNeedsCleanup
                    ? [.destroyValue(highElement)] : []) + [
                    .conditionalBranch(
                        condition: highPredicate,
                        trueTarget: decrementHigh,
                        trueArguments: [],
                        falseTarget: swap,
                        falseArguments: []
                    ),
                ]
            )
            appendSyntheticBlock(
                id: swap,
                instructions: [
                    .arrayMutationSwap(
                        state: context.state,
                        lhsIndex: currentLow,
                        rhsIndex: decrementedHigh
                    ),
                    .branch(target: advanceLow, arguments: []),
                ]
            )
            appendSyntheticBlock(
                id: complete,
                instructions: [
                    .loadStack(
                        result: physicalBoundary,
                        slot: lowSlot,
                        mode: .take
                    ),
                    .destroyStack(highSlot),
                    .checkedBinary(
                        result: boundary,
                        overflow: boundaryOverflow,
                        operation: .add,
                        lhs: context.indexBase,
                        rhs: physicalBoundary
                    ),
                    .conditionalBranch(
                        condition: boundaryOverflow,
                        trueTarget: overflowTrap,
                        trueArguments: [],
                        falseTarget: completeWriteback,
                        falseArguments: []
                    ),
                ]
            )
            appendSyntheticBlock(
                id: completeWriteback,
                instructions: [
                    .finishArrayMutation(
                        result: completedArray,
                        state: context.state
                    ),
                    .branch(
                        target: normalTarget,
                        arguments: [boundary, completedArray]
                    ),
                ]
            )
            appendSyntheticBlock(
                id: lowFailed,
                parameters: [lowError],
                instructions: (elementNeedsCleanup
                    ? [.destroyValue(lowElement)] : []) + [
                    .destroyStack(lowSlot),
                    .destroyStack(highSlot),
                    .finishArrayMutation(
                        result: lowErrorArray,
                        state: context.state
                    ),
                    .branch(
                        target: errorTarget,
                        arguments: [lowError, lowErrorArray]
                    ),
                ]
            )
            appendSyntheticBlock(
                id: highFailed,
                parameters: [highError],
                instructions: (elementNeedsCleanup
                    ? [.destroyValue(highElement)] : []) + [
                    .destroyStack(lowSlot),
                    .destroyStack(highSlot),
                    .finishArrayMutation(
                        result: highErrorArray,
                        state: context.state
                    ),
                    .branch(
                        target: errorTarget,
                        arguments: [highError, highErrorArray]
                    ),
                ]
            )
            appendSyntheticBlock(
                id: overflowTrap,
                instructions: [.trap(.integerOverflow)]
            )
        }

        /// `removeAll(where:)` on Array uses `_halfStablePartition`, then
        /// removes the matching suffix. Traverse the immutable input sequence
        /// while retaining the progressively swapped value for both exits.
        func lowerArrayHalfStableRemovalTryApply(
            plan: ArrayPredicateMutationPlan,
            normalTarget: Bytecode.BlockID,
            errorTarget: Bytecode.BlockID,
            line: Int
        ) throws {
            guard plan.operation == .removeAllWhere else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "half-stable removal received a different operation"
                )
            }
            let context = try prepareArrayPredicateMutation(
                plan: plan,
                normalTarget: normalTarget,
                errorTarget: errorTarget,
                line: line
            )
            guard let traversalSource = context.traversalSource else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "half-stable removal omitted its traversal snapshot"
                )
            }
            let elementNeedsCleanup = requiresManagedOwnership(plan.elementType)
                && context.closureSignature.parameterConventions[0] != .owned

            let indexSlot = try allocateStackSlot(type: .int64)
            let pivotSlot = try allocateStackSlot(type: .int64)
            let zeroIndex = try allocate(type: .int64)
            let zeroPivot = try allocate(type: .int64)
            appendInstruction(
                .constantInteger(result: zeroIndex, bitPattern: 0)
            )
            appendInstruction(
                .storeStack(
                    slot: indexSlot,
                    source: zeroIndex,
                    mode: .initialize
                )
            )
            appendInstruction(
                .constantInteger(result: zeroPivot, bitPattern: 0)
            )
            appendInstruction(
                .storeStack(
                    slot: pivotSlot,
                    source: zeroPivot,
                    mode: .initialize
                )
            )

            let initialLoop = try allocateSyntheticBlockID()
            let initialSome = try allocateSyntheticBlockID()
            let initialDecision = try allocateSyntheticBlockID()
            let incrementPivot = try allocateSyntheticBlockID()
            let storeIncrementedPivot = try allocateSyntheticBlockID()
            let suffixLoop = try allocateSyntheticBlockID()
            let suffixSome = try allocateSyntheticBlockID()
            let suffixDecision = try allocateSyntheticBlockID()
            let swap = try allocateSyntheticBlockID()
            let performSwap = try allocateSyntheticBlockID()
            let storeSwappedPivot = try allocateSyntheticBlockID()
            let complete = try allocateSyntheticBlockID()
            let computeLogicalEnd = try allocateSyntheticBlockID()
            let performRemoval = try allocateSyntheticBlockID()
            let initialFailed = try allocateSyntheticBlockID()
            let suffixFailed = try allocateSyntheticBlockID()
            let overflowTrap = try allocateSyntheticBlockID()
            let rangeOverflowTrap = try allocateSyntheticBlockID()

            let initialNext = try allocate(type: .optional(plan.elementType))
            let initialElement = try allocate(type: plan.elementType)
            let initialPredicate = try allocate(type: .bool)
            let suffixNext = try allocate(type: .optional(plan.elementType))
            let suffixElement = try allocate(type: plan.elementType)
            let suffixPredicate = try allocate(type: .bool)
            let currentPivot = try allocate(type: .int64)
            let onePivot = try allocate(type: .int64)
            let incrementedPivot = try allocate(type: .int64)
            let pivotOverflow = try allocate(type: .bool)
            let currentCursor = try allocate(type: .int64)
            let oneCursor = try allocate(type: .int64)
            let elementIndex = try allocate(type: .int64)
            let cursorOverflow = try allocate(type: .bool)
            let currentSwapPivot = try allocate(type: .int64)
            let oneSwap = try allocate(type: .int64)
            let incrementedSwapPivot = try allocate(type: .int64)
            let swapPivotOverflow = try allocate(type: .bool)
            let boundary = try allocate(type: .int64)
            let logicalBoundary = try allocate(type: .int64)
            let boundaryOverflow = try allocate(type: .bool)
            let logicalEnd = try allocate(type: .int64)
            let endOverflow = try allocate(type: .bool)
            let partitioned = try allocate(type: context.arrayType)
            let empty = try allocate(type: context.arrayType)
            let result = try allocate(type: context.arrayType)
            let initialError = try allocate(type: context.errorType)
            let suffixError = try allocate(type: context.errorType)
            let initialErrorArray = try allocate(type: context.arrayType)
            let suffixErrorArray = try allocate(type: context.arrayType)

            appendInstruction(.branch(target: initialLoop, arguments: []))
            finishCurrent()
            appendSyntheticBlock(
                id: initialLoop,
                instructions: [
                    .collectionNext(
                        result: initialNext,
                        collection: traversalSource,
                        indexSlot: indexSlot,
                        direction: .forward
                    ),
                    .switchOptional(
                        optional: initialNext,
                        someTarget: initialSome,
                        noneTarget: complete
                    ),
                ]
            )
            appendSyntheticBlock(
                id: initialSome,
                parameters: [initialElement],
                instructions: [
                    .closureTryApply(
                        closure: context.closure,
                        arguments: [initialElement],
                        normalTarget: initialDecision,
                        errorTarget: initialFailed
                    ),
                ]
            )
            appendSyntheticBlock(
                id: initialDecision,
                parameters: [initialPredicate],
                instructions: (elementNeedsCleanup
                    ? [.destroyValue(initialElement)] : []) + [
                    .conditionalBranch(
                        condition: initialPredicate,
                        trueTarget: suffixLoop,
                        trueArguments: [],
                        falseTarget: incrementPivot,
                        falseArguments: []
                    ),
                ]
            )
            appendSyntheticBlock(
                id: incrementPivot,
                instructions: [
                    .loadStack(
                        result: currentPivot,
                        slot: pivotSlot,
                        mode: .copy
                    ),
                    .constantInteger(result: onePivot, bitPattern: 1),
                    .checkedBinary(
                        result: incrementedPivot,
                        overflow: pivotOverflow,
                        operation: .add,
                        lhs: currentPivot,
                        rhs: onePivot
                    ),
                    .conditionalBranch(
                        condition: pivotOverflow,
                        trueTarget: overflowTrap,
                        trueArguments: [],
                        falseTarget: storeIncrementedPivot,
                        falseArguments: []
                    ),
                ]
            )
            appendSyntheticBlock(
                id: storeIncrementedPivot,
                instructions: [
                    .storeStack(
                        slot: pivotSlot,
                        source: incrementedPivot,
                        mode: .assign
                    ),
                    .branch(target: initialLoop, arguments: []),
                ]
            )
            appendSyntheticBlock(
                id: suffixLoop,
                instructions: [
                    .collectionNext(
                        result: suffixNext,
                        collection: traversalSource,
                        indexSlot: indexSlot,
                        direction: .forward
                    ),
                    .switchOptional(
                        optional: suffixNext,
                        someTarget: suffixSome,
                        noneTarget: complete
                    ),
                ]
            )
            appendSyntheticBlock(
                id: suffixSome,
                parameters: [suffixElement],
                instructions: [
                    .closureTryApply(
                        closure: context.closure,
                        arguments: [suffixElement],
                        normalTarget: suffixDecision,
                        errorTarget: suffixFailed
                    ),
                ]
            )
            appendSyntheticBlock(
                id: suffixDecision,
                parameters: [suffixPredicate],
                instructions: (elementNeedsCleanup
                    ? [.destroyValue(suffixElement)] : []) + [
                    .conditionalBranch(
                        condition: suffixPredicate,
                        trueTarget: suffixLoop,
                        trueArguments: [],
                        falseTarget: swap,
                        falseArguments: []
                    ),
                ]
            )
            appendSyntheticBlock(
                id: swap,
                instructions: [
                    .loadStack(
                        result: currentCursor,
                        slot: indexSlot,
                        mode: .copy
                    ),
                    .constantInteger(result: oneCursor, bitPattern: 1),
                    .checkedBinary(
                        result: elementIndex,
                        overflow: cursorOverflow,
                        operation: .subtract,
                        lhs: currentCursor,
                        rhs: oneCursor
                    ),
                    .conditionalBranch(
                        condition: cursorOverflow,
                        trueTarget: overflowTrap,
                        trueArguments: [],
                        falseTarget: performSwap,
                        falseArguments: []
                    ),
                ]
            )
            appendSyntheticBlock(
                id: performSwap,
                instructions: [
                    .loadStack(
                        result: currentSwapPivot,
                        slot: pivotSlot,
                        mode: .copy
                    ),
                    .arrayMutationSwap(
                        state: context.state,
                        lhsIndex: currentSwapPivot,
                        rhsIndex: elementIndex
                    ),
                    .constantInteger(result: oneSwap, bitPattern: 1),
                    .checkedBinary(
                        result: incrementedSwapPivot,
                        overflow: swapPivotOverflow,
                        operation: .add,
                        lhs: currentSwapPivot,
                        rhs: oneSwap
                    ),
                    .conditionalBranch(
                        condition: swapPivotOverflow,
                        trueTarget: overflowTrap,
                        trueArguments: [],
                        falseTarget: storeSwappedPivot,
                        falseArguments: []
                    ),
                ]
            )
            appendSyntheticBlock(
                id: storeSwappedPivot,
                instructions: [
                    .storeStack(
                        slot: pivotSlot,
                        source: incrementedSwapPivot,
                        mode: .assign
                    ),
                    .branch(target: suffixLoop, arguments: []),
                ]
            )
            appendSyntheticBlock(
                id: complete,
                instructions: [
                    .loadStack(
                        result: boundary,
                        slot: pivotSlot,
                        mode: .take
                    ),
                    .destroyStack(indexSlot),
                    .finishArrayMutation(
                        result: partitioned,
                        state: context.state
                    ),
                    .makeArray(result: empty, elements: []),
                    .checkedBinary(
                        result: logicalBoundary,
                        overflow: boundaryOverflow,
                        operation: .add,
                        lhs: context.indexBase,
                        rhs: boundary
                    ),
                    .conditionalBranch(
                        condition: boundaryOverflow,
                        trueTarget: rangeOverflowTrap,
                        trueArguments: [],
                        falseTarget: computeLogicalEnd,
                        falseArguments: []
                    ),
                ]
            )
            appendSyntheticBlock(
                id: computeLogicalEnd,
                instructions: [
                    .checkedBinary(
                        result: logicalEnd,
                        overflow: endOverflow,
                        operation: .add,
                        lhs: context.indexBase,
                        rhs: context.count
                    ),
                    .conditionalBranch(
                        condition: endOverflow,
                        trueTarget: rangeOverflowTrap,
                        trueArguments: [],
                        falseTarget: performRemoval,
                        falseArguments: []
                    ),
                ]
            )
            appendSyntheticBlock(
                id: performRemoval,
                instructions: [
                    .arrayReplaceSubrange(
                        result: result,
                        array: partitioned,
                        lowerBound: logicalBoundary,
                        upperBound: logicalEnd,
                        replacement: empty
                    ),
                    .destroyValue(partitioned),
                    .destroyValue(empty),
                    .destroyValue(traversalSource),
                    .branch(target: normalTarget, arguments: [result]),
                ]
            )
            appendSyntheticBlock(
                id: initialFailed,
                parameters: [initialError],
                instructions: (elementNeedsCleanup
                    ? [.destroyValue(initialElement)] : []) + [
                    .destroyStack(indexSlot),
                    .destroyStack(pivotSlot),
                    .destroyValue(traversalSource),
                    .finishArrayMutation(
                        result: initialErrorArray,
                        state: context.state
                    ),
                    .branch(
                        target: errorTarget,
                        arguments: [initialError, initialErrorArray]
                    ),
                ]
            )
            appendSyntheticBlock(
                id: suffixFailed,
                parameters: [suffixError],
                instructions: (elementNeedsCleanup
                    ? [.destroyValue(suffixElement)] : []) + [
                    .destroyStack(indexSlot),
                    .destroyStack(pivotSlot),
                    .destroyValue(traversalSource),
                    .finishArrayMutation(
                        result: suffixErrorArray,
                        state: context.state
                    ),
                    .branch(
                        target: errorTarget,
                        arguments: [suffixError, suffixErrorArray]
                    ),
                ]
            )
            appendSyntheticBlock(
                id: overflowTrap,
                instructions: [.trap(.integerOverflow)]
            )
            appendSyntheticBlock(
                id: rangeOverflowTrap,
                instructions: [.trap(.integerOverflow)]
            )
        }

        func lowerSequenceOrderingTryApply(
            operation: CanonicalSIL.OrderingIntrinsic,
            genericArguments: String,
            argumentText: String,
            normalTarget: Bytecode.BlockID,
            errorTarget: Bytecode.BlockID,
            line: Int
        ) throws {
            let plan = try parseSequenceOrderingPlan(
                operation: operation,
                genericArguments: genericArguments,
                argumentText: argumentText,
                line: line
            )
            switch operation {
            case .sortedBy, .sortBy:
                try lowerSequenceComparatorSortTryApply(
                    plan: plan,
                    normalTarget: normalTarget,
                    errorTarget: errorTarget,
                    line: line
                )
            case .sorted, .sort:
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "natural ordering unexpectedly used try_apply"
                )
            }
        }

        func lowerArrayPredicateMutationTryApply(
            operation: CanonicalSIL.ArrayPredicateMutationIntrinsic,
            genericArguments: String,
            argumentText: String,
            normalTarget: Bytecode.BlockID,
            errorTarget: Bytecode.BlockID,
            line: Int
        ) throws {
            let plan = try parseArrayPredicateMutationPlan(
                operation: operation,
                genericArguments: genericArguments,
                argumentText: argumentText,
                line: line
            )
            switch operation {
            case .partition:
                try lowerArrayBidirectionalPartitionTryApply(
                    plan: plan,
                    normalTarget: normalTarget,
                    errorTarget: errorTarget,
                    line: line
                )
            case .removeAllWhere:
                try lowerArrayHalfStableRemovalTryApply(
                    plan: plan,
                    normalTarget: normalTarget,
                    errorTarget: errorTarget,
                    line: line
                )
            }
        }

        func lowerArraySplitTryApply(
            genericArguments: String,
            argumentText: String,
            normalTarget: Bytecode.BlockID,
            errorTarget: Bytecode.BlockID,
            line: Int
        ) throws {
            let plan = try parseArraySplitPlan(
                operation: .predicate,
                genericArguments: genericArguments,
                argumentText: argumentText,
                line: line
            )
            let arrayType = Bytecode.ValueType.array(plan.elementType)
            let materialized = try materializeSequenceOperand(
                plan.source,
                token: plan.sourceToken,
                context: "split(whereSeparator:) source",
                line: line
            )
            let maximumSplits = try resolve(
                plan.maximumSplitsToken,
                line: line
            )
            let omittingEmptySubsequences = try resolve(
                plan.omittingEmptySubsequencesToken,
                line: line
            )
            let closure = try resolve(plan.decisionToken, line: line)
            guard registerTypes[Int(materialized.array.rawValue)] == arrayType,
                  registerTypes[Int(maximumSplits.rawValue)] == .int64,
                  registerTypes[Int(omittingEmptySubsequences.rawValue)] == .bool,
                  case let .closure(signature) = registerTypes[
                    Int(closure.rawValue)
                  ], signature.parameters == [plan.elementType],
                  signature.parameterConventions.count == 1,
                  signature.parameterConventions[0] != .inout,
                  signature.result == .bool,
                  signature.effects.mayThrow,
                  !signature.effects.isAsync
            else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: "<Array split predicate>"
                )
            }

            guard let errorType = try closureThrownType(
                signature,
                context: "Array split predicate"
            ) else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: "<Array split predicate>"
                )
            }
            let error = try allocate(type: errorType)
            let state = try allocate(
                type: .arrayState(kind: .split, element: plan.elementType)
            )
            let next = try allocate(type: .optional(plan.elementType))
            let element = try allocate(type: plan.elementType)
            let isSeparator = try allocate(type: .bool)
            let result = try allocate(type: .array(arrayType))
            let loop = try allocateSyntheticBlockID()
            let evaluate = try allocateSyntheticBlockID()
            let accepted = try allocateSyntheticBlockID()
            let complete = try allocateSyntheticBlockID()
            let failed = try allocateSyntheticBlockID()

            appendInstruction(
                .makeArraySplitState(
                    result: state,
                    array: materialized.array,
                    maxSplits: maximumSplits,
                    omittingEmptySubsequences: omittingEmptySubsequences
                )
            )
            for instruction in materialized.cleanup {
                appendInstruction(instruction)
            }
            appendInstruction(.branch(target: loop, arguments: []))
            finishCurrent()

            appendSyntheticBlock(
                id: loop,
                instructions: [
                    .arraySplitNextElement(result: next, state: state),
                    .switchOptional(
                        optional: next,
                        someTarget: evaluate,
                        noneTarget: complete
                    ),
                ]
            )
            appendSyntheticBlock(
                id: evaluate,
                parameters: [element],
                instructions: [
                    .closureTryApply(
                        closure: closure,
                        arguments: [element],
                        normalTarget: accepted,
                        errorTarget: failed
                    ),
                ]
            )
            let borrowedElementCleanup: [IntermediateRepresentation.Instruction]
            if requiresManagedOwnership(plan.elementType),
               signature.parameterConventions[0] == .borrowed {
                borrowedElementCleanup = [.destroyValue(element)]
            } else {
                borrowedElementCleanup = []
            }
            appendSyntheticBlock(
                id: accepted,
                parameters: [isSeparator],
                instructions: borrowedElementCleanup + [
                    .arraySplitAcceptElement(
                        state: state,
                        isSeparator: isSeparator
                    ),
                    .branch(target: loop, arguments: []),
                ]
            )
            appendSyntheticBlock(
                id: complete,
                instructions: [
                    .finishArraySplit(result: result, state: state),
                    .branch(target: normalTarget, arguments: [result]),
                ]
            )
            appendSyntheticBlock(
                id: failed,
                parameters: [error],
                instructions: borrowedElementCleanup + [
                    .destroyValue(state),
                    .branch(target: errorTarget, arguments: [error]),
                ]
            )
        }

        func lowerDictionaryAccumulationTryApply(
            intrinsic: CanonicalSIL.DictionaryAccumulationIntrinsic,
            genericArguments: String,
            argumentText: String,
            normalTarget: Bytecode.BlockID,
            errorTarget: Bytecode.BlockID,
            line: Int
        ) throws {
            let plan = try parseDictionaryAccumulationPlan(
                intrinsic: intrinsic,
                genericArguments: genericArguments,
                argumentText: argumentText,
                line: line
            )
            let source = try materializeOwnedValue(
                at: plan.sourceToken,
                line: line
            )
            guard registerTypes[Int(source.rawValue)] == plan.sourceType else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "Dictionary accumulation source does not match its specialization"
                )
            }

            let closure = try resolve(plan.closureToken, line: line)
            let expectedClosureParameters: [Bytecode.ValueType]
            let expectedClosureResult: Bytecode.ValueType
            switch plan.intrinsic.callback {
            case .combineValues:
                expectedClosureParameters = [plan.valueType, plan.valueType]
                expectedClosureResult = plan.valueType
            case .classifyElement:
                expectedClosureParameters = [plan.elementType]
                expectedClosureResult = plan.keyType
            }
            guard case let .closure(closureSignature) = registerTypes[
                Int(closure.rawValue)
            ], closureSignature.parameters == expectedClosureParameters,
               closureSignature.parameterConventions.count
                    == expectedClosureParameters.count,
               !closureSignature.parameterConventions.contains(.inout),
               closureSignature.result == expectedClosureResult,
               closureSignature.effects.mayThrow,
               !closureSignature.effects.isAsync
            else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: "<Dictionary accumulation closure>"
                )
            }
            for (type, convention) in zip(
                expectedClosureParameters,
                closureSignature.parameterConventions
            ) where type.requiresLinearOwnership
                && convention != .borrowed {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: "<Dictionary accumulation borrowed input>"
                )
            }

            let initialDictionary: Bytecode.Register?
            let writesBackPartialResult: Bool
            switch plan.intrinsic.seed {
            case .empty:
                guard let metatypeToken = plan.metatypeToken,
                      let metatype = dictionaryMetatypeValues[metatypeToken],
                      metatype.0 == plan.keyType,
                      metatype.1 == plan.valueType
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Dictionary accumulation metatype does not match its result"
                    )
                }
                initialDictionary = nil
                writesBackPartialResult = false

            case .ownedDictionary:
                guard let seedToken = plan.seedToken else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Dictionary accumulation omitted its owned seed"
                    )
                }
                let seed = try materializeOwnedValue(
                    at: seedToken,
                    line: line
                )
                guard registerTypes[Int(seed.rawValue)]
                        == plan.dictionaryType
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Dictionary accumulation seed has the wrong type"
                    )
                }
                initialDictionary = seed
                writesBackPartialResult = false

            case .inoutDictionary:
                guard let seedToken = plan.seedToken,
                      compilerAddressType(seedToken) == plan.dictionaryType,
                      let seed = try takeStoredValue(
                        at: seedToken,
                        line: line
                      ),
                      registerTypes[Int(seed.rawValue)]
                        == plan.dictionaryType,
                      implicitStackValues[normalTarget] == nil,
                      implicitStackValues[errorTarget] == nil,
                      suppressedTryNormalParameterTypes.updateValue(
                        .void,
                        forKey: normalTarget
                      ) == nil
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Dictionary accumulation inout seed cannot be written back"
                    )
                }
                let normalWriteback = try allocate(
                    type: plan.dictionaryType
                )
                let errorWriteback = try allocate(
                    type: plan.dictionaryType
                )
                implicitStackValues[normalTarget] = [
                    .init(seedToken, normalWriteback, storeMode: .initialize),
                ]
                implicitStackValues[errorTarget] = [
                    .init(seedToken, errorWriteback, storeMode: .initialize),
                ]
                initialDictionary = seed
                writesBackPartialResult = true
            }

            let builder = try allocate(
                type: .dictionaryState(
                    key: plan.keyType,
                    value: plan.valueType
                )
            )
            appendInstruction(
                .makeDictionaryBuilder(
                    result: builder,
                    initialValue: initialDictionary
                )
            )
            if let initialDictionary,
               requiresManagedOwnership(plan.dictionaryType) {
                appendInstruction(.destroyValue(initialDictionary))
            }

            let indexSlot = try allocateStackSlot(type: .int64)
            let initialIndex = try allocate(type: .int64)
            appendInstruction(
                .constantInteger(result: initialIndex, bitPattern: 0)
            )
            appendInstruction(
                .storeStack(
                    slot: indexSlot,
                    source: initialIndex,
                    mode: .initialize
                )
            )

            guard let errorType = try closureThrownType(
                closureSignature,
                context: "Dictionary accumulation closure"
            ) else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: "<Dictionary accumulation closure>"
                )
            }
            let error = try allocate(type: errorType)
            let completedDictionary = try allocate(
                type: plan.dictionaryType
            )
            let loop = try allocateSyntheticBlockID()
            let some = try allocateSyntheticBlockID()
            let complete = try allocateSyntheticBlockID()
            let failed = try allocateSyntheticBlockID()
            let next = try allocate(type: .optional(plan.elementType))
            let element = try allocate(type: plan.elementType)
            let sourceCleanup: [IntermediateRepresentation.Instruction] =
                requiresManagedOwnership(plan.sourceType)
                    ? [.destroyValue(source)] : []

            appendInstruction(.branch(target: loop, arguments: []))
            finishCurrent()
            appendSyntheticBlock(
                id: loop,
                instructions: [
                    .collectionNext(
                        result: next,
                        collection: source,
                        indexSlot: indexSlot,
                        direction: .forward
                    ),
                    .switchOptional(
                        optional: next,
                        someTarget: some,
                        noneTarget: complete
                    ),
                ]
            )

            switch plan.intrinsic.callback {
            case .combineValues:
                let key = try allocate(type: plan.keyType)
                let incoming = try allocate(type: plan.valueType)
                let existingOptional = try allocate(
                    type: .optional(plan.valueType)
                )
                let existing = try allocate(type: plan.valueType)
                let combined = try allocate(type: plan.valueType)
                let duplicate = try allocateSyntheticBlockID()
                let missing = try allocateSyntheticBlockID()
                let combinedValue = try allocateSyntheticBlockID()
                let keyCleanup: [IntermediateRepresentation.Instruction] =
                    requiresManagedOwnership(plan.keyType)
                        ? [.destroyValue(key)] : []
                let incomingCleanup: [IntermediateRepresentation.Instruction] =
                    requiresManagedOwnership(plan.valueType)
                        ? [.destroyValue(incoming)] : []
                let existingCleanup: [IntermediateRepresentation.Instruction] =
                    requiresManagedOwnership(plan.valueType)
                        ? [.destroyValue(existing)] : []
                let combinedCleanup: [IntermediateRepresentation.Instruction] =
                    requiresManagedOwnership(plan.valueType)
                        ? [.destroyValue(combined)] : []

                appendSyntheticBlock(
                    id: some,
                    parameters: [element],
                    instructions: [
                        .unpackTuple(
                            results: [key, incoming],
                            tuple: element
                        ),
                        .dictionaryBuilderGet(
                            result: existingOptional,
                            builder: builder,
                            key: key
                        ),
                        .switchOptional(
                            optional: existingOptional,
                            someTarget: duplicate,
                            noneTarget: missing
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: duplicate,
                    parameters: [existing],
                    instructions: [
                        .closureTryApply(
                            closure: closure,
                            arguments: [existing, incoming],
                            normalTarget: combinedValue,
                            errorTarget: failed
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: missing,
                    instructions: [
                        .dictionaryBuilderSet(
                            builder: builder,
                            key: key,
                            value: incoming
                        ),
                    ] + keyCleanup + incomingCleanup + [
                        .branch(target: loop, arguments: []),
                    ]
                )
                appendSyntheticBlock(
                    id: combinedValue,
                    parameters: [combined],
                    instructions: [
                        .dictionaryBuilderSet(
                            builder: builder,
                            key: key,
                            value: combined
                        ),
                    ] + keyCleanup + incomingCleanup + existingCleanup
                        + combinedCleanup + [
                        .branch(target: loop, arguments: []),
                    ]
                )

                var failureInstructions = keyCleanup + incomingCleanup
                    + existingCleanup
                if writesBackPartialResult {
                    let partial = try allocate(type: plan.dictionaryType)
                    failureInstructions.append(
                        .finishDictionaryBuilder(
                            result: partial,
                            builder: builder
                        )
                    )
                    failureInstructions.append(.destroyStack(indexSlot))
                    failureInstructions.append(contentsOf: sourceCleanup)
                    failureInstructions.append(
                        .branch(
                            target: errorTarget,
                            arguments: [error, partial]
                        )
                    )
                } else {
                    failureInstructions.append(.destroyValue(builder))
                    failureInstructions.append(.destroyStack(indexSlot))
                    failureInstructions.append(contentsOf: sourceCleanup)
                    failureInstructions.append(
                        .branch(
                            target: errorTarget,
                            arguments: [error]
                        )
                    )
                }
                appendSyntheticBlock(
                    id: failed,
                    parameters: [error],
                    instructions: failureInstructions
                )

            case .classifyElement:
                let key = try allocate(type: plan.keyType)
                let classified = try allocateSyntheticBlockID()
                let elementCleanup: [IntermediateRepresentation.Instruction] =
                    requiresManagedOwnership(plan.elementType)
                        ? [.destroyValue(element)] : []
                let keyCleanup: [IntermediateRepresentation.Instruction] =
                    requiresManagedOwnership(plan.keyType)
                        ? [.destroyValue(key)] : []
                appendSyntheticBlock(
                    id: some,
                    parameters: [element],
                    instructions: [
                        .closureTryApply(
                            closure: closure,
                            arguments: [element],
                            normalTarget: classified,
                            errorTarget: failed
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: classified,
                    parameters: [key],
                    instructions: [
                        .dictionaryBuilderAppendArrayElement(
                            builder: builder,
                            key: key,
                            element: element
                        ),
                    ] + keyCleanup + elementCleanup + [
                        .branch(target: loop, arguments: []),
                    ]
                )
                appendSyntheticBlock(
                    id: failed,
                    parameters: [error],
                    instructions: elementCleanup + [
                        .destroyValue(builder),
                        .destroyStack(indexSlot),
                    ] + sourceCleanup + [
                        .branch(
                            target: errorTarget,
                            arguments: [error]
                        ),
                    ]
                )
            }

            appendSyntheticBlock(
                id: complete,
                instructions: [
                    .finishDictionaryBuilder(
                        result: completedDictionary,
                        builder: builder
                    ),
                    .destroyStack(indexSlot),
                ] + sourceCleanup + [
                    .branch(
                        target: normalTarget,
                        arguments: [completedDictionary]
                    ),
                ]
            )
        }

        /// `Sequence.reduce(into:_:)` is the standard-library operation whose
        /// callback receives caller-owned mutable storage. Keep that storage
        /// in one frame slot and pass a scoped address into each invocation;
        /// this models Swift's inout exclusivity without copying the
        /// accumulator or teaching the VM about a particular accumulator type.
        func lowerSequenceReduceIntoTryApply(
            plan: SequenceHigherOrderPlan,
            normalTarget: Bytecode.BlockID,
            errorTarget: Bytecode.BlockID,
            line: Int
        ) throws {
            guard plan.operation == .reduceInto,
                  let initialToken = plan.initialToken,
                  let resultDestination = plan.resultDestination
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "reduce(into:_:) has an incomplete lowering plan"
                )
            }

            let closure = try resolve(plan.closureToken, line: line)
            let accumulatorAddressType = Bytecode.ValueType.address(
                plan.callResultType
            )
            guard case let .closure(closureSignature) = registerTypes[
                Int(closure.rawValue)
            ], closureSignature.parameters == [
                accumulatorAddressType,
                plan.inputType,
            ], closureSignature.parameterConventions.count == 2,
               closureSignature.parameterConventions[0] == .inout,
               closureSignature.parameterConventions[1] != .inout,
               closureSignature.result == .void,
               closureSignature.effects.mayThrow,
               !closureSignature.effects.isAsync
            else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: "<reduce(into:) closure>"
                )
            }
            let elementConvention = closureSignature.parameterConventions[1]
            if plan.inputType.requiresLinearOwnership,
               elementConvention != .borrowed {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: "<reduce(into:) borrowed element>"
                )
            }

            guard compilerAddressType(resultDestination)
                    == plan.callResultType,
                  implicitStackValues[normalTarget] == nil,
                  suppressedTryNormalParameterTypes.updateValue(
                    .void,
                    forKey: normalTarget
                  ) == nil
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "reduce(into:_:) indirect result destination is invalid"
                )
            }
            let propagatedResult = try allocate(type: plan.callResultType)
            implicitStackValues[normalTarget] = [
                .init(resultDestination, propagatedResult),
            ]

            guard let errorValueType = try closureThrownType(
                closureSignature,
                context: "reduce(into:) closure"
            ) else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: "<reduce(into:) closure>"
                )
            }
            let errorParameter = try allocate(type: errorValueType)
            if let errorDestination = plan.errorDestination {
                guard compilerAddressType(errorDestination) == errorValueType,
                      implicitStackValues[errorTarget] == nil
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "reduce(into:_:) indirect Error destination is invalid"
                    )
                }
                let propagatedError = try allocate(type: errorValueType)
                implicitStackValues[errorTarget] = [
                    .init(errorDestination, propagatedError),
                ]
            }

            let initialAccumulator: Bytecode.Register
            if stackType(at: initialToken) != nil {
                guard let taken = try takeStoredValue(
                    at: initialToken,
                    line: line
                ) else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "reduce(into:_:) initial accumulator is uninitialized"
                    )
                }
                initialAccumulator = taken
            } else {
                initialAccumulator = try materializeOwnedValue(
                    at: initialToken,
                    line: line
                )
            }
            guard registerTypes[Int(initialAccumulator.rawValue)]
                    == plan.callResultType
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "reduce(into:_:) initial accumulator has the wrong type"
                )
            }

            let accumulatorSlot = try allocateStackSlot(
                type: plan.callResultType
            )
            appendInstruction(
                .storeStack(
                    slot: accumulatorSlot,
                    source: initialAccumulator,
                    mode: .initialize
                )
            )
            let accumulatorAddress = try allocate(
                type: accumulatorAddressType
            )
            appendInstruction(
                .stackAddress(
                    result: accumulatorAddress,
                    slot: accumulatorSlot
                )
            )
            let traversal = try prepareSequenceTraversal(
                plan.source,
                token: plan.sourceToken,
                consumesSource: false,
                direction: .forward,
                line: line
            )

            let loop = try allocateSyntheticBlockID()
            let some = try allocateSyntheticBlockID()
            let empty = try allocateSyntheticBlockID()
            let closureContinuation = try allocateSyntheticBlockID()
            let closureError = try allocateSyntheticBlockID()
            let next = try allocate(type: .optional(plan.inputType))
            let element = try allocate(type: plan.inputType)
            let accumulatorAccess = try allocate(
                type: accumulatorAddressType
            )
            let finalAccumulator = try allocate(type: plan.callResultType)
            let elementCleanup: [IntermediateRepresentation.Instruction] =
                requiresManagedOwnership(plan.inputType)
                    ? [.destroyValue(element)] : []

            appendInstruction(.branch(target: loop, arguments: []))
            finishCurrent()

            appendSyntheticBlock(
                id: loop,
                instructions: [
                    try sequenceNextInstruction(
                        cursor: traversal.cursor,
                        result: next,
                        direction: .forward
                    ),
                    .switchOptional(
                        optional: next,
                        someTarget: some,
                        noneTarget: empty
                    ),
                ]
            )
            appendSyntheticBlock(
                id: some,
                parameters: [element],
                instructions: [
                    .beginAccess(
                        result: accumulatorAccess,
                        address: accumulatorAddress,
                        kind: .modify
                    ),
                    .closureTryApply(
                        closure: closure,
                        arguments: [accumulatorAccess, element],
                        normalTarget: closureContinuation,
                        errorTarget: closureError
                    ),
                ]
            )
            appendSyntheticBlock(
                id: closureContinuation,
                instructions: [
                    .endAccess(accumulatorAccess),
                ] + elementCleanup + [
                    .branch(target: loop, arguments: []),
                ]
            )
            appendSyntheticBlock(
                id: empty,
                instructions: [
                    .loadStack(
                        result: finalAccumulator,
                        slot: accumulatorSlot,
                        mode: .take
                    ),
                ] + traversalCleanup(traversal) + [
                    .branch(
                        target: normalTarget,
                        arguments: [finalAccumulator]
                    ),
                ]
            )
            appendSyntheticBlock(
                id: closureError,
                parameters: [errorParameter],
                instructions: [
                    .endAccess(accumulatorAccess),
                ] + elementCleanup + [
                    .destroyStack(accumulatorSlot),
                ] + traversalCleanup(traversal) + [
                    .branch(
                        target: errorTarget,
                        arguments: [errorParameter]
                    ),
                ]
            )
        }

        func lowerSequenceHigherOrderTryApply(
            operation: CanonicalSIL.HigherOrderIntrinsic,
            genericArguments: String,
            argumentText: String,
            normalTarget: Bytecode.BlockID,
            errorTarget: Bytecode.BlockID,
            line: Int
        ) throws {
            let plan = try parseSequenceHigherOrderPlan(
                operation: operation,
                genericArguments: genericArguments,
                argumentText: argumentText,
                line: line
            )
            if operation == .reduceInto {
                try lowerSequenceReduceIntoTryApply(
                    plan: plan,
                    normalTarget: normalTarget,
                    errorTarget: errorTarget,
                    line: line
                )
                return
            }
            func requiredRegister(
                _ register: Bytecode.Register?,
                _ role: String
            ) throws -> Bytecode.Register {
                guard let register else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "higher-order lowering omitted its \(role) register"
                    )
                }
                return register
            }
            let closure = try resolve(plan.closureToken, line: line)
            guard case let .closure(closureSignature) = registerTypes[
                Int(closure.rawValue)
            ], !closureSignature.effects.isAsync,
               closureSignature.result == plan.closureResultType
            else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: "<higher-order closure>"
                )
            }
            let dictionaryTypes: (
                key: Bytecode.ValueType,
                value: Bytecode.ValueType
            )? = if case let .dictionary(key, value)? =
                plan.source.managedCollectionType {
                (key, value)
            } else {
                nil
            }
            let expectedClosureParameters: [Bytecode.ValueType]
            switch plan.callbackShape {
            case .dictionaryValue:
                guard let dictionaryTypes else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Dictionary value callback has a non-Dictionary source"
                    )
                }
                expectedClosureParameters = [dictionaryTypes.value]
            case .dictionaryKeyValue:
                guard let dictionaryTypes else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Dictionary key/value callback has a non-Dictionary source"
                    )
                }
                expectedClosureParameters = [
                    dictionaryTypes.key,
                    dictionaryTypes.value,
                ]
            case .element:
                expectedClosureParameters = switch plan.operation {
                case .reduce:
                    [plan.callResultType, plan.inputType]
                case .minimumBy, .maximumBy:
                    [plan.inputType, plan.inputType]
                case .map, .flatMap, .filter(_), .compactMap, .prefixWhile,
                     .dropWhile, .forEach, .firstWhere, .lastWhere,
                     .firstIndexWhere, .lastIndexWhere, .containsWhere,
                     .allSatisfy, .countWhere, .reduceInto:
                    [plan.inputType]
                case .mapValues, .compactMapValues:
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Dictionary value transform lost its callback projection"
                    )
                }
            }
            guard closureSignature.parameters == expectedClosureParameters,
                  closureSignature.parameterConventions.count
                    == expectedClosureParameters.count,
                  !closureSignature.parameterConventions.contains(.inout)
            else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: "<higher-order closure>"
                )
            }
            if plan.operation.isComparatorSelection,
               plan.inputType.requiresLinearOwnership,
               closureSignature.parameterConventions != [.borrowed, .borrowed] {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: "<comparison closure>"
                )
            }

            let closureErrorType = try closureThrownType(
                closureSignature,
                context: "higher-order closure"
            )
            let isThrowing = closureErrorType != nil
            if let errorGenericIndex = plan.operation.explicitErrorGenericIndex {
                let genericSpellings = splitTopLevel(genericArguments)
                    .filter { !$0.isEmpty }
                guard genericSpellings.indices.contains(errorGenericIndex),
                      errorGenericIndex == genericSpellings.count - 1
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "typed-throws Sequence operation has an incomplete specialization"
                    )
                }
                let errorType = try parseType(
                    genericSpellings[errorGenericIndex]
                )
                guard try closureThrownType(
                    closureSignature,
                    matching: errorType,
                    context: "typed-throws Sequence operation"
                ) == closureErrorType,
                      plan.errorDestination.map({
                        compilerAddressType($0) == errorType
                      }) == true
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "typed-throws Sequence error specialization does not match its closure"
                    )
                }
            } else {
                guard let closureErrorType else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "higher-order rethrows ABI lost its Error channel"
                    )
                }
                if let destination = plan.errorDestination {
                    guard compilerAddressType(destination) == closureErrorType else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "higher-order rethrows Error does not match its closure"
                        )
                    }
                }
            }

            if let destination = plan.resultDestination {
                guard compilerAddressType(destination) == plan.callResultType,
                      implicitStackValues[normalTarget] == nil,
                      suppressedTryNormalParameterTypes.updateValue(
                        .void,
                        forKey: normalTarget
                      ) == nil
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "higher-order indirect result destination is invalid"
                    )
                }
                let parameter = try allocate(type: plan.callResultType)
                implicitStackValues[normalTarget] = [.init(destination, parameter)]
            } else if plan.callResultType == .void {
                guard suppressedTryNormalParameterTypes.updateValue(
                    .void,
                    forKey: normalTarget
                ) == nil
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "higher-order Void continuation is shared"
                    )
                }
            }

            let errorCleanup = try allocateSyntheticBlockID()
            let errorParameter: Bytecode.Register?
            if isThrowing {
                guard let errorValueType = closureErrorType else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "higher-order closure lost its Error channel"
                    )
                }
                errorParameter = try allocate(type: errorValueType)
                if let destination = plan.errorDestination {
                    guard compilerAddressType(destination) == errorValueType,
                          implicitStackValues[errorTarget] == nil
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "higher-order indirect Error destination is invalid"
                        )
                    }
                    let propagated = try allocate(type: errorValueType)
                    implicitStackValues[errorTarget] = [
                        .init(destination, propagated),
                    ]
                }
            } else {
                errorParameter = nil
            }

            let traversalDirection = plan.operation.traversalDirection
            let traversal = try prepareSequenceTraversal(
                plan.source,
                token: plan.sourceToken,
                consumesSource: plan.consumesSource,
                direction: traversalDirection,
                line: line
            )
            let cursorSlot = traversal.cursor.slot

            let sourceIndexBase: Bytecode.Register?
            if plan.sourceIndexModel != nil {
                guard case let .managedCollection(collection, _) =
                    traversal.cursor,
                    case .array = registerTypes[Int(collection.rawValue)]
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "integer-index result has a non-Array-backed source"
                    )
                }
                let base = try allocate(type: .int64)
                appendInstruction(
                    .arrayIndexBase(result: base, array: collection)
                )
                sourceIndexBase = base
            } else {
                sourceIndexBase = nil
            }

            let droppedCountSlot: Bytecode.StackSlot?
            if plan.preservesSubsequenceIndexBase,
               plan.operation == .dropWhile {
                let slot = try allocateStackSlot(type: .int64)
                let zero = try allocate(type: .int64)
                appendInstruction(
                    .constantInteger(result: zero, bitPattern: 0)
                )
                appendInstruction(
                    .storeStack(
                        slot: slot,
                        source: zero,
                        mode: .initialize
                    )
                )
                droppedCountSlot = slot
            } else {
                droppedCountSlot = nil
            }

            let builder: Bytecode.Register?
            if plan.operation.usesElementBuilder {
                let element: Bytecode.ValueType
                switch plan.builderOutput {
                case .representedCollection:
                    switch plan.callResultType {
                    case let .array(resultElement),
                         let .set(resultElement):
                        element = resultElement
                    case let .dictionary(key, value):
                        element = .tuple([key, value])
                    default:
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "higher-order builder has an unsupported result container"
                        )
                    }
                case .stringCharacters:
                    guard plan.callResultType == .string else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "text builder result must use represented String storage"
                        )
                    }
                    element = .string
                }
                let register = try allocate(
                    type: .arrayState(kind: .builder, element: element)
                )
                appendInstruction(.makeArrayBuilder(result: register))
                builder = register
            } else {
                builder = nil
            }
            func finishCollectionBuilder(
                _ builder: Bytecode.Register
            ) throws -> (
                result: Bytecode.Register,
                instructions: [IntermediateRepresentation.Instruction]
            ) {
                switch plan.builderOutput {
                case .stringCharacters:
                    let characters = try allocate(type: .array(.string))
                    let result = try allocate(type: .string)
                    return (
                        result,
                        [
                            .finishArrayBuilder(
                                result: characters,
                                builder: builder
                            ),
                            .stringJoin(
                                result: result,
                                elements: characters,
                                separator: nil,
                                elementKind: .character
                            ),
                        ]
                    )

                case .representedCollection:
                    break
                }

                let result = try allocate(type: plan.callResultType)
                switch plan.callResultType {
                case .array:
                    return (
                        result,
                        [.finishArrayBuilder(result: result, builder: builder)]
                    )
                case let .dictionary(key, value):
                    let bufferedType = Bytecode.ValueType.array(
                        .tuple([key, value])
                    )
                    let buffered = try allocate(type: bufferedType)
                    var instructions: [IntermediateRepresentation.Instruction] = [
                        .finishArrayBuilder(result: buffered, builder: builder),
                        .makeDictionary(result: result, pairs: buffered),
                    ]
                    if requiresManagedOwnership(bufferedType) {
                        instructions.append(.destroyValue(buffered))
                    }
                    return (result, instructions)
                case let .set(element):
                    let bufferedType = Bytecode.ValueType.array(element)
                    let buffered = try allocate(type: bufferedType)
                    var instructions: [IntermediateRepresentation.Instruction] = [
                        .finishArrayBuilder(result: buffered, builder: builder),
                        .makeSet(result: result, source: buffered),
                    ]
                    if requiresManagedOwnership(bufferedType) {
                        instructions.append(.destroyValue(buffered))
                    }
                    return (result, instructions)
                default:
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "higher-order builder has an unsupported result container"
                    )
                }
            }

            func finishIndexPreservingSubsequenceBuilder(
                _ builder: Bytecode.Register
            ) throws -> (
                result: Bytecode.Register,
                instructions: [IntermediateRepresentation.Instruction]
            ) {
                let finished = try finishCollectionBuilder(builder)
                guard plan.preservesSubsequenceIndexBase else {
                    return finished
                }
                guard case .array = plan.callResultType,
                      let sourceIndexBase
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "index-preserving subsequence has incomplete storage"
                    )
                }

                var instructions = finished.instructions
                let resultBase: Bytecode.Register
                if let droppedCountSlot {
                    let droppedCount = try allocate(type: .int64)
                    let rebased = try allocate(type: .int64)
                    let overflow = try allocate(type: .bool)
                    instructions.append(
                        .loadStack(
                            result: droppedCount,
                            slot: droppedCountSlot,
                            mode: .copy
                        )
                    )
                    instructions.append(
                        .checkedBinary(
                            result: rebased,
                            overflow: overflow,
                            operation: .add,
                            lhs: sourceIndexBase,
                            rhs: droppedCount
                        )
                    )
                    // The source value has already validated base + count and
                    // the traversal cursor never exceeds count. Therefore this
                    // checked addition cannot overflow for a valid VM value.
                    resultBase = rebased
                } else {
                    resultBase = sourceIndexBase
                }

                let result = try allocate(type: plan.callResultType)
                instructions.append(
                    .arrayRebase(
                        result: result,
                        array: finished.result,
                        indexBase: resultBase
                    )
                )
                return (result, instructions)
            }

            func appendDictionaryPair(
                key: Bytecode.Register,
                value: Bytecode.Register,
                to builder: Bytecode.Register
            ) throws -> [IntermediateRepresentation.Instruction] {
                guard case let .dictionary(keyType, valueType) =
                    plan.callResultType,
                    registerTypes[Int(key.rawValue)] == keyType,
                    registerTypes[Int(value.rawValue)] == valueType
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Dictionary builder pair does not match its result type"
                    )
                }
                let pairType = Bytecode.ValueType.tuple([keyType, valueType])
                let pair = try allocate(type: pairType)
                var instructions: [IntermediateRepresentation.Instruction] = [
                    .makeTuple(result: pair, elements: [key, value]),
                    .arrayBuilderAppend(builder: builder, value: pair),
                ]
                if requiresManagedOwnership(pairType) {
                    instructions.append(.destroyValue(pair))
                }
                return instructions
            }
            let accumulatorType: Bytecode.ValueType? = if plan.operation == .reduce
                || plan.operation == .countWhere {
                plan.callResultType
            } else if plan.operation.isComparatorSelection {
                plan.inputType
            } else {
                nil
            }
            let initialAccumulator: Bytecode.Register?
            if plan.operation == .reduce {
                guard let initialToken = plan.initialToken
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Sequence.reduce initial value does not match its result"
                    )
                }
                let storedInitial = try materializeOwnedValue(
                    at: initialToken,
                    line: line
                )
                guard registerTypes[Int(storedInitial.rawValue)]
                        == plan.callResultType
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Sequence.reduce initial value does not match its result"
                    )
                }
                initialAccumulator = storedInitial
            } else if plan.operation == .countWhere {
                let zero = try allocate(type: .int64)
                appendInstruction(
                    .constantInteger(result: zero, bitPattern: 0)
                )
                initialAccumulator = zero
            } else {
                initialAccumulator = nil
            }

            let loop = try allocateSyntheticBlockID()
            let some = try allocateSyntheticBlockID()
            let empty = try allocateSyntheticBlockID()
            let closureContinuation = try allocateSyntheticBlockID()
            let seed = try plan.operation.isComparatorSelection
                ? allocateSyntheticBlockID() : nil
            let seedSome = try plan.operation.isComparatorSelection
                ? allocateSyntheticBlockID() : nil
            let seedEmpty = try plan.operation.isComparatorSelection
                ? allocateSyntheticBlockID() : nil
            let loopAccumulator = try accumulatorType.map(allocate)
            let next = try allocate(type: .optional(plan.inputType))
            let element = try allocate(type: plan.inputType)
            let seedNext = try plan.operation.isComparatorSelection
                ? allocate(type: .optional(plan.inputType)) : nil
            let seedElement = try plan.operation.isComparatorSelection
                ? allocate(type: plan.inputType) : nil
            let directClosureResult = try isThrowing
                || plan.closureResultType == .void
                ? nil
                : allocate(type: plan.closureResultType)

            var closureArgumentPreparation: [
                IntermediateRepresentation.Instruction
            ] = []
            var dictionaryProjectionInstructions: [
                IntermediateRepresentation.Instruction
            ] = []
            var projectedFieldCleanup: [
                IntermediateRepresentation.Instruction
            ] = []
            let closureInput: Bytecode.Register?
            let projectedClosureArguments: [Bytecode.Register]
            let inputNeedsCleanup: Bool
            let dictionaryKey: Bytecode.Register?
            let dictionaryValue: Bytecode.Register?
            if plan.callbackShape == .element {
                dictionaryKey = nil
                dictionaryValue = nil
                projectedClosureArguments = []
                let inputConvention = closureSignature.parameterConventions[
                    plan.operation == .reduce ? 1 : 0
                ]
                if requiresManagedOwnership(plan.inputType),
                   inputConvention == .owned,
                   plan.operation.retainsInputAfterCall {
                    let copy = try allocate(type: plan.inputType)
                    closureArgumentPreparation.append(
                        .copyValue(result: copy, source: element)
                    )
                    closureInput = copy
                } else {
                    closureInput = element
                }
                inputNeedsCleanup = requiresManagedOwnership(plan.inputType)
                    && (inputConvention == .borrowed
                        || plan.operation.retainsInputAfterCall)
            } else {
                guard let dictionaryTypes,
                      plan.inputType == .tuple([
                        dictionaryTypes.key,
                        dictionaryTypes.value,
                      ])
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Dictionary callback projection has a mismatched element"
                    )
                }
                let key = try allocate(type: dictionaryTypes.key)
                let value = try allocate(type: dictionaryTypes.value)
                dictionaryKey = key
                dictionaryValue = value
                dictionaryProjectionInstructions = [
                    .unpackTuple(results: [key, value], tuple: element),
                ]
                if requiresManagedOwnership(dictionaryTypes.key) {
                    projectedFieldCleanup.append(.destroyValue(key))
                }
                if requiresManagedOwnership(dictionaryTypes.value) {
                    projectedFieldCleanup.append(.destroyValue(value))
                }
                func retainedClosureArgument(
                    _ register: Bytecode.Register,
                    type: Bytecode.ValueType,
                    convention: Bytecode.ParameterConvention
                ) throws -> Bytecode.Register {
                    guard requiresManagedOwnership(type),
                          convention == .owned
                    else { return register }
                    let copy = try allocate(type: type)
                    closureArgumentPreparation.append(
                        .copyValue(result: copy, source: register)
                    )
                    return copy
                }
                switch plan.callbackShape {
                case .dictionaryValue:
                    projectedClosureArguments = [
                        try retainedClosureArgument(
                            value,
                            type: dictionaryTypes.value,
                            convention: closureSignature.parameterConventions[0]
                        ),
                    ]
                case .dictionaryKeyValue:
                    projectedClosureArguments = [
                        try retainedClosureArgument(
                            key,
                            type: dictionaryTypes.key,
                            convention: closureSignature.parameterConventions[0]
                        ),
                        try retainedClosureArgument(
                            value,
                            type: dictionaryTypes.value,
                            convention: closureSignature.parameterConventions[1]
                        ),
                    ]
                case .element:
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "element callback entered Dictionary projection"
                    )
                }
                closureInput = nil
                inputNeedsCleanup = false
            }
            let accumulatorNeedsCleanup = accumulatorType.map(
                requiresManagedOwnership
            ) == true
                && (plan.operation.isComparatorSelection
                    || closureSignature.parameterConventions[0] == .borrowed)
            let sourceCleanup = traversal.cleanup

            let loopArguments = initialAccumulator.map { [$0] } ?? []
            let initialTarget = seed ?? loop
            if isThrowing {
                appendInstruction(
                    .branch(target: initialTarget, arguments: loopArguments)
                )
            } else {
                let mustSucceed = try allocate(type: .bool)
                appendInstruction(.constantBool(result: mustSucceed, value: true))
                appendInstruction(
                    .conditionalBranch(
                        condition: mustSucceed,
                        trueTarget: initialTarget,
                        trueArguments: loopArguments,
                        falseTarget: errorCleanup,
                        falseArguments: []
                    )
                )
            }
            finishCurrent()

            if let seed, let seedSome, let seedEmpty,
               let seedNext, let seedElement {
                appendSyntheticBlock(
                    id: seed,
                    instructions: [
                        try sequenceNextInstruction(
                            cursor: traversal.cursor,
                            result: seedNext,
                            direction: .forward
                        ),
                        .switchOptional(
                            optional: seedNext,
                            someTarget: seedSome,
                            noneTarget: seedEmpty
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: seedSome,
                    parameters: [seedElement],
                    instructions: [
                        .branch(target: loop, arguments: [seedElement]),
                    ]
                )
                let result = try allocate(type: plan.callResultType)
                appendSyntheticBlock(
                    id: seedEmpty,
                    instructions: [
                        .makeOptionalNone(result: result),
                        .destroyStack(cursorSlot),
                    ] + sourceCleanup + [
                        .branch(target: normalTarget, arguments: [result]),
                    ]
                )
            }

            appendSyntheticBlock(
                id: loop,
                parameters: loopAccumulator.map { [$0] } ?? [],
                instructions: [
                    try sequenceNextInstruction(
                        cursor: traversal.cursor,
                        result: next,
                        direction: traversalDirection
                    ),
                    .switchOptional(
                        optional: next,
                        someTarget: some,
                        noneTarget: empty
                    ),
                ]
            )

            let closureArguments: [Bytecode.Register]
            switch plan.callbackShape {
            case .dictionaryValue, .dictionaryKeyValue:
                closureArguments = projectedClosureArguments
            case .element:
                let closureInput = try requiredRegister(
                    closureInput,
                    "collection element callback input"
                )
                if plan.operation == .reduce {
                    closureArguments = [
                        try requiredRegister(
                            loopAccumulator,
                            "loop accumulator"
                        ),
                        closureInput,
                    ]
                } else if plan.operation == .minimumBy {
                    closureArguments = [
                        closureInput,
                        try requiredRegister(
                            loopAccumulator,
                            "minimum candidate"
                        ),
                    ]
                } else if plan.operation == .maximumBy {
                    closureArguments = [
                        try requiredRegister(
                            loopAccumulator,
                            "maximum candidate"
                        ),
                        closureInput,
                    ]
                } else {
                    closureArguments = [closureInput]
                }
            }
            let closureContinuationArguments = directClosureResult.map {
                [$0]
            } ?? []
            let closureInstructions: [IntermediateRepresentation.Instruction]
            if isThrowing {
                closureInstructions = closureArgumentPreparation + [
                    .closureTryApply(
                        closure: closure,
                        arguments: closureArguments,
                        normalTarget: closureContinuation,
                        errorTarget: errorCleanup
                    ),
                ]
            } else {
                closureInstructions = closureArgumentPreparation + [
                    .closureApply(
                        result: directClosureResult,
                        closure: closure,
                        arguments: closureArguments
                    ),
                    .branch(
                        target: closureContinuation,
                        arguments: closureContinuationArguments
                    ),
                ]
            }
            appendSyntheticBlock(
                id: some,
                parameters: [element],
                instructions: dictionaryProjectionInstructions
                    + closureInstructions
            )

            let continuationResult = try plan.closureResultType == .void
                ? nil
                : allocate(type: plan.closureResultType)
            let continuationParameters = continuationResult.map { [$0] } ?? []
            let materializedContinuationResult: Bytecode.Register?
            let resultMaterialization: [IntermediateRepresentation.Instruction]
            if [.map, .mapValues, .reduce].contains(plan.operation),
               plan.closureResultType == .void {
                let unit = try allocate(type: ValueRepresentation.unit)
                materializedContinuationResult = unit
                resultMaterialization = [
                    .makeTuple(result: unit, elements: []),
                ]
            } else {
                materializedContinuationResult = continuationResult
                resultMaterialization = []
            }
            var closureArgumentCleanup: [
                IntermediateRepresentation.Instruction
            ] = []
            if accumulatorNeedsCleanup {
                closureArgumentCleanup.append(
                    .destroyValue(
                        try requiredRegister(
                            loopAccumulator,
                            "borrowed loop accumulator"
                        )
                    )
                )
            }
            if inputNeedsCleanup {
                closureArgumentCleanup.append(.destroyValue(element))
            }
            switch plan.operation {
            case .map:
                let result = try requiredRegister(
                    materializedContinuationResult,
                    "map result"
                )
                var instructions = resultMaterialization + [
                    .arrayBuilderAppend(
                        builder: try requiredRegister(builder, "element builder"),
                        value: result
                    ),
                ]
                if requiresManagedOwnership(plan.callResultType) {
                    instructions.append(.destroyValue(result))
                }
                instructions.append(contentsOf: closureArgumentCleanup)
                instructions.append(.branch(target: loop, arguments: []))
                appendSyntheticBlock(
                    id: closureContinuation,
                    parameters: continuationParameters,
                    instructions: instructions
                )
            case .flatMap:
                let result = try requiredRegister(
                    continuationResult,
                    "flatMap sequence result"
                )
                var instructions: [IntermediateRepresentation.Instruction] = [
                    .arrayBuilderAppendContents(
                        builder: try requiredRegister(
                            builder,
                            "element builder"
                        ),
                        array: result
                    ),
                ]
                if requiresManagedOwnership(plan.closureResultType) {
                    instructions.append(.destroyValue(result))
                }
                instructions.append(contentsOf: closureArgumentCleanup)
                instructions.append(.branch(target: loop, arguments: []))
                appendSyntheticBlock(
                    id: closureContinuation,
                    parameters: continuationParameters,
                    instructions: instructions
                )
            case .filter(_):
                let predicate = try requiredRegister(
                    continuationResult,
                    "filter predicate"
                )
                let builder = try requiredRegister(builder, "element builder")
                let append = try allocateSyntheticBlockID()
                if plan.callbackShape == .dictionaryKeyValue {
                    let skip = try allocateSyntheticBlockID()
                    let key = try requiredRegister(
                        dictionaryKey,
                        "Dictionary.filter key"
                    )
                    let value = try requiredRegister(
                        dictionaryValue,
                        "Dictionary.filter value"
                    )
                    appendSyntheticBlock(
                        id: closureContinuation,
                        parameters: continuationParameters,
                        instructions: [
                            .conditionalBranch(
                                condition: predicate,
                                trueTarget: append,
                                trueArguments: [],
                                falseTarget: skip,
                                falseArguments: []
                            ),
                        ]
                    )
                    appendSyntheticBlock(
                        id: append,
                        instructions: try appendDictionaryPair(
                            key: key,
                            value: value,
                            to: builder
                        ) + [.branch(target: loop, arguments: [])]
                    )
                    appendSyntheticBlock(
                        id: skip,
                        instructions: projectedFieldCleanup + [
                            .branch(target: loop, arguments: []),
                        ]
                    )
                } else {
                    guard plan.callbackShape == .element else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "filter has an unsupported callback projection"
                        )
                    }
                    let skip = inputNeedsCleanup
                        ? try allocateSyntheticBlockID()
                        : loop
                    appendSyntheticBlock(
                        id: closureContinuation,
                        parameters: continuationParameters,
                        instructions: [
                            .conditionalBranch(
                                condition: predicate,
                                trueTarget: append,
                                trueArguments: [],
                                falseTarget: skip,
                                falseArguments: []
                            ),
                        ]
                    )
                    appendSyntheticBlock(
                        id: append,
                        instructions: [
                            .arrayBuilderAppend(
                                builder: builder,
                                value: element
                            ),
                        ] + (inputNeedsCleanup
                            ? [.destroyValue(element)] : [])
                            + [.branch(target: loop, arguments: [])]
                    )
                    if inputNeedsCleanup {
                        appendSyntheticBlock(
                            id: skip,
                            instructions: [
                                .destroyValue(element),
                                .branch(target: loop, arguments: []),
                            ]
                        )
                    }
                }
            case .compactMap:
                let optional = try requiredRegister(
                    continuationResult,
                    "compactMap result"
                )
                let builder = try requiredRegister(builder, "element builder")
                let append = try allocateSyntheticBlockID()
                let skip = try allocateSyntheticBlockID()
                guard case let .array(mappedType) = plan.callResultType else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "compactMap result is not an Array"
                    )
                }
                let mapped = try allocate(type: mappedType)
                appendSyntheticBlock(
                    id: closureContinuation,
                    parameters: continuationParameters,
                    instructions: closureArgumentCleanup + [
                        .switchOptional(
                            optional: optional,
                            someTarget: append,
                            noneTarget: skip
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: append,
                    parameters: [mapped],
                    instructions: [
                        .arrayBuilderAppend(
                            builder: builder,
                            value: mapped
                        ),
                    ] + (requiresManagedOwnership(mappedType)
                        ? [.destroyValue(mapped)] : [])
                        + [.branch(target: loop, arguments: [])]
                )
                appendSyntheticBlock(
                    id: skip,
                    instructions: [
                        .branch(target: loop, arguments: []),
                    ]
                )
            case .mapValues:
                guard plan.callbackShape == .dictionaryValue,
                      let dictionaryTypes,
                      case let .dictionary(_, mappedType) = plan.callResultType
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "mapValues has an invalid Dictionary lowering plan"
                    )
                }
                let key = try requiredRegister(
                    dictionaryKey,
                    "mapValues key"
                )
                let originalValue = try requiredRegister(
                    dictionaryValue,
                    "mapValues original value"
                )
                let mapped = try requiredRegister(
                    materializedContinuationResult,
                    "mapValues result"
                )
                guard registerTypes[Int(mapped.rawValue)] == mappedType else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "mapValues closure result does not match its Dictionary"
                    )
                }
                var instructions = resultMaterialization
                if requiresManagedOwnership(dictionaryTypes.value) {
                    instructions.append(.destroyValue(originalValue))
                }
                instructions.append(
                    contentsOf: try appendDictionaryPair(
                        key: key,
                        value: mapped,
                        to: try requiredRegister(builder, "element builder")
                    )
                )
                instructions.append(.branch(target: loop, arguments: []))
                appendSyntheticBlock(
                    id: closureContinuation,
                    parameters: continuationParameters,
                    instructions: instructions
                )
            case .compactMapValues:
                guard plan.callbackShape == .dictionaryValue,
                      let dictionaryTypes,
                      case let .dictionary(_, mappedType) = plan.callResultType
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "compactMapValues has an invalid Dictionary lowering plan"
                    )
                }
                let optional = try requiredRegister(
                    continuationResult,
                    "compactMapValues result"
                )
                let key = try requiredRegister(
                    dictionaryKey,
                    "compactMapValues key"
                )
                let originalValue = try requiredRegister(
                    dictionaryValue,
                    "compactMapValues original value"
                )
                let builder = try requiredRegister(builder, "element builder")
                let append = try allocateSyntheticBlockID()
                let skip = try allocateSyntheticBlockID()
                let mapped = try allocate(type: mappedType)
                var continuationInstructions: [
                    IntermediateRepresentation.Instruction
                ] = []
                if requiresManagedOwnership(dictionaryTypes.value) {
                    continuationInstructions.append(
                        .destroyValue(originalValue)
                    )
                }
                continuationInstructions.append(
                    .switchOptional(
                        optional: optional,
                        someTarget: append,
                        noneTarget: skip
                    )
                )
                appendSyntheticBlock(
                    id: closureContinuation,
                    parameters: continuationParameters,
                    instructions: continuationInstructions
                )
                appendSyntheticBlock(
                    id: append,
                    parameters: [mapped],
                    instructions: try appendDictionaryPair(
                        key: key,
                        value: mapped,
                        to: builder
                    ) + [.branch(target: loop, arguments: [])]
                )
                appendSyntheticBlock(
                    id: skip,
                    instructions: (requiresManagedOwnership(dictionaryTypes.key)
                        ? [.destroyValue(key)] : []) + [
                        .branch(target: loop, arguments: []),
                    ]
                )
            case .prefixWhile:
                let predicate = try requiredRegister(
                    continuationResult,
                    "prefix(while:) predicate"
                )
                let builder = try requiredRegister(builder, "element builder")
                let append = try allocateSyntheticBlockID()
                let finish = try allocateSyntheticBlockID()
                let finished = try finishIndexPreservingSubsequenceBuilder(
                    builder
                )
                appendSyntheticBlock(
                    id: closureContinuation,
                    parameters: continuationParameters,
                    instructions: [
                        .conditionalBranch(
                            condition: predicate,
                            trueTarget: append,
                            trueArguments: [],
                            falseTarget: finish,
                            falseArguments: []
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: append,
                    instructions: [
                        .arrayBuilderAppend(builder: builder, value: element),
                    ] + closureArgumentCleanup + [
                        .branch(target: loop, arguments: []),
                    ]
                )
                appendSyntheticBlock(
                    id: finish,
                    instructions: closureArgumentCleanup
                        + finished.instructions + [
                        .destroyStack(cursorSlot),
                    ] + sourceCleanup + [
                        .branch(
                            target: normalTarget,
                            arguments: [finished.result]
                        ),
                    ]
                )
            case .dropWhile:
                let predicate = try requiredRegister(
                    continuationResult,
                    "drop(while:) predicate"
                )
                let builder = try requiredRegister(builder, "element builder")
                let keepDropping = try allocateSyntheticBlockID()
                let appendRemainder = try allocateSyntheticBlockID()
                let remainderLoop = try allocateSyntheticBlockID()
                let remainderSome = try allocateSyntheticBlockID()
                let remainderNext = try allocate(
                    type: .optional(plan.inputType)
                )
                let remainderElement = try allocate(type: plan.inputType)
                appendSyntheticBlock(
                    id: closureContinuation,
                    parameters: continuationParameters,
                    instructions: [
                        .conditionalBranch(
                            condition: predicate,
                            trueTarget: keepDropping,
                            trueArguments: [],
                            falseTarget: appendRemainder,
                            falseArguments: []
                        ),
                    ]
                )
                var keepDroppingInstructions = closureArgumentCleanup
                if let droppedCountSlot {
                    let advancedCursor = try allocate(type: .int64)
                    keepDroppingInstructions += [
                        .loadStack(
                            result: advancedCursor,
                            slot: cursorSlot,
                            mode: .copy
                        ),
                        .storeStack(
                            slot: droppedCountSlot,
                            source: advancedCursor,
                            mode: .assign
                        ),
                    ]
                }
                keepDroppingInstructions.append(
                    .branch(target: loop, arguments: [])
                )
                appendSyntheticBlock(
                    id: keepDropping,
                    instructions: keepDroppingInstructions
                )
                appendSyntheticBlock(
                    id: appendRemainder,
                    instructions: [
                        .arrayBuilderAppend(builder: builder, value: element),
                    ] + closureArgumentCleanup + [
                        .branch(target: remainderLoop, arguments: []),
                    ]
                )
                appendSyntheticBlock(
                    id: remainderLoop,
                    instructions: [
                        try sequenceNextInstruction(
                            cursor: traversal.cursor,
                            result: remainderNext,
                            direction: .forward
                        ),
                        .switchOptional(
                            optional: remainderNext,
                            someTarget: remainderSome,
                            noneTarget: empty
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: remainderSome,
                    parameters: [remainderElement],
                    instructions: [
                        .arrayBuilderAppend(
                            builder: builder,
                            value: remainderElement
                        ),
                    ] + (requiresManagedOwnership(plan.inputType)
                        ? [.destroyValue(remainderElement)] : []) + [
                        .branch(target: remainderLoop, arguments: []),
                    ]
                )
            case .reduce:
                let result = try requiredRegister(
                    materializedContinuationResult,
                    "reduce result"
                )
                appendSyntheticBlock(
                    id: closureContinuation,
                    parameters: continuationParameters,
                    instructions: resultMaterialization
                        + closureArgumentCleanup + [
                        .branch(
                            target: loop,
                            arguments: [result]
                        ),
                    ]
                )
            case .reduceInto:
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "reduce(into:_:) reached value-returning higher-order lowering"
                )
            case .forEach:
                appendSyntheticBlock(
                    id: closureContinuation,
                    instructions: closureArgumentCleanup
                        + [.branch(target: loop, arguments: [])]
                )
            case .firstWhere, .lastWhere:
                let predicate = try requiredRegister(
                    continuationResult,
                    "first/last(where:) predicate"
                )
                let matched = try allocateSyntheticBlockID()
                let skipped = try allocateSyntheticBlockID()
                let result = try allocate(type: plan.callResultType)
                appendSyntheticBlock(
                    id: closureContinuation,
                    parameters: continuationParameters,
                    instructions: [
                        .conditionalBranch(
                            condition: predicate,
                            trueTarget: matched,
                            trueArguments: [],
                            falseTarget: skipped,
                            falseArguments: []
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: matched,
                    instructions: [
                        .makeOptionalSome(result: result, value: element),
                        .destroyStack(cursorSlot),
                    ] + sourceCleanup + [
                        .branch(target: normalTarget, arguments: [result]),
                    ]
                )
                appendSyntheticBlock(
                    id: skipped,
                    instructions: (inputNeedsCleanup
                        ? [.destroyValue(element)] : [])
                        + [.branch(target: loop, arguments: [])]
                )
            case .firstIndexWhere, .lastIndexWhere:
                guard let sourceIndexBase else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "predicate index search lost its Collection base"
                    )
                }
                let predicate = try requiredRegister(
                    continuationResult,
                    "first/lastIndex(where:) predicate"
                )
                let matched = try allocateSyntheticBlockID()
                let wrap = try allocateSyntheticBlockID()
                let overflowTrap = try allocateSyntheticBlockID()
                let skipped = try allocateSyntheticBlockID()
                let advancedIndex = try allocate(type: .int64)
                let cursorAdjustment = try allocate(type: .int64)
                let physicalIndex = try allocate(type: .int64)
                let subtractionOverflow = try allocate(type: .bool)
                let matchedIndex = try allocate(type: .int64)
                let additionOverflow = try allocate(type: .bool)
                let overflow = try allocate(type: .bool)
                let result = try allocate(type: plan.callResultType)
                let cursorAdjustmentBitPattern: UInt64 =
                    traversalDirection == .forward ? 1 : 0
                appendSyntheticBlock(
                    id: closureContinuation,
                    parameters: continuationParameters,
                    instructions: [
                        .conditionalBranch(
                            condition: predicate,
                            trueTarget: matched,
                            trueArguments: [],
                            falseTarget: skipped,
                            falseArguments: []
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: matched,
                    instructions: closureArgumentCleanup + [
                        .loadStack(
                            result: advancedIndex,
                            slot: cursorSlot,
                            mode: .copy
                        ),
                        .constantInteger(
                            result: cursorAdjustment,
                            bitPattern: cursorAdjustmentBitPattern
                        ),
                        .checkedBinary(
                            result: physicalIndex,
                            overflow: subtractionOverflow,
                            operation: .subtract,
                            lhs: advancedIndex,
                            rhs: cursorAdjustment
                        ),
                        .checkedBinary(
                            result: matchedIndex,
                            overflow: additionOverflow,
                            operation: .add,
                            lhs: sourceIndexBase,
                            rhs: physicalIndex
                        ),
                        .booleanBinary(
                            result: overflow,
                            operation: .or,
                            lhs: subtractionOverflow,
                            rhs: additionOverflow
                        ),
                        .conditionalBranch(
                            condition: overflow,
                            trueTarget: overflowTrap,
                            trueArguments: [],
                            falseTarget: wrap,
                            falseArguments: []
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: wrap,
                    instructions: [
                        .makeOptionalSome(
                            result: result,
                            value: matchedIndex
                        ),
                        .destroyStack(cursorSlot),
                    ] + sourceCleanup + [
                        .branch(target: normalTarget, arguments: [result]),
                    ]
                )
                appendSyntheticBlock(
                    id: overflowTrap,
                    instructions: [.trap(.integerOverflow)]
                )
                appendSyntheticBlock(
                    id: skipped,
                    instructions: closureArgumentCleanup + [
                        .branch(target: loop, arguments: []),
                    ]
                )
            case .containsWhere, .allSatisfy:
                let predicate = try requiredRegister(
                    continuationResult,
                    "predicate result"
                )
                let finished = try allocateSyntheticBlockID()
                let continued = try allocateSyntheticBlockID()
                let finishesWhenTrue = plan.operation == .containsWhere
                let result = try allocate(type: .bool)
                appendSyntheticBlock(
                    id: closureContinuation,
                    parameters: continuationParameters,
                    instructions: closureArgumentCleanup + [
                        .conditionalBranch(
                            condition: predicate,
                            trueTarget: finishesWhenTrue ? finished : continued,
                            trueArguments: [],
                            falseTarget: finishesWhenTrue ? continued : finished,
                            falseArguments: []
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: finished,
                    instructions: [
                        .constantBool(
                            result: result,
                            value: finishesWhenTrue
                        ),
                        .destroyStack(cursorSlot),
                    ] + sourceCleanup + [
                        .branch(target: normalTarget, arguments: [result]),
                    ]
                )
                appendSyntheticBlock(
                    id: continued,
                    instructions: [.branch(target: loop, arguments: [])]
                )
            case .countWhere:
                let predicate = try requiredRegister(
                    continuationResult,
                    "count(where:) predicate"
                )
                let accumulator = try requiredRegister(
                    loopAccumulator,
                    "count(where:) accumulator"
                )
                let increment = try allocateSyntheticBlockID()
                let wrap = try allocateSyntheticBlockID()
                let overflowTrap = try allocateSyntheticBlockID()
                let skip = try allocateSyntheticBlockID()
                let one = try allocate(type: .int64)
                let incremented = try allocate(type: .int64)
                let overflow = try allocate(type: .bool)
                appendSyntheticBlock(
                    id: closureContinuation,
                    parameters: continuationParameters,
                    instructions: closureArgumentCleanup + [
                        .conditionalBranch(
                            condition: predicate,
                            trueTarget: increment,
                            trueArguments: [],
                            falseTarget: skip,
                            falseArguments: []
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: increment,
                    instructions: [
                        .constantInteger(result: one, bitPattern: 1),
                        .checkedBinary(
                            result: incremented,
                            overflow: overflow,
                            operation: .add,
                            lhs: accumulator,
                            rhs: one
                        ),
                        .conditionalBranch(
                            condition: overflow,
                            trueTarget: overflowTrap,
                            trueArguments: [],
                            falseTarget: wrap,
                            falseArguments: []
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: wrap,
                    instructions: [
                        .branch(target: loop, arguments: [incremented]),
                    ]
                )
                appendSyntheticBlock(
                    id: overflowTrap,
                    instructions: [.trap(.integerOverflow)]
                )
                appendSyntheticBlock(
                    id: skip,
                    instructions: [
                        .branch(target: loop, arguments: [accumulator]),
                    ]
                )
            case .minimumBy, .maximumBy:
                let predicate = try requiredRegister(
                    continuationResult,
                    "comparison result"
                )
                let challengerWins = try allocateSyntheticBlockID()
                let candidateWins = try allocateSyntheticBlockID()
                let candidate = try requiredRegister(
                    loopAccumulator,
                    "comparison candidate"
                )
                appendSyntheticBlock(
                    id: closureContinuation,
                    parameters: continuationParameters,
                    instructions: [
                        .conditionalBranch(
                            condition: predicate,
                            trueTarget: challengerWins,
                            trueArguments: [],
                            falseTarget: candidateWins,
                            falseArguments: []
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: challengerWins,
                    instructions: (requiresManagedOwnership(plan.inputType)
                        ? [.destroyValue(candidate)] : []) + [
                        .branch(target: loop, arguments: [element]),
                    ]
                )
                appendSyntheticBlock(
                    id: candidateWins,
                    instructions: (requiresManagedOwnership(plan.inputType)
                        ? [.destroyValue(element)] : []) + [
                        .branch(target: loop, arguments: [candidate]),
                    ]
                )
            }

            let emptyInstructions: [IntermediateRepresentation.Instruction]
            switch plan.operation {
            case .map, .flatMap, .filter(_), .compactMap, .mapValues,
                 .compactMapValues, .prefixWhile, .dropWhile:
                let builder = try requiredRegister(
                    builder,
                    "element builder"
                )
                let finished = if plan.operation == .prefixWhile
                    || plan.operation == .dropWhile {
                    try finishIndexPreservingSubsequenceBuilder(builder)
                } else {
                    try finishCollectionBuilder(builder)
                }
                emptyInstructions = finished.instructions + [
                    .destroyStack(cursorSlot),
                ] + (droppedCountSlot.map { [.destroyStack($0)] } ?? [])
                    + sourceCleanup + [
                    .branch(
                        target: normalTarget,
                        arguments: [finished.result]
                    ),
                ]
            case .reduce, .countWhere:
                emptyInstructions = [
                    .destroyStack(cursorSlot),
                ] + sourceCleanup + [
                    .branch(
                        target: normalTarget,
                        arguments: [
                            try requiredRegister(
                                loopAccumulator,
                                "final Sequence accumulator"
                            ),
                        ]
                    ),
                ]
            case .reduceInto:
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "reduce(into:_:) reached value-returning higher-order lowering"
                )
            case .forEach:
                emptyInstructions = [
                    .destroyStack(cursorSlot),
                ] + sourceCleanup + [
                    .branch(target: normalTarget, arguments: []),
                ]
            case .firstWhere, .lastWhere, .firstIndexWhere,
                 .lastIndexWhere:
                let result = try allocate(type: plan.callResultType)
                emptyInstructions = [
                    .makeOptionalNone(result: result),
                    .destroyStack(cursorSlot),
                ] + sourceCleanup + [
                    .branch(target: normalTarget, arguments: [result]),
                ]
            case .containsWhere, .allSatisfy:
                let result = try allocate(type: .bool)
                emptyInstructions = [
                    .constantBool(
                        result: result,
                        value: plan.operation == .allSatisfy
                    ),
                    .destroyStack(cursorSlot),
                ] + sourceCleanup + [
                    .branch(target: normalTarget, arguments: [result]),
                ]
            case .minimumBy, .maximumBy:
                let result = try allocate(type: plan.callResultType)
                emptyInstructions = [
                    .makeOptionalSome(
                        result: result,
                        value: try requiredRegister(
                            loopAccumulator,
                            "final comparison candidate"
                        )
                    ),
                    .destroyStack(cursorSlot),
                ] + sourceCleanup + [
                    .branch(target: normalTarget, arguments: [result]),
                ]
            }
            appendSyntheticBlock(id: empty, instructions: emptyInstructions)

            let propagatedArguments = errorParameter.map { [$0] } ?? []
            var cleanupInstructions: [IntermediateRepresentation.Instruction] = []
            if isThrowing {
                cleanupInstructions.append(
                    contentsOf: plan.callbackShape == .element
                        ? closureArgumentCleanup : projectedFieldCleanup
                )
            }
            if let builder {
                cleanupInstructions.append(.destroyValue(builder))
            }
            cleanupInstructions.append(.destroyStack(cursorSlot))
            if let droppedCountSlot {
                cleanupInstructions.append(.destroyStack(droppedCountSlot))
            }
            cleanupInstructions.append(contentsOf: sourceCleanup)
            cleanupInstructions.append(
                .branch(
                    target: errorTarget,
                    arguments: propagatedArguments
                )
            )
            appendSyntheticBlock(
                id: errorCleanup,
                parameters: errorParameter.map { [$0] } ?? [],
                instructions: cleanupInstructions
            )
        }

        func resultContainer(
            success: String,
            failure: String
        ) throws -> CanonicalSIL.AlgebraicTransform.Container {
            let type = try parseType("Result<\(success), \(failure)>")
            guard case let .local(key) = type else {
                throw CanonicalSIL.LoweringError.unsupportedType(
                    "concrete Result container"
                )
            }
            return .enumeration(key: key)
        }

        func isSupportedErrorType(
            _ type: Bytecode.ValueType,
            spelling: String
        ) throws -> Bool {
            switch ValueRepresentation.storable(type) {
            case .never, .error:
                return true
            case .string:
                let normalized = spelling
                    .replacingOccurrences(of: "Swift.", with: "")
                    .filter { !$0.isWhitespace }
                return normalized == "Error" || normalized == "anyError"
            case let .local(key):
                return try typeEnvironment.definition(for: key)
                    .conformsToError
            default:
                return false
            }
        }

        func algebraicEnumerationCase(
            named name: String,
            payloadType: Bytecode.ValueType,
            in container: CanonicalSIL.AlgebraicTransform.Container
        ) throws -> CanonicalSIL.AlgebraicTransform.Case {
            guard case let .enumeration(key) = container else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "algebraic enum case requires an enum container"
                )
            }
            let index = try typeEnvironment.enumCaseIndex(
                type: key,
                name: name
            )
            guard let exact = UInt32(exactly: index) else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "algebraic enum case index exceeds UInt32"
                )
            }
            return .init(
                tag: .enumeration(exact),
                payloadType: payloadType
            )
        }

        func parseAlgebraicTransformPlan(
            _ intrinsic: CanonicalSIL.AlgebraicIntrinsic,
            genericArguments: String,
            argumentText: String,
            line: Int
        ) throws -> CanonicalSIL.AlgebraicTransform.Plan {
            let genericSpellings = splitTopLevel(genericArguments)
                .filter { !$0.isEmpty }
            let arguments = try parseApplyValueTokens(
                argumentText,
                line: line
            )

            switch intrinsic {
            case let .optional(transformation):
                guard genericSpellings.count == 3,
                      arguments.count == 4
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Optional transform has an unsupported specialization"
                    )
                }
                let genericTypes = try genericSpellings.map(parseType)
                guard try isSupportedErrorType(
                    genericTypes[1],
                    spelling: genericSpellings[1]
                ) else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "Optional transform Error \(genericTypes[1])"
                    )
                }
                let inputPayload = ValueRepresentation.storable(
                    genericTypes[0]
                )
                let outputPayload = ValueRepresentation.storable(
                    genericTypes[2]
                )
                let input = CanonicalSIL.AlgebraicTransform.Container
                    .optional(wrapped: inputPayload)
                let output = CanonicalSIL.AlgebraicTransform.Container
                    .optional(wrapped: outputPayload)
                let inputSome = CanonicalSIL.AlgebraicTransform.Case(
                    tag: .optionalSome,
                    payloadType: inputPayload
                )
                let outputSome = CanonicalSIL.AlgebraicTransform.Case(
                    tag: .optionalSome,
                    payloadType: outputPayload
                )
                let none = CanonicalSIL.AlgebraicTransform.Case(
                    tag: .optionalNone,
                    payloadType: nil
                )
                let closureOutput: CanonicalSIL.AlgebraicTransform
                    .ClosureOutput = switch transformation {
                case .map:
                    .payload(
                        logicalType: genericTypes[2],
                        storedType: outputPayload,
                        outputCase: outputSome
                    )
                case .flatMap:
                    .container(output.type)
                }
                return .init(
                    sourceToken: arguments[3],
                    closureToken: arguments[2],
                    resultDestination: arguments[0],
                    errorDestination: arguments[1],
                    errorType: genericTypes[1],
                    input: input,
                    output: output,
                    transformedInputCase: inputSome,
                    passthroughInputCase: none,
                    passthroughOutputCase: none,
                    closureOutput: closureOutput
                )

            case let .result(selectedCase, transformation):
                guard genericSpellings.count == 3,
                      arguments.count == 3
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Result transform has an unsupported specialization"
                    )
                }
                let genericTypes = try genericSpellings.map(parseType)
                let outputFailureIsSupported: Bool
                if selectedCase == .success {
                    outputFailureIsSupported = true
                } else {
                    outputFailureIsSupported = try isSupportedErrorType(
                        genericTypes[2],
                        spelling: genericSpellings[2]
                    )
                }
                guard try isSupportedErrorType(
                    genericTypes[1],
                    spelling: genericSpellings[1]
                ),
                      outputFailureIsSupported
                else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "Result transform Failure specialization"
                    )
                }
                let success = ValueRepresentation.storable(genericTypes[0])
                let failure = ValueRepresentation.storable(genericTypes[1])
                let transformedOutput = ValueRepresentation.storable(
                    genericTypes[2]
                )
                let input = try resultContainer(
                    success: genericSpellings[0],
                    failure: genericSpellings[1]
                )
                let output: CanonicalSIL.AlgebraicTransform.Container
                let transformedInputPayload: Bytecode.ValueType
                let passthroughPayload: Bytecode.ValueType
                let outputSuccess: Bytecode.ValueType
                let outputFailure: Bytecode.ValueType
                switch selectedCase {
                case .success:
                    output = try resultContainer(
                        success: genericSpellings[2],
                        failure: genericSpellings[1]
                    )
                    transformedInputPayload = success
                    passthroughPayload = failure
                    outputSuccess = transformedOutput
                    outputFailure = failure
                case .failure:
                    output = try resultContainer(
                        success: genericSpellings[0],
                        failure: genericSpellings[2]
                    )
                    transformedInputPayload = failure
                    passthroughPayload = success
                    outputSuccess = success
                    outputFailure = transformedOutput
                }
                let transformedInputCase = try algebraicEnumerationCase(
                    named: selectedCase.rawValue,
                    payloadType: transformedInputPayload,
                    in: input
                )
                let passthroughInputCase = try algebraicEnumerationCase(
                    named: selectedCase.opposite.rawValue,
                    payloadType: passthroughPayload,
                    in: input
                )
                let transformedOutputCase = try algebraicEnumerationCase(
                    named: selectedCase.rawValue,
                    payloadType: selectedCase == .success
                        ? outputSuccess : outputFailure,
                    in: output
                )
                let passthroughOutputCase = try algebraicEnumerationCase(
                    named: selectedCase.opposite.rawValue,
                    payloadType: passthroughPayload,
                    in: output
                )
                let closureOutput: CanonicalSIL.AlgebraicTransform
                    .ClosureOutput = switch transformation {
                case .map:
                    .payload(
                        logicalType: genericTypes[2],
                        storedType: transformedOutput,
                        outputCase: transformedOutputCase
                    )
                case .flatMap:
                    .container(output.type)
                }
                return .init(
                    sourceToken: arguments[2],
                    closureToken: arguments[1],
                    resultDestination: arguments[0],
                    errorDestination: nil,
                    errorType: nil,
                    input: input,
                    output: output,
                    transformedInputCase: transformedInputCase,
                    passthroughInputCase: passthroughInputCase,
                    passthroughOutputCase: passthroughOutputCase,
                    closureOutput: closureOutput
                )

            case .resultGet:
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "Result.get entered closure-transform planning"
                )

            case .resultCatching:
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "Result(catching:) entered closure-transform planning"
                )
            }
        }

        func parseResultCatchingPlan(
            genericArguments: String,
            argumentText: String,
            line: Int
        ) throws -> CanonicalSIL.AlgebraicConstruction.CatchingPlan {
            let genericSpellings = splitTopLevel(genericArguments)
                .filter { !$0.isEmpty }
            let arguments = try parseApplyValueTokens(
                argumentText,
                line: line
            )
            guard genericSpellings.count == 2,
                  arguments.count == 3
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "Result(catching:) has an unsupported specialization"
                )
            }

            let logicalSuccess = try parseType(genericSpellings[0])
            let logicalFailure = try parseType(genericSpellings[1])
            let storedSuccess = ValueRepresentation.storable(logicalSuccess)
            let storedFailure = ValueRepresentation.storable(logicalFailure)
            let runtimeErrorType: Bytecode.ValueType = typeEnvironment
                .preservesTypedErrors ? .error : .string
            guard try isSupportedErrorType(
                logicalFailure,
                spelling: genericSpellings[1]
            ), storedFailure == runtimeErrorType
            else {
                throw CanonicalSIL.LoweringError.unsupportedType(
                    "Result(catching:) Failure \(logicalFailure)"
                )
            }

            let output = try resultContainer(
                success: genericSpellings[0],
                failure: genericSpellings[1]
            )
            guard case let .enumeration(outputKey) = output,
                  localMetatypeValues[arguments[2]] == outputKey
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "Result(catching:) metatype does not match its output"
                )
            }
            return .init(
                closureToken: arguments[1],
                resultDestination: arguments[0],
                output: output,
                successCase: try algebraicEnumerationCase(
                    named: CanonicalSIL.AlgebraicIntrinsic.ResultCase
                        .success.rawValue,
                    payloadType: storedSuccess,
                    in: output
                ),
                failureCase: try algebraicEnumerationCase(
                    named: CanonicalSIL.AlgebraicIntrinsic.ResultCase
                        .failure.rawValue,
                    payloadType: runtimeErrorType,
                    in: output
                ),
                logicalSuccessType: logicalSuccess,
                storedSuccessType: storedSuccess,
                errorType: runtimeErrorType
            )
        }

        func appendAlgebraicSwitch(
            source: Bytecode.Register,
            container: CanonicalSIL.AlgebraicTransform.Container,
            transformedCase: CanonicalSIL.AlgebraicTransform.Case,
            transformedTarget: Bytecode.BlockID,
            passthroughCase: CanonicalSIL.AlgebraicTransform.Case,
            passthroughTarget: Bytecode.BlockID
        ) throws {
            switch container {
            case .optional:
                let someTarget: Bytecode.BlockID
                let noneTarget: Bytecode.BlockID
                switch (transformedCase.tag, passthroughCase.tag) {
                case (.optionalSome, .optionalNone):
                    someTarget = transformedTarget
                    noneTarget = passthroughTarget
                case (.optionalNone, .optionalSome):
                    someTarget = passthroughTarget
                    noneTarget = transformedTarget
                default:
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Optional transform must cover .some and .none exactly once"
                    )
                }
                appendInstruction(
                    .switchOptional(
                        optional: source,
                        someTarget: someTarget,
                        noneTarget: noneTarget
                    )
                )

            case .enumeration:
                guard case let .enumeration(transformedIndex) =
                        transformedCase.tag,
                      case let .enumeration(passthroughIndex) =
                        passthroughCase.tag,
                      transformedIndex != passthroughIndex
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "enum transform must cover two distinct cases"
                    )
                }
                appendInstruction(
                    .switchEnum(
                        enumeration: source,
                        cases: [
                            .init(
                                caseIndex: transformedIndex,
                                target: transformedTarget
                            ),
                            .init(
                                caseIndex: passthroughIndex,
                                target: passthroughTarget
                            ),
                        ],
                        defaultTarget: nil
                    )
                )
            }
        }

        func algebraicCaseIsValid(
            _ shape: CanonicalSIL.AlgebraicTransform.Case,
            in container: CanonicalSIL.AlgebraicTransform.Container
        ) throws -> Bool {
            switch (container, shape.tag) {
            case let (.optional(wrapped), .optionalSome):
                return shape.payloadType == wrapped
            case (.optional, .optionalNone):
                return shape.payloadType == nil
            case let (.enumeration(key), .enumeration(rawIndex)):
                guard case let .enumeration(cases) = try typeEnvironment
                        .definition(for: key).kind,
                      let index = Int(exactly: rawIndex),
                      cases.indices.contains(index)
                else { return false }
                return cases[index].payloadType == shape.payloadType
            default:
                return false
            }
        }

        func makeAlgebraicCase(
            _ shape: CanonicalSIL.AlgebraicTransform.Case,
            in container: CanonicalSIL.AlgebraicTransform.Container,
            payload: Bytecode.Register?
        ) throws -> (
            value: Bytecode.Register,
            instructions: [IntermediateRepresentation.Instruction]
        ) {
            let payloadType = payload.map {
                registerTypes[Int($0.rawValue)]
            }
            guard payloadType == shape.payloadType else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "algebraic case payload does not match its plan"
                )
            }
            let value = try allocate(type: container.type)
            switch (container, shape.tag) {
            case let (.optional(wrapped), .optionalSome):
                guard shape.payloadType == wrapped, let payload else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Optional.some transform has an invalid payload"
                    )
                }
                return (
                    value,
                    [.makeOptionalSome(result: value, value: payload)]
                )
            case (.optional, .optionalNone):
                guard payload == nil, shape.payloadType == nil else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Optional.none transform unexpectedly has a payload"
                    )
                }
                return (value, [.makeOptionalNone(result: value)])
            case let (.enumeration, .enumeration(index)):
                return (
                    value,
                    [
                        .makeEnum(
                            result: value,
                            caseIndex: index,
                            payload: payload
                        ),
                    ]
                )
            default:
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "algebraic case does not belong to its output container"
                )
            }
        }

        func lowerResultCatching(
            _ plan: CanonicalSIL.AlgebraicConstruction.CatchingPlan,
            resultToken: String,
            line: Int
        ) throws {
            guard compilerAddressType(plan.resultDestination)
                    == plan.output.type,
                  try algebraicCaseIsValid(
                    plan.successCase,
                    in: plan.output
                  ),
                  try algebraicCaseIsValid(
                    plan.failureCase,
                    in: plan.output
                  ),
                  plan.successCase.payloadType == plan.storedSuccessType,
                  plan.failureCase.payloadType == plan.errorType
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "Result(catching:) plan does not match its physical ABI"
                )
            }

            let closure = try resolve(plan.closureToken, line: line)
            guard case let .closure(signature) = registerTypes[
                Int(closure.rawValue)
            ], signature.parameters.isEmpty,
               signature.parameterConventions.isEmpty,
               signature.result == plan.logicalSuccessType,
               signature.effects.mayThrow,
               !signature.effects.isAsync
            else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: "Result(catching:)"
                )
            }
            guard try closureThrownType(
                signature,
                matching: plan.errorType,
                context: "Result(catching:) closure"
            ) != nil else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: "Result(catching:)"
                )
            }

            let successTarget = try allocateSyntheticBlockID()
            let failureTarget = try allocateSyntheticBlockID()
            let completionTarget = try allocateSyntheticBlockID()
            appendInstruction(
                .closureTryApply(
                    closure: closure,
                    arguments: [],
                    normalTarget: successTarget,
                    errorTarget: failureTarget
                )
            )
            finishCurrent()

            let successParameter: Bytecode.Register? =
                plan.logicalSuccessType == .void
                    ? nil : try allocate(type: plan.storedSuccessType)
            let successPayload: Bytecode.Register
            var successInstructions: [IntermediateRepresentation.Instruction]
            if let successParameter {
                successPayload = successParameter
                successInstructions = []
            } else {
                successPayload = try allocate(type: ValueRepresentation.unit)
                successInstructions = [
                    .makeTuple(result: successPayload, elements: []),
                ]
            }
            let success = try makeAlgebraicCase(
                plan.successCase,
                in: plan.output,
                payload: successPayload
            )
            successInstructions.append(contentsOf: success.instructions)
            successInstructions.append(
                .branch(
                    target: completionTarget,
                    arguments: [success.value]
                )
            )
            appendSyntheticBlock(
                id: successTarget,
                parameters: successParameter.map { [$0] } ?? [],
                instructions: successInstructions
            )

            let failureParameter = try allocate(type: plan.errorType)
            let failure = try makeAlgebraicCase(
                plan.failureCase,
                in: plan.output,
                payload: failureParameter
            )
            appendSyntheticBlock(
                id: failureTarget,
                parameters: [failureParameter],
                instructions: failure.instructions + [
                    .branch(
                        target: completionTarget,
                        arguments: [failure.value]
                    ),
                ]
            )

            let result = try allocate(type: plan.output.type)
            retainFlow.activate(completionTarget)
            current = .init(
                id: completionTarget,
                parameters: [result],
                instructions: []
            )
            try storeConstructedValue(
                result,
                at: plan.resultDestination,
                mode: .initialize
            )
            voidValues.insert(resultToken)
        }

        func lowerAlgebraicTransform(
            _ plan: CanonicalSIL.AlgebraicTransform.Plan,
            invocation: AlgebraicTransformInvocation,
            line: Int
        ) throws {
            let errorABIIsValid: Bool = switch (
                plan.errorDestination,
                plan.errorType
            ) {
            case (nil, nil):
                true
            case let (.some(destination), .some(type)):
                compilerAddressType(destination) == type
            default:
                false
            }
            let outputCaseIsValid: Bool
            switch plan.closureOutput {
            case let .payload(_, _, outputCase):
                outputCaseIsValid = try algebraicCaseIsValid(
                    outputCase,
                    in: plan.output
                )
            case .container:
                outputCaseIsValid = true
            }
            guard let closureParameterType =
                    plan.transformedInputCase.payloadType,
                  try algebraicCaseIsValid(
                    plan.transformedInputCase,
                    in: plan.input
                  ),
                  try algebraicCaseIsValid(
                    plan.passthroughInputCase,
                    in: plan.input
                  ),
                  try algebraicCaseIsValid(
                    plan.passthroughOutputCase,
                    in: plan.output
                  ),
                  outputCaseIsValid,
                  plan.passthroughInputCase.payloadType
                    == plan.passthroughOutputCase.payloadType,
                  compilerAddressType(plan.resultDestination)
                    == plan.output.type,
                  errorABIIsValid
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "algebraic transform plan does not match its physical ABI"
                )
            }
            switch plan.closureOutput {
            case let .payload(logicalType, storedType, outputCase):
                guard outputCase.payloadType == storedType,
                      logicalType == .void
                        || ValueRepresentation.storable(logicalType)
                            == storedType
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "algebraic map result does not match its output case"
                    )
                }
            case let .container(type):
                guard type == plan.output.type else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "algebraic flatMap result is not its output container"
                    )
                }
            }

            let source = try materializeOwnedValue(
                at: plan.sourceToken,
                line: line
            )
            let closure = try resolve(plan.closureToken, line: line)
            guard registerTypes[Int(source.rawValue)] == plan.input.type,
                  case let .closure(signature) = registerTypes[
                    Int(closure.rawValue)
                  ],
                  signature.parameters == [closureParameterType],
                  signature.parameterConventions.count == 1,
                  signature.parameterConventions[0] != .inout,
                  signature.result == plan.closureOutput.logicalType,
                  !signature.effects.isAsync
            else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: "algebraic transform"
                )
            }

            let completionTarget: Bytecode.BlockID
            let directResultToken: String?
            let errorTarget: Bytecode.BlockID?
            let closureErrorType = try closureThrownType(
                signature,
                context: "algebraic transform closure"
            )
            switch invocation {
            case let .direct(resultToken):
                guard closureErrorType == nil,
                      plan.errorDestination == nil,
                      plan.errorType == nil
                else {
                    throw CanonicalSIL.LoweringError.callSignatureMismatch(
                        line: line,
                        mangledName: "nonthrowing algebraic transform"
                    )
                }
                completionTarget = try allocateSyntheticBlockID()
                directResultToken = resultToken
                errorTarget = nil

            case let .branching(normalTarget, branchErrorTarget):
                guard let errorType = plan.errorType,
                      plan.errorDestination != nil,
                      try closureThrownType(
                        signature,
                        matching: errorType,
                        context: "algebraic transform closure"
                      ) == closureErrorType,
                      implicitStackValues[normalTarget] == nil,
                      suppressedTryNormalParameterTypes.updateValue(
                        .void,
                        forKey: normalTarget
                      ) == nil
                else {
                    throw CanonicalSIL.LoweringError.callSignatureMismatch(
                        line: line,
                        mangledName: "rethrowing algebraic transform"
                    )
                }
                let propagatedResult = try allocate(type: plan.output.type)
                implicitStackValues[normalTarget] = [
                    .init(plan.resultDestination, propagatedResult),
                ]
                completionTarget = normalTarget
                directResultToken = nil
                errorTarget = branchErrorTarget
            }

            let isThrowing = closureErrorType != nil
            let errorCleanup: Bytecode.BlockID?
            let errorParameter: Bytecode.Register?
            if let errorTarget {
                let cleanup = try allocateSyntheticBlockID()
                errorCleanup = cleanup
                if isThrowing {
                    guard let expectedErrorType = closureErrorType,
                          plan.errorType == expectedErrorType,
                          let errorDestination = plan.errorDestination,
                          implicitStackValues[errorTarget] == nil
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "algebraic rethrows Error does not match its image"
                        )
                    }
                    let parameter = try allocate(type: expectedErrorType)
                    let propagated = try allocate(type: expectedErrorType)
                    implicitStackValues[errorTarget] = [
                        .init(errorDestination, propagated),
                    ]
                    errorParameter = parameter
                } else {
                    errorParameter = nil
                }
            } else {
                errorCleanup = nil
                errorParameter = nil
            }

            let dispatch = try allocateSyntheticBlockID()
            let transformed = try allocateSyntheticBlockID()
            let passthrough = try allocateSyntheticBlockID()
            let closureContinuation = try allocateSyntheticBlockID()
            if let errorCleanup, !isThrowing {
                // A Never-specialized `try_apply` still has an error edge in
                // SIL. Preserve it as verified but statically impossible CFG.
                let mustSucceed = try allocate(type: .bool)
                appendInstruction(.constantBool(result: mustSucceed, value: true))
                appendInstruction(
                    .conditionalBranch(
                        condition: mustSucceed,
                        trueTarget: dispatch,
                        trueArguments: [],
                        falseTarget: errorCleanup,
                        falseArguments: []
                    )
                )
            } else {
                appendInstruction(.branch(target: dispatch, arguments: []))
            }
            finishCurrent()

            retainFlow.activate(dispatch)
            current = .init(id: dispatch, parameters: [], instructions: [])
            try appendAlgebraicSwitch(
                source: source,
                container: plan.input,
                transformedCase: plan.transformedInputCase,
                transformedTarget: transformed,
                passthroughCase: plan.passthroughInputCase,
                passthroughTarget: passthrough
            )
            finishCurrent()

            let payload = try allocate(type: closureParameterType)
            let closureResultType: Bytecode.ValueType? = switch plan.closureOutput {
            case let .payload(logicalType, storedType, _):
                logicalType == .void ? nil : storedType
            case let .container(type):
                type
            }
            let closureResult = try closureResultType.map(allocate)
            let transformedInstructions: [IntermediateRepresentation.Instruction]
            if isThrowing {
                guard let errorCleanup else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "throwing algebraic transform has no error cleanup"
                    )
                }
                transformedInstructions = [
                    .closureTryApply(
                        closure: closure,
                        arguments: [payload],
                        normalTarget: closureContinuation,
                        errorTarget: errorCleanup
                    ),
                ]
            } else {
                transformedInstructions = [
                    .closureApply(
                        result: closureResult,
                        closure: closure,
                        arguments: [payload]
                    ),
                    .branch(
                        target: closureContinuation,
                        arguments: closureResult.map { [$0] } ?? []
                    ),
                ]
            }
            appendSyntheticBlock(
                id: transformed,
                parameters: [payload],
                instructions: transformedInstructions
            )

            let continuationResult = try closureResultType.map(allocate)
            let transformedValue: Bytecode.Register
            var continuationInstructions: [IntermediateRepresentation.Instruction]
            switch plan.closureOutput {
            case let .payload(_, _, outputCase):
                let storedPayload: Bytecode.Register
                let payloadMaterialization: [IntermediateRepresentation.Instruction]
                if let continuationResult {
                    storedPayload = continuationResult
                    payloadMaterialization = []
                } else {
                    storedPayload = try allocate(type: ValueRepresentation.unit)
                    payloadMaterialization = [
                        .makeTuple(result: storedPayload, elements: []),
                    ]
                }
                let constructed = try makeAlgebraicCase(
                    outputCase,
                    in: plan.output,
                    payload: storedPayload
                )
                transformedValue = constructed.value
                continuationInstructions = payloadMaterialization
                    + constructed.instructions
            case .container:
                guard let continuationResult else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "flatMap closure did not produce its container"
                    )
                }
                transformedValue = continuationResult
                continuationInstructions = []
            }
            let payloadNeedsCleanup = requiresManagedOwnership(
                closureParameterType
            )
                && signature.parameterConventions[0] == .borrowed
            if payloadNeedsCleanup {
                continuationInstructions.append(.destroyValue(payload))
            }
            continuationInstructions.append(
                .branch(
                    target: completionTarget,
                    arguments: [transformedValue]
                )
            )
            appendSyntheticBlock(
                id: closureContinuation,
                parameters: continuationResult.map { [$0] } ?? [],
                instructions: continuationInstructions
            )

            let passthroughPayload = try plan.passthroughInputCase
                .payloadType.map(allocate)
            let forwarded = try makeAlgebraicCase(
                plan.passthroughOutputCase,
                in: plan.output,
                payload: passthroughPayload
            )
            appendSyntheticBlock(
                id: passthrough,
                parameters: passthroughPayload.map { [$0] } ?? [],
                instructions: forwarded.instructions + [
                    .branch(
                        target: completionTarget,
                        arguments: [forwarded.value]
                    ),
                ]
            )

            if let errorCleanup, let errorTarget {
                var instructions: [IntermediateRepresentation.Instruction] = []
                if isThrowing && payloadNeedsCleanup {
                    instructions.append(.destroyValue(payload))
                } else if !isThrowing,
                          requiresManagedOwnership(plan.input.type) {
                    // The impossible edge precedes the consuming Optional
                    // switch, so it still owns the materialized source.
                    instructions.append(.destroyValue(source))
                }
                instructions.append(
                    .branch(
                        target: errorTarget,
                        arguments: errorParameter.map { [$0] } ?? []
                    )
                )
                appendSyntheticBlock(
                    id: errorCleanup,
                    parameters: errorParameter.map { [$0] } ?? [],
                    instructions: instructions
                )
            }

            if let directResultToken {
                let mergedResult = try allocate(type: plan.output.type)
                retainFlow.activate(completionTarget)
                current = .init(
                    id: completionTarget,
                    parameters: [mergedResult],
                    instructions: []
                )
                try storeConstructedValue(
                    mergedResult,
                    at: plan.resultDestination,
                    mode: .initialize
                )
                voidValues.insert(directResultToken)
            }
        }

        func parseResultProjectionPlan(
            genericArguments: String,
            argumentText: String,
            line: Int
        ) throws -> CanonicalSIL.AlgebraicTransform.ProjectionPlan {
            let genericSpellings = splitTopLevel(genericArguments)
                .filter { !$0.isEmpty }
            let arguments = try parseApplyValueTokens(
                argumentText,
                line: line
            )
            guard genericSpellings.count == 2, arguments.count == 3 else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "Result.get has an unsupported specialization"
                )
            }
            let genericTypes = try genericSpellings.map(parseType)
            guard try isSupportedErrorType(
                genericTypes[1],
                spelling: genericSpellings[1]
            ) else {
                throw CanonicalSIL.LoweringError.unsupportedType(
                    "Result.get Failure \(genericTypes[1])"
                )
            }
            let success = ValueRepresentation.storable(genericTypes[0])
            let failure = ValueRepresentation.storable(genericTypes[1])
            let input = try resultContainer(
                success: genericSpellings[0],
                failure: genericSpellings[1]
            )
            return .init(
                sourceToken: arguments[2],
                resultDestination: arguments[0],
                errorDestination: arguments[1],
                input: input,
                successCase: try algebraicEnumerationCase(
                    named: CanonicalSIL.AlgebraicIntrinsic.ResultCase
                        .success.rawValue,
                    payloadType: success,
                    in: input
                ),
                failureCase: try algebraicEnumerationCase(
                    named: CanonicalSIL.AlgebraicIntrinsic.ResultCase
                        .failure.rawValue,
                    payloadType: failure,
                    in: input
                )
            )
        }

        func lowerResultProjection(
            _ plan: CanonicalSIL.AlgebraicTransform.ProjectionPlan,
            normalTarget: Bytecode.BlockID,
            errorTarget: Bytecode.BlockID,
            line: Int
        ) throws {
            guard let successType = plan.successCase.payloadType,
                  let failureType = plan.failureCase.payloadType,
                  try algebraicCaseIsValid(
                    plan.successCase,
                    in: plan.input
                  ),
                  try algebraicCaseIsValid(
                    plan.failureCase,
                    in: plan.input
                  ),
                  compilerAddressType(plan.resultDestination) == successType,
                  compilerAddressType(plan.errorDestination) == failureType,
                  implicitStackValues[normalTarget] == nil,
                  implicitStackValues[errorTarget] == nil,
                  suppressedTryNormalParameterTypes.updateValue(
                    .void,
                    forKey: normalTarget
                  ) == nil
            else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: "Result.get"
                )
            }
            let source = try materializeOwnedValue(
                at: plan.sourceToken,
                line: line
            )
            guard registerTypes[Int(source.rawValue)] == plan.input.type else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: "Result.get"
                )
            }

            let propagatedSuccess = try allocate(type: successType)
            let propagatedFailure = try allocate(type: failureType)
            implicitStackValues[normalTarget] = [
                .init(plan.resultDestination, propagatedSuccess),
            ]
            implicitStackValues[errorTarget] = [
                .init(plan.errorDestination, propagatedFailure),
            ]

            let success = try allocateSyntheticBlockID()
            let failure = try allocateSyntheticBlockID()
            try appendAlgebraicSwitch(
                source: source,
                container: plan.input,
                transformedCase: plan.successCase,
                transformedTarget: success,
                passthroughCase: plan.failureCase,
                passthroughTarget: failure
            )
            finishCurrent()

            let successPayload = try allocate(type: successType)
            appendSyntheticBlock(
                id: success,
                parameters: [successPayload],
                instructions: [
                    .branch(
                        target: normalTarget,
                        arguments: [successPayload]
                    ),
                ]
            )
            let failurePayload = try allocate(type: failureType)
            appendSyntheticBlock(
                id: failure,
                parameters: [failurePayload],
                instructions: [
                    .branch(
                        target: errorTarget,
                        arguments: [failurePayload]
                    ),
                ]
            )
        }

        func progressionSequenceType(
            _ raw: String
        ) throws -> CanonicalSIL.Progression.SequenceType? {
            try CanonicalSIL.Progression.sequenceType(raw) {
                try parseStoredType($0)
            }
        }

        func progressionIteratorType(
            _ raw: String
        ) throws -> CanonicalSIL.Progression.SequenceType? {
            try CanonicalSIL.Progression.iteratorType(raw) {
                try parseStoredType($0)
            }
        }

        func normalizedIteratorCollectionType(
            _ shape: CanonicalSIL.CollectionIntrinsic.IteratorShape,
            genericArguments: String
        ) throws -> Bytecode.ValueType {
            let spelling: String = switch shape {
            case .collection:
                genericArguments
            case .reversed:
                "ReversedCollection<\(genericArguments)>"
            case .enumerated:
                "EnumeratedSequence<\(genericArguments)>"
            case .zipped:
                "Zip2Sequence<\(genericArguments)>"
            case .flattened:
                "FlattenSequence<\(genericArguments)>"
            case .joined:
                "JoinedSequence<\(genericArguments)>"
            }
            let type = try parseType(spelling)
            guard case .array = type else {
                throw CanonicalSIL.LoweringError.unsupportedType(
                    "collection iterator \(spelling)"
                )
            }
            return type
        }

        func progressionValue(
            at address: String,
            line: Int
        ) throws -> CanonicalSIL.Progression.Value {
            let base = addressBase(address)
            guard let value = progressionAddressValues[base],
                  progressionAddresses[base] == value.type
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "progression operation references uninitialized or mismatched storage at line \(line)"
                )
            }
            return value
        }

        func progressionOperand(
            _ token: String,
            expected: CanonicalSIL.Progression.SequenceType,
            line: Int
        ) throws -> CanonicalSIL.Progression.Value {
            let value = try progressionValues[token]
                ?? progressionValue(at: token, line: line)
            guard value.type == expected else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "progression operand does not match its Sequence specialization"
                )
            }
            return value
        }

        func initializeProgressionIterator(
            type: CanonicalSIL.Progression.SequenceType,
            outputAddress: String,
            inputAddress: String,
            resultToken: String,
            line: Int
        ) throws {
            let output = addressBase(outputAddress)
            let value = try progressionValue(at: inputAddress, line: line)
            guard type.supportsIteration,
                  value.type == type,
                  progressionIteratorAddresses[output] == type,
                  progressionIteratorStates[output] == nil
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "progression makeIterator types or storage do not match"
                )
            }
            progressionIteratorStates[output] = try makeProgressionCursor(
                value,
                line: line
            )
            voidValues.insert(resultToken)
        }

        func makeProgressionCursor(
            _ value: CanonicalSIL.Progression.Value,
            line: Int
        ) throws -> CanonicalSIL.Progression.IteratorState {
            let type = value.type
            guard type.supportsIteration else {
                throw CanonicalSIL.LoweringError.unsupportedType(
                    "progression cursor \(type) at line \(line)"
                )
            }
            let stride: Bytecode.Register
            if type.family.usesExplicitStride {
                guard let explicit = value.stride,
                      registerTypes[Int(explicit.rawValue)] == type.stride
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Stride progression has no matching stride value"
                    )
                }
                stride = explicit
            } else {
                guard type.stride == .int64 else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "progression iterator element \(type.element)"
                    )
                }
                stride = try allocate(type: .int64)
                appendInstruction(.constantInteger(result: stride, bitPattern: 1))
            }
            let initial = try allocate(type: .optional(type.element))
            appendInstruction(
                .makeOptionalSome(result: initial, value: value.start)
            )
            let cursorSlot = try allocateStackSlot(
                type: .optional(type.element)
            )
            appendInstruction(
                .storeStack(
                    slot: cursorSlot,
                    source: initial,
                    mode: .initialize
                )
            )
            return .init(
                type: type,
                end: value.end,
                stride: stride,
                cursorSlot: cursorSlot
            )
        }

        func prepareSequenceTraversal(
            _ specialization: CanonicalSIL.SequenceSpecialization,
            token: String,
            consumesSource: Bool,
            direction: Bytecode.CollectionTraversalDirection,
            line: Int
        ) throws -> PreparedSequenceTraversal {
            func makeCollectionCursor(
                source: Bytecode.Register,
                sourceType: Bytecode.ValueType,
                cleanup: [IntermediateRepresentation.Instruction]
            ) throws -> PreparedSequenceTraversal {
                guard registerTypes[Int(source.rawValue)] == sourceType else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Sequence source does not match its specialization"
                    )
                }
                if direction == .reverse, case .array = sourceType {
                    // Array-backed normalization preserves bidirectional order.
                } else if direction == .reverse {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "reverse traversal requires represented bidirectional storage"
                    )
                }
                let initialIndex = try allocate(type: .int64)
                if direction == .reverse {
                    appendInstruction(
                        .arrayCount(result: initialIndex, array: source)
                    )
                } else {
                    appendInstruction(
                        .constantInteger(result: initialIndex, bitPattern: 0)
                    )
                }
                let indexSlot = try allocateStackSlot(type: .int64)
                appendInstruction(
                    .storeStack(
                        slot: indexSlot,
                        source: initialIndex,
                        mode: .initialize
                    )
                )
                return .init(
                    cursor: .managedCollection(
                        collection: source,
                        indexSlot: indexSlot
                    ),
                    cleanup: cleanup
                )
            }

            switch specialization {
            case .stringCharacters:
                guard !consumesSource else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "consuming String traversal is not required by the current frontend ABI"
                    )
                }
                let materialized = try materializeSequenceOperand(
                    specialization,
                    token: token,
                    context: "String traversal",
                    line: line
                )
                return try makeCollectionCursor(
                    source: materialized.array,
                    sourceType: .array(.string),
                    cleanup: materialized.cleanup
                )

            case let .managedCollection(sourceType, element):
                guard sourceType.managedCollectionElement == element else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "managed Sequence specialization has inconsistent Element"
                    )
                }
                let borrowedSource: BorrowedStoredValue?
                let source: Bytecode.Register
                if consumesSource {
                    borrowedSource = nil
                    source = try materializeOwnedValue(at: token, line: line)
                } else {
                    borrowedSource = try borrowStoredValue(at: token, line: line)
                    source = try borrowedSource?.register
                        ?? resolve(token, line: line)
                }
                let cleanup: [IntermediateRepresentation.Instruction]
                if consumesSource, requiresManagedOwnership(sourceType) {
                    cleanup = [.destroyValue(source)]
                } else {
                    cleanup = borrowedSource?.temporaryOwner.map {
                        [.destroyValue($0)]
                    } ?? []
                }
                return try makeCollectionCursor(
                    source: source,
                    sourceType: sourceType,
                    cleanup: cleanup
                )

            case let .progression(type):
                guard !consumesSource, direction == .forward else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "progression traversal supports only borrowed forward iteration"
                    )
                }
                let value = try progressionOperand(
                    token,
                    expected: type,
                    line: line
                )
                let state = try makeProgressionCursor(value, line: line)
                return .init(
                    cursor: .progression(
                        end: state.end,
                        stride: state.stride,
                        cursorSlot: state.cursorSlot,
                        boundary: state.type.family.boundary
                    ),
                    cleanup: []
                )
            }
        }

        func sequenceNextInstruction(
            cursor: SequenceCursor,
            result: Bytecode.Register,
            direction: Bytecode.CollectionTraversalDirection
        ) throws -> IntermediateRepresentation.Instruction {
            switch cursor {
            case let .managedCollection(collection, indexSlot):
                return .collectionNext(
                    result: result,
                    collection: collection,
                    indexSlot: indexSlot,
                    direction: direction
                )
            case let .progression(end, stride, cursorSlot, boundary):
                guard direction == .forward else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "reverse progression traversal"
                    )
                }
                return .progressionNext(
                    result: result,
                    cursorSlot: cursorSlot,
                    end: end,
                    stride: stride,
                    boundary: boundary
                )
            }
        }

        func traversalCleanup(
            _ traversal: PreparedSequenceTraversal
        ) -> [IntermediateRepresentation.Instruction] {
            [.destroyStack(traversal.cursor.slot)] + traversal.cleanup
        }

        /// Produces the exact `Int` cardinality of an integer Range without
        /// iterating it. The unsigned order-key path also handles the complete
        /// 64-bit signed domain without overflowing an intermediate `Int64`.
        func lowerIntegerProgressionCount(
            _ value: CanonicalSIL.Progression.Value
        ) throws -> Bytecode.Register {
            guard value.type.family == .range
                    || value.type.family == .closedRange,
                  case let .integer(width, signed) = value.type.element
            else {
                throw CanonicalSIL.LoweringError.unsupportedType(
                    "Collection.count requires an integer Range or ClosedRange"
                )
            }

            func checked(
                _ operation: Bytecode.BinaryOperation,
                lhs: Bytecode.Register,
                rhs: Bytecode.Register,
                type: Bytecode.ValueType
            ) throws -> Bytecode.Register {
                let result = try allocate(type: type)
                let overflow = try allocate(type: .bool)
                appendInstruction(
                    .checkedBinary(
                        result: result,
                        overflow: overflow,
                        operation: operation,
                        lhs: lhs,
                        rhs: rhs
                    )
                )
                try appendConditionalTrap(
                    condition: overflow,
                    reason: .integerOverflow
                )
                return result
            }

            let includesUpperBound = value.type.family == .closedRange
            if width < 64 {
                let conversion: Bytecode.IntegerConversionOperation = signed
                    ? .signExtend : .zeroExtend
                let lower = try allocate(type: .int64)
                let upper = try allocate(type: .int64)
                appendInstruction(
                    .integerConvert(
                        result: lower,
                        operation: conversion,
                        value: value.start
                    )
                )
                appendInstruction(
                    .integerConvert(
                        result: upper,
                        operation: conversion,
                        value: value.end
                    )
                )
                var count = try checked(
                    .subtract,
                    lhs: upper,
                    rhs: lower,
                    type: .int64
                )
                if includesUpperBound {
                    let one = try allocate(type: .int64)
                    appendInstruction(
                        .constantInteger(result: one, bitPattern: 1)
                    )
                    count = try checked(
                        .add,
                        lhs: count,
                        rhs: one,
                        type: .int64
                    )
                }
                return count
            }

            let unsigned64 = Bytecode.ValueType.integer(
                bitWidth: 64,
                signed: false
            )
            let signBit: Bytecode.Register?
            if signed {
                let value = try allocate(type: unsigned64)
                appendInstruction(
                    .constantInteger(
                        result: value,
                        bitPattern: UInt64(1) << 63
                    )
                )
                signBit = value
            } else {
                signBit = nil
            }
            func orderKey(
                _ source: Bytecode.Register
            ) throws -> Bytecode.Register {
                if !signed { return source }
                guard let signBit else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "signed Range count has no order-key sign bit"
                    )
                }
                let bits = try allocate(type: unsigned64)
                appendInstruction(
                    .integerConvert(
                        result: bits,
                        operation: .reinterpret,
                        value: source
                    )
                )
                let key = try allocate(type: unsigned64)
                let ignoredOverflow = try allocate(type: .bool)
                appendInstruction(
                    .checkedBinary(
                        result: key,
                        overflow: ignoredOverflow,
                        operation: .bitXor,
                        lhs: bits,
                        rhs: signBit
                    )
                )
                return key
            }

            let lower = try orderKey(value.start)
            let upper = try orderKey(value.end)
            var unsignedCount = try checked(
                .subtract,
                lhs: upper,
                rhs: lower,
                type: unsigned64
            )
            if includesUpperBound {
                let one = try allocate(type: unsigned64)
                appendInstruction(
                    .constantInteger(result: one, bitPattern: 1)
                )
                unsignedCount = try checked(
                    .add,
                    lhs: unsignedCount,
                    rhs: one,
                    type: unsigned64
                )
            }
            let maximum = try allocate(type: unsigned64)
            appendInstruction(
                .constantInteger(
                    result: maximum,
                    bitPattern: UInt64(Int64.max)
                )
            )
            let exceedsInt = try allocate(type: .bool)
            appendInstruction(
                .compare(
                    result: exceedsInt,
                    predicate: .greaterThan,
                    lhs: unsignedCount,
                    rhs: maximum
                )
            )
            try appendConditionalTrap(
                condition: exceedsInt,
                reason: .integerOverflow
            )
            let result = try allocate(type: .int64)
            appendInstruction(
                .integerConvert(
                    result: result,
                    operation: .reinterpret,
                    value: unsignedCount
                )
            )
            return result
        }

        func borrowRepresentedSequenceSource(
            type: Bytecode.ValueType,
            token: String,
            operation: String,
            line: Int
        ) throws -> BorrowedStoredValue {
            let borrowed = try borrowStoredValue(
                at: token,
                line: line
            ) ?? .init(
                register: try resolve(token, line: line),
                temporaryOwner: nil
            )
            guard registerTypes[Int(borrowed.register.rawValue)] == type else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "\(operation) source does not match its specialization"
                )
            }
            return borrowed
        }

        /// StrideTo/StrideThrough expose an exact underestimatedCount through
        /// their Sequence witness. Count by the same typed cursor so floating
        /// stepping and endpoint inclusion remain identical without building
        /// a temporary Array; VM fuel bounds pathological progressions.
        func lowerProgressionCountByTraversal(
            _ value: CanonicalSIL.Progression.Value,
            line: Int
        ) throws -> Bytecode.Register {
            let state = try makeProgressionCursor(value, line: line)
            let cursor = SequenceCursor.progression(
                end: state.end,
                stride: state.stride,
                cursorSlot: state.cursorSlot,
                boundary: state.type.family.boundary
            )
            let zero = try allocate(type: .int64)
            let one = try allocate(type: .int64)
            appendInstruction(.constantInteger(result: zero, bitPattern: 0))
            appendInstruction(.constantInteger(result: one, bitPattern: 1))

            let loop = try allocateSyntheticBlockID()
            let increment = try allocateSyntheticBlockID()
            let finish = try allocateSyntheticBlockID()
            let overflowTrap = try allocateSyntheticBlockID()
            let completion = try allocateSyntheticBlockID()
            let count = try allocate(type: .int64)
            let next = try allocate(type: .optional(state.type.element))
            let element = try allocate(type: state.type.element)
            let incremented = try allocate(type: .int64)
            let overflow = try allocate(type: .bool)
            let result = try allocate(type: .int64)

            appendInstruction(.branch(target: loop, arguments: [zero]))
            finishCurrent()
            appendSyntheticBlock(
                id: loop,
                parameters: [count],
                instructions: [
                    try sequenceNextInstruction(
                        cursor: cursor,
                        result: next,
                        direction: .forward
                    ),
                    .switchOptional(
                        optional: next,
                        someTarget: increment,
                        noneTarget: finish
                    ),
                ]
            )
            appendSyntheticBlock(
                id: increment,
                parameters: [element],
                instructions: [
                    .checkedBinary(
                        result: incremented,
                        overflow: overflow,
                        operation: .add,
                        lhs: count,
                        rhs: one
                    ),
                    .conditionalBranch(
                        condition: overflow,
                        trueTarget: overflowTrap,
                        trueArguments: [],
                        falseTarget: loop,
                        falseArguments: [incremented]
                    ),
                ]
            )
            appendSyntheticBlock(
                id: finish,
                instructions: [
                    .destroyStack(state.cursorSlot),
                    .branch(target: completion, arguments: [count]),
                ]
            )
            appendSyntheticBlock(
                id: overflowTrap,
                instructions: [.trap(.integerOverflow)]
            )
            retainFlow.activate(completion)
            current = .init(
                id: completion,
                parameters: [result],
                instructions: []
            )
            return result
        }

        func lowerSequenceCount(
            _ specialization: CanonicalSIL.SequenceSpecialization,
            sourceToken: String,
            line: Int
        ) throws -> Bytecode.Register {
            switch specialization {
            case .stringCharacters:
                let borrowed = try borrowRepresentedSequenceSource(
                    type: .string,
                    token: sourceToken,
                    operation: "String.count",
                    line: line
                )
                let result = try allocate(type: .int64)
                appendInstruction(
                    .stringCount(result: result, string: borrowed.register)
                )
                if let owner = borrowed.temporaryOwner {
                    appendInstruction(.destroyValue(owner))
                }
                return result

            case let .managedCollection(type, _):
                let borrowed = try borrowRepresentedSequenceSource(
                    type: type,
                    token: sourceToken,
                    operation: "Collection.count",
                    line: line
                )
                let result = try allocate(type: .int64)
                switch type {
                case .array:
                    appendInstruction(
                        .arrayCount(result: result, array: borrowed.register)
                    )
                case .dictionary:
                    appendInstruction(
                        .dictionaryCount(
                            result: result,
                            dictionary: borrowed.register
                        )
                    )
                case .set:
                    appendInstruction(
                        .setCount(result: result, set: borrowed.register)
                    )
                default:
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "Collection.count source \(type)"
                    )
                }
                if let owner = borrowed.temporaryOwner {
                    appendInstruction(.destroyValue(owner))
                }
                return result

            case let .progression(type):
                let value = try progressionOperand(
                    sourceToken,
                    expected: type,
                    line: line
                )
                if type.family == .range || type.family == .closedRange {
                    return try lowerIntegerProgressionCount(value)
                }
                return try lowerProgressionCountByTraversal(value, line: line)
            }
        }

        func lowerSequenceIsEmpty(
            _ specialization: CanonicalSIL.SequenceSpecialization,
            sourceToken: String,
            line: Int
        ) throws -> Bytecode.Register {
            switch specialization {
            case .stringCharacters:
                let borrowed = try borrowRepresentedSequenceSource(
                    type: .string,
                    token: sourceToken,
                    operation: "String.isEmpty",
                    line: line
                )
                let result = try allocate(type: .bool)
                appendInstruction(
                    .stringIsEmpty(result: result, string: borrowed.register)
                )
                if let owner = borrowed.temporaryOwner {
                    appendInstruction(.destroyValue(owner))
                }
                return result

            case let .managedCollection(type, _):
                let borrowed = try borrowRepresentedSequenceSource(
                    type: type,
                    token: sourceToken,
                    operation: "Collection.isEmpty",
                    line: line
                )
                let result = try allocate(type: .bool)
                switch type {
                case .array:
                    appendInstruction(
                        .arrayIsEmpty(result: result, array: borrowed.register)
                    )
                case .dictionary:
                    appendInstruction(
                        .dictionaryIsEmpty(
                            result: result,
                            dictionary: borrowed.register
                        )
                    )
                case .set:
                    appendInstruction(
                        .setIsEmpty(result: result, set: borrowed.register)
                    )
                default:
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "Collection.isEmpty source \(type)"
                    )
                }
                if let owner = borrowed.temporaryOwner {
                    appendInstruction(.destroyValue(owner))
                }
                return result

            case let .progression(type):
                guard type.family == .range || type.family == .closedRange
                else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "Collection.isEmpty progression \(type)"
                    )
                }
                let value = try progressionOperand(
                    sourceToken,
                    expected: type,
                    line: line
                )
                let result = try allocate(type: .bool)
                if type.family == .closedRange {
                    appendInstruction(
                        .constantBool(result: result, value: false)
                    )
                } else {
                    appendInstruction(
                        .compare(
                            result: result,
                            predicate: .equal,
                            lhs: value.start,
                            rhs: value.end
                        )
                    )
                }
                return result
            }
        }

        func lowerSequenceFirst(
            _ specialization: CanonicalSIL.SequenceSpecialization,
            sourceToken: String,
            line: Int
        ) throws -> Bytecode.Register {
            let traversal = try prepareSequenceTraversal(
                specialization,
                token: sourceToken,
                consumesSource: false,
                direction: .forward,
                line: line
            )
            let result = try allocate(type: .optional(specialization.element))
            appendInstruction(
                try sequenceNextInstruction(
                    cursor: traversal.cursor,
                    result: result,
                    direction: .forward
                )
            )
            for instruction in traversalCleanup(traversal) {
                appendInstruction(instruction)
            }
            return result
        }

        func lowerSequenceLast(
            _ specialization: CanonicalSIL.SequenceSpecialization,
            sourceToken: String,
            line: Int
        ) throws -> Bytecode.Register {
            switch specialization {
            case .stringCharacters:
                let traversal = try prepareSequenceTraversal(
                    specialization,
                    token: sourceToken,
                    consumesSource: false,
                    direction: .reverse,
                    line: line
                )
                let result = try allocate(type: .optional(.string))
                appendInstruction(
                    try sequenceNextInstruction(
                        cursor: traversal.cursor,
                        result: result,
                        direction: .reverse
                    )
                )
                for instruction in traversalCleanup(traversal) {
                    appendInstruction(instruction)
                }
                return result

            case let .managedCollection(type, element):
                guard case .array = type else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "Collection.last requires represented bidirectional storage"
                    )
                }
                let borrowed = try borrowRepresentedSequenceSource(
                    type: type,
                    token: sourceToken,
                    operation: "Collection.last",
                    line: line
                )
                let result = try allocate(type: .optional(element))
                appendInstruction(
                    .arrayBoundary(
                        result: result,
                        operation: .last,
                        array: borrowed.register
                    )
                )
                if let owner = borrowed.temporaryOwner {
                    appendInstruction(.destroyValue(owner))
                }
                return result

            case let .progression(type):
                guard type.family == .range || type.family == .closedRange,
                      case .integer = type.element
                else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "Collection.last progression \(type)"
                    )
                }
                let value = try progressionOperand(
                    sourceToken,
                    expected: type,
                    line: line
                )
                let resultType = Bytecode.ValueType.optional(type.element)
                if type.family == .closedRange {
                    let result = try allocate(type: resultType)
                    appendInstruction(
                        .makeOptionalSome(result: result, value: value.end)
                    )
                    return result
                }

                let calculate = try allocateSyntheticBlockID()
                let wrap = try allocateSyntheticBlockID()
                let overflowTrap = try allocateSyntheticBlockID()
                let empty = try allocateSyntheticBlockID()
                let completion = try allocateSyntheticBlockID()
                let isEmpty = try allocate(type: .bool)
                let one = try allocate(type: type.element)
                let last = try allocate(type: type.element)
                let overflow = try allocate(type: .bool)
                let present = try allocate(type: resultType)
                let absent = try allocate(type: resultType)
                let result = try allocate(type: resultType)
                appendInstruction(
                    .compare(
                        result: isEmpty,
                        predicate: .equal,
                        lhs: value.start,
                        rhs: value.end
                    )
                )
                appendInstruction(
                    .conditionalBranch(
                        condition: isEmpty,
                        trueTarget: empty,
                        trueArguments: [],
                        falseTarget: calculate,
                        falseArguments: []
                    )
                )
                finishCurrent()
                appendSyntheticBlock(
                    id: calculate,
                    instructions: [
                        .constantInteger(result: one, bitPattern: 1),
                        .checkedBinary(
                            result: last,
                            overflow: overflow,
                            operation: .subtract,
                            lhs: value.end,
                            rhs: one
                        ),
                        .conditionalBranch(
                            condition: overflow,
                            trueTarget: overflowTrap,
                            trueArguments: [],
                            falseTarget: wrap,
                            falseArguments: []
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: wrap,
                    instructions: [
                        .makeOptionalSome(result: present, value: last),
                        .branch(target: completion, arguments: [present]),
                    ]
                )
                appendSyntheticBlock(
                    id: overflowTrap,
                    instructions: [.trap(.integerOverflow)]
                )
                appendSyntheticBlock(
                    id: empty,
                    instructions: [
                        .makeOptionalNone(result: absent),
                        .branch(target: completion, arguments: [absent]),
                    ]
                )
                retainFlow.activate(completion)
                current = .init(
                    id: completion,
                    parameters: [result],
                    instructions: []
                )
                return result
            }
        }

        func materializeProgressionElements(
            _ value: CanonicalSIL.Progression.Value,
            line: Int
        ) throws -> Bytecode.Register {
            let state = try makeProgressionCursor(value, line: line)
            let cursor = SequenceCursor.progression(
                end: state.end,
                stride: state.stride,
                cursorSlot: state.cursorSlot,
                boundary: state.type.family.boundary
            )
            let builder = try allocate(
                type: .arrayState(
                    kind: .builder,
                    element: state.type.element
                )
            )
            appendInstruction(.makeArrayBuilder(result: builder))

            let loop = try allocateSyntheticBlockID()
            let append = try allocateSyntheticBlockID()
            let finish = try allocateSyntheticBlockID()
            let completion = try allocateSyntheticBlockID()
            let next = try allocate(type: .optional(state.type.element))
            let element = try allocate(type: state.type.element)
            let finished = try allocate(type: .array(state.type.element))
            let result = try allocate(type: .array(state.type.element))

            appendInstruction(.branch(target: loop, arguments: []))
            finishCurrent()
            appendSyntheticBlock(
                id: loop,
                instructions: [
                    try sequenceNextInstruction(
                        cursor: cursor,
                        result: next,
                        direction: .forward
                    ),
                    .switchOptional(
                        optional: next,
                        someTarget: append,
                        noneTarget: finish
                    ),
                ]
            )
            appendSyntheticBlock(
                id: append,
                parameters: [element],
                instructions: [
                    .arrayBuilderAppend(builder: builder, value: element),
                    .branch(target: loop, arguments: []),
                ]
            )
            appendSyntheticBlock(
                id: finish,
                instructions: [
                    .finishArrayBuilder(result: finished, builder: builder),
                    .destroyStack(state.cursorSlot),
                    .branch(target: completion, arguments: [finished]),
                ]
            )
            retainFlow.activate(completion)
            current = .init(
                id: completion,
                parameters: [result],
                instructions: []
            )
            return result
        }

        func materializeSequenceOperand(
            _ specialization: CanonicalSIL.SequenceSpecialization,
            token: String,
            context: String,
            line: Int
        ) throws -> (
            array: Bytecode.Register,
            cleanup: [IntermediateRepresentation.Instruction]
        ) {
            switch specialization {
            case .stringCharacters:
                if let storageType = stackType(at: token),
                   storageType != .string {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "\(context) String storage does not match its Sequence specialization"
                    )
                }
                let borrowed = try borrowStoredValue(at: token, line: line)
                let source = try borrowed?.register ?? resolve(token, line: line)
                guard registerTypes[Int(source.rawValue)] == .string else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "\(context) String value does not match its Sequence specialization"
                    )
                }
                let characters = try allocate(type: .array(.string))
                appendInstruction(
                    .stringCharacters(result: characters, string: source)
                )
                return (
                    characters,
                    borrowed?.temporaryOwner.map { [.destroyValue($0)] } ?? []
                )

            case let .managedCollection(sourceType, element):
                guard sourceType.managedCollectionElement == element else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "\(context) has an inconsistent managed Sequence specialization"
                    )
                }
                if let storageType = stackType(at: token),
                   storageType != sourceType {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "\(context) storage does not match its Sequence specialization"
                    )
                }
                let borrowed = try borrowStoredValue(at: token, line: line)
                let source = try borrowed?.register ?? resolve(token, line: line)
                guard registerTypes[Int(source.rawValue)] == sourceType else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "\(context) value does not match its Sequence specialization"
                    )
                }
                let materialized = try materializeManagedCollectionElements(
                    source,
                    sourceType: sourceType,
                    context: context
                )
                var cleanup: [IntermediateRepresentation.Instruction] = []
                if let owner = materialized.cleanupOwner {
                    cleanup.append(.destroyValue(owner))
                }
                if let owner = borrowed?.temporaryOwner {
                    cleanup.append(.destroyValue(owner))
                }
                return (materialized.array, cleanup)

            case let .progression(type):
                let value = try progressionOperand(
                    token,
                    expected: type,
                    line: line
                )
                let array = try materializeProgressionElements(
                    value,
                    line: line
                )
                let arrayType = Bytecode.ValueType.array(type.element)
                return (
                    array,
                    requiresManagedOwnership(arrayType)
                        ? [.destroyValue(array)] : []
                )
            }
        }

        func lowerStringJoin(
            elements: Bytecode.Register,
            separator: Bytecode.Register?,
            elementKind: Bytecode.StringJoinElementKind,
            context: String
        ) throws -> Bytecode.Register {
            guard registerTypes[Int(elements.rawValue)] == .array(.string),
                  separator.map({
                      registerTypes[Int($0.rawValue)] == .string
                  }) ?? true,
                  elementKind != .character || separator == nil
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "\(context) does not match its represented text elements"
                )
            }
            let result = try allocate(type: .string)
            appendInstruction(
                .stringJoin(
                    result: result,
                    elements: elements,
                    separator: separator,
                    elementKind: elementKind
                )
            )
            return result
        }

        func appendDistinctCleanups(
            _ groups: [[IntermediateRepresentation.Instruction]]
        ) {
            // Source and destination materializations may borrow the same
            // temporary owner. Preserve cleanup order while releasing each
            // aliased resource exactly once.
            var appended = Set<IntermediateRepresentation.Instruction>()
            for instruction in groups.joined() {
                if appended.insert(instruction).inserted {
                    appendInstruction(instruction)
                }
            }
        }

        func materializeRangeReplaceableElements(
            _ representation: CanonicalSIL
                .RangeReplaceableCollectionRepresentation,
            token: String,
            context: String,
            line: Int
        ) throws -> (
            elements: Bytecode.Register,
            cleanup: [IntermediateRepresentation.Instruction]
        ) {
            guard compilerAddressType(token) == representation.storageType
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "\(context) destination does not match its specialization"
                )
            }
            let materialized = try materializeSequenceOperand(
                representation.sequence,
                token: token,
                context: context,
                line: line
            )
            guard registerTypes[Int(materialized.array.rawValue)]
                    == representation.elementsType
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "\(context) produced mismatched element storage"
                )
            }
            return (
                elements: materialized.array,
                cleanup: materialized.cleanup
            )
        }

        func finalizeRangeReplaceableElements(
            _ elements: Bytecode.Register,
            representation: CanonicalSIL
                .RangeReplaceableCollectionRepresentation,
            context: String
        ) throws -> Bytecode.Register {
            guard registerTypes[Int(elements.rawValue)]
                    == representation.elementsType
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "\(context) finalizer received mismatched elements"
                )
            }
            switch representation {
            case .representedArray:
                return elements
            case .stringCharacters:
                return try lowerStringJoin(
                    elements: elements,
                    separator: nil,
                    elementKind: .character,
                    context: context
                )
            }
        }

        func makeEmptyRangeReplaceableElements(
            _ representation: CanonicalSIL
                .RangeReplaceableCollectionRepresentation
        ) throws -> Bytecode.Register {
            let result = try allocate(type: representation.elementsType)
            appendInstruction(.makeArray(result: result, elements: []))
            return result
        }

        func makeEmptyRangeReplaceableStorage(
            _ representation: CanonicalSIL
                .RangeReplaceableCollectionRepresentation
        ) throws -> Bytecode.Register {
            switch representation {
            case .representedArray:
                return try makeEmptyRangeReplaceableElements(representation)
            case .stringCharacters:
                let result = try allocate(type: .string)
                appendInstruction(.constantString(result: result, value: ""))
                return result
            }
        }

        /// Executes equality membership through the shared cursor so a finite
        /// progression can short-circuit without first allocating its full
        /// element sequence. The same CFG also remains valid for represented
        /// managed Collections.
        func lowerSequenceContainsElement(
            _ specialization: CanonicalSIL.SequenceSpecialization,
            sourceToken: String,
            needleToken: String,
            line: Int
        ) throws -> Bytecode.Register {
            let elementType = specialization.element
            guard elementType.isVMEquatable else {
                throw CanonicalSIL.LoweringError.unsupportedType(
                    "Sequence.contains element \(elementType) lacks VM-defined Equatable semantics"
                )
            }
            let needle = try borrowStoredValue(
                at: needleToken,
                line: line
            ) ?? .init(
                register: try resolve(needleToken, line: line),
                temporaryOwner: nil
            )
            guard registerTypes[Int(needle.register.rawValue)] == elementType
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "Sequence.contains value does not match Sequence.Element"
                )
            }
            let traversal = try prepareSequenceTraversal(
                specialization,
                token: sourceToken,
                consumesSource: false,
                direction: .forward,
                line: line
            )

            let loop = try allocateSyntheticBlockID()
            let compare = try allocateSyntheticBlockID()
            let found = try allocateSyntheticBlockID()
            let advance = try allocateSyntheticBlockID()
            let absent = try allocateSyntheticBlockID()
            let completion = try allocateSyntheticBlockID()
            let next = try allocate(type: .optional(elementType))
            let element = try allocate(type: elementType)
            let matches = try allocate(type: .bool)
            let presentValue = try allocate(type: .bool)
            let absentValue = try allocate(type: .bool)
            let result = try allocate(type: .bool)
            let elementCleanup: [IntermediateRepresentation.Instruction] =
                requiresManagedOwnership(elementType)
                    ? [.destroyValue(element)] : []
            let terminalCleanup = traversalCleanup(traversal)
                + (needle.temporaryOwner.map { [.destroyValue($0)] } ?? [])

            appendInstruction(.branch(target: loop, arguments: []))
            finishCurrent()
            appendSyntheticBlock(
                id: loop,
                instructions: [
                    try sequenceNextInstruction(
                        cursor: traversal.cursor,
                        result: next,
                        direction: .forward
                    ),
                    .switchOptional(
                        optional: next,
                        someTarget: compare,
                        noneTarget: absent
                    ),
                ]
            )
            appendSyntheticBlock(
                id: compare,
                parameters: [element],
                instructions: [
                    .compare(
                        result: matches,
                        predicate: .equal,
                        lhs: element,
                        rhs: needle.register
                    ),
                    .conditionalBranch(
                        condition: matches,
                        trueTarget: found,
                        trueArguments: [],
                        falseTarget: advance,
                        falseArguments: []
                    ),
                ]
            )
            appendSyntheticBlock(
                id: found,
                instructions: elementCleanup + terminalCleanup + [
                    .constantBool(result: presentValue, value: true),
                    .branch(
                        target: completion,
                        arguments: [presentValue]
                    ),
                ]
            )
            appendSyntheticBlock(
                id: advance,
                instructions: elementCleanup + [
                    .branch(target: loop, arguments: []),
                ]
            )
            appendSyntheticBlock(
                id: absent,
                instructions: terminalCleanup + [
                    .constantBool(result: absentValue, value: false),
                    .branch(
                        target: completion,
                        arguments: [absentValue]
                    ),
                ]
            )
            retainFlow.activate(completion)
            current = .init(
                id: completion,
                parameters: [result],
                instructions: []
            )
            return result
        }

        /// Natural extrema require a full scan but not a full materialization.
        /// Keep one owned candidate in frame storage and replace it only for a
        /// strict improvement, preserving Swift's first-element tie behavior.
        func lowerNaturalSequenceExtremum(
            _ operation: CanonicalSIL.CollectionIntrinsic.ExtremumOperation,
            specialization: CanonicalSIL.SequenceSpecialization,
            sourceToken: String,
            line: Int
        ) throws -> Bytecode.Register {
            let elementType = specialization.element
            guard elementType.isVMComparable else {
                throw CanonicalSIL.LoweringError.unsupportedType(
                    "Sequence extremum element \(elementType) lacks VM-defined Comparable semantics"
                )
            }
            let traversal = try prepareSequenceTraversal(
                specialization,
                token: sourceToken,
                consumesSource: false,
                direction: .forward,
                line: line
            )
            let candidateSlot = try allocateStackSlot(type: elementType)
            let readFirst = try allocateSyntheticBlockID()
            let initialize = try allocateSyntheticBlockID()
            let empty = try allocateSyntheticBlockID()
            let scan = try allocateSyntheticBlockID()
            let compare = try allocateSyntheticBlockID()
            let replace = try allocateSyntheticBlockID()
            let keep = try allocateSyntheticBlockID()
            let finish = try allocateSyntheticBlockID()
            let completion = try allocateSyntheticBlockID()
            let first = try allocate(type: elementType)
            let firstNext = try allocate(type: .optional(elementType))
            let next = try allocate(type: .optional(elementType))
            let element = try allocate(type: elementType)
            let candidate = try allocate(type: elementType)
            let improves = try allocate(type: .bool)
            let finalCandidate = try allocate(type: elementType)
            let selected = try allocate(type: .optional(elementType))
            let noSelection = try allocate(type: .optional(elementType))
            let result = try allocate(type: .optional(elementType))
            let candidateCleanup: [IntermediateRepresentation.Instruction] =
                requiresManagedOwnership(elementType)
                    ? [.destroyValue(candidate)] : []
            let elementCleanup: [IntermediateRepresentation.Instruction] =
                requiresManagedOwnership(elementType)
                    ? [.destroyValue(element)] : []
            let terminalCleanup = traversalCleanup(traversal)

            appendInstruction(.branch(target: readFirst, arguments: []))
            finishCurrent()
            appendSyntheticBlock(
                id: readFirst,
                instructions: [
                    try sequenceNextInstruction(
                        cursor: traversal.cursor,
                        result: firstNext,
                        direction: .forward
                    ),
                    .switchOptional(
                        optional: firstNext,
                        someTarget: initialize,
                        noneTarget: empty
                    ),
                ]
            )
            appendSyntheticBlock(
                id: initialize,
                parameters: [first],
                instructions: [
                    .storeStack(
                        slot: candidateSlot,
                        source: first,
                        mode: .initialize
                    ),
                    .branch(target: scan, arguments: []),
                ]
            )
            appendSyntheticBlock(
                id: scan,
                instructions: [
                    try sequenceNextInstruction(
                        cursor: traversal.cursor,
                        result: next,
                        direction: .forward
                    ),
                    .switchOptional(
                        optional: next,
                        someTarget: compare,
                        noneTarget: finish
                    ),
                ]
            )
            appendSyntheticBlock(
                id: compare,
                parameters: [element],
                instructions: [
                    .loadStack(
                        result: candidate,
                        slot: candidateSlot,
                        mode: .copy
                    ),
                    .compare(
                        result: improves,
                        predicate: .lessThan,
                        lhs: operation == .minimum ? element : candidate,
                        rhs: operation == .minimum ? candidate : element
                    ),
                    .conditionalBranch(
                        condition: improves,
                        trueTarget: replace,
                        trueArguments: [],
                        falseTarget: keep,
                        falseArguments: []
                    ),
                ]
            )
            appendSyntheticBlock(
                id: replace,
                instructions: candidateCleanup + [
                    .storeStack(
                        slot: candidateSlot,
                        source: element,
                        mode: .assign
                    ),
                    .branch(target: scan, arguments: []),
                ]
            )
            appendSyntheticBlock(
                id: keep,
                instructions: candidateCleanup + elementCleanup + [
                    .branch(target: scan, arguments: []),
                ]
            )
            appendSyntheticBlock(
                id: finish,
                instructions: [
                    .loadStack(
                        result: finalCandidate,
                        slot: candidateSlot,
                        mode: .take
                    ),
                    .makeOptionalSome(
                        result: selected,
                        value: finalCandidate
                    ),
                ] + terminalCleanup + [
                    .branch(target: completion, arguments: [selected]),
                ]
            )
            appendSyntheticBlock(
                id: empty,
                instructions: [
                    .makeOptionalNone(result: noSelection),
                ] + terminalCleanup + [
                    .branch(target: completion, arguments: [noSelection]),
                ]
            )
            retainFlow.activate(completion)
            current = .init(
                id: completion,
                parameters: [result],
                instructions: []
            )
            return result
        }

        /// Compares two concrete element sequences directly through their
        /// cursors. This preserves prefix and lexicographic short-circuiting
        /// for progressions without introducing Sequence-specific bytecode or
        /// invoking Swift witness-table ABI at runtime.
        func lowerSequenceRelation(
            _ operation: CanonicalSIL.CollectionIntrinsic.RelationOperation,
            lhs: CanonicalSIL.SequenceSpecialization,
            lhsToken: String,
            rhs: CanonicalSIL.SequenceSpecialization,
            rhsToken: String,
            line: Int
        ) throws -> Bytecode.Register {
            let elementType = lhs.element
            guard rhs.element == elementType else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "Sequence relation operands have different Element types"
                )
            }
            let supportsElementOperation = switch operation {
            case .elementsEqual, .startsWith: elementType.isVMEquatable
            case .lexicographicallyPrecedes: elementType.isVMComparable
            }
            guard supportsElementOperation else {
                throw CanonicalSIL.LoweringError.unsupportedType(
                    "Sequence relation element \(elementType)"
                )
            }
            let lhsTraversal = try prepareSequenceTraversal(
                lhs,
                token: lhsToken,
                consumesSource: false,
                direction: .forward,
                line: line
            )
            let rhsTraversal = try prepareSequenceTraversal(
                rhs,
                token: rhsToken,
                consumesSource: false,
                direction: .forward,
                line: line
            )
            let succeed = try allocateSyntheticBlockID()
            let fail = try allocateSyntheticBlockID()
            let completion = try allocateSyntheticBlockID()
            let trueValue = try allocate(type: .bool)
            let falseValue = try allocate(type: .bool)
            let result = try allocate(type: .bool)
            let terminalCleanup = traversalCleanup(lhsTraversal)
                + traversalCleanup(rhsTraversal)

            switch operation {
            case .elementsEqual:
                let loop = try allocateSyntheticBlockID()
                let readRHS = try allocateSyntheticBlockID()
                let checkRHSEnd = try allocateSyntheticBlockID()
                let compare = try allocateSyntheticBlockID()
                let advance = try allocateSyntheticBlockID()
                let mismatch = try allocateSyntheticBlockID()
                let rhsEnded = try allocateSyntheticBlockID()
                let rhsTrailing = try allocateSyntheticBlockID()
                let lhsNext = try allocate(type: .optional(elementType))
                let rhsNext = try allocate(type: .optional(elementType))
                let trailingNext = try allocate(type: .optional(elementType))
                let lhsElement = try allocate(type: elementType)
                let rhsElement = try allocate(type: elementType)
                let trailingElement = try allocate(type: elementType)
                let equal = try allocate(type: .bool)
                let lhsCleanup: [IntermediateRepresentation.Instruction] =
                    requiresManagedOwnership(elementType)
                        ? [.destroyValue(lhsElement)] : []
                let rhsCleanup: [IntermediateRepresentation.Instruction] =
                    requiresManagedOwnership(elementType)
                        ? [.destroyValue(rhsElement)] : []
                let trailingCleanup: [IntermediateRepresentation.Instruction] =
                    requiresManagedOwnership(elementType)
                        ? [.destroyValue(trailingElement)] : []

                appendInstruction(.branch(target: loop, arguments: []))
                finishCurrent()
                appendSyntheticBlock(
                    id: loop,
                    instructions: [
                        try sequenceNextInstruction(
                            cursor: lhsTraversal.cursor,
                            result: lhsNext,
                            direction: .forward
                        ),
                        .switchOptional(
                            optional: lhsNext,
                            someTarget: readRHS,
                            noneTarget: checkRHSEnd
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: readRHS,
                    parameters: [lhsElement],
                    instructions: [
                        try sequenceNextInstruction(
                            cursor: rhsTraversal.cursor,
                            result: rhsNext,
                            direction: .forward
                        ),
                        .switchOptional(
                            optional: rhsNext,
                            someTarget: compare,
                            noneTarget: rhsEnded
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: compare,
                    parameters: [rhsElement],
                    instructions: [
                        .compare(
                            result: equal,
                            predicate: .equal,
                            lhs: lhsElement,
                            rhs: rhsElement
                        ),
                        .conditionalBranch(
                            condition: equal,
                            trueTarget: advance,
                            trueArguments: [],
                            falseTarget: mismatch,
                            falseArguments: []
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: advance,
                    instructions: lhsCleanup + rhsCleanup + [
                        .branch(target: loop, arguments: []),
                    ]
                )
                appendSyntheticBlock(
                    id: mismatch,
                    instructions: lhsCleanup + rhsCleanup + [
                        .branch(target: fail, arguments: []),
                    ]
                )
                appendSyntheticBlock(
                    id: rhsEnded,
                    instructions: lhsCleanup + [
                        .branch(target: fail, arguments: []),
                    ]
                )
                appendSyntheticBlock(
                    id: checkRHSEnd,
                    instructions: [
                        try sequenceNextInstruction(
                            cursor: rhsTraversal.cursor,
                            result: trailingNext,
                            direction: .forward
                        ),
                        .switchOptional(
                            optional: trailingNext,
                            someTarget: rhsTrailing,
                            noneTarget: succeed
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: rhsTrailing,
                    parameters: [trailingElement],
                    instructions: trailingCleanup + [
                        .branch(target: fail, arguments: []),
                    ]
                )

            case .startsWith:
                let loop = try allocateSyntheticBlockID()
                let readLHS = try allocateSyntheticBlockID()
                let compare = try allocateSyntheticBlockID()
                let advance = try allocateSyntheticBlockID()
                let mismatch = try allocateSyntheticBlockID()
                let lhsEnded = try allocateSyntheticBlockID()
                let rhsNext = try allocate(type: .optional(elementType))
                let lhsNext = try allocate(type: .optional(elementType))
                let rhsElement = try allocate(type: elementType)
                let lhsElement = try allocate(type: elementType)
                let equal = try allocate(type: .bool)
                let rhsCleanup: [IntermediateRepresentation.Instruction] =
                    requiresManagedOwnership(elementType)
                        ? [.destroyValue(rhsElement)] : []
                let lhsCleanup: [IntermediateRepresentation.Instruction] =
                    requiresManagedOwnership(elementType)
                        ? [.destroyValue(lhsElement)] : []

                appendInstruction(.branch(target: loop, arguments: []))
                finishCurrent()
                appendSyntheticBlock(
                    id: loop,
                    instructions: [
                        try sequenceNextInstruction(
                            cursor: rhsTraversal.cursor,
                            result: rhsNext,
                            direction: .forward
                        ),
                        .switchOptional(
                            optional: rhsNext,
                            someTarget: readLHS,
                            noneTarget: succeed
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: readLHS,
                    parameters: [rhsElement],
                    instructions: [
                        try sequenceNextInstruction(
                            cursor: lhsTraversal.cursor,
                            result: lhsNext,
                            direction: .forward
                        ),
                        .switchOptional(
                            optional: lhsNext,
                            someTarget: compare,
                            noneTarget: lhsEnded
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: compare,
                    parameters: [lhsElement],
                    instructions: [
                        .compare(
                            result: equal,
                            predicate: .equal,
                            lhs: lhsElement,
                            rhs: rhsElement
                        ),
                        .conditionalBranch(
                            condition: equal,
                            trueTarget: advance,
                            trueArguments: [],
                            falseTarget: mismatch,
                            falseArguments: []
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: advance,
                    instructions: lhsCleanup + rhsCleanup + [
                        .branch(target: loop, arguments: []),
                    ]
                )
                appendSyntheticBlock(
                    id: mismatch,
                    instructions: lhsCleanup + rhsCleanup + [
                        .branch(target: fail, arguments: []),
                    ]
                )
                appendSyntheticBlock(
                    id: lhsEnded,
                    instructions: rhsCleanup + [
                        .branch(target: fail, arguments: []),
                    ]
                )

            case .lexicographicallyPrecedes:
                let loop = try allocateSyntheticBlockID()
                let readRHS = try allocateSyntheticBlockID()
                let checkRHSTrailing = try allocateSyntheticBlockID()
                let compare = try allocateSyntheticBlockID()
                let compareReverse = try allocateSyntheticBlockID()
                let advance = try allocateSyntheticBlockID()
                let precedes = try allocateSyntheticBlockID()
                let doesNotPrecede = try allocateSyntheticBlockID()
                let rhsEnded = try allocateSyntheticBlockID()
                let rhsTrailing = try allocateSyntheticBlockID()
                let lhsNext = try allocate(type: .optional(elementType))
                let rhsNext = try allocate(type: .optional(elementType))
                let trailingNext = try allocate(type: .optional(elementType))
                let lhsElement = try allocate(type: elementType)
                let rhsElement = try allocate(type: elementType)
                let trailingElement = try allocate(type: elementType)
                let lhsBefore = try allocate(type: .bool)
                let rhsBefore = try allocate(type: .bool)
                let lhsCleanup: [IntermediateRepresentation.Instruction] =
                    requiresManagedOwnership(elementType)
                        ? [.destroyValue(lhsElement)] : []
                let rhsCleanup: [IntermediateRepresentation.Instruction] =
                    requiresManagedOwnership(elementType)
                        ? [.destroyValue(rhsElement)] : []
                let trailingCleanup: [IntermediateRepresentation.Instruction] =
                    requiresManagedOwnership(elementType)
                        ? [.destroyValue(trailingElement)] : []

                appendInstruction(.branch(target: loop, arguments: []))
                finishCurrent()
                appendSyntheticBlock(
                    id: loop,
                    instructions: [
                        try sequenceNextInstruction(
                            cursor: lhsTraversal.cursor,
                            result: lhsNext,
                            direction: .forward
                        ),
                        .switchOptional(
                            optional: lhsNext,
                            someTarget: readRHS,
                            noneTarget: checkRHSTrailing
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: readRHS,
                    parameters: [lhsElement],
                    instructions: [
                        try sequenceNextInstruction(
                            cursor: rhsTraversal.cursor,
                            result: rhsNext,
                            direction: .forward
                        ),
                        .switchOptional(
                            optional: rhsNext,
                            someTarget: compare,
                            noneTarget: rhsEnded
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: compare,
                    parameters: [rhsElement],
                    instructions: [
                        .compare(
                            result: lhsBefore,
                            predicate: .lessThan,
                            lhs: lhsElement,
                            rhs: rhsElement
                        ),
                        .conditionalBranch(
                            condition: lhsBefore,
                            trueTarget: precedes,
                            trueArguments: [],
                            falseTarget: compareReverse,
                            falseArguments: []
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: compareReverse,
                    instructions: [
                        .compare(
                            result: rhsBefore,
                            predicate: .lessThan,
                            lhs: rhsElement,
                            rhs: lhsElement
                        ),
                        .conditionalBranch(
                            condition: rhsBefore,
                            trueTarget: doesNotPrecede,
                            trueArguments: [],
                            falseTarget: advance,
                            falseArguments: []
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: advance,
                    instructions: lhsCleanup + rhsCleanup + [
                        .branch(target: loop, arguments: []),
                    ]
                )
                appendSyntheticBlock(
                    id: precedes,
                    instructions: lhsCleanup + rhsCleanup + [
                        .branch(target: succeed, arguments: []),
                    ]
                )
                appendSyntheticBlock(
                    id: doesNotPrecede,
                    instructions: lhsCleanup + rhsCleanup + [
                        .branch(target: fail, arguments: []),
                    ]
                )
                appendSyntheticBlock(
                    id: rhsEnded,
                    instructions: lhsCleanup + [
                        .branch(target: fail, arguments: []),
                    ]
                )
                appendSyntheticBlock(
                    id: checkRHSTrailing,
                    instructions: [
                        try sequenceNextInstruction(
                            cursor: rhsTraversal.cursor,
                            result: trailingNext,
                            direction: .forward
                        ),
                        .switchOptional(
                            optional: trailingNext,
                            someTarget: rhsTrailing,
                            noneTarget: fail
                        ),
                    ]
                )
                appendSyntheticBlock(
                    id: rhsTrailing,
                    parameters: [trailingElement],
                    instructions: trailingCleanup + [
                        .branch(target: succeed, arguments: []),
                    ]
                )
            }

            appendSyntheticBlock(
                id: succeed,
                instructions: terminalCleanup + [
                    .constantBool(result: trueValue, value: true),
                    .branch(target: completion, arguments: [trueValue]),
                ]
            )
            appendSyntheticBlock(
                id: fail,
                instructions: terminalCleanup + [
                    .constantBool(result: falseValue, value: false),
                    .branch(target: completion, arguments: [falseValue]),
                ]
            )
            retainFlow.activate(completion)
            current = .init(
                id: completion,
                parameters: [result],
                instructions: []
            )
            return result
        }

        func lowerProgressionIteratorNext(
            type: CanonicalSIL.Progression.SequenceType,
            resultAddress: String,
            iteratorAddress: String,
            resultToken: String,
            line: Int
        ) throws {
            let iterator = addressBase(iteratorAddress)
            guard type.supportsIteration,
                  stackType(at: resultAddress) == .optional(type.element),
                  progressionIteratorAddresses[iterator] == type,
                  let state = progressionIteratorStates[iterator],
                  state.type == type
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "progression iterator next types or storage do not match"
                )
            }
            let result = try allocate(type: .optional(type.element))
            appendInstruction(
                .progressionNext(
                    result: result,
                    cursorSlot: state.cursorSlot,
                    end: state.end,
                    stride: state.stride,
                    boundary: type.family.boundary
                )
            )
            try storeConstructedValue(
                result,
                at: resultAddress,
                mode: .initialize
            )
            voidValues.insert(resultToken)
        }

        func roundingOperation(
            for rule: CompilerEnumCase
        ) throws -> Bytecode.FloatUnaryOperation {
            guard rule.typeName == "FloatingPointRoundingRule" else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "rounding operation references an unrelated compiler enum"
                )
            }
            return switch rule.caseName {
            case "down": .roundDown
            case "up": .roundUp
            case "towardZero": .roundTowardZero
            case "awayFromZero": .roundAwayFromZero
            case "toNearestOrAwayFromZero": .roundToNearestOrAwayFromZero
            case "toNearestOrEven": .roundToNearestOrEven
            default:
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "unknown FloatingPointRoundingRule case \(rule.caseName)"
                )
            }
        }

        func emitScalarLiteral(
            _ literal: CanonicalSIL.ScalarIntrinsic.StaticValue.Literal
        ) throws -> Bytecode.Register {
            switch literal {
            case let .integer(type, bitPattern):
                let result = try allocate(type: type)
                appendInstruction(
                    .constantInteger(result: result, bitPattern: bitPattern)
                )
                return result
            case let .floating(type, bitPattern):
                let result = try allocate(type: type)
                appendInstruction(
                    .constantFloat(result: result, bitPattern: bitPattern)
                )
                return result
            case let .boolean(value):
                let result = try allocate(type: .bool)
                appendInstruction(.constantBool(result: result, value: value))
                return result
            }
        }

        func emitFloatingUnary(
            _ operation: Bytecode.FloatUnaryOperation,
            operand: Bytecode.Register
        ) throws -> Bytecode.Register {
            let type = registerTypes[Int(operand.rawValue)]
            guard case .float = type else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "floating scalar operation has a non-floating operand"
                )
            }
            let result = try allocate(type: type)
            appendInstruction(
                .floatingUnary(
                    result: result,
                    operation: operation,
                    operand: operand
                )
            )
            return result
        }

        func emitFloatingBinary(
            _ operation: Bytecode.FloatBinaryOperation,
            lhs: Bytecode.Register,
            rhs: Bytecode.Register
        ) throws -> Bytecode.Register {
            let type = registerTypes[Int(lhs.rawValue)]
            guard case .float = type,
                  registerTypes[Int(rhs.rawValue)] == type
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "floating binary operation does not use one float type"
                )
            }
            let result = try allocate(type: type)
            appendInstruction(
                .floatingBinary(
                    result: result,
                    operation: operation,
                    lhs: lhs,
                    rhs: rhs
                )
            )
            return result
        }

        func emitFloatingIntegerProperty(
            _ operation: Bytecode.FloatIntegerPropertyOperation,
            operand: Bytecode.Register
        ) throws -> Bytecode.Register {
            guard case let .float(width)
                = registerTypes[Int(operand.rawValue)]
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "floating integer property has a non-floating operand"
                )
            }
            let type: Bytecode.ValueType = switch operation {
            case .exponent, .significandWidth: .int64
            case .exponentBitPattern:
                .integer(bitWidth: 64, signed: false)
            case .significandBitPattern:
                .integer(bitWidth: width, signed: false)
            }
            let result = try allocate(type: type)
            appendInstruction(
                .floatingIntegerProperty(
                    result: result,
                    operation: operation,
                    operand: operand
                )
            )
            return result
        }

        func emitScalarBitCast(
            _ operand: Bytecode.Register,
            to type: Bytecode.ValueType
        ) throws -> Bytecode.Register {
            let source = registerTypes[Int(operand.rawValue)]
            switch (source, type) {
            case let (.integer(sourceWidth, _), .float(targetWidth))
            where sourceWidth == targetWidth:
                break
            case let (.float(sourceWidth), .integer(targetWidth, _))
            where sourceWidth == targetWidth:
                break
            default:
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "scalar bit-pattern conversion does not preserve width"
                )
            }
            let result = try allocate(type: type)
            appendInstruction(.scalarBitCast(result: result, operand: operand))
            return result
        }

        func emitIntegerUnary(
            _ operation: Bytecode.IntegerUnaryOperation,
            operand: Bytecode.Register
        ) throws -> Bytecode.Register {
            let type = registerTypes[Int(operand.rawValue)]
            guard case let .integer(width, signed) = type else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "integer scalar operation has a non-integer operand"
                )
            }
            let primitiveType: Bytecode.ValueType = operation == .magnitude
                ? .integer(bitWidth: width, signed: false)
                : type
            if operation == .signum, !signed {
                throw CanonicalSIL.LoweringError.unsupportedType(
                    "unsigned integer signum"
                )
            }
            let primitive = try allocate(type: primitiveType)
            appendInstruction(
                .integerUnary(
                    result: primitive,
                    operation: operation,
                    operand: operand
                )
            )
            guard operation == .nonzeroBitCount
                    || operation == .leadingZeroBitCount
                    || operation == .trailingZeroBitCount
            else { return primitive }
            if primitiveType == .int64 { return primitive }
            let result = try allocate(type: .int64)
            let conversion: Bytecode.IntegerConversionOperation
            if width == 64 {
                conversion = .reinterpret
            } else {
                conversion = signed ? .signExtend : .zeroExtend
            }
            appendInstruction(
                .integerConvert(
                    result: result,
                    operation: conversion,
                    value: primitive
                )
            )
            return result
        }

        func lowerScalarIntrinsic(
            _ intrinsic: CanonicalSIL.ScalarIntrinsic,
            resultToken: String,
            genericArguments: String,
            arguments: [String],
            line: Int
        ) throws {
            switch intrinsic {
            case let .staticValue(property):
                guard let metatype = arguments.last,
                      let receiver = scalarMetatypeValues[metatype],
                      arguments.count == 1 || arguments.count == 2
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "scalar static property has unsupported arguments"
                    )
                }
                if !genericArguments.isEmpty,
                   try parseStoredType(genericArguments) != receiver {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "scalar static property specialization disagrees with its metatype"
                    )
                }
                guard let literal = property.literal(for: receiver) else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "scalar static property \(property) on \(receiver)"
                    )
                }
                let value = try emitScalarLiteral(literal)
                if arguments.count == 2 {
                    guard compilerAddressType(arguments[0])
                            == registerTypes[Int(value.rawValue)]
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "indirect scalar static result has the wrong storage type"
                        )
                    }
                    try storeConstructedValue(
                        value,
                        at: arguments[0],
                        mode: .initialize
                    )
                    voidValues.insert(resultToken)
                } else {
                    values[resultToken] = value
                }

            case let .floatingUnary(operation):
                let operand: Bytecode.Register
                let destination: String?
                if arguments.count == 1, genericArguments.isEmpty {
                    operand = try resolve(arguments[0], line: line)
                    destination = nil
                } else if arguments.count == 2, !genericArguments.isEmpty {
                    let type = try parseStoredType(genericArguments)
                    guard compilerAddressType(arguments[0]) == type,
                          stackType(at: arguments[1]) == type,
                          let stored = try copyStoredValue(
                              at: arguments[1],
                              line: line
                          ),
                          registerTypes[Int(stored.rawValue)] == type
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "indirect floating operation does not match its specialization"
                        )
                    }
                    operand = stored
                    destination = arguments[0]
                } else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "floating scalar operation has unsupported arguments"
                    )
                }
                let result = try emitFloatingUnary(operation, operand: operand)
                if let destination {
                    try storeConstructedValue(
                        result,
                        at: destination,
                        mode: .initialize
                    )
                    voidValues.insert(resultToken)
                } else {
                    values[resultToken] = result
                }

            case let .floatingBinary(operation, form):
                switch form {
                case .instance:
                    guard arguments.count == 3,
                          !genericArguments.isEmpty
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "FloatingPoint binary operation has unsupported arguments"
                        )
                    }
                    let type = try parseStoredType(genericArguments)
                    guard case .float = type,
                          compilerAddressType(arguments[0]) == type,
                          stackType(at: arguments[1]) == type,
                          stackType(at: arguments[2]) == type,
                          let rhs = try copyStoredValue(
                              at: arguments[1],
                              line: line
                          ),
                          let lhs = try copyStoredValue(
                              at: arguments[2],
                              line: line
                          )
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "FloatingPoint binary specialization does not match its storage"
                        )
                    }
                    try storeConstructedValue(
                        try emitFloatingBinary(operation, lhs: lhs, rhs: rhs),
                        at: arguments[0],
                        mode: .initialize
                    )
                    voidValues.insert(resultToken)

                case .mutating:
                    guard genericArguments.isEmpty,
                          arguments.count == 2,
                          let lhs = try copyStoredValue(
                              at: arguments[1],
                              line: line
                          )
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "mutating floating binary operation has unsupported arguments"
                        )
                    }
                    let rhs = try resolve(arguments[0], line: line)
                    try storeConstructedValue(
                        try emitFloatingBinary(operation, lhs: lhs, rhs: rhs),
                        at: arguments[1]
                    )
                    voidValues.insert(resultToken)

                case .staticMember:
                    guard arguments.count == 4,
                          !genericArguments.isEmpty
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "static FloatingPoint binary operation has unsupported arguments"
                        )
                    }
                    let type = try parseStoredType(genericArguments)
                    guard case .float = type,
                          compilerAddressType(arguments[0]) == type,
                          stackType(at: arguments[1]) == type,
                          stackType(at: arguments[2]) == type,
                          scalarMetatypeValues[arguments[3]] == type,
                          let lhs = try copyStoredValue(
                              at: arguments[1],
                              line: line
                          ),
                          let rhs = try copyStoredValue(
                              at: arguments[2],
                              line: line
                          )
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "static FloatingPoint specialization does not match its storage"
                        )
                    }
                    try storeConstructedValue(
                        try emitFloatingBinary(operation, lhs: lhs, rhs: rhs),
                        at: arguments[0],
                        mode: .initialize
                    )
                    voidValues.insert(resultToken)
                }

            case let .floatingPredicate(operation):
                guard genericArguments.isEmpty, arguments.count == 1 else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "floating predicate has unsupported arguments"
                    )
                }
                let operand = try resolve(arguments[0], line: line)
                guard case .float = registerTypes[Int(operand.rawValue)] else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "floating predicate has a non-floating operand"
                    )
                }
                let result = try allocate(type: .bool)
                values[resultToken] = result
                appendInstruction(
                    .floatingPredicate(
                        result: result,
                        operation: operation,
                        operand: operand
                    )
                )

            case let .floatingBinaryPredicate(operation):
                guard arguments.count == 2,
                      !genericArguments.isEmpty
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "floating binary predicate has unsupported arguments"
                    )
                }
                let type = try parseStoredType(genericArguments)
                guard case .float = type,
                      stackType(at: arguments[0]) == type,
                      stackType(at: arguments[1]) == type,
                      let rhs = try copyStoredValue(
                          at: arguments[0],
                          line: line
                      ),
                      let lhs = try copyStoredValue(
                          at: arguments[1],
                          line: line
                      )
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "floating binary predicate specialization does not match its storage"
                    )
                }
                let result = try allocate(type: .bool)
                values[resultToken] = result
                appendInstruction(
                    .floatingBinaryPredicate(
                        result: result,
                        operation: operation,
                        lhs: lhs,
                        rhs: rhs
                    )
                )

            case let .floatingIntegerProperty(operation):
                guard genericArguments.isEmpty,
                      arguments.count == 1
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "floating integer property has unsupported arguments"
                    )
                }
                values[resultToken] = try emitFloatingIntegerProperty(
                    operation,
                    operand: resolve(arguments[0], line: line)
                )

            case let .floatingBitPattern(direction):
                guard genericArguments.isEmpty else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "floating bit-pattern operation cannot be generic"
                    )
                }
                switch direction {
                case .extract:
                    guard arguments.count == 1 else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "floating bit-pattern getter has unsupported arguments"
                        )
                    }
                    let operand = try resolve(arguments[0], line: line)
                    guard case let .float(width)
                        = registerTypes[Int(operand.rawValue)]
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "floating bit-pattern getter has a non-floating receiver"
                        )
                    }
                    values[resultToken] = try emitScalarBitCast(
                        operand,
                        to: .integer(bitWidth: width, signed: false)
                    )
                case .initialize:
                    guard arguments.count == 2,
                          let type = scalarMetatypeValues[arguments[1]],
                          case let .float(width) = type
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "floating bit-pattern initializer has unsupported arguments"
                        )
                    }
                    let operand = try resolve(arguments[0], line: line)
                    guard registerTypes[Int(operand.rawValue)]
                            == .integer(bitWidth: width, signed: false)
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "floating bit-pattern initializer has a mismatched integer"
                        )
                    }
                    values[resultToken] = try emitScalarBitCast(
                        operand,
                        to: type
                    )
                }

            case .floatingSign:
                guard genericArguments.isEmpty, arguments.count == 1 else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "floating sign getter has unsupported arguments"
                    )
                }
                let operand = try resolve(arguments[0], line: line)
                guard case .float = registerTypes[Int(operand.rawValue)] else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "floating sign getter has a non-floating operand"
                    )
                }
                let isMinus = try allocate(type: .bool)
                appendInstruction(
                    .floatingPredicate(
                        result: isMinus,
                        operation: .isSignMinus,
                        operand: operand
                    )
                )
                floatingSignValues[resultToken] = isMinus

            case .floatingRoundDefault:
                guard arguments.count == 2, !genericArguments.isEmpty,
                      let operand = try copyStoredValue(
                          at: arguments[1],
                          line: line
                      )
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "FloatingPoint.rounded() has unsupported arguments"
                    )
                }
                let type = try parseStoredType(genericArguments)
                guard compilerAddressType(arguments[0]) == type,
                      stackType(at: arguments[1]) == type,
                      registerTypes[Int(operand.rawValue)] == type
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "FloatingPoint.rounded() specialization does not match its storage"
                    )
                }
                let result = try emitFloatingUnary(
                    .roundToNearestOrAwayFromZero,
                    operand: operand
                )
                try storeConstructedValue(
                    result,
                    at: arguments[0],
                    mode: .initialize
                )
                voidValues.insert(resultToken)

            case .floatingRoundRule:
                guard arguments.count == 3, !genericArguments.isEmpty,
                      let rule = compilerEnumAddressCases[
                          addressBase(arguments[1])
                      ],
                      let operand = try copyStoredValue(
                          at: arguments[2],
                          line: line
                      )
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "FloatingPoint.rounded(_:) has unsupported arguments"
                    )
                }
                let type = try parseStoredType(genericArguments)
                guard compilerAddressType(arguments[0]) == type,
                      stackType(at: arguments[2]) == type,
                      registerTypes[Int(operand.rawValue)] == type
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "FloatingPoint.rounded(_:) specialization does not match its storage"
                    )
                }
                let result = try emitFloatingUnary(
                    try roundingOperation(for: rule),
                    operand: operand
                )
                try storeConstructedValue(
                    result,
                    at: arguments[0],
                    mode: .initialize
                )
                voidValues.insert(resultToken)

            case .floatingRoundSlowPath:
                guard genericArguments.isEmpty, arguments.count == 2,
                      let rule = compilerEnumAddressCases[
                          addressBase(arguments[0])
                      ],
                      let operand = try copyStoredValue(
                          at: arguments[1],
                          line: line
                      )
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "floating round slow path has unsupported arguments"
                    )
                }
                let result = try emitFloatingUnary(
                    try roundingOperation(for: rule),
                    operand: operand
                )
                try storeConstructedValue(result, at: arguments[1])
                voidValues.insert(resultToken)

            case let .integerUnary(operation):
                if genericArguments.isEmpty, arguments.count == 1 {
                    let operand = try resolve(arguments[0], line: line)
                    values[resultToken] = try emitIntegerUnary(
                        operation,
                        operand: operand
                    )
                } else if !genericArguments.isEmpty,
                          arguments.count == 2 {
                    let type = try parseStoredType(genericArguments)
                    guard case .integer = type,
                          compilerAddressType(arguments[0]) == type,
                          stackType(at: arguments[1]) == type,
                          let operand = try copyStoredValue(
                              at: arguments[1],
                              line: line
                          )
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "generic integer unary specialization does not match its storage"
                        )
                    }
                    try storeConstructedValue(
                        try emitIntegerUnary(operation, operand: operand),
                        at: arguments[0],
                        mode: .initialize
                    )
                    voidValues.insert(resultToken)
                } else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "integer unary operation has unsupported arguments"
                    )
                }

            case .integerIsMultiple:
                guard arguments.count == 2, !genericArguments.isEmpty else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "BinaryInteger.isMultiple(of:) has unsupported arguments"
                    )
                }
                let type = try parseStoredType(genericArguments)
                guard case .integer = type,
                      stackType(at: arguments[0]) == type,
                      stackType(at: arguments[1]) == type,
                      let divisor = try copyStoredValue(
                          at: arguments[0],
                          line: line
                      ),
                      let value = try copyStoredValue(
                          at: arguments[1],
                          line: line
                      )
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "BinaryInteger.isMultiple(of:) specialization does not match its storage"
                    )
                }
                let remainder = try allocate(type: type)
                let overflow = try allocate(type: .bool)
                appendInstruction(
                    .checkedBinary(
                        result: remainder,
                        overflow: overflow,
                        operation: .remainder,
                        lhs: value,
                        rhs: divisor
                    )
                )
                let zero = try allocate(type: type)
                appendInstruction(
                    .constantInteger(result: zero, bitPattern: 0)
                )
                let result = try allocate(type: .bool)
                values[resultToken] = result
                appendInstruction(
                    .compare(
                        result: result,
                        predicate: .equal,
                        lhs: remainder,
                        rhs: zero
                    )
                )

            case .integerQuotientAndRemainder:
                guard arguments.count == 4, !genericArguments.isEmpty else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "BinaryInteger.quotientAndRemainder(dividingBy:) has unsupported arguments"
                    )
                }
                let type = try parseStoredType(genericArguments)
                guard case .integer = type,
                      compilerAddressType(arguments[0]) == type,
                      compilerAddressType(arguments[1]) == type,
                      stackType(at: arguments[2]) == type,
                      stackType(at: arguments[3]) == type,
                      let divisor = try copyStoredValue(
                          at: arguments[2],
                          line: line
                      ),
                      let value = try copyStoredValue(
                          at: arguments[3],
                          line: line
                      )
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "BinaryInteger quotient/remainder specialization does not match its storage"
                    )
                }
                let zero = try allocate(type: type)
                appendInstruction(
                    .constantInteger(result: zero, bitPattern: 0)
                )
                let dividesByZero = try allocate(type: .bool)
                appendInstruction(
                    .compare(
                        result: dividesByZero,
                        predicate: .equal,
                        lhs: divisor,
                        rhs: zero
                    )
                )
                try appendConditionalTrap(
                    condition: dividesByZero,
                    reason: .divisionByZero
                )
                let quotient = try allocate(type: type)
                let quotientOverflow = try allocate(type: .bool)
                appendInstruction(
                    .checkedBinary(
                        result: quotient,
                        overflow: quotientOverflow,
                        operation: .divide,
                        lhs: value,
                        rhs: divisor
                    )
                )
                try appendConditionalTrap(
                    condition: quotientOverflow,
                    reason: .integerOverflow
                )
                let remainder = try allocate(type: type)
                let remainderOverflow = try allocate(type: .bool)
                appendInstruction(
                    .checkedBinary(
                        result: remainder,
                        overflow: remainderOverflow,
                        operation: .remainder,
                        lhs: value,
                        rhs: divisor
                    )
                )
                try appendConditionalTrap(
                    condition: remainderOverflow,
                    reason: .integerOverflow
                )
                try storeConstructedValue(
                    quotient,
                    at: arguments[0],
                    mode: .initialize
                )
                try storeConstructedValue(
                    remainder,
                    at: arguments[1],
                    mode: .initialize
                )
                voidValues.insert(resultToken)

            case let .integerReportingOverflow(operation):
                guard genericArguments.isEmpty, arguments.count == 2 else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "integer reporting-overflow operation has unsupported arguments"
                    )
                }
                let rhs = try resolve(arguments[0], line: line)
                let lhs = try resolve(arguments[1], line: line)
                let type = registerTypes[Int(lhs.rawValue)]
                guard case .integer = type,
                      registerTypes[Int(rhs.rawValue)] == type
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "integer reporting-overflow operands do not match"
                    )
                }
                let partial = try allocate(type: type)
                let overflow = try allocate(type: .bool)
                appendInstruction(
                    .checkedBinary(
                        result: partial,
                        overflow: overflow,
                        operation: operation,
                        lhs: lhs,
                        rhs: rhs
                    )
                )
                let result = try allocate(type: .tuple([type, .bool]))
                values[resultToken] = result
                appendInstruction(
                    .makeTuple(
                        result: result,
                        elements: [partial, overflow]
                    )
                )

            case .integerClampingConversion:
                let specializations = try splitTopLevel(genericArguments)
                    .filter { !$0.isEmpty }
                    .map(parseStoredType)
                guard specializations.count == 2,
                      arguments.count == 3,
                      case .integer = specializations[0],
                      case .integer = specializations[1],
                      compilerAddressType(arguments[0])
                        == specializations[0],
                      stackType(at: arguments[1]) == specializations[1],
                      scalarMetatypeValues[arguments[2]]
                        == specializations[0],
                      let source = try copyStoredValue(
                          at: arguments[1],
                          line: line
                      )
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "clamping integer conversion does not match its specialization"
                    )
                }
                let result = try allocate(type: specializations[0])
                appendInstruction(
                    .integerConvert(
                        result: result,
                        operation: .clamp,
                        value: source
                    )
                )
                try storeConstructedValue(
                    result,
                    at: arguments[0],
                    mode: .initialize
                )
                voidValues.insert(resultToken)

            case .integerFullWidthMultiply:
                guard genericArguments.isEmpty,
                      arguments.count == 2
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "full-width integer multiply has unsupported arguments"
                    )
                }
                let rhs = try resolve(arguments[0], line: line)
                let lhs = try resolve(arguments[1], line: line)
                let type = registerTypes[Int(lhs.rawValue)]
                guard case let .integer(width, _) = type,
                      registerTypes[Int(rhs.rawValue)] == type
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "full-width integer multiply operands do not match"
                    )
                }
                let lowType = Bytecode.ValueType.integer(
                    bitWidth: width,
                    signed: false
                )
                let high = try allocate(type: type)
                let low = try allocate(type: lowType)
                appendInstruction(
                    .integerFullWidthMultiply(
                        high: high,
                        low: low,
                        lhs: lhs,
                        rhs: rhs
                    )
                )
                let result = try allocate(type: .tuple([type, lowType]))
                values[resultToken] = result
                appendInstruction(
                    .makeTuple(result: result, elements: [high, low])
                )

            case .integerFullWidthDivide:
                guard genericArguments.isEmpty,
                      arguments.count == 3
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "full-width integer divide has unsupported arguments"
                    )
                }
                let dividendHigh = try resolve(arguments[0], line: line)
                let dividendLow = try resolve(arguments[1], line: line)
                let divisor = try resolve(arguments[2], line: line)
                let type = registerTypes[Int(divisor.rawValue)]
                guard case let .integer(width, _) = type,
                      registerTypes[Int(dividendHigh.rawValue)] == type,
                      registerTypes[Int(dividendLow.rawValue)]
                        == .integer(bitWidth: width, signed: false)
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "full-width integer divide operands do not match"
                    )
                }
                let quotient = try allocate(type: type)
                let remainder = try allocate(type: type)
                appendInstruction(
                    .integerFullWidthDivide(
                        quotient: quotient,
                        remainder: remainder,
                        dividendHigh: dividendHigh,
                        dividendLow: dividendLow,
                        divisor: divisor
                    )
                )
                let result = try allocate(type: .tuple([type, type]))
                values[resultToken] = result
                appendInstruction(
                    .makeTuple(
                        result: result,
                        elements: [quotient, remainder]
                    )
                )
            }
        }

        func validateCapacity(
            token: String,
            displayName: String,
            line: Int
        ) throws {
            let capacity: Bytecode.Register
            if let stored = try copyStoredValue(
                at: token,
                line: line
            ) {
                capacity = stored
            } else {
                capacity = try resolve(token, line: line)
            }
            guard registerTypes[Int(capacity.rawValue)] == .int64 else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "\(displayName) has unsupported arguments"
                )
            }
            try appendNonnegativePrecondition(
                capacity,
                reason: "\(displayName) must not be negative"
            )
        }

        func lowerCapacityHint(
            capacityToken: String,
            storageToken: String,
            expectedType: Bytecode.ValueType,
            displayName: String,
            resultToken: String,
            line: Int
        ) throws {
            guard compilerAddressType(storageToken) == expectedType else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "\(displayName) storage does not match its specialization"
                )
            }
            try validateCapacity(
                token: capacityToken,
                displayName: displayName,
                line: line
            )
            guard let collection = try borrowStoredValue(
                at: storageToken,
                line: line
            ), registerTypes[Int(collection.register.rawValue)] == expectedType
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "\(displayName) has unsupported arguments"
                )
            }
            if let owner = collection.temporaryOwner {
                appendInstruction(.destroyValue(owner))
            }
            // Capacity is not observable through the supported collection
            // APIs. Validate Swift's precondition while retaining immutable
            // VM value storage.
            voidValues.insert(resultToken)
        }

        func appendNonnegativePrecondition(
            _ value: Bytecode.Register,
            reason: String
        ) throws {
            guard registerTypes[Int(value.rawValue)] == .int64 else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "nonnegative precondition requires Int"
                )
            }
            let zero = try allocate(type: .int64)
            appendInstruction(.constantInteger(result: zero, bitPattern: 0))
            let isNegative = try allocate(type: .bool)
            appendInstruction(
                .compare(
                    result: isNegative,
                    predicate: .lessThan,
                    lhs: value,
                    rhs: zero
                )
            )
            try appendConditionalTrap(
                condition: isNegative,
                reason: .explicit(reason)
            )
        }

        func partialRangeValue(
            at token: String
        ) throws -> CanonicalSIL.RangeExpression.PartialValue {
            let address = addressBase(token)
            if let value = partialRangeAddressValues[address] {
                guard partialRangeAddresses[address] == value.shape else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "partial range storage has a mismatched value"
                    )
                }
                return value
            }
            guard let value = partialRangeValues[token] else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "partial range operand is not initialized"
                )
            }
            return value
        }

        func clearPartialRangeBoundProjections(root: String) {
            let projections = partialRangeBoundProjectionRoots.compactMap {
                projection, candidate in
                candidate == root ? projection : nil
            }
            for projection in projections {
                partialRangeBoundProjectionRoots.removeValue(
                    forKey: projection
                )
                stackAddressTypes.removeValue(forKey: projection)
                stackAddressValues.removeValue(forKey: projection)
            }
        }

        func clearProgressionBoundProjections(root: String) {
            let projections = progressionBoundProjectionRoots.compactMap {
                projection, candidate in
                candidate == root ? projection : nil
            }
            for projection in projections {
                progressionBoundProjectionRoots.removeValue(
                    forKey: projection
                )
                stackAddressTypes.removeValue(forKey: projection)
                stackAddressValues.removeValue(forKey: projection)
            }
        }

        func emitBoundedRangeContainment(
            _ range: CanonicalSIL.Progression.Value,
            candidate: Bytecode.Register
        ) throws -> Bytecode.Register {
            let element = range.type.element
            guard range.type.family == .range
                    || range.type.family == .closedRange,
                  element.isVMComparable,
                  registerTypes[Int(candidate.rawValue)] == element,
                  registerTypes[Int(range.start.rawValue)] == element,
                  registerTypes[Int(range.end.rawValue)] == element
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "bounded RangeExpression operands do not match"
                )
            }
            let meetsLower = try allocate(type: .bool)
            appendInstruction(
                .compare(
                    result: meetsLower,
                    predicate: .lessThanOrEqual,
                    lhs: range.start,
                    rhs: candidate
                )
            )
            let meetsUpper = try allocate(type: .bool)
            appendInstruction(
                .compare(
                    result: meetsUpper,
                    predicate: range.type.family == .closedRange
                        ? .lessThanOrEqual
                        : .lessThan,
                    lhs: candidate,
                    rhs: range.end
                )
            )
            let result = try allocate(type: .bool)
            appendInstruction(
                .booleanBinary(
                    result: result,
                    operation: .and,
                    lhs: meetsLower,
                    rhs: meetsUpper
                )
            )
            return result
        }

        func emitPartialRangeContainment(
            _ range: CanonicalSIL.RangeExpression.PartialValue,
            candidate: Bytecode.Register
        ) throws -> Bytecode.Register {
            let boundType = range.shape.boundType
            guard boundType.isVMComparable,
                  registerTypes[Int(range.bound.rawValue)] == boundType,
                  registerTypes[Int(candidate.rawValue)] == boundType
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "partial RangeExpression operands do not match"
                )
            }
            let comparison = range.shape.boundary.containmentComparison
            func operand(
                _ source: CanonicalSIL.RangeExpression.ComparisonOperand
            ) -> Bytecode.Register {
                switch source {
                case .bound: range.bound
                case .candidate: candidate
                }
            }
            let result = try allocate(type: .bool)
            appendInstruction(
                .compare(
                    result: result,
                    predicate: comparison.predicate,
                    lhs: operand(comparison.lhs),
                    rhs: operand(comparison.rhs)
                )
            )
            return result
        }

        func lowerCollectionIntrinsic(
            _ intrinsic: CanonicalSIL.CollectionIntrinsic,
            resultToken: String,
            genericArguments: String,
            arguments: [String],
            line: Int
        ) throws {
            func trivialOperand(
                _ token: String,
                as expected: Bytecode.ValueType
            ) throws -> Bytecode.Register {
                guard expected.isTrivial else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "nontrivial collection operand requires an explicit borrow or ownership transfer"
                    )
                }
                let value = if let stored = try copyStoredValue(
                    at: token,
                    line: line
                ) {
                    stored
                } else {
                    try resolve(token, line: line)
                }
                guard registerTypes[Int(value.rawValue)] == expected else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "collection operand does not match its specialization"
                    )
                }
                return value
            }

            func ownedOperand(
                _ token: String,
                as expected: Bytecode.ValueType,
                context: String
            ) throws -> Bytecode.Register {
                let value = try materializeOwnedValue(at: token, line: line)
                guard registerTypes[Int(value.rawValue)] == expected else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "\(context) operand does not match its specialization"
                    )
                }
                return value
            }

            func borrowOperand(
                _ token: String,
                as expected: Bytecode.ValueType,
                context: String
            ) throws -> BorrowedStoredValue {
                let borrowed = try borrowStoredValue(at: token, line: line)
                    ?? .init(
                        register: try resolve(token, line: line),
                        temporaryOwner: nil
                    )
                guard registerTypes[Int(borrowed.register.rawValue)]
                        == expected
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "\(context) operand does not match its specialization"
                    )
                }
                return borrowed
            }

            func validateOperandType(
                _ token: String,
                as expected: Bytecode.ValueType,
                context: String
            ) throws {
                if let stored = stackType(at: token) {
                    guard stored == expected else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "\(context) operand does not match its specialization"
                        )
                    }
                    return
                }
                let value = try resolve(token, line: line)
                guard registerTypes[Int(value.rawValue)] == expected else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "\(context) operand does not match its specialization"
                    )
                }
            }

            func destroyBorrowedOwners(
                _ operands: [BorrowedStoredValue]
            ) {
                var destroyed = Set<Bytecode.Register>()
                for owner in operands.compactMap(\.temporaryOwner)
                where destroyed.insert(owner).inserted {
                    appendInstruction(.destroyValue(owner))
                }
            }

            func emitArrayCount(
                _ array: Bytecode.Register
            ) throws -> Bytecode.Register {
                guard case .array = registerTypes[Int(array.rawValue)] else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Array index operation has a non-Array operand"
                    )
                }
                let count = try allocate(type: .int64)
                appendInstruction(.arrayCount(result: count, array: array))
                return count
            }

            func emitArrayIndexBase(
                _ array: Bytecode.Register
            ) throws -> Bytecode.Register {
                guard case .array = registerTypes[Int(array.rawValue)] else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Collection index operation has a non-Array-backed operand"
                    )
                }
                let base = try allocate(type: .int64)
                appendInstruction(.arrayIndexBase(result: base, array: array))
                return base
            }

            func emitArrayEndIndex(
                _ array: Bytecode.Register
            ) throws -> Bytecode.Register {
                try emitCheckedIndexArithmetic(
                    .add,
                    emitArrayIndexBase(array),
                    emitArrayCount(array)
                )
            }

            func emitCheckedIndexArithmetic(
                _ operation: Bytecode.BinaryOperation,
                _ lhs: Bytecode.Register,
                _ rhs: Bytecode.Register
            ) throws -> Bytecode.Register {
                let result = try allocate(type: .int64)
                let overflow = try allocate(type: .bool)
                appendInstruction(
                    .checkedBinary(
                        result: result,
                        overflow: overflow,
                        operation: operation,
                        lhs: lhs,
                        rhs: rhs
                    )
                )
                try appendConditionalTrap(
                    condition: overflow,
                    reason: .integerOverflow
                )
                return result
            }

            func emitArraySubsequence(
                source: CanonicalSIL.SequenceSpecialization,
                sourceToken: String,
                operation: Bytecode.ArraySubsequenceOperation,
                bound: Bytecode.Register,
                destination: String
            ) throws {
                let resultType = Bytecode.ValueType.array(source.element)
                guard compilerAddressType(destination) == resultType else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "collection subsequence output does not match Element"
                    )
                }
                let materialized = try materializeSequenceOperand(
                    source,
                    token: sourceToken,
                    context: "collection subsequence",
                    line: line
                )
                let result = try allocate(type: resultType)
                appendInstruction(
                    .arraySubsequence(
                        result: result,
                        operation: operation,
                        array: materialized.array,
                        bound: bound
                    )
                )
                for instruction in materialized.cleanup {
                    appendInstruction(instruction)
                }
                try storeConstructedValue(
                    result,
                    at: destination,
                    mode: .initialize
                )
                voidValues.insert(resultToken)
            }

            /// Moves one integer Range boundary toward the opposite boundary
            /// by at most `count` elements. Narrow integers use Int64 working
            /// arithmetic; UInt64 reinterprets the already-proven nonnegative
            /// count. This keeps the operation constant-time without ever
            /// narrowing the complete Range cardinality to Int.
            func clampedIntegerRangeBoundary(
                from initial: Bytecode.Register,
                toward limit: Bytecode.Register,
                count: Bytecode.Register,
                direction: Bytecode.CollectionTraversalDirection
            ) throws -> Bytecode.Register {
                let element = registerTypes[Int(initial.rawValue)]
                guard case let .integer(width, signed) = element,
                      registerTypes[Int(limit.rawValue)] == element,
                      registerTypes[Int(count.rawValue)] == .int64
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "integer Range subsequence boundaries do not match"
                    )
                }
                try appendNonnegativePrecondition(
                    count,
                    reason: "collection subsequence count must not be negative"
                )

                let workingType: Bytecode.ValueType = width < 64 || signed
                    ? .int64
                    : .integer(bitWidth: 64, signed: false)
                func convert(
                    _ value: Bytecode.Register,
                    to type: Bytecode.ValueType,
                    operation: Bytecode.IntegerConversionOperation
                ) throws -> Bytecode.Register {
                    guard registerTypes[Int(value.rawValue)] != type else {
                        return value
                    }
                    let converted = try allocate(type: type)
                    appendInstruction(
                        .integerConvert(
                            result: converted,
                            operation: operation,
                            value: value
                        )
                    )
                    return converted
                }

                let widening: Bytecode.IntegerConversionOperation = signed
                    ? .signExtend : .zeroExtend
                let workingInitial = try convert(
                    initial,
                    to: workingType,
                    operation: width < 64 ? widening : .reinterpret
                )
                let workingLimit = try convert(
                    limit,
                    to: workingType,
                    operation: width < 64 ? widening : .reinterpret
                )
                let workingCount = try convert(
                    count,
                    to: workingType,
                    operation: .reinterpret
                )
                let candidate = try allocate(type: workingType)
                let overflow = try allocate(type: .bool)
                appendInstruction(
                    .checkedBinary(
                        result: candidate,
                        overflow: overflow,
                        operation: direction == .forward ? .add : .subtract,
                        lhs: workingInitial,
                        rhs: workingCount
                    )
                )
                let crossesLimit = try allocate(type: .bool)
                appendInstruction(
                    .compare(
                        result: crossesLimit,
                        predicate: direction == .forward
                            ? .greaterThan : .lessThan,
                        lhs: candidate,
                        rhs: workingLimit
                    )
                )
                let clampsToLimit = try allocate(type: .bool)
                appendInstruction(
                    .booleanBinary(
                        result: clampsToLimit,
                        operation: .or,
                        lhs: overflow,
                        rhs: crossesLimit
                    )
                )
                let selected = try allocate(type: workingType)
                appendInstruction(
                    .select(
                        result: selected,
                        condition: clampsToLimit,
                        trueValue: workingLimit,
                        falseValue: candidate
                    )
                )
                return try convert(
                    selected,
                    to: element,
                    operation: .clamp
                )
            }

            switch intrinsic {
            case let .query(query):
                let queryPlan = try parseCollectionQuerySpecialization(
                    query.source,
                    genericArguments: genericArguments
                )
                let specialization = queryPlan.source
                let result: Bytecode.Register
                switch query.operation {
                case .count:
                    guard arguments.count == 1 else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Collection count query has unsupported arguments"
                        )
                    }
                    result = try lowerSequenceCount(
                        specialization,
                        sourceToken: arguments[0],
                        line: line
                    )
                    values[resultToken] = result

                case .underestimatedCount:
                    guard arguments.count == 1 else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Collection underestimatedCount query has unsupported arguments"
                        )
                    }
                    if queryPlan.underestimatedCountIsExact {
                        result = try lowerSequenceCount(
                            specialization,
                            sourceToken: arguments[0],
                            line: line
                        )
                    } else {
                        result = try allocate(type: .int64)
                        appendInstruction(
                            .constantInteger(result: result, bitPattern: 0)
                        )
                    }
                    values[resultToken] = result

                case .isEmpty:
                    guard arguments.count == 1 else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Collection.isEmpty has unsupported arguments"
                        )
                    }
                    result = try lowerSequenceIsEmpty(
                        specialization,
                        sourceToken: arguments[0],
                        line: line
                    )
                    values[resultToken] = result

                case .first, .last:
                    let resultType = Bytecode.ValueType.optional(
                        specialization.element
                    )
                    guard arguments.count == 2,
                          compilerAddressType(arguments[0]) == resultType
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Collection boundary query has unsupported arguments"
                        )
                    }
                    result = try query.operation == .first
                        ? lowerSequenceFirst(
                            specialization,
                            sourceToken: arguments[1],
                            line: line
                        )
                        : lowerSequenceLast(
                            specialization,
                            sourceToken: arguments[1],
                            line: line
                        )
                    try storeConstructedValue(
                        result,
                        at: arguments[0],
                        mode: .initialize
                    )
                    voidValues.insert(resultToken)
                }

            case let .equality(container):
                guard arguments.count == 3 else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "collection equality has unsupported arguments"
                    )
                }
                let type: Bytecode.ValueType
                switch container {
                case .array:
                    let element = try parseStoredType(genericArguments)
                    guard element.isVMEquatable,
                          arrayMetatypeValues[arguments[2]] == element
                    else {
                        throw CanonicalSIL.LoweringError.unsupportedType(
                            "Array equality element \(element)"
                        )
                    }
                    type = .array(element)
                case .dictionary:
                    let types = try parseDictionaryGenericArguments(
                        genericArguments
                    )
                    guard types.key.isVMHashable,
                          types.value.isVMEquatable,
                          dictionaryMetatypeValues[arguments[2]]?.0
                            == types.key,
                          dictionaryMetatypeValues[arguments[2]]?.1
                            == types.value
                    else {
                        throw CanonicalSIL.LoweringError.unsupportedType(
                            "Dictionary equality specialization"
                        )
                    }
                    type = .dictionary(
                        key: types.key,
                        value: types.value
                    )
                }
                let lhs = try borrowOperand(
                    arguments[0],
                    as: type,
                    context: "collection equality"
                )
                let rhs = try borrowOperand(
                    arguments[1],
                    as: type,
                    context: "collection equality"
                )
                let result = try allocate(type: .bool)
                values[resultToken] = result
                appendInstruction(
                    .compare(
                        result: result,
                        predicate: .equal,
                        lhs: lhs.register,
                        rhs: rhs.register
                    )
                )
                destroyBorrowedOwners([lhs, rhs])

            case let .search(operation):
                guard arguments.count == 3 else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Collection index search has unsupported arguments"
                    )
                }
                let specializations = splitTopLevel(genericArguments)
                    .filter { !$0.isEmpty }
                guard specializations.count == 1 else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Collection index search has an incomplete specialization"
                    )
                }
                let collection = try parseType(specializations[0])
                guard case let .array(element) = collection,
                      typeEnvironment.collectionIndexModel(
                        for: specializations[0]
                      ) != .opaque,
                      element.isVMEquatable,
                      compilerAddressType(arguments[0]) == .optional(.int64),
                      stackType(at: arguments[1]) == element,
                      stackType(at: arguments[2]) == collection
                else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "Collection index search specialization \(collection)"
                    )
                }
                let needle = try borrowOperand(
                    arguments[1],
                    as: element,
                    context: "Collection index search"
                )
                let array = try borrowOperand(
                    arguments[2],
                    as: collection,
                    context: "Collection index search"
                )
                let result = try allocate(type: .optional(.int64))
                appendInstruction(
                    .arraySearch(
                        result: result,
                        operation: operation,
                        array: array.register,
                        value: needle.register
                    )
                )
                destroyBorrowedOwners([needle, array])
                try storeConstructedValue(
                    result,
                    at: arguments[0],
                    mode: .initialize
                )
                voidValues.insert(resultToken)

            case let .extremum(operation):
                guard arguments.count == 2 else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Sequence extremum has unsupported arguments"
                    )
                }
                let sequence = try parseSequenceSpecialization(
                    genericArguments,
                    context: "Sequence extremum"
                )
                let element = sequence.element
                guard element.isVMComparable,
                      compilerAddressType(arguments[0]) == .optional(element)
                else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "Sequence extremum specialization \(sequence)"
                    )
                }
                let result = try lowerNaturalSequenceExtremum(
                    operation,
                    specialization: sequence,
                    sourceToken: arguments[1],
                    line: line
                )
                try storeConstructedValue(
                    result,
                    at: arguments[0],
                    mode: .initialize
                )
                voidValues.insert(resultToken)

            case let .relation(operation):
                let specializationSpellings = splitTopLevel(genericArguments)
                    .filter { !$0.isEmpty }
                let specializations = try specializationSpellings.map {
                    try parseSequenceSpecialization(
                        $0,
                        context: "Sequence relation"
                    )
                }
                guard specializations.count == 2,
                      arguments.count == 2,
                      specializations[0].element == specializations[1].element
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Sequence relation has unsupported specializations"
                    )
                }
                let element = specializations[0].element
                let supportsElementOperation = switch operation {
                case .elementsEqual, .startsWith: element.isVMEquatable
                case .lexicographicallyPrecedes: element.isVMComparable
                }
                guard supportsElementOperation else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "Sequence relation element \(element)"
                    )
                }
                values[resultToken] = try lowerSequenceRelation(
                    operation,
                    lhs: specializations[0],
                    lhsToken: arguments[1],
                    rhs: specializations[1],
                    rhsToken: arguments[0],
                    line: line
                )

            case let .adapter(.transform(operation)):
                guard arguments.count == 2 else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "collection adapter has unsupported arguments"
                    )
                }
                let source = try parseSequenceSpecialization(
                    genericArguments,
                    context: "collection adapter"
                )
                let element = source.element
                let resultType: Bytecode.ValueType
                switch operation {
                case .reversed:
                    if case let .managedCollection(sourceType, _) = source,
                       sourceType != .array(element) {
                        throw CanonicalSIL.LoweringError.unsupportedType(
                            "reversed requires a represented bidirectional Collection"
                        )
                    }
                    resultType = .array(element)
                case .enumerated:
                    resultType = .array(.tuple([.int64, element]))
                }
                guard compilerAddressType(arguments[0]) == resultType else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "collection adapter storage does not match its specialization"
                    )
                }
                let materialized = try materializeSequenceOperand(
                    source,
                    token: arguments[1],
                    context: "collection adapter",
                    line: line
                )
                let result = try allocate(type: resultType)
                appendInstruction(
                    .arrayAdapter(
                        result: result,
                        operation: operation,
                        array: materialized.array
                    )
                )
                for instruction in materialized.cleanup {
                    appendInstruction(instruction)
                }
                try storeConstructedValue(
                    result,
                    at: arguments[0],
                    mode: .initialize
                )
                voidValues.insert(resultToken)

            case .adapter(.arrayFromSequence):
                let specializations = splitTopLevel(genericArguments)
                    .filter { !$0.isEmpty }
                guard specializations.count == 2, arguments.count == 2 else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Array sequence initializer specialization does not match"
                    )
                }
                let resultElement = try parseStoredType(specializations[0])
                let sourceSpecialization = try parseSequenceSpecialization(
                    specializations[1],
                    context: "Array sequence initializer"
                )
                guard resultElement == sourceSpecialization.element,
                      arrayMetatypeValues[arguments[1]] == resultElement
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Array sequence initializer Element does not match"
                    )
                }
                switch sourceSpecialization {
                case .stringCharacters:
                    guard stackType(at: arguments[0]) == .string else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Array sequence initializer String storage does not match"
                        )
                    }
                    let materialized = try materializeSequenceOperand(
                        sourceSpecialization,
                        token: arguments[0],
                        context: "Array sequence initializer",
                        line: line
                    )
                    values[resultToken] = materialized.array
                    for instruction in materialized.cleanup {
                        appendInstruction(instruction)
                    }

                case let .managedCollection(sourceType, _):
                    guard stackType(at: arguments[0]) == sourceType else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Array sequence initializer storage does not match"
                        )
                    }
                    let source = try ownedOperand(
                        arguments[0],
                        as: sourceType,
                        context: "Array sequence initializer"
                    )
                    let materialized = try materializeManagedCollectionElements(
                        source,
                        sourceType: sourceType,
                        context: "Array sequence initializer"
                    )
                    let zero = try allocate(type: .int64)
                    appendInstruction(
                        .constantInteger(result: zero, bitPattern: 0)
                    )
                    let result = try allocate(
                        type: .array(resultElement)
                    )
                    appendInstruction(
                        .arrayRebase(
                            result: result,
                            array: materialized.array,
                            indexBase: zero
                        )
                    )
                    if requiresManagedOwnership(sourceType),
                       source != materialized.array {
                        appendInstruction(.destroyValue(source))
                    }
                    // Array.init always establishes Array's zero-based index
                    // identity, even when its source is an ArraySlice or a
                    // normalized Slice whose runtime storage carries a base.
                    values[resultToken] = result

                case let .progression(type):
                    let progression = try progressionOperand(
                        arguments[0],
                        expected: type,
                        line: line
                    )
                    values[resultToken] = try materializeProgressionElements(
                        progression,
                        line: line
                    )
                }

            case let .adapter(.arrayRepeat(hasMetatype)):
                guard arguments.count == 3 else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "repeated collection has unsupported arguments"
                    )
                }
                let element = try parseStoredType(genericArguments)
                let valueIndex = hasMetatype ? 0 : 1
                let countIndex = hasMetatype ? 1 : 2
                if hasMetatype,
                   arrayMetatypeValues[arguments[2]] != element {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Array(repeating:) metatype does not match Element"
                    )
                }
                let value = try borrowOperand(
                    arguments[valueIndex],
                    as: element,
                    context: "repeated collection"
                )
                let count = try trivialOperand(
                    arguments[countIndex],
                    as: .int64
                )
                let result = try allocate(type: .array(element))
                appendInstruction(
                    .arrayRepeat(
                        result: result,
                        value: value.register,
                        count: count
                    )
                )
                destroyBorrowedOwners([value])
                if hasMetatype {
                    values[resultToken] = result
                } else {
                    guard compilerAddressType(arguments[0]) == .array(element)
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "repeatElement output does not match Element"
                        )
                    }
                    try storeConstructedValue(
                        result,
                        at: arguments[0],
                        mode: .initialize
                    )
                    voidValues.insert(resultToken)
                }

            case .adapter(.sliceFromBounds):
                let specializations = splitTopLevel(genericArguments)
                    .filter { !$0.isEmpty }
                guard specializations.count == 1, arguments.count == 4 else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Slice.init(base:bounds:) has unsupported arguments"
                    )
                }
                let baseSpelling = specializations[0]
                let sliceSpelling = "Slice<\(baseSpelling)>"
                let source = try parseSequenceSpecialization(
                    baseSpelling,
                    context: "Slice.init(base:bounds:)"
                )
                let resultType = Bytecode.ValueType.array(source.element)
                guard typeEnvironment.collectionIndexModel(
                        for: sliceSpelling
                      ) != .opaque,
                      source.managedCollectionType == resultType,
                      compilerAddressType(arguments[0]) == resultType,
                      representedCollectionMetatypeIdentities[arguments[3]]
                        == CanonicalSIL.SwiftTypeIdentity.normalized(
                            sliceSpelling
                        )
                else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "Slice.init(base:bounds:) requires an Array-backed Base with represented integer indices"
                    )
                }
                let range = try progressionOperand(
                    arguments[2],
                    expected: .init(family: .range, element: .int64),
                    line: line
                )
                let materialized = try materializeSequenceOperand(
                    source,
                    token: arguments[1],
                    context: "Slice.init(base:bounds:)",
                    line: line
                )
                let result = try allocate(type: resultType)
                appendInstruction(
                    .arrayRangeSlice(
                        result: result,
                        array: materialized.array,
                        lowerBound: range.start,
                        upperBound: range.end
                    )
                )
                for instruction in materialized.cleanup {
                    appendInstruction(instruction)
                }
                try storeConstructedValue(
                    result,
                    at: arguments[0],
                    mode: .initialize
                )
                voidValues.insert(resultToken)

            case let .adapter(.subsequence(operation)):
                guard arguments.count == 3 else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "collection subsequence has unsupported arguments"
                    )
                }
                let source = try parseSequenceSpecialization(
                    genericArguments,
                    context: "collection subsequence"
                )
                if case let .progression(type) = source {
                    guard type.family == .range,
                          case .integer = type.element,
                          [.dropFirst, .dropLast, .prefix, .suffix]
                            .contains(operation),
                          arguments.count == 3
                    else {
                        throw CanonicalSIL.LoweringError.unsupportedType(
                            "collection subsequence specialization \(genericArguments)"
                        )
                    }
                    let output = addressBase(arguments[0])
                    guard progressionAddresses[output] == type else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Range subsequence output does not match its specialization"
                        )
                    }
                    let count = try trivialOperand(arguments[1], as: .int64)
                    let value = try progressionOperand(
                        arguments[2],
                        expected: type,
                        line: line
                    )
                    let movesForward = operation == .dropFirst
                        || operation == .prefix
                    let boundary = try clampedIntegerRangeBoundary(
                        from: movesForward ? value.start : value.end,
                        toward: movesForward ? value.end : value.start,
                        count: count,
                        direction: movesForward ? .forward : .reverse
                    )
                    let replacesLowerBound = operation == .dropFirst
                        || operation == .suffix
                    progressionAddressValues[output] = .init(
                        type: type,
                        start: replacesLowerBound ? boundary : value.start,
                        end: replacesLowerBound ? value.end : boundary,
                        stride: nil
                    )
                    retiredProgressionAddresses.remove(output)
                    voidValues.insert(resultToken)
                    return
                }
                let indexModel = typeEnvironment.collectionIndexModel(
                    for: genericArguments
                )
                let usesConcreteIndex = switch operation {
                case .prefixUpTo, .prefixThrough, .suffixFrom: true
                case .dropFirst, .dropLast, .prefix, .suffix: false
                }
                guard source.normalizedCollectionType
                        == .array(source.element),
                      !usesConcreteIndex || (
                          indexModel != .opaque
                            && source.managedCollectionType
                                == .array(source.element)
                      )
                else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "collection subsequence specialization \(genericArguments)"
                    )
                }
                let bound = try trivialOperand(arguments[1], as: .int64)
                try emitArraySubsequence(
                    source: source,
                    sourceToken: arguments[2],
                    operation: operation,
                    bound: bound,
                    destination: arguments[0]
                )

            case .adapter(.rangeSlice):
                guard arguments.count == 2 else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Array range subscript has unsupported arguments"
                    )
                }
                let element = try parseStoredType(genericArguments)
                guard let range = progressionValues[arguments[0]],
                      range.type == .init(family: .range, element: .int64),
                      range.stride == nil
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Array range subscript requires Range<Int>"
                    )
                }
                let source = try borrowOperand(
                    arguments[1],
                    as: .array(element),
                    context: "Array range slice"
                )
                let result = try allocate(type: .array(element))
                appendInstruction(
                    .arrayRangeSlice(
                        result: result,
                        array: source.register,
                        lowerBound: range.start,
                        upperBound: range.end
                    )
                )
                destroyBorrowedOwners([source])
                if !hasFutureSemanticUse(
                    of: arguments[0],
                    after: currentSILLineIndex
                ) {
                    progressionValues.removeValue(forKey: arguments[0])
                }
                values[resultToken] = result

            case .adapter(.rangeExpressionSlice):
                let specializations = splitTopLevel(genericArguments)
                    .filter { !$0.isEmpty }
                guard specializations.count == 2 else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "RangeExpression collection subscript requires Collection and RangeExpression specializations, got \(genericArguments)"
                    )
                }
                guard arguments.count == 3 else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "RangeExpression collection subscript has unsupported arguments"
                    )
                }
                guard let rangeShape = try CanonicalSIL.RangeExpression
                    .parseCollectionSlice(
                        specializations[1],
                        resolve: parseStoredType
                    )
                else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "range expression \(specializations[1])"
                    )
                }
                let source = try parseSequenceSpecialization(
                    specializations[0],
                    context: "RangeExpression collection subscript"
                )
                guard typeEnvironment.collectionIndexModel(
                        for: specializations[0]
                      ) != .opaque,
                      source.managedCollectionType == .array(source.element),
                      rangeShape.boundIdentity == "Int",
                      rangeShape.boundType == .int64
                else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "RangeExpression collection subscript \(genericArguments)"
                    )
                }
                switch rangeShape.boundary {
                case let .partial(boundary):
                    let range = try partialRangeValue(at: arguments[1])
                    guard range.shape.boundary == boundary else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "partial range value does not match its specialization"
                        )
                    }
                    try emitArraySubsequence(
                        source: source,
                        sourceToken: arguments[2],
                        operation: boundary.subsequenceOperation,
                        bound: range.bound,
                        destination: arguments[0]
                    )
                    if partialRangeValues[arguments[1]] != nil,
                       !hasFutureSemanticUse(
                           of: arguments[1],
                           after: currentSILLineIndex
                       ) {
                        partialRangeValues.removeValue(forKey: arguments[1])
                    }

                case .halfOpen, .closed:
                    let family: CanonicalSIL.Progression.Family =
                        rangeShape.boundary == .halfOpen
                        ? .range : .closedRange
                    let expected = CanonicalSIL.Progression.SequenceType(
                        family: family,
                        element: .int64
                    )
                    let range = try progressionOperand(
                        arguments[1],
                        expected: expected,
                        line: line
                    )
                    let upperBound: Bytecode.Register
                    if rangeShape.boundary == .closed {
                        let one = try allocate(type: .int64)
                        appendInstruction(
                            .constantInteger(result: one, bitPattern: 1)
                        )
                        upperBound = try emitCheckedIndexArithmetic(
                            .add,
                            range.end,
                            one
                        )
                    } else {
                        upperBound = range.end
                    }
                    let array = try borrowOperand(
                        arguments[2],
                        as: .array(source.element),
                        context: "RangeExpression collection subscript"
                    )
                    let result = try allocate(type: .array(source.element))
                    appendInstruction(
                        .arrayRangeSlice(
                            result: result,
                            array: array.register,
                            lowerBound: range.start,
                            upperBound: upperBound
                        )
                    )
                    destroyBorrowedOwners([array])
                    try storeConstructedValue(
                        result,
                        at: arguments[0],
                        mode: .initialize
                    )
                    if progressionValues[arguments[1]] != nil,
                       !hasFutureSemanticUse(
                           of: arguments[1],
                           after: currentSILLineIndex
                       ) {
                        progressionValues.removeValue(forKey: arguments[1])
                    }
                    voidValues.insert(resultToken)
                }

            case .adapter(.fullRangeSlice):
                let source = try parseSequenceSpecialization(
                    genericArguments,
                    context: "full-range subscript"
                )
                let resultType = Bytecode.ValueType.array(source.element)
                guard arguments.count == 3,
                      source.normalizedCollectionType == resultType,
                      unboundedRangeClosureValues.contains(arguments[1]),
                      compilerAddressType(arguments[0]) == resultType
                else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "full-range subscript \(genericArguments)"
                    )
                }
                let materialized = try materializeSequenceOperand(
                    source,
                    token: arguments[2],
                    context: "full-range subscript",
                    line: line
                )
                let result = try allocate(type: resultType)
                appendInstruction(
                    .copyValue(result: result, source: materialized.array)
                )
                for instruction in materialized.cleanup {
                    appendInstruction(instruction)
                }
                try storeConstructedValue(
                    result,
                    at: arguments[0],
                    mode: .initialize
                )
                voidValues.insert(resultToken)
                if !hasFutureSemanticUse(
                    of: arguments[1],
                    after: currentSILLineIndex
                ) {
                    unboundedRangeClosureValues.remove(arguments[1])
                }

            case .adapter(.zip):
                let sequenceSpellings = splitTopLevel(genericArguments)
                    .filter { !$0.isEmpty }
                guard sequenceSpellings.count == 2, arguments.count == 3 else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "zip requires two supported sequence specializations"
                    )
                }
                let sequences = try sequenceSpellings.map {
                    try parseSequenceSpecialization(
                        $0,
                        context: "zip"
                    )
                }
                let lhsElement = sequences[0].element
                let rhsElement = sequences[1].element
                let resultType: Bytecode.ValueType = .array(
                    .tuple([lhsElement, rhsElement])
                )
                guard compilerAddressType(arguments[0]) == resultType else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "zip storage does not match its sequence elements"
                    )
                }
                let lhs = try materializeSequenceOperand(
                    sequences[0],
                    token: arguments[1],
                    context: "zip lhs",
                    line: line
                )
                let rhs = try materializeSequenceOperand(
                    sequences[1],
                    token: arguments[2],
                    context: "zip rhs",
                    line: line
                )
                let result = try allocate(type: resultType)
                appendInstruction(
                    .arrayZip(result: result, lhs: lhs.array, rhs: rhs.array)
                )
                for instruction in lhs.cleanup + rhs.cleanup {
                    appendInstruction(instruction)
                }
                try storeConstructedValue(
                    result,
                    at: arguments[0],
                    mode: .initialize
                )
                voidValues.insert(resultToken)

            case let .adapter(.joined(hasSeparator)):
                let sequences = try splitTopLevel(genericArguments)
                    .filter { !$0.isEmpty }
                    .map(parseType)
                let expectedSpecializations = hasSeparator ? 2 : 1
                let expectedArguments = hasSeparator ? 3 : 2
                guard sequences.count == expectedSpecializations,
                      arguments.count == expectedArguments,
                      case let .array(.array(element)) = sequences[0]
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "joined requires an Array-backed nested sequence"
                    )
                }
                let resultType: Bytecode.ValueType = .array(element)
                let sourceIndex = hasSeparator ? 2 : 1
                guard compilerAddressType(arguments[0]) == resultType,
                      stackType(at: arguments[sourceIndex]) == sequences[0]
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "joined storage does not match its nested sequence"
                    )
                }
                let separator: BorrowedStoredValue?
                if hasSeparator {
                    guard sequences[1] == resultType,
                          stackType(at: arguments[1]) == resultType
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "joined separator does not match nested Element"
                        )
                    }
                    separator = try borrowOperand(
                        arguments[1],
                        as: resultType,
                        context: "joined separator"
                    )
                } else {
                    separator = nil
                }
                let source = try borrowOperand(
                    arguments[sourceIndex],
                    as: sequences[0],
                    context: "joined source"
                )
                let result = try allocate(type: resultType)
                appendInstruction(
                    .arrayJoined(
                        result: result,
                        arrays: source.register,
                        separator: separator?.register
                    )
                )
                destroyBorrowedOwners(
                    separator.map { [source, $0] } ?? [source]
                )
                try storeConstructedValue(
                    result,
                    at: arguments[0],
                    mode: .initialize
                )
                voidValues.insert(resultToken)

            case let .collectionIndex(intrinsic):
                let collection: Bytecode.ValueType
                let indexModel: CanonicalSIL.CollectionIndex.Model
                switch intrinsic.source {
                case .arrayElement:
                    collection = .array(
                        try parseStoredType(genericArguments)
                    )
                    indexModel = .zeroBasedInteger
                case .arraySliceElement:
                    collection = .array(
                        try parseStoredType(genericArguments)
                    )
                    indexModel = .preservedBaseInteger
                case .sliceBase:
                    let specializations = splitTopLevel(genericArguments)
                        .filter { !$0.isEmpty }
                    guard specializations.count == 1 else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Slice index operation has an incomplete Base specialization"
                        )
                    }
                    let slice = "Slice<\(specializations[0])>"
                    collection = try parseType(slice)
                    indexModel = typeEnvironment.collectionIndexModel(
                        for: slice
                    )
                case .genericCollection:
                    let specializations = splitTopLevel(genericArguments)
                        .filter { !$0.isEmpty }
                    guard specializations.count == 1 else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Collection index operation has an incomplete specialization"
                        )
                    }
                    collection = try parseType(specializations[0])
                    indexModel = typeEnvironment.collectionIndexModel(
                        for: specializations[0]
                    )
                }
                guard case .array = collection, indexModel != .opaque else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "Collection index operation requires a represented integer index for \(genericArguments)"
                    )
                }
                let returnsIndexIndirectly = intrinsic.returnsIndexIndirectly

                func input(_ directPosition: Int) -> String {
                    arguments[
                        directPosition + (returnsIndexIndirectly ? 1 : 0)
                    ]
                }

                func publish(
                    _ result: Bytecode.Register,
                    as resultType: Bytecode.ValueType
                ) throws {
                    if returnsIndexIndirectly {
                        guard compilerAddressType(arguments[0]) == resultType
                        else {
                            throw CanonicalSIL.LoweringError.malformedSIL(
                                "Slice index output does not match its Index type"
                            )
                        }
                        try storeConstructedValue(
                            result,
                            at: arguments[0],
                            mode: .initialize
                        )
                        voidValues.insert(resultToken)
                    } else {
                        values[resultToken] = result
                    }
                }

                func predicate(
                    _ comparison: Bytecode.ComparisonPredicate,
                    _ lhs: Bytecode.Register,
                    _ rhs: Bytecode.Register
                ) throws -> Bytecode.Register {
                    let result = try allocate(type: .bool)
                    appendInstruction(
                        .compare(
                            result: result,
                            predicate: comparison,
                            lhs: lhs,
                            rhs: rhs
                        )
                    )
                    return result
                }

                func boolean(
                    _ operation: Bytecode.BooleanBinaryOperation,
                    _ lhs: Bytecode.Register,
                    _ rhs: Bytecode.Register
                ) throws -> Bytecode.Register {
                    let result = try allocate(type: .bool)
                    appendInstruction(
                        .booleanBinary(
                            result: result,
                            operation: operation,
                            lhs: lhs,
                            rhs: rhs
                        )
                    )
                    return result
                }

                func negated(
                    _ operand: Bytecode.Register
                ) throws -> Bytecode.Register {
                    let trueValue = try allocate(type: .bool)
                    appendInstruction(
                        .constantBool(result: trueValue, value: true)
                    )
                    return try boolean(.xor, operand, trueValue)
                }

                func outOfBounds(
                    _ index: Bytecode.Register,
                    in array: Bytecode.Register,
                    allowsEnd: Bool
                ) throws -> Bytecode.Register {
                    let base = try emitArrayIndexBase(array)
                    let end = try emitArrayEndIndex(array)
                    let belowStart = try predicate(.lessThan, index, base)
                    let aboveEnd = try predicate(
                        allowsEnd ? .greaterThan : .greaterThanOrEqual,
                        index,
                        end
                    )
                    return try boolean(.or, belowStart, aboveEnd)
                }

                func validateIndex(
                    _ index: Bytecode.Register,
                    in array: Bytecode.Register,
                    allowsEnd: Bool
                ) throws {
                    try appendConditionalTrap(
                        condition: outOfBounds(
                            index,
                            in: array,
                            allowsEnd: allowsEnd
                        ),
                        reason: .explicit("Collection index is out of bounds")
                    )
                }

                switch intrinsic.operation {
                case .start, .end:
                    guard arguments.count
                            == (returnsIndexIndirectly ? 2 : 1)
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Collection boundary index has unsupported arguments"
                        )
                    }
                    let array = try borrowOperand(
                        input(0),
                        as: collection,
                        context: "Collection boundary index"
                    )
                    let result = intrinsic.operation == .start
                        ? try emitArrayIndexBase(array.register)
                        : try emitArrayEndIndex(array.register)
                    destroyBorrowedOwners([array])
                    try publish(result, as: .int64)

                case .distance:
                    guard arguments.count
                            == 3 + (returnsIndexIndirectly ? 1 : 0)
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Collection distance has unsupported arguments"
                        )
                    }
                    let from = try trivialOperand(input(0), as: .int64)
                    let to = try trivialOperand(input(1), as: .int64)
                    let array = try borrowOperand(
                        input(2),
                        as: collection,
                        context: "Collection distance"
                    )
                    try validateIndex(from, in: array.register, allowsEnd: true)
                    try validateIndex(to, in: array.register, allowsEnd: true)
                    let result = try emitCheckedIndexArithmetic(
                        .subtract,
                        to,
                        from
                    )
                    destroyBorrowedOwners([array])
                    try publish(result, as: .int64)

                case .indices:
                    guard arguments.count == 2 else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Collection.indices has unsupported arguments"
                        )
                    }
                    let output = addressBase(arguments[0])
                    let range = CanonicalSIL.Progression.SequenceType(
                        family: .range,
                        element: .int64
                    )
                    guard progressionAddresses[output] == range else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Collection.indices storage does not match Range<Int>"
                        )
                    }
                    let array = try borrowOperand(
                        arguments[1],
                        as: collection,
                        context: "Collection.indices"
                    )
                    progressionAddressValues[output] = .init(
                        type: range,
                        start: try emitArrayIndexBase(array.register),
                        end: try emitArrayEndIndex(array.register),
                        stride: nil
                    )
                    retiredProgressionAddresses.remove(output)
                    destroyBorrowedOwners([array])
                    voidValues.insert(resultToken)

                case .after, .before, .formAfter, .formBefore:
                    let mutatesIndex = intrinsic.operation == .formAfter
                        || intrinsic.operation == .formBefore
                    let movesForward = intrinsic.operation == .after
                        || intrinsic.operation == .formAfter
                    guard arguments.count
                            == 2 + (returnsIndexIndirectly ? 1 : 0)
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Collection index movement has unsupported arguments"
                        )
                    }
                    let index = try trivialOperand(input(0), as: .int64)
                    let array = try borrowOperand(
                        input(1),
                        as: collection,
                        context: "Collection index movement"
                    )
                    if movesForward {
                        try validateIndex(
                            index,
                            in: array.register,
                            allowsEnd: false
                        )
                    } else {
                        try validateIndex(
                            index,
                            in: array.register,
                            allowsEnd: true
                        )
                        let atOrBeforeStart = try predicate(
                            .lessThanOrEqual,
                            index,
                            emitArrayIndexBase(array.register)
                        )
                        try appendConditionalTrap(
                            condition: atOrBeforeStart,
                            reason: .explicit(
                                "Collection index(before:) precedes startIndex"
                            )
                        )
                    }
                    let one = try allocate(type: .int64)
                    appendInstruction(
                        .constantInteger(result: one, bitPattern: 1)
                    )
                    let result = try emitCheckedIndexArithmetic(
                        movesForward ? .add : .subtract,
                        index,
                        one
                    )
                    destroyBorrowedOwners([array])
                    if mutatesIndex {
                        try storeConstructedValue(
                            result,
                            at: input(0),
                            mode: .assign
                        )
                        voidValues.insert(resultToken)
                    } else {
                        try publish(result, as: .int64)
                    }

                case .offsetBy, .offsetByLimited, .formOffsetBy,
                     .formOffsetByLimited:
                    let mutatesIndex = intrinsic.operation == .formOffsetBy
                        || intrinsic.operation == .formOffsetByLimited
                    let isLimited = intrinsic.operation == .offsetByLimited
                        || intrinsic.operation == .formOffsetByLimited
                    let directArgumentCount = isLimited ? 4 : 3
                    guard arguments.count == directArgumentCount
                        + (returnsIndexIndirectly ? 1 : 0)
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Collection offset index has unsupported arguments"
                        )
                    }
                    let index = try trivialOperand(input(0), as: .int64)
                    let distance = try trivialOperand(input(1), as: .int64)
                    let array = try borrowOperand(
                        input(isLimited ? 3 : 2),
                        as: collection,
                        context: "Collection offset index"
                    )
                    try validateIndex(
                        index,
                        in: array.register,
                        allowsEnd: true
                    )
                    guard isLimited else {
                        let destination = try emitCheckedIndexArithmetic(
                            .add,
                            index,
                            distance
                        )
                        try validateIndex(
                            destination,
                            in: array.register,
                            allowsEnd: true
                        )
                        destroyBorrowedOwners([array])
                        if mutatesIndex {
                            try storeConstructedValue(
                                destination,
                                at: input(0),
                                mode: .assign
                            )
                            voidValues.insert(resultToken)
                        } else {
                            try publish(destination, as: .int64)
                        }
                        break
                    }

                    let limit = try trivialOperand(input(2), as: .int64)
                    try validateIndex(
                        limit,
                        in: array.register,
                        allowsEnd: true
                    )
                    let destination = try allocate(type: .int64)
                    let overflow = try allocate(type: .bool)
                    appendInstruction(
                        .checkedBinary(
                            result: destination,
                            overflow: overflow,
                            operation: .add,
                            lhs: index,
                            rhs: distance
                        )
                    )
                    let zero = try allocate(type: .int64)
                    appendInstruction(
                        .constantInteger(result: zero, bitPattern: 0)
                    )

                    // A limit constrains movement only when it lies in the
                    // requested direction from the starting index.
                    let movingForward = try predicate(
                        .greaterThan,
                        distance,
                        zero
                    )
                    let forwardLimitApplies = try boolean(
                        .and,
                        movingForward,
                        predicate(.greaterThanOrEqual, limit, index)
                    )
                    let positiveExceeded = try boolean(
                        .and,
                        forwardLimitApplies,
                        boolean(
                            .or,
                            overflow,
                            predicate(.greaterThan, destination, limit)
                        )
                    )
                    let movingBackward = try predicate(
                        .lessThan,
                        distance,
                        zero
                    )
                    let backwardLimitApplies = try boolean(
                        .and,
                        movingBackward,
                        predicate(.lessThanOrEqual, limit, index)
                    )
                    let negativeExceeded = try boolean(
                        .and,
                        backwardLimitApplies,
                        boolean(
                            .or,
                            overflow,
                            predicate(.lessThan, destination, limit)
                        )
                    )
                    let limitApplies = try boolean(
                        .or,
                        forwardLimitApplies,
                        backwardLimitApplies
                    )
                    try appendConditionalTrap(
                        condition: boolean(
                            .and,
                            overflow,
                            negated(limitApplies)
                        ),
                        reason: .integerOverflow
                    )
                    let exceeded = try boolean(
                        .or,
                        positiveExceeded,
                        negativeExceeded
                    )
                    try appendConditionalTrap(
                        condition: boolean(
                            .and,
                            outOfBounds(
                                destination,
                                in: array.register,
                                allowsEnd: true
                            ),
                            negated(exceeded)
                        ),
                        reason: .explicit("Collection index is out of bounds")
                    )
                    if mutatesIndex {
                        let updated = try allocate(type: .int64)
                        appendInstruction(
                            .select(
                                result: updated,
                                condition: exceeded,
                                trueValue: limit,
                                falseValue: destination
                            )
                        )
                        let succeeded = try negated(exceeded)
                        destroyBorrowedOwners([array])
                        try storeConstructedValue(
                            updated,
                            at: input(0),
                            mode: .assign
                        )
                        values[resultToken] = succeeded
                        break
                    }

                    let some = try allocate(type: .optional(.int64))
                    appendInstruction(
                        .makeOptionalSome(result: some, value: destination)
                    )
                    let none = try allocate(type: .optional(.int64))
                    appendInstruction(.makeOptionalNone(result: none))
                    let result = try allocate(type: .optional(.int64))
                    appendInstruction(
                        .select(
                            result: result,
                            condition: exceeded,
                            trueValue: none,
                            falseValue: some
                        )
                    )
                    destroyBorrowedOwners([array])
                    try publish(result, as: .optional(.int64))
                }

            case let .rangeReplaceableEdit(edit):
                let context = "RangeReplaceableCollection edit"
                let destinationPlan = try
                    parseRangeReplaceableCollectionRepresentation(
                        destination: edit.destination,
                        genericArguments: genericArguments,
                        context: context
                    )
                let representation = destinationPlan.representation
                let storageType = representation.storageType
                let element = representation.element
                let elementsType = representation.elementsType

                func integerConstant(
                    _ bitPattern: UInt64
                ) throws -> Bytecode.Register {
                    let result = try allocate(type: .int64)
                    appendInstruction(
                        .constantInteger(
                            result: result,
                            bitPattern: bitPattern
                        )
                    )
                    return result
                }

                func destroyManagedTemporary(_ value: Bytecode.Register) {
                    if requiresManagedOwnership(
                        registerTypes[Int(value.rawValue)]
                    ) {
                        appendInstruction(.destroyValue(value))
                    }
                }

                func replace(
                    _ elements: Bytecode.Register,
                    from lowerBound: Bytecode.Register,
                    to upperBound: Bytecode.Register,
                    with replacement: Bytecode.Register
                ) throws -> Bytecode.Register {
                    let result = try allocate(type: elementsType)
                    appendInstruction(
                        .arrayReplaceSubrange(
                            result: result,
                            array: elements,
                            lowerBound: lowerBound,
                            upperBound: upperBound,
                            replacement: replacement
                        )
                    )
                    return result
                }

                switch edit.operation {
                case .removeFirst, .removeLast:
                    guard arguments.count == 2,
                          compilerAddressType(arguments[0]) == element
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "RangeReplaceableCollection element removal has unsupported arguments"
                        )
                    }
                    let destination = try materializeRangeReplaceableElements(
                        representation,
                        token: arguments[1],
                        context: context,
                        line: line
                    )
                    let index: Bytecode.Register
                    if edit.operation == .removeFirst {
                        index = try emitArrayIndexBase(destination.elements)
                    } else {
                        let end = try emitArrayEndIndex(destination.elements)
                        index = try emitCheckedIndexArithmetic(
                            .subtract,
                            end,
                            integerConstant(1)
                        )
                    }
                    let removed = try allocate(type: element)
                    appendInstruction(
                        .arrayGet(
                            result: removed,
                            array: destination.elements,
                            index: index
                        )
                    )
                    let upperBound = try emitCheckedIndexArithmetic(
                        .add,
                        index,
                        integerConstant(1)
                    )
                    let empty = try makeEmptyRangeReplaceableElements(
                        representation
                    )
                    var updatedElements = try replace(
                        destination.elements,
                        from: index,
                        to: upperBound,
                        with: empty
                    )
                    destroyManagedTemporary(empty)
                    if edit.operation == .removeFirst,
                       destinationPlan.indexModel == .preservedBaseInteger {
                        let rebased = try allocate(type: elementsType)
                        appendInstruction(
                            .arrayRebase(
                                result: rebased,
                                array: updatedElements,
                                indexBase: upperBound
                            )
                        )
                        updatedElements = rebased
                    }
                    let updated = try finalizeRangeReplaceableElements(
                        updatedElements,
                        representation: representation,
                        context: context
                    )
                    appendDistinctCleanups([destination.cleanup])
                    try storeConstructedValue(
                        removed,
                        at: arguments[0],
                        mode: .initialize
                    )
                    try storeConstructedValue(
                        updated,
                        at: arguments[1],
                        mode: .assign
                    )
                    voidValues.insert(resultToken)

                case .removeFirstCount, .removeLastCount:
                    guard arguments.count == 2 else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "RangeReplaceableCollection counted removal has unsupported arguments"
                        )
                    }
                    let count = try trivialOperand(arguments[0], as: .int64)
                    try appendNonnegativePrecondition(
                        count,
                        reason: "Collection removal count must not be negative"
                    )
                    let destination = try materializeRangeReplaceableElements(
                        representation,
                        token: arguments[1],
                        context: context,
                        line: line
                    )
                    let start = try emitArrayIndexBase(destination.elements)
                    let end = try emitArrayEndIndex(destination.elements)
                    let lowerBound: Bytecode.Register
                    let upperBound: Bytecode.Register
                    if edit.operation == .removeFirstCount {
                        lowerBound = start
                        upperBound = try emitCheckedIndexArithmetic(
                            .add,
                            start,
                            count
                        )
                    } else {
                        lowerBound = try emitCheckedIndexArithmetic(
                            .subtract,
                            end,
                            count
                        )
                        upperBound = end
                    }
                    let empty = try makeEmptyRangeReplaceableElements(
                        representation
                    )
                    var updatedElements = try replace(
                        destination.elements,
                        from: lowerBound,
                        to: upperBound,
                        with: empty
                    )
                    destroyManagedTemporary(empty)
                    if edit.operation == .removeFirstCount,
                       destinationPlan.indexModel == .preservedBaseInteger {
                        let rebased = try allocate(type: elementsType)
                        appendInstruction(
                            .arrayRebase(
                                result: rebased,
                                array: updatedElements,
                                indexBase: upperBound
                            )
                        )
                        updatedElements = rebased
                    }
                    let updated = try finalizeRangeReplaceableElements(
                        updatedElements,
                        representation: representation,
                        context: context
                    )
                    appendDistinctCleanups([destination.cleanup])
                    try storeConstructedValue(
                        updated,
                        at: arguments[1],
                        mode: .assign
                    )
                    voidValues.insert(resultToken)

                case .popLast:
                    guard arguments.count == 2,
                          compilerAddressType(arguments[0])
                            == .optional(element)
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "RangeReplaceableCollection.popLast has unsupported arguments"
                        )
                    }
                    let destination = try materializeRangeReplaceableElements(
                        representation,
                        token: arguments[1],
                        context: context,
                        line: line
                    )
                    let removed = try allocate(type: .optional(element))
                    let updatedElements = try allocate(type: elementsType)
                    appendInstruction(
                        .arrayPopLast(
                            elementResult: removed,
                            arrayResult: updatedElements,
                            array: destination.elements
                        )
                    )
                    let updated = try finalizeRangeReplaceableElements(
                        updatedElements,
                        representation: representation,
                        context: context
                    )
                    appendDistinctCleanups([destination.cleanup])
                    try storeConstructedValue(
                        removed,
                        at: arguments[0],
                        mode: .initialize
                    )
                    try storeConstructedValue(
                        updated,
                        at: arguments[1],
                        mode: .assign
                    )
                    voidValues.insert(resultToken)

                case .removeAll:
                    guard arguments.count == 2,
                          compilerAddressType(arguments[1]) == storageType
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "RangeReplaceableCollection.removeAll has unsupported arguments"
                        )
                    }
                    let keepingCapacity = try trivialOperand(
                        arguments[0],
                        as: .bool
                    )
                    guard let destination = try borrowStoredValue(
                        at: arguments[1],
                        line: line
                    ), registerTypes[Int(destination.register.rawValue)]
                        == storageType
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "RangeReplaceableCollection.removeAll references uninitialized storage"
                        )
                    }
                    let result: Bytecode.Register
                    if destinationPlan.indexModel == .preservedBaseInteger,
                       case .representedArray = representation {
                        let zero = try integerConstant(0)
                        let preserved = try allocate(type: storageType)
                        appendInstruction(
                            .arraySubsequence(
                                result: preserved,
                                operation: .prefix,
                                array: destination.register,
                                bound: zero
                            )
                        )
                        let reset = try makeEmptyRangeReplaceableStorage(
                            representation
                        )
                        result = try allocate(type: storageType)
                        appendInstruction(
                            .select(
                                result: result,
                                condition: keepingCapacity,
                                trueValue: preserved,
                                falseValue: reset
                            )
                        )
                        destroyManagedTemporary(preserved)
                        destroyManagedTemporary(reset)
                    } else {
                        result = try makeEmptyRangeReplaceableStorage(
                            representation
                        )
                    }
                    if let owner = destination.temporaryOwner {
                        appendInstruction(.destroyValue(owner))
                    }
                    try storeConstructedValue(
                        result,
                        at: arguments[1],
                        mode: .assign
                    )
                    voidValues.insert(resultToken)

                case .reserveCapacity:
                    guard arguments.count == 2 else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "RangeReplaceableCollection.reserveCapacity has unsupported arguments"
                        )
                    }
                    try lowerCapacityHint(
                        capacityToken: arguments[0],
                        storageToken: arguments[1],
                        expectedType: storageType,
                        displayName: "Collection capacity",
                        resultToken: resultToken,
                        line: line
                    )
                }

            case let .rangeReplaceableAppend(append):
                let context = "RangeReplaceableCollection append"
                let plan = try parseRangeReplaceableAppendPlan(
                    append,
                    genericArguments: genericArguments,
                    arguments: arguments,
                    context: context
                )
                if let metatypeToken = plan.metatypeToken {
                    guard representedCollectionMetatypeIdentities[
                        metatypeToken
                    ] == plan.destination.logicalTypeIdentity else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "RangeReplaceableCollection += metatype does not match Self"
                        )
                    }
                }

                let representation = plan.destination.representation
                let storageType = representation.storageType
                let element = representation.element
                let elementsType = representation.elementsType

                switch representation {
                case .stringCharacters:
                    let destination = try borrowOperand(
                        plan.destinationToken,
                        as: storageType,
                        context: context
                    )
                    let suffix: Bytecode.Register
                    var sourceCleanup: [
                        IntermediateRepresentation.Instruction
                    ] = []
                    switch plan.input {
                    case let .element(token):
                        let source = try borrowOperand(
                            token,
                            as: element,
                            context: context
                        )
                        suffix = source.register
                        if let owner = source.temporaryOwner {
                            sourceCleanup.append(.destroyValue(owner))
                        }

                    case let .sequence(token, specialization):
                        if specialization == .stringCharacters {
                            let source = try borrowOperand(
                                token,
                                as: .string,
                                context: context
                            )
                            suffix = source.register
                            if let owner = source.temporaryOwner {
                                sourceCleanup.append(.destroyValue(owner))
                            }
                        } else {
                            let source = try materializeSequenceOperand(
                                specialization,
                                token: token,
                                context: context,
                                line: line
                            )
                            guard registerTypes[Int(source.array.rawValue)]
                                    == elementsType
                            else {
                                throw CanonicalSIL.LoweringError.malformedSIL(
                                    "\(context) source does not match Element"
                                )
                            }
                            suffix = try lowerStringJoin(
                                elements: source.array,
                                separator: nil,
                                elementKind: .character,
                                context: context
                            )
                            sourceCleanup = source.cleanup
                        }
                    }

                    let result = try allocate(type: .string)
                    appendInstruction(
                        .stringConcat(
                            result: result,
                            lhs: destination.register,
                            rhs: suffix
                        )
                    )
                    appendDistinctCleanups([
                        sourceCleanup,
                        destination.temporaryOwner.map {
                            [.destroyValue($0)]
                        } ?? [],
                    ])
                    try storeConstructedValue(
                        result,
                        at: plan.destinationToken,
                        mode: .assign
                    )

                case .representedArray:
                    let destination = try
                        materializeRangeReplaceableElements(
                            representation,
                            token: plan.destinationToken,
                            context: context,
                            line: line
                        )
                    let result: Bytecode.Register
                    var sourceCleanup: [
                        IntermediateRepresentation.Instruction
                    ] = []
                    switch plan.input {
                    case let .element(token):
                        let source = try borrowOperand(
                            token,
                            as: element,
                            context: context
                        )
                        result = try allocate(type: elementsType)
                        appendInstruction(
                            .arrayAppend(
                                result: result,
                                array: destination.elements,
                                value: source.register
                            )
                        )
                        if let owner = source.temporaryOwner {
                            sourceCleanup.append(.destroyValue(owner))
                        }

                    case let .sequence(token, specialization):
                        let source = try materializeSequenceOperand(
                            specialization,
                            token: token,
                            context: context,
                            line: line
                        )
                        guard registerTypes[Int(source.array.rawValue)]
                                == elementsType
                        else {
                            throw CanonicalSIL.LoweringError.malformedSIL(
                                "\(context) source does not match Element"
                            )
                        }
                        let end = try emitArrayEndIndex(destination.elements)
                        result = try allocate(type: elementsType)
                        appendInstruction(
                            .arrayReplaceSubrange(
                                result: result,
                                array: destination.elements,
                                lowerBound: end,
                                upperBound: end,
                                replacement: source.array
                            )
                        )
                        sourceCleanup = source.cleanup
                    }
                    appendDistinctCleanups([
                        sourceCleanup,
                        destination.cleanup,
                    ])
                    try storeConstructedValue(
                        result,
                        at: plan.destinationToken,
                        mode: .assign
                    )
                }
                voidValues.insert(resultToken)

            case let .arrayEdit(operation):
                let specializations = try splitTopLevel(genericArguments)
                    .filter { !$0.isEmpty }
                    .map(parseType)
                let specialization = try operation.resolveSpecialization(
                    specializations
                )
                let arrayType = specialization.array
                let element = specialization.element

                func borrowArray(
                    at token: String
                ) throws -> BorrowedStoredValue {
                    let borrowed: BorrowedStoredValue
                    if let stored = try borrowStoredValue(
                        at: token,
                        line: line
                    ) {
                        borrowed = stored
                    } else {
                        borrowed = .init(
                            register: try resolve(token, line: line),
                            temporaryOwner: nil
                        )
                    }
                    guard registerTypes[Int(borrowed.register.rawValue)]
                            == arrayType
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Array edit operand does not match its specialization"
                        )
                    }
                    return borrowed
                }

                func destroyTemporaryOwners(
                    _ values: [BorrowedStoredValue]
                ) {
                    var destroyed = Set<Bytecode.Register>()
                    for owner in values.compactMap(\.temporaryOwner)
                    where destroyed.insert(owner).inserted {
                        appendInstruction(.destroyValue(owner))
                    }
                }

                func integerConstant(
                    _ bitPattern: UInt64
                ) throws -> Bytecode.Register {
                    let result = try allocate(type: .int64)
                    appendInstruction(
                        .constantInteger(
                            result: result,
                            bitPattern: bitPattern
                        )
                    )
                    return result
                }

                func emptyArray() throws -> Bytecode.Register {
                    let result = try allocate(type: arrayType)
                    appendInstruction(.makeArray(result: result, elements: []))
                    return result
                }

                func replace(
                    _ array: Bytecode.Register,
                    from lowerBound: Bytecode.Register,
                    to upperBound: Bytecode.Register,
                    with replacement: Bytecode.Register
                ) throws -> Bytecode.Register {
                    let result = try allocate(type: arrayType)
                    appendInstruction(
                        .arrayReplaceSubrange(
                            result: result,
                            array: array,
                            lowerBound: lowerBound,
                            upperBound: upperBound,
                            replacement: replacement
                        )
                    )
                    return result
                }

                func destroyManagedTemporary(_ value: Bytecode.Register) {
                    if requiresManagedOwnership(
                        registerTypes[Int(value.rawValue)]
                    ) {
                        appendInstruction(.destroyValue(value))
                    }
                }

                func rangeValue(
                    at token: String
                ) throws -> CanonicalSIL.Progression.Value {
                    let isDirect = progressionValues[token] != nil
                    let value = if let direct = progressionValues[token] {
                        direct
                    } else {
                        try progressionValue(at: token, line: line)
                    }
                    guard value.type == .init(
                        family: .range,
                        element: .int64
                    ), value.stride == nil else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Array range edit requires Range<Int>"
                        )
                    }
                    if isDirect, !hasFutureSemanticUse(
                        of: token,
                        after: currentSILLineIndex
                    ) {
                        progressionValues.removeValue(forKey: token)
                    }
                    return value
                }

                switch operation {
                case .concatenating:
                    guard arguments.count == 3,
                          arrayMetatypeValues[arguments[2]] == element
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Array concatenation has unsupported arguments"
                        )
                    }
                    let lhs = try borrowArray(at: arguments[0])
                    let rhs = try borrowArray(at: arguments[1])
                    let end = try emitArrayCount(lhs.register)
                    let result = try replace(
                        lhs.register,
                        from: end,
                        to: end,
                        with: rhs.register
                    )
                    destroyTemporaryOwners([lhs, rhs])
                    values[resultToken] = result

                case .insertElement:
                    guard arguments.count == 3,
                          compilerAddressType(arguments[2]) == arrayType
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Array.insert has unsupported arguments"
                        )
                    }
                    let value = try materializeOwnedValue(
                        at: arguments[0],
                        line: line
                    )
                    guard registerTypes[Int(value.rawValue)] == element else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Array.insert value does not match Element"
                        )
                    }
                    let singleton = try allocate(type: arrayType)
                    appendInstruction(
                        .makeArray(result: singleton, elements: [value])
                    )
                    let index = try trivialOperand(arguments[1], as: .int64)
                    let destination = try borrowArray(at: arguments[2])
                    let result = try replace(
                        destination.register,
                        from: index,
                        to: index,
                        with: singleton
                    )
                    destroyManagedTemporary(singleton)
                    destroyTemporaryOwners([destination])
                    try storeConstructedValue(
                        result,
                        at: arguments[2],
                        mode: .assign
                    )
                    voidValues.insert(resultToken)

                case .insertContents:
                    guard arguments.count == 3,
                          compilerAddressType(arguments[2]) == arrayType
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "insert(contentsOf:at:) has unsupported arguments"
                        )
                    }
                    let contents = try borrowArray(at: arguments[0])
                    let index = try trivialOperand(arguments[1], as: .int64)
                    let destination = try borrowArray(at: arguments[2])
                    let result = try replace(
                        destination.register,
                        from: index,
                        to: index,
                        with: contents.register
                    )
                    destroyTemporaryOwners([contents, destination])
                    try storeConstructedValue(
                        result,
                        at: arguments[2],
                        mode: .assign
                    )
                    voidValues.insert(resultToken)

                case .replaceSubrange:
                    guard arguments.count == 3,
                          compilerAddressType(arguments[2]) == arrayType
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Array.replaceSubrange has unsupported arguments"
                        )
                    }
                    let bounds = try rangeValue(at: arguments[0])
                    let replacement = try borrowArray(at: arguments[1])
                    let destination = try borrowArray(at: arguments[2])
                    let result = try replace(
                        destination.register,
                        from: bounds.start,
                        to: bounds.end,
                        with: replacement.register
                    )
                    destroyTemporaryOwners([replacement, destination])
                    try storeConstructedValue(
                        result,
                        at: arguments[2],
                        mode: .assign
                    )
                    voidValues.insert(resultToken)

                case .removeAt:
                    guard arguments.count == 3 else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Array element removal has unsupported arguments"
                        )
                    }
                    let outputToken = arguments[0]
                    let destinationToken = arguments[2]
                    guard compilerAddressType(outputToken) == element,
                          compilerAddressType(destinationToken) == arrayType
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Array element removal storage has the wrong type"
                        )
                    }
                    let destination = try borrowArray(at: destinationToken)
                    let index = try trivialOperand(arguments[1], as: .int64)
                    let removed = try allocate(type: element)
                    appendInstruction(
                        .arrayGet(
                            result: removed,
                            array: destination.register,
                            index: index
                        )
                    )
                    let one = try integerConstant(1)
                    let upperBound = try emitCheckedIndexArithmetic(
                        .add,
                        index,
                        one
                    )
                    let empty = try emptyArray()
                    let result = try replace(
                        destination.register,
                        from: index,
                        to: upperBound,
                        with: empty
                    )
                    destroyManagedTemporary(empty)
                    destroyTemporaryOwners([destination])
                    try storeConstructedValue(
                        removed,
                        at: outputToken,
                        mode: .initialize
                    )
                    try storeConstructedValue(
                        result,
                        at: destinationToken,
                        mode: .assign
                    )
                    voidValues.insert(resultToken)

                case .removeSubrange:
                    guard arguments.count == 2,
                          compilerAddressType(arguments[1]) == arrayType
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Array.removeSubrange has unsupported arguments"
                        )
                    }
                    let bounds = try rangeValue(at: arguments[0])
                    let destination = try borrowArray(at: arguments[1])
                    let empty = try emptyArray()
                    let result = try replace(
                        destination.register,
                        from: bounds.start,
                        to: bounds.end,
                        with: empty
                    )
                    destroyManagedTemporary(empty)
                    destroyTemporaryOwners([destination])
                    try storeConstructedValue(
                        result,
                        at: arguments[1],
                        mode: .assign
                    )
                    voidValues.insert(resultToken)

                case .reverse:
                    guard arguments.count == 1,
                          compilerAddressType(arguments[0]) == arrayType
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "MutableCollection.reverse has unsupported arguments"
                        )
                    }
                    let genericSpellings = splitTopLevel(genericArguments)
                        .filter { !$0.isEmpty }
                    guard genericSpellings.count == 1 else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "MutableCollection.reverse has unsupported specializations"
                        )
                    }
                    let indexModel = typeEnvironment.collectionIndexModel(
                        for: genericSpellings[0]
                    )
                    guard indexModel != .opaque else {
                        throw CanonicalSIL.LoweringError.unsupportedType(
                            "reverse requires represented integer indices for "
                                + genericSpellings[0]
                        )
                    }
                    let destination = try borrowArray(at: arguments[0])
                    let reversed = try allocate(type: arrayType)
                    appendInstruction(
                        .arrayAdapter(
                            result: reversed,
                            operation: .reversed,
                            array: destination.register
                        )
                    )
                    let result: Bytecode.Register
                    if indexModel == .preservedBaseInteger {
                        let base = try emitArrayIndexBase(
                            destination.register
                        )
                        result = try allocate(type: arrayType)
                        appendInstruction(
                            .arrayRebase(
                                result: result,
                                array: reversed,
                                indexBase: base
                            )
                        )
                    } else {
                        result = reversed
                    }
                    destroyTemporaryOwners([destination])
                    try storeConstructedValue(
                        result,
                        at: arguments[0],
                        mode: .assign
                    )
                    voidValues.insert(resultToken)

                case .swapAt:
                    guard arguments.count == 3,
                          compilerAddressType(arguments[2]) == arrayType
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Array.swapAt has unsupported arguments"
                        )
                    }
                    let lhsIndex = try trivialOperand(arguments[0], as: .int64)
                    let rhsIndex = try trivialOperand(arguments[1], as: .int64)
                    let destination = try borrowArray(at: arguments[2])
                    let result = try allocate(type: arrayType)
                    appendInstruction(
                        .arraySwap(
                            result: result,
                            array: destination.register,
                            lhsIndex: lhsIndex,
                            rhsIndex: rhsIndex
                        )
                    )
                    destroyTemporaryOwners([destination])
                    try storeConstructedValue(
                        result,
                        at: arguments[2],
                        mode: .assign
                    )
                    voidValues.insert(resultToken)

                }
            }
        }

        /// Selects an existing Dictionary value or evaluates the default
        /// closure lazily. Both the getter and `_modify` coroutine share this
        /// CFG, which keeps autoclosure behavior in ordinary verified closure
        /// control flow and needs no API-specific VM instruction.
        func lowerDictionaryValueOrDefault(
            dictionary: Bytecode.Register,
            key: Bytecode.Register,
            closureToken: String,
            keyType: Bytecode.ValueType,
            valueType: Bytecode.ValueType,
            line: Int
        ) throws -> Bytecode.Register {
            let dictionaryType = Bytecode.ValueType.dictionary(
                key: keyType,
                value: valueType
            )
            let closure = try resolve(closureToken, line: line)
            guard keyType.isVMHashable,
                  registerTypes[Int(dictionary.rawValue)] == dictionaryType,
                  registerTypes[Int(key.rawValue)] == keyType,
                  case let .closure(signature) = registerTypes[
                    Int(closure.rawValue)
                  ], signature.parameters.isEmpty,
                  signature.parameterConventions.isEmpty,
                  signature.result == valueType,
                  !signature.effects.mayThrow,
                  !signature.effects.isAsync
            else {
                throw CanonicalSIL.LoweringError.callSignatureMismatch(
                    line: line,
                    mangledName: "Dictionary.subscript(default:)"
                )
            }

            let lookup = try allocate(type: .optional(valueType))
            let existingTarget = try allocateSyntheticBlockID()
            let defaultTarget = try allocateSyntheticBlockID()
            let mergeTarget = try allocateSyntheticBlockID()
            appendInstruction(
                .dictionaryGet(
                    result: lookup,
                    dictionary: dictionary,
                    key: key
                )
            )
            appendInstruction(
                .switchOptional(
                    optional: lookup,
                    someTarget: existingTarget,
                    noneTarget: defaultTarget
                )
            )
            finishCurrent()

            let existing = try allocate(type: valueType)
            appendSyntheticBlock(
                id: existingTarget,
                parameters: [existing],
                instructions: [
                    .branch(target: mergeTarget, arguments: [existing]),
                ]
            )
            let defaultValue = try allocate(type: valueType)
            appendSyntheticBlock(
                id: defaultTarget,
                instructions: [
                    .closureApply(
                        result: defaultValue,
                        closure: closure,
                        arguments: []
                    ),
                    .branch(target: mergeTarget, arguments: [defaultValue]),
                ]
            )

            let selected = try allocate(type: valueType)
            retainFlow.activate(mergeTarget)
            current = .init(
                id: mergeTarget,
                parameters: [selected],
                instructions: []
            )
            return selected
        }

        /// Completes either the normal or unwind edge of a collection
        /// `_modify` coroutine. The stack slot is path-local at runtime even
        /// though several textual exits share one lowering record.
        func finalizeCollectionElementMutation(
            yieldToken: String,
            line: Int
        ) throws {
            guard let mutation = collectionElementMutations[yieldToken],
                  let access = runtimeAddress(at: yieldToken),
                  isScopedRuntimeAddress(yieldToken),
                  let element = try takeStoredValue(
                    at: yieldToken,
                    line: line
                  ),
                  registerTypes[Int(element.rawValue)] == mutation.elementType
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "collection _modify ended with uninitialized or mismatched element storage"
                )
            }
            appendInstruction(.endAccess(access))

            switch mutation.source {
            case let .array(array, index):
                let updated = try allocate(type: .array(mutation.elementType))
                appendInstruction(
                    .arrayUpdate(
                        result: updated,
                        array: array,
                        index: index,
                        value: element
                    )
                )
                for temporary in [array, element]
                where requiresManagedOwnership(
                    registerTypes[Int(temporary.rawValue)]
                ) {
                    appendInstruction(.destroyValue(temporary))
                }
                try storeConstructedValue(
                    updated,
                    at: mutation.collectionAddress,
                    mode: .assign
                )

            case let .dictionaryDefault(
                dictionary,
                key,
                keyType,
                valueType
            ):
                let update = try allocate(type: .optional(valueType))
                appendInstruction(
                    .makeOptionalSome(result: update, value: element)
                )
                let previous = try allocate(type: .optional(valueType))
                let updated = try allocate(
                    type: .dictionary(key: keyType, value: valueType)
                )
                appendInstruction(
                    .dictionarySet(
                        previousValueResult: previous,
                        dictionaryResult: updated,
                        dictionary: dictionary,
                        key: key,
                        value: update
                    )
                )
                for temporary in [dictionary, key, update, previous]
                where requiresManagedOwnership(
                    registerTypes[Int(temporary.rawValue)]
                ) {
                    appendInstruction(.destroyValue(temporary))
                }
                try storeConstructedValue(
                    updated,
                    at: mutation.collectionAddress,
                    mode: .assign
                )
            }
        }

        func removeCollectionMutationMetadata(yieldToken: String) {
            collectionElementMutations.removeValue(forKey: yieldToken)
            runtimeStackSlots.removeValue(forKey: yieldToken)
            runtimeAddressValues.removeValue(forKey: yieldToken)
            runtimeAddressPointees.removeValue(forKey: yieldToken)
            scopedRuntimeAddresses.remove(yieldToken)
            stackAddressTypes.removeValue(forKey: yieldToken)
            stackAddressValues.removeValue(forKey: yieldToken)
            values.removeValue(forKey: yieldToken)
        }

        func beginCollectionElementMutation(
            yieldToken: String,
            continuationToken: String,
            initialElement: Bytecode.Register,
            mutation: CollectionElementMutation
        ) throws {
            guard registerTypes[Int(initialElement.rawValue)]
                    == mutation.elementType,
                  collectionElementMutations[yieldToken] == nil,
                  collectionMutationYieldByToken[continuationToken] == nil,
                  stackType(at: yieldToken) == nil
            else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "collection _modify has mismatched or overlapping access state"
                )
            }
            let slot = try allocateStackSlot(type: mutation.elementType)
            appendInstruction(
                .storeStack(
                    slot: slot,
                    source: initialElement,
                    mode: .initialize
                )
            )
            let address = try allocate(type: .address(mutation.elementType))
            appendInstruction(.stackAddress(result: address, slot: slot))
            let access = try allocate(type: .address(mutation.elementType))
            appendInstruction(
                .beginAccess(
                    result: access,
                    address: address,
                    kind: .modify
                )
            )

            stackAddressTypes[yieldToken] = mutation.elementType
            runtimeStackSlots[yieldToken] = slot
            runtimeAddressValues[yieldToken] = access
            runtimeAddressPointees[yieldToken] = mutation.elementType
            scopedRuntimeAddresses.insert(yieldToken)
            values[yieldToken] = access
            collectionElementMutations[yieldToken] = mutation
            collectionMutationYieldByToken[continuationToken] = yieldToken
        }

        func lowerSwiftCoreIntrinsic(
            _ intrinsic: SwiftCoreIntrinsic,
            resultToken: String,
            genericArguments: String,
            argumentText: String,
            line: Int
        ) throws {
            let arguments = try parseApplyValueTokens(argumentText, line: line)
            guard !resultToken.isEmpty else {
                throw CanonicalSIL.LoweringError.malformedSIL(
                    "Swift core intrinsic does not define a result"
                )
            }

            func materializeSetOperand(
                _ token: String,
                element expectedElement: Bytecode.ValueType,
                expectedSequence: CanonicalSIL.SequenceSpecialization? = nil
            ) throws -> Bytecode.Register {
                if let expectedSequence {
                    guard expectedSequence.element == expectedElement else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Set Sequence.Element does not match Set.Element"
                        )
                    }
                    let materialized = try materializeSequenceOperand(
                        expectedSequence,
                        token: token,
                        context: "Set Sequence operand",
                        line: line
                    )
                    let result = try allocate(type: .set(expectedElement))
                    appendInstruction(
                        .makeSet(result: result, source: materialized.array)
                    )
                    for instruction in materialized.cleanup {
                        appendInstruction(instruction)
                    }
                    return result
                }
                let source = try materializeOwnedValue(at: token, line: line)
                let sourceType = registerTypes[Int(source.rawValue)]
                switch sourceType {
                case .set(let element) where element == expectedElement:
                    return source
                case .array(let element) where element == expectedElement:
                    let result = try allocate(type: .set(expectedElement))
                    appendInstruction(.makeSet(result: result, source: source))
                    return result
                default:
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "Set operations support Array<Element> and Set<Element> sequences"
                    )
                }
            }

            func makeEmptyDictionary(
                key: Bytecode.ValueType,
                value: Bytecode.ValueType
            ) throws -> Bytecode.Register {
                let pairType = Bytecode.ValueType.tuple([key, value])
                let pairs = try allocate(type: .array(pairType))
                appendInstruction(.makeArray(result: pairs, elements: []))
                let result = try allocate(type: .dictionary(key: key, value: value))
                appendInstruction(.makeDictionary(result: result, pairs: pairs))
                if requiresManagedOwnership(
                    registerTypes[Int(pairs.rawValue)]
                ) {
                    appendInstruction(.destroyValue(pairs))
                }
                return result
            }

            func emitDictionarySet(
                dictionary: Bytecode.Register,
                key: Bytecode.Register,
                update: Bytecode.Register,
                keyType: Bytecode.ValueType,
                valueType: Bytecode.ValueType
            ) throws -> (
                previous: Bytecode.Register,
                updated: Bytecode.Register
            ) {
                let dictionaryType = Bytecode.ValueType.dictionary(
                    key: keyType,
                    value: valueType
                )
                guard registerTypes[Int(dictionary.rawValue)] == dictionaryType,
                      registerTypes[Int(key.rawValue)] == keyType,
                      registerTypes[Int(update.rawValue)] == .optional(valueType)
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Dictionary update operands do not match its specialization"
                    )
                }
                let previous = try allocate(type: .optional(valueType))
                let updated = try allocate(type: dictionaryType)
                appendInstruction(
                    .dictionarySet(
                        previousValueResult: previous,
                        dictionaryResult: updated,
                        dictionary: dictionary,
                        key: key,
                        value: update
                    )
                )
                return (previous, updated)
            }

            func destroyManagedTemporary(_ register: Bytecode.Register) {
                if requiresManagedOwnership(
                    registerTypes[Int(register.rawValue)]
                ) {
                    appendInstruction(.destroyValue(register))
                }
            }

            func lowerRepresentationIdenticalCollectionCast(
                _ cast: CanonicalSIL.ManagedCollectionCastIntrinsic
            ) throws {
                let genericSpellings = splitTopLevel(genericArguments)
                    .filter { !$0.isEmpty }
                let substitutions = try genericSpellings.map(parseStoredType)
                let sourceType: Bytecode.ValueType
                let destinationType: Bytecode.ValueType
                switch cast {
                case .arrayForce:
                    guard substitutions.count == 2 else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Array cast requires source and destination element types"
                        )
                    }
                    sourceType = .array(substitutions[0])
                    destinationType = .array(substitutions[1])
                case .dictionaryUp:
                    guard substitutions.count == 4 else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Dictionary cast requires source and destination key/value types"
                        )
                    }
                    sourceType = .dictionary(
                        key: substitutions[0],
                        value: substitutions[1]
                    )
                    destinationType = .dictionary(
                        key: substitutions[2],
                        value: substitutions[3]
                    )
                }
                guard arguments.count == 1 else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "managed Collection cast has unsupported arguments"
                    )
                }
                guard cast.isTupleLabelErasure(genericSpellings),
                      sourceType == destinationType
                else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "managed Collection cast is not a representation-identical Tuple-label erasure"
                    )
                }
                let result = try materializeOwnedValue(
                    at: arguments[0],
                    line: line
                )
                guard registerTypes[Int(result.rawValue)] == sourceType else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "managed Collection cast operand does not match its specialization"
                    )
                }
                values[resultToken] = result
            }

            func lowerDefaultIntegerParsingRadix() throws {
                let specializations = splitTopLevel(genericArguments)
                    .filter { !$0.isEmpty }
                guard arguments.isEmpty,
                      specializations.count == 2,
                      case .integer = try parseStoredType(specializations[0]),
                      let sourceKind = CanonicalSIL.TextRepresentation.kind(
                          of: specializations[1]
                      ),
                      sourceKind != .character
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "integer parsing default radix has unsupported specializations"
                    )
                }
                let result = try allocate(type: .int64)
                appendInstruction(
                    .constantInteger(result: result, bitPattern: 10)
                )
                values[resultToken] = result
            }

            func lowerDefaultIntegerFormattingCase() throws {
                let specializations = splitTopLevel(genericArguments)
                    .filter { !$0.isEmpty }
                guard arguments.isEmpty,
                      specializations.count == 1,
                      case .integer = try parseStoredType(specializations[0])
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "integer formatting default case has unsupported specializations"
                    )
                }
                let result = try allocate(type: .bool)
                appendInstruction(.constantBool(result: result, value: false))
                values[resultToken] = result
            }

            func lowerIntegerTextFormatting() throws {
                let specializations = splitTopLevel(genericArguments)
                    .filter { !$0.isEmpty }
                guard specializations.count == 1,
                      arguments.count == 4,
                      metatypeValues.contains(arguments[3]),
                      let value = try copyStoredValue(
                          at: arguments[0],
                          line: line
                      )
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "integer text formatting has unsupported arguments"
                    )
                }
                let type = try parseStoredType(specializations[0])
                guard case .integer = type else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "integer text formatting payload \(specializations[0])"
                    )
                }
                let radix = try resolve(arguments[1], line: line)
                let uppercase = try resolve(arguments[2], line: line)
                guard registerTypes[Int(value.rawValue)] == type,
                      registerTypes[Int(radix.rawValue)] == .int64,
                      registerTypes[Int(uppercase.rawValue)] == .bool
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "integer text formatting operands do not match its specialization"
                    )
                }
                let result = try allocate(type: .string)
                appendInstruction(
                    .integerToString(
                        result: result,
                        value: value,
                        radix: radix,
                        uppercase: uppercase
                    )
                )
                values[resultToken] = result
            }

            func lowerScalarTextParsing(
                _ parsing: CanonicalSIL.ScalarTextIntrinsic.Parsing
            ) throws {
                var specializations = ArraySlice(
                    splitTopLevel(genericArguments).filter { !$0.isEmpty }
                )
                let target: Bytecode.ValueType
                switch parsing.target {
                case .genericInteger:
                    guard let spelling = specializations.popFirst() else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "integer text parsing is missing its target specialization"
                        )
                    }
                    target = try parseStoredType(spelling)
                    guard case .integer = target else {
                        throw CanonicalSIL.LoweringError.unsupportedType(
                            "text parsing target \(spelling) is not a represented integer"
                        )
                    }
                case let .fixed(type):
                    target = type
                }

                let sourceKind: CanonicalSIL.TextRepresentation.Kind
                switch parsing.source {
                case .ownedString:
                    sourceKind = .string
                case .ownedSubstring:
                    sourceKind = .substring
                case .stringProtocolAddress:
                    guard let spelling = specializations.popFirst(),
                          let kind = CanonicalSIL.TextRepresentation.kind(
                              of: spelling
                          ),
                          kind != .character
                    else {
                        throw CanonicalSIL.LoweringError.unsupportedType(
                            "scalar text parsing requires represented String or Substring"
                        )
                    }
                    sourceKind = kind
                }
                guard specializations.isEmpty else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "scalar text parsing has unexpected specializations"
                    )
                }

                switch (target, parsing.radix) {
                case (.integer, .decimal), (.integer, .argument),
                     (.bool, .none), (.float, .none):
                    break
                default:
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "scalar text parsing target and radix shape disagree"
                    )
                }

                let expectedArgumentCount = (parsing.hasIndirectResult ? 1 : 0)
                    + 1 + (parsing.radix == .argument ? 1 : 0) + 1
                guard arguments.count == expectedArgumentCount else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "scalar text parsing has unsupported arguments"
                    )
                }
                var argumentIndex = 0
                let destination: String?
                if parsing.hasIndirectResult {
                    destination = arguments[argumentIndex]
                    argumentIndex += 1
                } else {
                    destination = nil
                }
                if let destination,
                   compilerAddressType(destination) != .optional(target) {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "scalar text parsing result address has the wrong type"
                    )
                }

                let sourceToken = arguments[argumentIndex]
                argumentIndex += 1
                let representedSource: Bytecode.Register
                switch parsing.source {
                case .ownedString, .ownedSubstring:
                    representedSource = try materializeOwnedValue(
                        at: sourceToken,
                        line: line
                    )
                case .stringProtocolAddress:
                    guard let copied = try copyStoredValue(
                        at: sourceToken,
                        line: line
                    ) else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "scalar text parsing source address is uninitialized"
                        )
                    }
                    representedSource = copied
                }

                let source: Bytecode.Register
                switch sourceKind {
                case .string:
                    guard registerTypes[Int(representedSource.rawValue)] == .string else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "scalar text parsing String source has the wrong representation"
                        )
                    }
                    source = representedSource
                case .substring:
                    guard registerTypes[Int(representedSource.rawValue)]
                            == .array(.string)
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "scalar text parsing Substring source has the wrong representation"
                        )
                    }
                    source = try lowerStringJoin(
                        elements: representedSource,
                        separator: nil,
                        elementKind: .character,
                        context: "scalar text parsing"
                    )
                case .character:
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Character does not conform to StringProtocol"
                    )
                }

                let radix: Bytecode.Register?
                if parsing.radix == .argument {
                    radix = try resolve(arguments[argumentIndex], line: line)
                    argumentIndex += 1
                } else {
                    radix = nil
                }
                if let radix,
                   registerTypes[Int(radix.rawValue)] != .int64 {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "scalar text parsing radix must be Int"
                    )
                }
                let metatype = arguments[argumentIndex]
                argumentIndex += 1
                guard argumentIndex == arguments.count,
                      scalarMetatypeValues[metatype] == target
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "scalar text parsing metatype does not match its target"
                    )
                }

                let result = try allocate(type: .optional(target))
                appendInstruction(
                    .scalarFromString(
                        result: result,
                        string: source,
                        radix: radix
                    )
                )
                if let destination {
                    try storeConstructedValue(
                        result,
                        at: destination,
                        mode: .initialize
                    )
                    voidValues.insert(resultToken)
                } else {
                    values[resultToken] = result
                }
            }

            func lowerScalarTextIntrinsic(
                _ intrinsic: CanonicalSIL.ScalarTextIntrinsic
            ) throws {
                switch intrinsic {
                case .defaultIntegerRadix:
                    try lowerDefaultIntegerParsingRadix()
                case .defaultUppercase:
                    try lowerDefaultIntegerFormattingCase()
                case .integerToString:
                    try lowerIntegerTextFormatting()
                case let .parse(parsing):
                    try lowerScalarTextParsing(parsing)
                }
            }

            func emitSourceFailure(
                prefix: String,
                detail: Bytecode.Register
            ) throws {
                guard !prefix.isEmpty,
                      try isRepresentedErrorType(
                        registerTypes[Int(detail.rawValue)]
                      )
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Swift source failure has an invalid diagnostic value"
                    )
                }
                // The frontend may route a compiler-inserted semantic trap
                // through the same runtime helper as source-level fatalError.
                // A preceding diagnostic intrinsic is authoritative when it
                // has already classified that trap (for example, force unwrap).
                if let blockID = current?.id,
                   let reason = unreachableTrapReasons.removeValue(
                       forKey: blockID
                   ) {
                    appendInstruction(.trap(reason))
                } else {
                    appendInstruction(
                        .sourceFailure(prefix: prefix, detail: detail)
                    )
                }
                voidValues.insert(resultToken)
                discardsRemainingCurrentSILBlock = true
            }

            func emitStaticSourceFailure(
                prefix: String,
                detail: String
            ) throws {
                guard !prefix.isEmpty, !detail.isEmpty else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Swift static source failure has empty diagnostic metadata"
                    )
                }
                // StaticString forms are emitted by compiler and standard-
                // library checks rather than the public String-autoclosure
                // APIs. Preserve their established semantic trap category.
                appendInstruction(.trap(trapReason(for: detail)))
                voidValues.insert(resultToken)
                discardsRemainingCurrentSILBlock = true
            }

            func lowerSourceFailure(
                _ failure: CanonicalSIL.SourceFailureIntrinsic
            ) throws {
                let uint = Bytecode.ValueType.integer(
                    bitWidth: 64,
                    signed: false
                )
                if failure != .typedUnexpectedError,
                   !genericArguments.isEmpty {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Swift source failure unexpectedly has generic arguments"
                    )
                }

                func hasUnexpectedErrorMetadata() -> Bool {
                    guard arguments.count == 5,
                          let filename = stringLiterals[arguments[1]],
                          let filenameLength = wordLiterals[arguments[2]],
                          let filenameIsASCII = boolLiterals[arguments[3]],
                          let sourceLine = wordLiterals[arguments[4]]
                    else { return false }
                    return UInt64(filename.utf8.count) == filenameLength
                        && filename.utf8.allSatisfy({ $0 < 0x80 })
                            == filenameIsASCII
                        && sourceLine > 0
                }

                switch failure {
                case .runtimeAssertion:
                    guard arguments.count == 5,
                          let prefix = staticStringValues[arguments[0]],
                          !prefix.isEmpty,
                          let detail = values[arguments[1]],
                          registerTypes[Int(detail.rawValue)] == .string,
                          let file = staticStringValues[arguments[2]],
                          !file.isEmpty,
                          let sourceLine = values[arguments[3]],
                          registerTypes[Int(sourceLine.rawValue)] == uint,
                          let flags = values[arguments[4]],
                          registerTypes[Int(flags.rawValue)]
                            == .integer(bitWidth: 32, signed: false)
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Swift runtime assertion has unsupported metadata"
                        )
                    }
                    try emitSourceFailure(prefix: prefix, detail: detail)

                case .runtimeAssertionWithoutLocation:
                    guard arguments.count == 3,
                          let prefix = staticStringValues[arguments[0]],
                          !prefix.isEmpty,
                          let detail = values[arguments[1]],
                          registerTypes[Int(detail.rawValue)] == .string,
                          let flags = values[arguments[2]],
                          registerTypes[Int(flags.rawValue)]
                            == .integer(bitWidth: 32, signed: false)
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Swift runtime assertion has unsupported metadata"
                        )
                    }
                    try emitSourceFailure(prefix: prefix, detail: detail)

                case .runtimeStaticAssertion:
                    guard arguments.count == 5,
                          let prefix = staticStringValues[arguments[0]],
                          let detail = staticStringValues[arguments[1]],
                          let file = staticStringValues[arguments[2]],
                          !file.isEmpty,
                          let sourceLine = values[arguments[3]],
                          registerTypes[Int(sourceLine.rawValue)] == uint,
                          let flags = values[arguments[4]],
                          registerTypes[Int(flags.rawValue)]
                            == .integer(bitWidth: 32, signed: false)
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Swift static runtime assertion has unsupported metadata"
                        )
                    }
                    try emitStaticSourceFailure(
                        prefix: prefix,
                        detail: detail
                    )

                case .debugAssertion:
                    guard arguments.count == 3,
                          let file = staticStringValues[arguments[1]],
                          !file.isEmpty,
                          let sourceLine = values[arguments[2]],
                          registerTypes[Int(sourceLine.rawValue)] == uint
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Swift debug assertion has unsupported metadata"
                        )
                    }
                    let closure = try resolve(arguments[0], line: line)
                    guard case let .closure(signature) = registerTypes[
                        Int(closure.rawValue)
                    ], signature.parameters.isEmpty,
                       signature.parameterConventions.isEmpty,
                       signature.result == .string,
                       !signature.effects.mayThrow,
                       !signature.effects.isAsync
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Swift debug assertion message is not a String autoclosure"
                        )
                    }
                    let detail = try allocate(type: .string)
                    appendInstruction(
                        .closureApply(
                            result: detail,
                            closure: closure,
                            arguments: []
                        )
                    )
                    try emitSourceFailure(
                        prefix: "Assertion failed",
                        detail: detail
                    )

                case .unexpectedError:
                    guard hasUnexpectedErrorMetadata(),
                          let detail = try materializeErrorValue(
                            from: arguments[0]
                          )
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Swift unexpected-error trap has unsupported metadata"
                        )
                    }
                    try emitSourceFailure(
                        prefix: "try! expression unexpectedly raised an error",
                        detail: detail
                    )

                case .typedUnexpectedError:
                    let specializations = splitTopLevel(genericArguments)
                        .filter { !$0.isEmpty }
                    guard specializations.count == 1,
                          hasUnexpectedErrorMetadata()
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Swift typed unexpected-error trap has unsupported metadata"
                        )
                    }
                    let errorType = try parseStoredType(specializations[0])
                    guard try isRepresentedErrorType(errorType),
                          compilerAddressType(arguments[0]) == errorType,
                          let detail = try copyStoredValue(
                            at: arguments[0],
                            line: line
                          ),
                          registerTypes[Int(detail.rawValue)] == errorType
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Swift typed unexpected-error payload does not match its Error type"
                        )
                    }
                    try emitSourceFailure(
                        prefix: "try! expression unexpectedly raised an error",
                        detail: detail
                    )
                }
            }

            func lowerUnsafeOptionalUnwrap() throws {
                let specializations = splitTopLevel(genericArguments)
                    .filter { !$0.isEmpty }
                guard specializations.count == 1,
                      arguments.count == 2
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Optional.unsafelyUnwrapped has unsupported arguments"
                    )
                }
                let wrapped = try parseStoredType(specializations[0])
                guard compilerAddressType(arguments[0]) == wrapped,
                      compilerAddressType(arguments[1]) == .optional(wrapped),
                      let optional = try copyStoredValue(
                        at: arguments[1],
                        line: line
                      ),
                      registerTypes[Int(optional.rawValue)]
                        == .optional(wrapped)
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Optional.unsafelyUnwrapped storage does not match its specialization"
                    )
                }
                let result = try allocate(type: wrapped)
                appendInstruction(
                    .unwrapOptional(result: result, optional: optional)
                )
                try storeConstructedValue(
                    result,
                    at: arguments[0],
                    mode: .initialize
                )
                voidValues.insert(resultToken)
            }

            func lowerValueMutation(
                _ mutation: CanonicalSIL.ValueMutationIntrinsic
            ) throws {
                switch mutation {
                case .logicalToggle:
                    guard genericArguments.isEmpty,
                          arguments.count == 1,
                          compilerAddressType(arguments[0]) == .bool,
                          let currentValue = try copyStoredValue(
                            at: arguments[0],
                            line: line
                          ),
                          registerTypes[Int(currentValue.rawValue)] == .bool
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Bool.toggle has unsupported storage"
                        )
                    }
                    let trueValue = try allocate(type: .bool)
                    appendInstruction(
                        .constantBool(result: trueValue, value: true)
                    )
                    let toggled = try allocate(type: .bool)
                    appendInstruction(
                        .booleanBinary(
                            result: toggled,
                            operation: .xor,
                            lhs: currentValue,
                            rhs: trueValue
                        )
                    )
                    try storeConstructedValue(
                        toggled,
                        at: arguments[0],
                        mode: .assign
                    )

                case .exchange:
                    guard !genericArguments.isEmpty, arguments.count == 2 else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "swap has unsupported arguments"
                        )
                    }
                    let type = try parseStoredType(genericArguments)
                    guard compilerAddressType(arguments[0]) == type,
                          compilerAddressType(arguments[1]) == type
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "swap storage does not match its specialization"
                        )
                    }
                    let firstIdentity = compilerStorageIdentity(
                        for: arguments[0]
                    )
                    let secondIdentity = compilerStorageIdentity(
                        for: arguments[1]
                    )
                    guard !firstIdentity.overlaps(secondIdentity) else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "swap requires non-overlapping storage"
                        )
                    }
                    guard let first = try copyStoredValue(
                        at: arguments[0],
                        line: line
                    ), let second = try copyStoredValue(
                        at: arguments[1],
                        line: line
                    ), registerTypes[Int(first.rawValue)] == type,
                       registerTypes[Int(second.rawValue)] == type
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "swap references uninitialized storage"
                        )
                    }
                    // Both reads precede either write, preserving exchange
                    // semantics for compiler, frame, projected, and cell storage.
                    try storeConstructedValue(
                        second,
                        at: arguments[0],
                        mode: .assign
                    )
                    try storeConstructedValue(
                        first,
                        at: arguments[1],
                        mode: .assign
                    )
                }
                voidValues.insert(resultToken)
            }

            func lowerRange(
                _ operation: CanonicalSIL.RangeIntrinsic
            ) throws {
                guard !genericArguments.isEmpty else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Range operation has no bound specialization"
                    )
                }
                let element = try parseStoredType(genericArguments)
                let type = CanonicalSIL.Progression.SequenceType(
                    family: .range,
                    element: element
                )
                guard element.isVMComparable else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "Range operation bound \(element)"
                    )
                }

                func compare(
                    _ predicate: Bytecode.ComparisonPredicate,
                    _ lhs: Bytecode.Register,
                    _ rhs: Bytecode.Register
                ) throws -> Bytecode.Register {
                    guard registerTypes[Int(lhs.rawValue)] == element,
                          registerTypes[Int(rhs.rawValue)] == element
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Range operation has mismatched bounds"
                        )
                    }
                    let result = try allocate(type: .bool)
                    appendInstruction(
                        .compare(
                            result: result,
                            predicate: predicate,
                            lhs: lhs,
                            rhs: rhs
                        )
                    )
                    return result
                }

                func clamp(
                    _ bound: Bytecode.Register,
                    to limits: CanonicalSIL.Progression.Value
                ) throws -> Bytecode.Register {
                    let below = try compare(.lessThan, bound, limits.start)
                    let lowerBounded = try allocate(type: element)
                    appendInstruction(
                        .select(
                            result: lowerBounded,
                            condition: below,
                            trueValue: limits.start,
                            falseValue: bound
                        )
                    )
                    let above = try compare(.lessThan, limits.end, bound)
                    let result = try allocate(type: element)
                    appendInstruction(
                        .select(
                            result: result,
                            condition: above,
                            trueValue: limits.end,
                            falseValue: lowerBounded
                        )
                    )
                    return result
                }

                switch operation {
                case .overlaps:
                    guard arguments.count == 2 else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Range.overlaps has unsupported arguments"
                        )
                    }
                    let other = try progressionValue(
                        at: arguments[0],
                        line: line
                    )
                    let receiver = try progressionValue(
                        at: arguments[1],
                        line: line
                    )
                    guard other.type == type, receiver.type == type else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Range.overlaps operands do not match its specialization"
                        )
                    }
                    let receiverIsNonempty = try compare(
                        .lessThan,
                        receiver.start,
                        receiver.end
                    )
                    let otherIsNonempty = try compare(
                        .lessThan,
                        other.start,
                        other.end
                    )
                    let receiverStartsBeforeOtherEnds = try compare(
                        .lessThan,
                        receiver.start,
                        other.end
                    )
                    let otherStartsBeforeReceiverEnds = try compare(
                        .lessThan,
                        other.start,
                        receiver.end
                    )
                    let bothNonempty = try allocate(type: .bool)
                    appendInstruction(
                        .booleanBinary(
                            result: bothNonempty,
                            operation: .and,
                            lhs: receiverIsNonempty,
                            rhs: otherIsNonempty
                        )
                    )
                    let boundsIntersect = try allocate(type: .bool)
                    appendInstruction(
                        .booleanBinary(
                            result: boundsIntersect,
                            operation: .and,
                            lhs: receiverStartsBeforeOtherEnds,
                            rhs: otherStartsBeforeReceiverEnds
                        )
                    )
                    let result = try allocate(type: .bool)
                    appendInstruction(
                        .booleanBinary(
                            result: result,
                            operation: .and,
                            lhs: bothNonempty,
                            rhs: boundsIntersect
                        )
                    )
                    values[resultToken] = result

                case .clamped:
                    guard arguments.count == 3 else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Range.clamped(to:) has unsupported arguments"
                        )
                    }
                    let output = addressBase(arguments[0])
                    let limits = try progressionValue(
                        at: arguments[1],
                        line: line
                    )
                    let receiver = try progressionValue(
                        at: arguments[2],
                        line: line
                    )
                    guard progressionAddresses[output] == type,
                          progressionAddressValues[output] == nil,
                          limits.type == type,
                          receiver.type == type
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "Range.clamped(to:) storage does not match its specialization"
                        )
                    }
                    progressionAddressValues[output] = .init(
                        type: type,
                        start: try clamp(receiver.start, to: limits),
                        end: try clamp(receiver.end, to: limits),
                        stride: nil
                    )
                    retiredProgressionAddresses.remove(output)
                    voidValues.insert(resultToken)
                }
            }

            switch intrinsic {
            case let .valueMutation(mutation):
                try lowerValueMutation(mutation)
            case let .range(operation):
                try lowerRange(operation)
            case .defaultValue(.emptyString):
                guard genericArguments.isEmpty, arguments.isEmpty else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Swift empty-String default helper has unexpected arguments"
                    )
                }
                let result = try allocate(type: .string)
                values[resultToken] = result
                appendInstruction(
                    .constantString(result: result, value: "")
                )

            case let .scalar(scalar):
                try lowerScalarIntrinsic(
                    scalar,
                    resultToken: resultToken,
                    genericArguments: genericArguments,
                    arguments: arguments,
                    line: line
                )
            case let .collection(collection):
                try lowerCollectionIntrinsic(
                    collection,
                    resultToken: resultToken,
                    genericArguments: genericArguments,
                    arguments: arguments,
                    line: line
                )
            case let .ordering(operation) where !operation.usesClosure:
                try lowerNaturalSequenceOrdering(
                    operation,
                    resultToken: resultToken,
                    genericArguments: genericArguments,
                    arguments: arguments,
                    line: line
                )
            case let .split(operation) where !operation.usesClosure:
                try lowerSeparatorArraySplit(
                    resultToken: resultToken,
                    genericArguments: genericArguments,
                    argumentText: argumentText,
                    line: line
                )
            case let .managedCollectionCast(cast):
                try lowerRepresentationIdenticalCollectionCast(cast)
            case .higherOrder, .ordering, .arrayPredicateMutation, .split,
                 .algebraic, .dictionaryAccumulation:
                throw CanonicalSIL.LoweringError.unsupportedInstruction(
                    line: line,
                    text: "Swift intrinsic requires control-flow lowering"
                )
            case let .partialRangeConstructor(boundary):
                let boundType = try parseStoredType(genericArguments)
                let shape = CanonicalSIL.RangeExpression.PartialShape(
                    boundary: boundary,
                    boundIdentity: CanonicalSIL.SwiftTypeIdentity.normalized(
                        genericArguments
                    ),
                    boundType: boundType
                )
                guard arguments.count == 3,
                      boundType.isVMComparable,
                      partialRangeMetatypeValues[arguments[2]] == shape
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "partial range constructor has an unsupported specialization"
                    )
                }
                let destination = addressBase(arguments[0])
                guard partialRangeAddresses[destination] == shape,
                      partialRangeAddressValues[destination] == nil,
                      let bound = try copyStoredValue(
                          at: arguments[1],
                          line: line
                      ),
                      registerTypes[Int(bound.rawValue)] == boundType
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "partial range constructor output does not match its metatype"
                    )
                }
                partialRangeAddressValues[destination] = .init(
                    shape: shape,
                    bound: bound
                )
                retiredPartialRangeAddresses.remove(destination)
                voidValues.insert(resultToken)

            case let .progressionConstructor(family):
                guard arguments.count == 4,
                      !genericArguments.isEmpty,
                      family.usesExplicitStride
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "stride constructor has unsupported arguments"
                    )
                }
                let type = CanonicalSIL.Progression.SequenceType(
                    family: family,
                    element: try parseStoredType(genericArguments)
                )
                guard type.supportsIteration,
                      let strideType = type.stride,
                      progressionAddresses[addressBase(arguments[0])] == type,
                      stackType(at: arguments[1]) == type.element,
                      stackType(at: arguments[2]) == type.element,
                      stackType(at: arguments[3]) == strideType,
                      let start = try copyStoredValue(
                          at: arguments[1],
                          line: line
                      ),
                      let end = try copyStoredValue(
                          at: arguments[2],
                          line: line
                      ),
                      let stride = try copyStoredValue(
                          at: arguments[3],
                          line: line
                      ),
                      registerTypes[Int(start.rawValue)] == type.element,
                      registerTypes[Int(end.rawValue)] == type.element,
                      registerTypes[Int(stride.rawValue)] == strideType
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "stride constructor specialization does not match its storage"
                    )
                }
                let zero = try allocate(type: strideType)
                switch strideType {
                case .integer:
                    appendInstruction(
                        .constantInteger(result: zero, bitPattern: 0)
                    )
                case .float:
                    appendInstruction(
                        .constantFloat(result: zero, bitPattern: 0)
                    )
                default:
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "stride distance \(strideType)"
                    )
                }
                let isZero = try allocate(type: .bool)
                appendInstruction(
                    .compare(
                        result: isZero,
                        predicate: .equal,
                        lhs: stride,
                        rhs: zero
                    )
                )
                try appendConditionalTrap(
                    condition: isZero,
                    reason: .explicit("Stride size must not be zero")
                )
                let output = addressBase(arguments[0])
                progressionAddressValues[output] = .init(
                    type: type,
                    start: start,
                    end: end,
                    stride: stride
                )
                retiredProgressionAddresses.remove(output)
                voidValues.insert(resultToken)

            case let .progressionMakeIterator(family):
                guard arguments.count == 2, !genericArguments.isEmpty else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Stride.makeIterator has unsupported arguments"
                    )
                }
                let type = CanonicalSIL.Progression.SequenceType(
                    family: family,
                    element: try parseStoredType(genericArguments)
                )
                try initializeProgressionIterator(
                    type: type,
                    outputAddress: arguments[0],
                    inputAddress: arguments[1],
                    resultToken: resultToken,
                    line: line
                )

            case let .progressionIteratorNext(family):
                guard arguments.count == 2, !genericArguments.isEmpty else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Stride iterator next has unsupported arguments"
                    )
                }
                let type = CanonicalSIL.Progression.SequenceType(
                    family: family,
                    element: try parseStoredType(genericArguments)
                )
                try lowerProgressionIteratorNext(
                    type: type,
                    resultAddress: arguments[0],
                    iteratorAddress: arguments[1],
                    resultToken: resultToken,
                    line: line
                )

            case let .rangeContains(family):
                guard arguments.count == 2,
                      !genericArguments.isEmpty,
                      family == .range || family == .closedRange
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Range.contains has unsupported arguments"
                    )
                }
                let element = try parseStoredType(genericArguments)
                let value = try progressionValue(
                    at: arguments[1],
                    line: line
                )
                guard value.type == .init(family: family, element: element),
                      let needle = try copyStoredValue(
                          at: arguments[0],
                          line: line
                      )
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Range.contains specialization does not match its operands"
                    )
                }
                values[resultToken] = try emitBoundedRangeContainment(
                    value,
                    candidate: needle
                )

            case .rangeExpressionContains:
                guard arguments.count == 3,
                      !genericArguments.isEmpty,
                      let candidateType = stackType(at: arguments[1]),
                      let candidate = try copyStoredValue(
                          at: arguments[1],
                          line: line
                      ),
                      registerTypes[Int(candidate.rawValue)] == candidateType
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "RangeExpression pattern match has unsupported operands"
                    )
                }
                if let type = try progressionSequenceType(genericArguments) {
                    guard type.family == .range || type.family == .closedRange,
                          type.element == candidateType,
                          progressionMetatypeValues[arguments[2]] == type
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "bounded RangeExpression pattern specialization does not match"
                        )
                    }
                    let range = try progressionOperand(
                        arguments[0],
                        expected: type,
                        line: line
                    )
                    values[resultToken] = try emitBoundedRangeContainment(
                        range,
                        candidate: candidate
                    )
                } else if let shape = try CanonicalSIL.RangeExpression
                    .parsePartial(
                        genericArguments,
                        resolve: parseStoredType
                    ) {
                    let range = try partialRangeValue(at: arguments[0])
                    guard shape.boundType == candidateType,
                          range.shape == shape,
                          partialRangeMetatypeValues[arguments[2]] == shape
                    else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "partial RangeExpression pattern specialization does not match"
                        )
                    }
                    values[resultToken] = try emitPartialRangeContainment(
                        range,
                        candidate: candidate
                    )
                } else {
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "RangeExpression pattern \(genericArguments)"
                    )
                }

            case .minimum, .maximum:
                guard arguments.count == 3, !genericArguments.isEmpty else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Swift min/max has unsupported arguments"
                    )
                }
                let type = try parseType(genericArguments)
                switch type {
                case .integer, .float, .string:
                    break
                default:
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "min/max operand \(type)"
                    )
                }
                guard compilerAddressType(arguments[0]) == type,
                      stackType(at: arguments[1]) == type,
                      stackType(at: arguments[2]) == type,
                      let lhs = try copyStoredValue(at: arguments[1], line: line),
                      let rhs = try copyStoredValue(at: arguments[2], line: line),
                      registerTypes[Int(lhs.rawValue)] == type,
                      registerTypes[Int(rhs.rawValue)] == type
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Swift min/max operands do not match their specialization"
                    )
                }
                let condition = try allocate(type: .bool)
                let predicate: Bytecode.ComparisonPredicate = intrinsic == .minimum
                    ? .lessThan
                    : .lessThanOrEqual
                appendInstruction(
                    .compare(
                        result: condition,
                        predicate: predicate,
                        lhs: intrinsic == .minimum ? rhs : lhs,
                        rhs: intrinsic == .minimum ? lhs : rhs
                    )
                )
                let result = try allocate(type: type)
                appendInstruction(
                    .select(
                        result: result,
                        condition: condition,
                        trueValue: rhs,
                        falseValue: lhs
                    )
                )
                try storeConstructedValue(
                    result,
                    at: arguments[0],
                    mode: .initialize
                )
                voidValues.insert(resultToken)

            case .absoluteValue:
                guard arguments.count == 2, !genericArguments.isEmpty else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Swift abs has unsupported arguments"
                    )
                }
                let type = try parseType(genericArguments)
                guard compilerAddressType(arguments[0]) == type,
                      stackType(at: arguments[1]) == type,
                      let operand = try copyStoredValue(
                        at: arguments[1],
                        line: line
                      ),
                      registerTypes[Int(operand.rawValue)] == type
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Swift abs operand does not match its specialization"
                    )
                }
                let result: Bytecode.Register
                switch type {
                case .integer(_, signed: true):
                    let zero = try allocate(type: type)
                    appendInstruction(.constantInteger(result: zero, bitPattern: 0))
                    let isNegative = try allocate(type: .bool)
                    appendInstruction(
                        .compare(
                            result: isNegative,
                            predicate: .lessThan,
                            lhs: operand,
                            rhs: zero
                        )
                    )
                    let negated = try allocate(type: type)
                    let overflow = try allocate(type: .bool)
                    appendInstruction(
                        .checkedBinary(
                            result: negated,
                            overflow: overflow,
                            operation: .subtract,
                            lhs: zero,
                            rhs: operand
                        )
                    )
                    try appendConditionalTrap(
                        condition: overflow,
                        reason: .integerOverflow
                    )
                    result = try allocate(type: type)
                    appendInstruction(
                        .select(
                            result: result,
                            condition: isNegative,
                            trueValue: negated,
                            falseValue: operand
                        )
                    )
                case .float:
                    result = try allocate(type: type)
                    appendInstruction(
                        .floatingUnary(
                            result: result,
                            operation: .absolute,
                            operand: operand
                        )
                    )
                default:
                    throw CanonicalSIL.LoweringError.unsupportedType(
                        "abs operand \(type)"
                    )
                }
                try storeConstructedValue(
                    result,
                    at: arguments[0],
                    mode: .initialize
                )
                voidValues.insert(resultToken)

            case .unexpectedNilOptional:
                guard genericArguments.isEmpty,
                      arguments.count == 5,
                      let filename = stringLiterals[arguments[0]],
                      let filenameLength = wordLiterals[arguments[1]],
                      let filenameIsASCII = boolLiterals[arguments[2]],
                      let sourceLine = wordLiterals[arguments[3]],
                      boolLiterals[arguments[4]] != nil,
                      UInt64(filename.utf8.count) == filenameLength,
                      filename.utf8.allSatisfy({ $0 < 0x80 })
                        == filenameIsASCII,
                      sourceLine > 0,
                      let blockID = current?.id,
                      unreachableTrapReasons[blockID] == nil
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "unexpected-nil Optional diagnostic has unsupported metadata"
                    )
                }
                // Source metadata is diagnostic-only. Preserve the semantic
                // trap category on the following `unreachable` terminator.
                unreachableTrapReasons[blockID] = .optionalUnwrapOfNil
                voidValues.insert(resultToken)

            case let .sourceFailure(failure):
                try lowerSourceFailure(failure)

            case .anyObjectBridge:
                let specializations = splitTopLevel(genericArguments)
                    .filter { !$0.isEmpty }
                guard !resultToken.isEmpty,
                      specializations.count == 1,
                      arguments.count == 1
                else {
                    throw CanonicalSIL.LoweringError.malformedSIL(
                        "Swift AnyObject bridge has an invalid specialization"
                    )
                }
                let source = try materializeOwnedValue(
                    at: arguments[0],
                    line: line
                )
                let dynamicType: Bytecode.DynamicType
                if CanonicalSIL.AnyObjectBridge.isOpenedAnyArchetype(
                    specializations[0]
                ) {
                    guard registerTypes[Int(source.rawValue)] == .any else {
                        throw CanonicalSIL.LoweringError.malformedSIL(
                            "opened AnyObject bridge lost its enclosing Any value"
